window.DATA_A1_V=[{"id":"V1","q":"La ropa de color azul te ____ muy bien.","o":["saca","da","sale","sienta"],"a":3,"k":"sentar bien 표현","t":"파란색 옷은 너한테 아주 잘 어울려.","e":"옷이나 색깔이 누군가에게 '잘 어울리다'라고 할 때는 'sentar bien a + 사람'을 씁니다. sentar는 원래 '앉히다'라는 뜻이지만 옷과 함께 쓰면 '어울리다'가 됩니다. 'te'는 간접목적격 대명사(~에게)라서 '너에게 잘 어울린다'가 됩니다. 예: Ese vestido te sienta genial.(그 원피스 너한테 정말 잘 어울려.)","x":["saca: sacar(꺼내다)의 3인칭 단수로, 옷이 어울린다는 뜻이 없습니다 ✗","da: dar(주다)의 3인칭 단수로, '어울리다' 의미로 쓰지 않습니다 ✗","sale: salir(나가다)의 3인칭 단수로, 이 문맥과 맞지 않습니다 ✗","sienta: sentar(어울리다)의 3인칭 단수로, 'sentar bien'이 '잘 어울리다'라는 고정 표현 → 정답 ✓"]},{"id":"V2","q":"Tiene ojeras porque no ____ casi nada.","o":["bebe","duerme","se ejercita","pasea"],"a":1,"k":"일상 동사 어휘","t":"그는 거의 잠을 안 자서 눈 밑에 다크서클이 있다.","e":"ojeras는 '눈 밑 다크서클'을 뜻합니다. 다크서클의 가장 흔한 원인은 잠이 부족한 것이므로 dormir(자다)의 3인칭 단수 duerme가 자연스럽습니다. dormir는 어간의 o가 ue로 바뀌는 불규칙 동사(어간모음 변화 동사)입니다: duermo, duermes, duerme.","x":["bebe: beber(마시다)로, '거의 아무것도 안 마신다'는 다크서클의 이유로 어색합니다 ✗","duerme: dormir(자다)의 3인칭 단수, 잠을 못 자서 다크서클이 생김 → 정답 ✓","se ejercita: ejercitarse(운동하다)로, 다크서클과 직접 관련이 없습니다 ✗","pasea: pasear(산책하다)로, 다크서클의 원인으로 맞지 않습니다 ✗"]},{"id":"V3","q":"Ana, te ____ a Miguel. —Encantada, Miguel.","o":["descubro","enseño","muestro","presento"],"a":3,"k":"소개하기 presentar","t":"아나, 너에게 미겔을 소개할게. —반가워요, 미겔.","e":"사람을 다른 사람에게 '소개하다'는 presentar를 씁니다. 'Te presento a + 사람'은 '너에게 ~를 소개할게'라는 아주 자주 쓰는 표현입니다. 사람이 목적어일 때는 앞에 a를 붙입니다(인칭 a). 소개받은 사람은 Encantado/Encantada(반가워요)로 대답합니다.","x":["descubro: descubrir(발견하다)로, 사람을 소개할 때 쓰지 않습니다 ✗","enseño: enseñar(가르치다, 보여 주다)로, 사람 소개에는 쓰지 않습니다 ✗","muestro: mostrar(보여 주다)로, 물건을 보여 줄 때 쓰고 사람 소개에는 쓰지 않습니다 ✗","presento: presentar(소개하다)의 1인칭 단수 → 정답 ✓"]},{"id":"V4","q":"¿Qué ____ típico de la gastronomía andaluza te gusta más? —El gazpacho.","o":["frasco","cuenco","plato","vaso"],"a":2,"k":"음식 관련 어휘","t":"안달루시아 요리 중 어떤 대표 음식이 제일 좋아? —가스파초.","e":"plato는 '접시'라는 뜻도 있지만 '요리, 음식 한 가지'라는 뜻으로도 아주 많이 씁니다. 'plato típico'는 '(지역의) 대표 음식, 전통 요리'라는 표현입니다. 가스파초는 안달루시아 지방의 차가운 토마토 수프입니다.","x":["frasco: 병, 유리병으로, 요리를 가리키지 않습니다 ✗","cuenco: 사발, 그릇으로, 요리 자체를 뜻하지 않습니다 ✗","plato: 요리, 음식(접시), 'plato típico'는 대표 음식 → 정답 ✓","vaso: 컵, 유리잔으로, 음식을 가리키지 않습니다 ✗"]},{"id":"V5","q":"Este bolso es muy caro. ¿No tienen algo más ____?","o":["cómodo","barato","grande","moderno"],"a":1,"k":"형용사 반의어","t":"이 가방은 너무 비싸요. 좀 더 싼 거 없나요?","e":"caro(비싼)의 반대말은 barato(싼)입니다. 가방이 비싸다고 했으니 '더 싼 것'을 찾는 것이 자연스럽습니다. 'algo más + 형용사'는 '좀 더 ~한 것'이라는 뜻입니다. 예: ¿Tiene algo más pequeño?(좀 더 작은 거 있나요?)","x":["cómodo: 편안한으로, 가격 이야기와 연결되지 않습니다 ✗","barato: 싼, caro(비싼)의 반대말 → 정답 ✓","grande: 큰으로, 가격 문제의 해결이 아닙니다 ✗","moderno: 현대적인으로, 가격과 관련이 없습니다 ✗"]},{"id":"V6","q":"Esta es la ____ que uso para el cuerpo y esta otra para el pelo.","o":["bayeta","alfombra","toalla","cortina"],"a":2,"k":"욕실 용품 어휘","t":"이건 몸에 쓰는 수건이고 이 다른 건 머리에 쓰는 거야.","e":"toalla는 '수건, 타월'입니다. 몸을 닦는 수건과 머리를 말리는 수건을 구분하는 문맥이므로 toalla가 맞습니다. 참고로 'toalla de baño'는 목욕 수건, 'toalla de mano'는 손수건(핸드타월)입니다.","x":["bayeta: 행주, 걸레로, 몸이나 머리에 쓰지 않습니다 ✗","alfombra: 카펫, 양탄자로, 몸에 쓰는 물건이 아닙니다 ✗","toalla: 수건, 타월 → 정답 ✓","cortina: 커튼으로, 몸이나 머리에 쓰지 않습니다 ✗"]},{"id":"V7","q":"La actualidad se refiere al tiempo ____.","o":["presente","meteorológico","futuro","pasado"],"a":0,"k":"시간 관련 어휘","t":"'actualidad'는 현재의 시간을 가리킨다.","e":"actualidad는 '현재, 지금, 오늘날'이라는 뜻입니다. 영어 actually(사실은)와 비슷해 보여 헷갈리기 쉽지만 스페인어 actual은 '현재의'라는 뜻입니다. 그래서 'tiempo presente(현재 시간)'가 정답입니다. 예: En la actualidad vivo en Madrid.(현재 나는 마드리드에 산다.)","x":["presente: 현재의, actualidad의 뜻과 일치 → 정답 ✓","meteorológico: 기상의(날씨의)로, tiempo가 '날씨'일 때 쓰는 말입니다 ✗","futuro: 미래의로, actualidad와 반대 의미입니다 ✗","pasado: 과거의로, actualidad와 맞지 않습니다 ✗"]},{"id":"V8","q":"La fruta que menos me gusta es el ____.","o":["apio","champiñón","coco","arroz"],"a":2,"k":"과일 어휘","t":"내가 가장 싫어하는 과일은 코코넛이다.","e":"문제는 '과일(fruta)'을 묻고 있으므로 보기 중 과일인 coco(코코넛)가 정답입니다. 나머지는 채소, 버섯, 곡물입니다. 'la fruta que menos me gusta'는 '내가 가장 덜 좋아하는 과일', 즉 '가장 싫어하는 과일'이라는 뜻입니다.","x":["apio: 셀러리로, 채소입니다 ✗","champiñón: 양송이버섯으로, 과일이 아닙니다 ✗","coco: 코코넛, 과일 → 정답 ✓","arroz: 쌀로, 곡물입니다 ✗"]},{"id":"V9","q":"No viajo en avión porque me ____ miedo las alturas.","o":["quitan","tienen","ponen","dan"],"a":3,"k":"dar miedo 표현","t":"나는 높은 곳이 무서워서 비행기를 타지 않는다.","e":"'무섭게 하다'는 'dar miedo'라는 고정 표현을 씁니다. gustar처럼 무서운 대상이 주어가 되고, 무서워하는 사람은 간접목적격 대명사(me, te, le...)로 나타냅니다. 주어 'las alturas(높은 곳)'가 복수이므로 동사도 복수 dan이 됩니다. 예: Me dan miedo las arañas.(나는 거미가 무서워.)","x":["quitan: quitar(빼앗다, 없애다)로, 'quitar el miedo'는 오히려 두려움을 없앤다는 뜻입니다 ✗","tienen: tener(가지다)로, 'tener miedo'는 사람이 주어일 때 쓰는 구조라 여기선 맞지 않습니다 ✗","ponen: poner(놓다)로, 'poner miedo'라는 표현은 쓰지 않습니다 ✗","dan: dar(주다)의 3인칭 복수, 'dar miedo'(무섭게 하다) → 정답 ✓"]},{"id":"V10","q":"Los niños lo pasaron muy bien en las atracciones de la ____.","o":["iglesia","gasolinera","feria","librería"],"a":2,"k":"장소 어휘","t":"아이들은 놀이공원(축제장)의 놀이기구에서 아주 즐거운 시간을 보냈다.","e":"feria는 '축제, 장터, 박람회'라는 뜻으로, 스페인에서는 회전목마 같은 놀이기구(atracciones)가 있는 축제장을 가리킵니다. 'pasarlo bien'은 '즐거운 시간을 보내다'라는 자주 쓰는 표현입니다.","x":["iglesia: 교회, 성당으로, 놀이기구가 없습니다 ✗","gasolinera: 주유소로, 놀이기구가 없습니다 ✗","feria: 축제(장), 놀이기구가 있는 곳 → 정답 ✓","librería: 서점으로, 놀이기구와 관련이 없습니다 ✗"]},{"id":"V11","q":"Las personas ____ suelen tener más problemas de salud que las jóvenes.","o":["mejores","especiales","lindas","mayores"],"a":3,"k":"나이 관련 형용사","t":"나이 든 사람들은 젊은 사람들보다 건강 문제가 더 많은 편이다.","e":"'personas mayores'는 '노인, 나이 드신 분들'을 정중하게 부르는 표현입니다. mayor는 '더 나이 많은'이라는 뜻으로, 뒤의 jóvenes(젊은)와 대비됩니다. 'soler + 동사원형'은 '~하는 편이다, 보통 ~한다'라는 뜻입니다.","x":["mejores: 더 좋은으로, 젊은 사람과의 대비가 되지 않습니다 ✗","especiales: 특별한으로, 문맥과 맞지 않습니다 ✗","lindas: 예쁜(주로 중남미에서 씀)으로, 나이와 관련이 없습니다 ✗","mayores: 나이 든, jóvenes(젊은)과 대비 → 정답 ✓"]},{"id":"V12","q":"Me encanta estar en casa; soy muy ____.","o":["educado","hogareño","noble","inestable"],"a":1,"k":"성격 형용사","t":"나는 집에 있는 게 정말 좋아. 나는 아주 집순이(집돌이)야.","e":"hogareño는 hogar(가정, 집)에서 나온 형용사로 '집에 있기 좋아하는, 가정적인'이라는 뜻입니다. 집에 있는 걸 좋아한다고 했으니 hogareño가 딱 맞습니다. 여성형은 hogareña입니다.","x":["educado: 예의 바른으로, 집에 있는 것과 관련이 없습니다 ✗","hogareño: 집에 있기 좋아하는, 가정적인 → 정답 ✓","noble: 고귀한, 품위 있는으로, 문맥과 맞지 않습니다 ✗","inestable: 불안정한으로, 문맥과 맞지 않습니다 ✗"]},{"id":"V13","q":"¿Cuántas palabras dice vuestro ____?","o":["caballo","burro","loro","pez"],"a":2,"k":"동물 어휘","t":"너희 앵무새는 단어를 몇 개나 말하니?","e":"사람의 말을 따라 하는 동물은 loro(앵무새)입니다. 그래서 '단어를 몇 개 말하냐'는 질문에 어울립니다. vuestro는 '너희의'로, 스페인에서 쓰는 vosotros의 소유형입니다(중남미에서는 보통 su를 씁니다).","x":["caballo: 말(馬)로, 말을 하지 못합니다 ✗","burro: 당나귀로, 말을 하지 못합니다 ✗","loro: 앵무새, 사람 말을 따라 함 → 정답 ✓","pez: 물고기로, 말을 하지 못합니다 ✗"]},{"id":"V14","q":"Málaga es una ciudad ____. ¡Me encantaría volver!","o":["desagradable","triste","maravillosa","contaminada"],"a":2,"k":"긍정 형용사","t":"말라가는 멋진 도시야. 꼭 다시 가고 싶어!","e":"'다시 가고 싶다(¡Me encantaría volver!)'고 했으니 도시에 대한 좋은 평가가 와야 합니다. maravillosa는 '멋진, 훌륭한'이라는 뜻입니다. ciudad가 여성명사라서 형용사도 여성형 -a로 끝납니다.","x":["desagradable: 불쾌한으로, 다시 가고 싶다는 말과 모순됩니다 ✗","triste: 슬픈, 우울한으로, 긍정적 평가가 아닙니다 ✗","maravillosa: 멋진, 훌륭한 → 정답 ✓","contaminada: 오염된으로, 부정적 평가입니다 ✗"]},{"id":"V15","q":"Ese hombre está ____ de control. No hables con él.","o":["dentro","lejos","detrás","fuera"],"a":3,"k":"fuera de control","t":"저 남자는 통제 불능 상태야. 그와 말하지 마.","e":"'fuera de control'은 '통제 불능의, 제정신이 아닌'이라는 고정 표현입니다. fuera de는 '~의 밖에'라는 뜻이라 '통제의 밖에 있다'가 됩니다. 반대로 'bajo control'은 '통제하에 있는'입니다.","x":["dentro: ~안에로, 'dentro de control'이라는 표현은 쓰지 않습니다 ✗","lejos: 멀리로, control과 함께 쓰지 않습니다 ✗","detrás: ~뒤에로, 문맥과 맞지 않습니다 ✗","fuera: ~밖에, 'fuera de control'(통제 불능) → 정답 ✓"]},{"id":"V16","q":"Mi hermana quiere ser ____, por eso estudia Derecho.","o":["abogada","ingeniera","obrera","camarera"],"a":0,"k":"직업 어휘","t":"우리 언니(여동생)는 변호사가 되고 싶어 해서 법학을 공부한다.","e":"Derecho는 대문자로 쓰면 '법학'이라는 학문을 뜻합니다. 법학을 공부하는 이유이므로 abogada(변호사)가 정답입니다. 여성 주어(mi hermana)이므로 직업명도 여성형 -a를 씁니다.","x":["abogada: 변호사(여), 법학과 연결 → 정답 ✓","ingeniera: 엔지니어(여)로, 공학을 공부합니다 ✗","obrera: 노동자(여)로, 법학과 관련이 없습니다 ✗","camarera: 웨이트리스로, 법학과 관련이 없습니다 ✗"]},{"id":"V17","q":"El camarero va a traernos la ____ de bebidas.","o":["libreta","carta","tarjeta","entrada"],"a":1,"k":"식당 어휘","t":"웨이터가 우리에게 음료 메뉴판을 가져다줄 거야.","e":"식당의 '메뉴판'은 스페인어로 carta라고 합니다. 'carta de bebidas'는 '음료 메뉴판', 'carta de vinos'는 '와인 리스트'입니다. carta는 '편지'라는 뜻도 있지만 식당에서는 메뉴판입니다. 참고로 'menú'는 보통 정해진 코스(오늘의 메뉴)를 말합니다.","x":["libreta: 수첩, 메모장으로, 메뉴판이 아닙니다 ✗","carta: 메뉴판(편지), 'carta de bebidas' → 정답 ✓","tarjeta: 카드(신용카드, 명함)로, 메뉴판이 아닙니다 ✗","entrada: 입장권, 입구, 전채 요리로, 문맥과 맞지 않습니다 ✗"]},{"id":"V18","q":"Tengo que llevar al ____ a la guardería.","o":["joven","anciano","bebé","adolescente"],"a":2,"k":"연령대 어휘","t":"나는 아기를 어린이집에 데려다줘야 해.","e":"guardería는 '어린이집, 탁아소'입니다. 어린이집에 가는 사람은 bebé(아기)입니다. bebé는 남녀 모두 'el bebé'로 쓰는 경우가 많습니다. 'llevar a + 사람'은 '~를 데려가다'입니다.","x":["joven: 젊은이로, 어린이집에 가지 않습니다 ✗","anciano: 노인으로, 어린이집에 가지 않습니다 ✗","bebé: 아기, 어린이집(guardería)에 감 → 정답 ✓","adolescente: 청소년으로, 어린이집에 가지 않습니다 ✗"]},{"id":"V19","q":"Tengo tres mascotas, un perro y dos ____.","o":["plantas","flores","gatos","jardines"],"a":2,"k":"반려동물 어휘","t":"나는 반려동물이 세 마리 있어. 개 한 마리와 고양이 두 마리.","e":"mascota는 '반려동물, 애완동물'입니다. 개와 함께 나열되는 반려동물이어야 하므로 gatos(고양이들)가 정답입니다. dos(둘) 뒤라서 복수형을 씁니다.","x":["plantas: 식물로, 반려동물(mascota)이 아닙니다 ✗","flores: 꽃으로, 반려동물이 아닙니다 ✗","gatos: 고양이(복수), 반려동물 → 정답 ✓","jardines: 정원으로, 반려동물이 아닙니다 ✗"]},{"id":"V20","q":"Me gustan mucho estas botas, pero son ____.","o":["incómodas","comodísimas","magníficas","maravillosas"],"a":0,"k":"형용사 반의어","t":"나는 이 부츠가 정말 마음에 들지만 불편해.","e":"pero(하지만)는 앞 내용과 반대되는 말을 이끕니다. '마음에 든다' 뒤에 pero가 오므로 단점인 incómodas(불편한)가 와야 합니다. in-은 반대 의미를 만드는 접두사입니다: cómodo(편한) → incómodo(불편한).","x":["incómodas: 불편한, pero 뒤의 단점 → 정답 ✓","comodísimas: 아주 편한으로, pero와 대조가 되지 않습니다 ✗","magníficas: 훌륭한으로, 장점이라 pero와 맞지 않습니다 ✗","maravillosas: 멋진으로, 장점이라 pero와 맞지 않습니다 ✗"]},{"id":"V21","q":"____ árboles es bueno para las ciudades donde hace calor.","o":["Eliminar","Cortar","Destruir","Plantar"],"a":3,"k":"환경 동사 어휘","t":"나무를 심는 것은 더운 도시에 좋다.","e":"plantar는 '심다'라는 뜻입니다. 나무는 그늘을 만들어 더운 도시에 도움이 되므로 '나무를 심는 것'이 좋다는 말이 자연스럽습니다. 동사원형이 문장 맨 앞에서 주어 역할(~하는 것은)을 할 수 있습니다.","x":["Eliminar: 없애다로, 더운 도시에 좋은 일이 아닙니다 ✗","Cortar: 자르다, 베다로, 문맥과 반대입니다 ✗","Destruir: 파괴하다로, 문맥과 반대입니다 ✗","Plantar: 심다, 나무를 심으면 그늘이 생김 → 정답 ✓"]},{"id":"V22","q":"¿Qué ____ tenía cuando empezó a aprender inglés? —Seis años.","o":["edad","nombre","situación","opción"],"a":0,"k":"나이 묻기","t":"영어를 배우기 시작했을 때 몇 살이었어요? —여섯 살이요.","e":"'¿Qué edad tiene?'는 '몇 살이에요?'를 묻는 표현으로, '¿Cuántos años tiene?'와 같은 뜻입니다. edad는 '나이'입니다. 대답이 'Seis años(여섯 살)'이므로 edad가 정답입니다. 스페인어는 나이를 tener(가지다)로 말한다는 점도 기억하세요.","x":["edad: 나이, 'Seis años'라는 대답과 연결 → 정답 ✓","nombre: 이름으로, 대답이 나이라서 맞지 않습니다 ✗","situación: 상황으로, 문맥과 맞지 않습니다 ✗","opción: 선택지로, 문맥과 맞지 않습니다 ✗"]},{"id":"V23","q":"Pon los vasos, los platos, los cubiertos y las ____ en la mesa, por favor.","o":["camisetas","toallas","sábanas","servilletas"],"a":3,"k":"식탁 용품 어휘","t":"식탁에 컵, 접시, 수저(커틀러리), 그리고 냅킨을 놓아 줘.","e":"servilleta는 '냅킨'입니다. 컵(vasos), 접시(platos), 커틀러리(cubiertos: 포크·나이프·숟가락)와 함께 식탁에 놓는 물건이므로 servilletas가 맞습니다. 'poner la mesa'는 '상을 차리다'라는 표현입니다.","x":["camisetas: 티셔츠로, 식탁에 놓지 않습니다 ✗","toallas: 수건으로, 욕실에서 씁니다 ✗","sábanas: 침대 시트로, 침실에서 씁니다 ✗","servilletas: 냅킨, 식탁 용품 → 정답 ✓"]},{"id":"V24","q":"Es muy optimista, siempre ve el lado ____ de las cosas.","o":["feo","positivo","negativo","triste"],"a":1,"k":"긍정/부정 어휘","t":"그는 아주 낙관적이라서 항상 일의 긍정적인 면을 본다.","e":"optimista(낙관적인)인 사람은 항상 'el lado positivo(긍정적인 면)'를 봅니다. lado는 '쪽, 면'이라는 뜻입니다. optimista는 남녀 모두 같은 형태입니다.","x":["feo: 못생긴, 보기 흉한으로, 낙관적인 사람과 맞지 않습니다 ✗","positivo: 긍정적인, 낙관적인 사람이 보는 면 → 정답 ✓","negativo: 부정적인으로, 낙관적과 반대입니다 ✗","triste: 슬픈으로, 낙관적과 맞지 않습니다 ✗"]},{"id":"V25","q":"No me interesa el lujo, prefiero las cosas ____.","o":["caras","raras","sencillas","extrañas"],"a":2,"k":"형용사 반의어","t":"나는 사치에 관심 없어. 소박한 것들이 더 좋아.","e":"lujo(사치, 호화로움)의 반대 개념은 sencillo(소박한, 단순한)입니다. '사치에 관심 없다'고 했으니 소박한 것을 선호한다는 말이 자연스럽습니다. cosas가 여성 복수라서 sencillas가 됩니다.","x":["caras: 비싼으로, 사치와 같은 방향이라 모순됩니다 ✗","raras: 이상한, 드문으로, 사치와 대비되지 않습니다 ✗","sencillas: 소박한, 단순한, 사치의 반대 → 정답 ✓","extrañas: 이상한으로, 문맥과 맞지 않습니다 ✗"]},{"id":"V26","q":"Mi padre ya no ____, está jubilado.","o":["disfruta","trabaja","habla","camina"],"a":1,"k":"일·은퇴 어휘","t":"우리 아버지는 이제 일하지 않으셔. 은퇴하셨어.","e":"jubilado는 '은퇴한, 퇴직한'이라는 뜻입니다. 은퇴했다는 것은 더 이상 일하지(trabajar) 않는다는 의미입니다. 'ya no + 동사'는 '더 이상 ~하지 않다'라는 표현입니다.","x":["disfruta: disfrutar(즐기다)로, 은퇴와 반대 의미가 아닙니다 ✗","trabaja: trabajar(일하다), 은퇴해서 더 이상 일하지 않음 → 정답 ✓","habla: hablar(말하다)로, 은퇴와 관련이 없습니다 ✗","camina: caminar(걷다)로, 은퇴와 관련이 없습니다 ✗"]},{"id":"V27","q":"¿Cuándo ____ a tu novio? —Hace cuatro años.","o":["saludaste","conociste","creaste","sacaste"],"a":1,"k":"conocer 처음 만나다","t":"남자친구를 언제 처음 만났어? —4년 전에.","e":"conocer는 '알다'라는 뜻 외에 과거형(점과거)으로 쓰면 '(누군가를) 처음 만나다, 알게 되다'라는 뜻이 됩니다. conociste는 tú의 점과거형입니다. 'hace + 기간'은 '~전에'입니다. 예: Conocí a mi mujer en Madrid.(나는 아내를 마드리드에서 처음 만났다.)","x":["saludaste: saludar(인사하다)로, '처음 만나다'의 뜻이 아닙니다 ✗","conociste: conocer의 점과거, '처음 만났다' → 정답 ✓","creaste: crear(만들어 내다, 창조하다)로, 사람에게 쓰지 않습니다 ✗","sacaste: sacar(꺼내다)로, 문맥과 맞지 않습니다 ✗"]},{"id":"V28","q":"Mi padre es conductor de ____.","o":["autobús","avión","globo","helicóptero"],"a":0,"k":"교통수단 어휘","t":"우리 아버지는 버스 운전기사이다.","e":"conductor는 '운전기사, 운전자'로, 자동차·버스 등 도로 위의 차량을 운전하는 사람입니다. 비행기나 헬리콥터를 조종하는 사람은 piloto(조종사)라고 합니다. 그래서 autobús(버스)가 정답입니다. 중남미에서는 버스를 bus, camión(멕시코), colectivo(아르헨티나) 등으로도 부릅니다.","x":["autobús: 버스, conductor가 운전함 → 정답 ✓","avión: 비행기로, 조종하는 사람은 piloto입니다 ✗","globo: 열기구, 풍선으로, conductor라고 하지 않습니다 ✗","helicóptero: 헬리콥터로, 조종하는 사람은 piloto입니다 ✗"]},{"id":"V29","q":"El ____ de esta iglesia es muy querido por todos los habitantes del pueblo.","o":["agente","repartidor","cura","maestro"],"a":2,"k":"종교·직업 어휘","t":"이 성당의 신부님은 마을 주민 모두에게 사랑받는다.","e":"cura는 가톨릭 '신부님'입니다. iglesia(성당, 교회)와 연결되는 사람이므로 cura가 정답입니다. 참고로 cura는 여성명사(la cura)로 쓰면 '치료'라는 다른 뜻입니다. 'querido por todos'는 '모두에게 사랑받는'입니다.","x":["agente: 요원, 경찰관, 대리인으로, 성당과 관련이 없습니다 ✗","repartidor: 배달원으로, 성당과 관련이 없습니다 ✗","cura: 신부(가톨릭 사제), iglesia와 연결 → 정답 ✓","maestro: 선생님으로, 성당의 직책이 아닙니다 ✗"]},{"id":"V30","q":"Antes vivía en un apartamento oscuro, pero ahora vivo en una casa ____.","o":["antigua","reformada","limpia","luminosa"],"a":3,"k":"집 묘사 형용사","t":"전에는 어두운 아파트에 살았지만, 지금은 밝은 집에 산다.","e":"pero(하지만)로 과거와 현재를 대비하고 있습니다. oscuro(어두운)의 반대말은 luminoso(밝은, 채광이 좋은)입니다. luz(빛)에서 나온 말이라 '빛이 잘 드는'이라는 뜻입니다. casa가 여성명사라서 luminosa가 됩니다.","x":["antigua: 오래된으로, oscuro와 대비되지 않습니다 ✗","reformada: 리모델링한으로, oscuro와 직접 대비되지 않습니다 ✗","limpia: 깨끗한으로, oscuro의 반대말이 아닙니다 ✗","luminosa: 밝은, 채광 좋은, oscuro의 반대 → 정답 ✓"]},{"id":"V31","q":"Esta camisa me ____ pequeña.","o":["pone","deja","da","queda"],"a":3,"k":"quedar 옷 크기","t":"이 셔츠는 나한테 작아.","e":"옷의 크기나 어울림을 말할 때 'quedar + 형용사/부사 + a + 사람'을 씁니다. 'Me queda pequeña'는 '나한테 작다(맞지 않다)'라는 뜻입니다. 예: Estos pantalones me quedan grandes.(이 바지는 나한테 커.) 'me queda bien'은 '잘 맞다, 잘 어울린다'입니다.","x":["pone: poner(놓다, 입다)로, 옷 크기를 말할 때 쓰지 않습니다 ✗","deja: dejar(남기다, 두다)로, 문맥과 맞지 않습니다 ✗","da: dar(주다)로, 옷 크기를 말할 때 쓰지 않습니다 ✗","queda: quedar(맞다, ~하게 되다), 'me queda pequeña' → 정답 ✓"]},{"id":"V32","q":"Estoy ____ porque no me gusta la idea de casarme.","o":["interesado","contento","soltero","ocupado"],"a":2,"k":"결혼 여부 어휘","t":"결혼한다는 생각이 마음에 들지 않아서 나는 미혼이다.","e":"soltero는 '미혼의, 독신의'라는 뜻입니다. 결혼하고 싶지 않다는 이유가 나오므로 soltero가 정답입니다. 결혼 상태를 말할 때는 estar 또는 ser를 모두 씁니다(estoy soltero / soy soltero). 반대말은 casado(기혼의)입니다.","x":["interesado: 관심 있는으로, 결혼을 원치 않는 이유와 맞지 않습니다 ✗","contento: 기쁜, 만족한으로, 결혼 여부를 나타내지 않습니다 ✗","soltero: 미혼의, 독신의 → 정답 ✓","ocupado: 바쁜으로, 문맥과 맞지 않습니다 ✗"]},{"id":"V33","q":"No puedo concentrarme con tanto ____. ¿Podéis guardar silencio, por favor?","o":["ruido","viento","frío","movimiento"],"a":0,"k":"소리 관련 어휘","t":"이렇게 시끄러우면 집중할 수 없어. 좀 조용히 해 줄래?","e":"ruido는 '소음, 시끄러운 소리'입니다. 'guardar silencio(조용히 하다)'를 부탁하므로 집중을 방해하는 것은 소음입니다. 'tanto + 남성명사'는 '그렇게 많은 ~'이라는 뜻입니다. ¿Podéis~?는 스페인의 vosotros 형태입니다(중남미에서는 ¿Pueden~?).","x":["ruido: 소음, 조용히 해 달라는 요청과 연결 → 정답 ✓","viento: 바람으로, 조용히 해 달라는 말과 맞지 않습니다 ✗","frío: 추위로, 조용히 해 달라는 말과 맞지 않습니다 ✗","movimiento: 움직임으로, 조용히 해 달라는 말과 직접 연결되지 않습니다 ✗"]},{"id":"V34","q":"En este supermercado, los productos de limpieza están al final de ese ____.","o":["pasillo","salón","paso","sillón"],"a":0,"k":"매장 공간 어휘","t":"이 슈퍼마켓에서 청소용품은 저 통로 끝에 있어요.","e":"pasillo는 '복도, 통로'로, 슈퍼마켓 진열대 사이의 통로를 말합니다. 'al final de'는 '~의 끝에'입니다. 슈퍼마켓에서 물건 위치를 물을 때 자주 듣는 단어입니다.","x":["pasillo: 통로, 복도, 슈퍼마켓 진열대 사이 → 정답 ✓","salón: 거실, 홀로, 슈퍼마켓 안의 공간이 아닙니다 ✗","paso: 걸음, 통과로, 장소의 통로를 말할 때 쓰지 않습니다 ✗","sillón: 안락의자로, 장소가 아닙니다 ✗"]},{"id":"V35","q":"Para mí, el ____ ideal es tranquilo, histórico y bien comunicado.","o":["viaje","barrio","hombre","trabajo"],"a":1,"k":"동네 어휘","t":"나에게 이상적인 동네는 조용하고, 역사가 있고, 교통이 편리한 곳이다.","e":"barrio는 '동네, 지역'입니다. tranquilo(조용한), histórico(역사적인), 'bien comunicado(교통이 편리한)'는 모두 장소를 묘사하는 말이므로 barrio가 맞습니다. 'bien comunicado'는 집이나 동네를 소개할 때 자주 나오는 표현입니다.","x":["viaje: 여행으로, '교통이 편리한' 같은 장소 묘사와 맞지 않습니다 ✗","barrio: 동네, 장소 묘사와 맞음 → 정답 ✓","hombre: 남자로, 'histórico, bien comunicado'와 어울리지 않습니다 ✗","trabajo: 일, 직장으로, 이 묘사와 맞지 않습니다 ✗"]},{"id":"V36","q":"Por favor, abrid el libro por la ____ veinte.","o":["avenida","escalera","calle","página"],"a":3,"k":"교실 어휘","t":"자, 책 20쪽을 펴세요.","e":"página는 '페이지, 쪽'입니다. 'abrir el libro por la página + 숫자'는 '책 ~쪽을 펴다'라는 교실 표현입니다. abrid는 vosotros에게 하는 명령형으로 스페인에서 씁니다(중남미에서는 abran).","x":["avenida: 대로, 큰길로, 책과 관련이 없습니다 ✗","escalera: 계단으로, 책과 관련이 없습니다 ✗","calle: 거리로, 책과 관련이 없습니다 ✗","página: 페이지, 쪽 → 정답 ✓"]},{"id":"V37","q":"El ____ es el fruto de la higuera.","o":["limón","higo","plátano","melocotón"],"a":1,"k":"과일 어휘","t":"무화과는 무화과나무의 열매이다.","e":"higuera는 '무화과나무'이고 그 열매는 higo(무화과)입니다. 스페인어에서는 열매 이름에서 나무 이름이 나오는 경우가 많습니다: manzana(사과) → manzano(사과나무), naranja(오렌지) → naranjo(오렌지나무).","x":["limón: 레몬으로, 레몬나무(limonero)의 열매입니다 ✗","higo: 무화과, higuera의 열매 → 정답 ✓","plátano: 바나나로, 바나나나무의 열매입니다 ✗","melocotón: 복숭아로, 복숭아나무(melocotonero)의 열매입니다 ✗"]},{"id":"V38","q":"Es un piso ____, por eso tiene tanta luz.","o":["exterior","alquilado","amueblado","interior"],"a":0,"k":"집 묘사 어휘","t":"외부(바깥)를 향한 집이라서 빛이 많이 들어온다.","e":"스페인에서 'piso exterior'는 창문이 거리 쪽을 향한 집이라 햇빛이 잘 드는 집을 말하고, 'piso interior'는 안뜰 쪽을 향해 어두운 집을 말합니다. 빛이 많다(tanta luz)고 했으니 exterior가 정답입니다. piso는 스페인에서 '아파트'를 뜻합니다.","x":["exterior: 바깥쪽을 향한, 빛이 잘 듦 → 정답 ✓","alquilado: 임대한(세 든)으로, 빛과 관련이 없습니다 ✗","amueblado: 가구가 딸린으로, 빛과 관련이 없습니다 ✗","interior: 안쪽을 향한으로, 오히려 빛이 적습니다 ✗"]},{"id":"V39","q":"Perdonadme por llegar tarde. —No ____ nada, todavía no ha empezado la reunión.","o":["tiene","pasa","hay","da"],"a":1,"k":"No pasa nada","t":"늦어서 미안해. —괜찮아, 아직 회의 시작 안 했어.","e":"'No pasa nada'는 '괜찮아, 별일 아니야'라는 아주 자주 쓰는 표현입니다. 사과를 받았을 때 대답으로 씁니다. pasar는 여기서 '일어나다, 생기다'라는 뜻이라 직역하면 '아무 일도 일어나지 않아'입니다. Perdonadme는 vosotros에게 하는 명령형입니다.","x":["tiene: tener(가지다)로, 'No tiene nada'는 '아무것도 없다'라는 뜻이라 맞지 않습니다 ✗","pasa: pasar(일어나다), 'No pasa nada'(괜찮아) → 정답 ✓","hay: '있다'로, 'No hay nada'는 '아무것도 없다'라서 사과에 대한 대답이 아닙니다 ✗","da: dar(주다)로, 'No da nada'라는 표현은 쓰지 않습니다 ✗"]},{"id":"V40","q":"Desde la ventana de mi cuarto ____ un parque.","o":["encuentro","tomo","veo","escucho"],"a":2,"k":"지각 동사 ver","t":"내 방 창문에서 공원이 보인다.","e":"ver는 '보다, 보이다'입니다. 창문에서 공원을 '본다'는 것은 시각이므로 veo(ver의 1인칭 단수)가 정답입니다. ver의 1인칭 단수는 불규칙으로 veo입니다.","x":["encuentro: encontrar(찾다, 발견하다)로, 창문에서 늘 보이는 풍경에는 어색합니다 ✗","tomo: tomar(잡다, 먹다)로, 문맥과 맞지 않습니다 ✗","veo: ver(보다)의 1인칭 단수 → 정답 ✓","escucho: escuchar(듣다)로, 공원은 보는 대상입니다 ✗"]},{"id":"V41","q":"Esta cama es pequeña, por eso únicamente necesito una ____.","o":["almohada","alfombra","sábana","cortina"],"a":0,"k":"침구 어휘","t":"이 침대는 작아서 베개는 하나만 있으면 돼.","e":"almohada는 '베개'입니다. 작은 1인용 침대에는 베개 하나면 충분하다는 의미입니다. únicamente는 '오직, ~만'이라는 뜻으로 solo와 같습니다.","x":["almohada: 베개, 침대 크기에 따라 개수가 달라짐 → 정답 ✓","alfombra: 카펫으로, 침대 크기와 관련이 없습니다 ✗","sábana: 시트로, 보통 침대에 두 장(위·아래)을 쓰므로 문맥과 맞지 않습니다 ✗","cortina: 커튼으로, 침대와 관련이 없습니다 ✗"]},{"id":"V42","q":"Voy a conducir luego, así que es mejor tomar una cerveza sin ____.","o":["aceite","alcohol","sal","azúcar"],"a":1,"k":"음료 어휘","t":"이따가 운전할 거라서 무알코올 맥주를 마시는 게 낫다.","e":"'cerveza sin alcohol'은 '무알코올 맥주'입니다. 운전해야 하므로 알코올이 없는 맥주를 고르는 것입니다. 'así que'는 '그래서'라는 뜻의 연결어입니다.","x":["aceite: 기름, 식용유로, 맥주와 관련이 없습니다 ✗","alcohol: 알코올, 'sin alcohol'(무알코올) → 정답 ✓","sal: 소금으로, 운전과 관련이 없습니다 ✗","azúcar: 설탕으로, 운전과 관련이 없습니다 ✗"]},{"id":"V43","q":"Para mí, el ____ más difícil de aprender es el árabe.","o":["idioma","oficio","deporte","juego"],"a":0,"k":"언어 어휘","t":"나에게 배우기 가장 어려운 언어는 아랍어다.","e":"idioma는 '언어, 외국어'입니다. 아랍어(el árabe)는 언어이므로 idioma가 정답입니다. idioma는 -a로 끝나지만 남성명사(el idioma)라는 점에 주의하세요. 같은 경우로 el problema, el tema가 있습니다.","x":["idioma: 언어(남성명사), 아랍어는 언어 → 정답 ✓","oficio: 직업, 기술로, 아랍어와 맞지 않습니다 ✗","deporte: 스포츠로, 아랍어와 맞지 않습니다 ✗","juego: 놀이, 게임으로, 아랍어와 맞지 않습니다 ✗"]},{"id":"V44","q":"Nuestros hijos estudian en el ____ que está enfrente de nuestra casa.","o":["puerto","instituto","mercado","dormitorio"],"a":1,"k":"학교 어휘","t":"우리 아이들은 우리 집 맞은편에 있는 고등학교에 다닌다.","e":"스페인에서 instituto는 '중·고등학교(공립 중등학교)'를 뜻합니다. '공부하는 곳'이므로 instituto가 정답입니다. 'enfrente de'는 '~의 맞은편에'입니다. 중남미에서는 colegio, liceo, preparatoria 등 나라마다 부르는 말이 다릅니다.","x":["puerto: 항구로, 공부하는 곳이 아닙니다 ✗","instituto: 중·고등학교, 공부하는 곳 → 정답 ✓","mercado: 시장으로, 공부하는 곳이 아닙니다 ✗","dormitorio: 침실로, 학교가 아닙니다 ✗"]},{"id":"V45","q":"Esta actriz se hizo famosa por su ____ en una serie estadounidense.","o":["hoja","papel","bloc","libreta"],"a":1,"k":"papel 역할","t":"이 여배우는 미국 드라마의 배역으로 유명해졌다.","e":"papel은 '종이'라는 뜻이 가장 기본이지만 배우가 맡는 '역할, 배역'이라는 뜻도 있습니다. 'hacer el papel de~'는 '~의 역할을 하다'입니다. 다른 보기들은 모두 종이·노트 종류라 배역을 뜻하지 않습니다.","x":["hoja: 종이 한 장, 나뭇잎으로, 배역이라는 뜻이 없습니다 ✗","papel: 종이, 역할(배역) → 정답 ✓","bloc: 메모장, 스케치북으로, 배역이라는 뜻이 없습니다 ✗","libreta: 수첩으로, 배역이라는 뜻이 없습니다 ✗"]},{"id":"V46","q":"Hay que ____ antes de ir a dormir.","o":["vestirse","desmaquillarse","peinarse","afeitarse"],"a":1,"k":"재귀동사 어휘","t":"자러 가기 전에 화장을 지워야 한다.","e":"desmaquillarse는 '화장을 지우다'입니다. maquillarse(화장하다)에 반대를 뜻하는 des-가 붙은 형태입니다. 자기 전에 하는 일로 가장 자연스럽습니다. 'Hay que + 동사원형'은 '~해야 한다'(일반적인 의무)입니다.","x":["vestirse: 옷을 입다로, 자기 전에 하는 일로 어색합니다 ✗","desmaquillarse: 화장을 지우다, 자기 전에 하는 일 → 정답 ✓","peinarse: 머리를 빗다로, 보통 외출 전에 합니다 ✗","afeitarse: 면도하다로, 보통 아침에 합니다 ✗"]},{"id":"V47","q":"¿Me ____ a mover estas cajas? No puedo hacerlo yo solo.","o":["ayudas","invitas","obligas","pones"],"a":0,"k":"부탁하기 ayudar","t":"이 상자들 옮기는 것 좀 도와줄래? 나 혼자서는 못 하겠어.","e":"'ayudar a + 사람 + a + 동사원형'은 '(누가) ~하는 것을 돕다'입니다. '¿Me ayudas a ~?'는 '~하는 것 좀 도와줄래?'라는 부탁 표현입니다. 혼자서는 못 한다(yo solo)는 말과 연결됩니다.","x":["ayudas: ayudar(돕다), '¿Me ayudas a~?' → 정답 ✓","invitas: invitar(초대하다)로, 상자 옮기기와 맞지 않습니다 ✗","obligas: obligar(강요하다)로, 부탁하는 말로 맞지 않습니다 ✗","pones: poner(놓다)로, 'poner a + 동사'는 부탁 표현이 아닙니다 ✗"]},{"id":"V48","q":"Siempre viajo con esta ____ porque en ella cabe todo lo que necesito.","o":["caja","taza","maleta","botella"],"a":2,"k":"여행 용품 어휘","t":"나는 필요한 게 다 들어가서 늘 이 여행 가방을 가지고 여행한다.","e":"maleta는 '여행 가방, 캐리어'입니다. 여행할 때 필요한 물건을 다 넣는 것이므로 maleta가 정답입니다. 'caber'는 '들어가다'라는 뜻으로 cabe는 3인칭 단수입니다. 중남미 일부에서는 valija라고도 합니다.","x":["caja: 상자로, 여행할 때 들고 다니는 물건이 아닙니다 ✗","taza: 머그컵, 찻잔으로, 물건을 넣지 않습니다 ✗","maleta: 여행 가방 → 정답 ✓","botella: 병으로, 필요한 물건을 다 넣을 수 없습니다 ✗"]},{"id":"V49","q":"Mi ____ no va bien. Mi marido y yo tenemos diferencias importantes.","o":["negocio","tienda","matrimonio","bazar"],"a":2,"k":"가족 관계 어휘","t":"내 결혼 생활이 잘 안 되고 있어. 남편과 나는 큰 의견 차이가 있어.","e":"matrimonio는 '결혼, 부부, 결혼 생활'입니다. 남편(marido)과의 차이를 이야기하므로 matrimonio가 맞습니다. 'ir bien/mal'은 '잘 되다/잘 안 되다'라는 표현입니다.","x":["negocio: 사업, 장사로, 남편과의 차이와 직접 관련이 없습니다 ✗","tienda: 가게로, 남편과의 관계와 관련이 없습니다 ✗","matrimonio: 결혼 생활, 부부 → 정답 ✓","bazar: 잡화점으로, 문맥과 맞지 않습니다 ✗"]},{"id":"V50","q":"No podemos entrar en casa porque no tenemos las ____.","o":["llaves","bolsas","claves","carteras"],"a":0,"k":"생활 물건 어휘","t":"열쇠가 없어서 우리는 집에 들어갈 수 없다.","e":"llave는 '열쇠'입니다. 집에 들어가려면 열쇠가 필요하므로 llaves가 정답입니다. clave는 '비밀번호, 암호, 핵심'이라는 뜻이라 문 열쇠에는 쓰지 않습니다. 비슷한 생김새에 속지 마세요.","x":["llaves: 열쇠(복수), 집에 들어갈 때 필요 → 정답 ✓","bolsas: 봉지, 가방으로, 집에 들어가는 것과 관련이 없습니다 ✗","claves: 비밀번호, 암호로, 문 열쇠가 아닙니다 ✗","carteras: 지갑으로, 집에 들어가는 것과 관련이 없습니다 ✗"]},{"id":"V51","q":"No puedo escribir libros de ____ porque no tengo imaginación.","o":["ficción","historia","gramática","matemáticas"],"a":0,"k":"책 장르 어휘","t":"나는 상상력이 없어서 소설(픽션) 책을 쓸 수 없다.","e":"ficción은 '허구, 픽션'으로 작가의 상상으로 만든 이야기를 말합니다. 상상력(imaginación)이 없어서 못 쓴다는 것이므로 ficción이 정답입니다. 'ciencia ficción'은 '공상과학(SF)'입니다.","x":["ficción: 픽션, 상상력이 필요함 → 정답 ✓","historia: 역사로, 사실에 바탕을 두어 상상력이 핵심이 아닙니다 ✗","gramática: 문법으로, 상상력이 필요한 장르가 아닙니다 ✗","matemáticas: 수학으로, 상상력과 관련이 적습니다 ✗"]},{"id":"V52","q":"En esta empresa, ____, gano más dinero.","o":["afortunadamente","desafortunadamente","desgraciadamente","tristemente"],"a":0,"k":"감정 부사 어휘","t":"이 회사에서는 다행히 돈을 더 많이 번다.","e":"afortunadamente는 '다행히, 운 좋게'라는 뜻의 부사입니다. 돈을 더 번다는 것은 좋은 일이므로 긍정적인 부사가 와야 합니다. 형용사에 -mente를 붙이면 부사가 됩니다: afortunado(운 좋은) → afortunadamente(다행히).","x":["afortunadamente: 다행히, 좋은 일과 연결 → 정답 ✓","desafortunadamente: 불행히도로, 돈을 더 버는 것과 맞지 않습니다 ✗","desgraciadamente: 불행하게도로, 좋은 일과 맞지 않습니다 ✗","tristemente: 슬프게도로, 좋은 일과 맞지 않습니다 ✗"]},{"id":"V53","q":"El cepillo de barrer y el ____ están en ese cuarto.","o":["recogedor","computador","exprimidor","reloj"],"a":0,"k":"청소 도구 어휘","t":"빗자루와 쓰레받기는 저 방에 있다.","e":"recogedor는 '쓰레받기'입니다. recoger(줍다, 모으다)에서 나온 말로 쓸어 모은 먼지를 담는 도구입니다. cepillo de barrer(빗자루)와 짝을 이루는 청소 도구입니다. 빗자루는 escoba라고도 합니다.","x":["recogedor: 쓰레받기, 빗자루와 짝 → 정답 ✓","computador: 컴퓨터(중남미식)로, 청소 도구가 아닙니다 ✗","exprimidor: 착즙기(즙 짜는 도구)로, 청소 도구가 아닙니다 ✗","reloj: 시계로, 청소 도구가 아닙니다 ✗"]},{"id":"V54","q":"Aunque ya no somos pareja, todavía tenemos una buena ____.","o":["cantidad","especialidad","casualidad","amistad"],"a":3,"k":"인간관계 어휘","t":"우리는 더 이상 연인은 아니지만 여전히 좋은 친구 사이다.","e":"amistad는 '우정, 친구 관계'입니다. 연인(pareja)은 아니지만 좋은 관계를 유지한다는 의미이므로 amistad가 맞습니다. -dad로 끝나는 명사는 여성명사입니다(la amistad, la ciudad). aunque는 '~이지만'입니다.","x":["cantidad: 양, 수량으로, 관계를 나타내지 않습니다 ✗","especialidad: 전문, 특산품으로, 관계를 나타내지 않습니다 ✗","casualidad: 우연으로, 관계를 나타내지 않습니다 ✗","amistad: 우정, 친구 관계 → 정답 ✓"]},{"id":"V55","q":"En este armario no cabe casi nada, necesito uno más ____.","o":["grande","caro","barato","pequeño"],"a":0,"k":"크기 형용사","t":"이 옷장에는 거의 아무것도 안 들어가. 더 큰 게 필요해.","e":"옷장에 물건이 거의 안 들어간다는 것은 옷장이 작다는 뜻입니다. 그래서 '더 큰 것(uno más grande)'이 필요합니다. 'uno'는 앞의 armario(옷장)를 다시 가리키는 대명사입니다.","x":["grande: 큰, 더 많이 들어감 → 정답 ✓","caro: 비싼으로, 공간 문제의 해결이 아닙니다 ✗","barato: 싼으로, 공간 문제의 해결이 아닙니다 ✗","pequeño: 작은으로, 문제를 더 악화시킵니다 ✗"]},{"id":"V56","q":"Le ____ envidia porque es guapa, rica e inteligente.","o":["toman","hacen","ponen","tienen"],"a":3,"k":"tener envidia","t":"그녀는 예쁘고 부유하고 똑똑해서 사람들이 그녀를 질투한다.","e":"'tener envidia a + 사람'은 '~를 질투하다, 부러워하다'라는 표현입니다. 주어는 생략된 '사람들(ellos)'이고, 질투의 대상인 그녀는 간접목적격 le로 나타냅니다. tener와 함께 쓰는 감정 표현으로 tener miedo(무서워하다), tener celos(질투하다)도 있습니다.","x":["toman: tomar(잡다, 먹다)로, envidia와 함께 쓰지 않습니다 ✗","hacen: hacer(하다)로, envidia와 함께 쓰는 표현이 아닙니다 ✗","ponen: poner(놓다)로, envidia와 함께 쓰지 않습니다 ✗","tienen: tener(가지다), 'tener envidia'(질투하다) → 정답 ✓"]},{"id":"V57","q":"¡Qué bien canta Elena! Tiene una ____ preciosa.","o":["voz","cara","boca","nariz"],"a":0,"k":"신체 어휘","t":"엘레나는 노래를 정말 잘하네! 목소리가 너무 아름다워.","e":"voz는 '목소리'입니다. 노래를 잘한다는 칭찬 뒤이므로 목소리가 예쁘다는 말이 자연스럽습니다. voz는 여성명사이고 복수형은 z가 c로 바뀌어 voces가 됩니다.","x":["voz: 목소리, 노래와 연결 → 정답 ✓","cara: 얼굴로, 노래 실력과 관련이 없습니다 ✗","boca: 입으로, 노래 칭찬으로 어색합니다 ✗","nariz: 코로, 노래와 관련이 없습니다 ✗"]},{"id":"V58","q":"Estas tijeras no son adecuadas para ____ el pelo.","o":["lavar","cortar","alisar","rizar"],"a":1,"k":"미용 동사 어휘","t":"이 가위는 머리카락을 자르는 데 적합하지 않다.","e":"tijeras(가위)로 하는 일은 cortar(자르다)입니다. 'cortar el pelo'는 '머리카락을 자르다'입니다. 스페인어로 가위는 항상 복수형 tijeras로 씁니다. 'adecuado para + 동사원형'은 '~하기에 적합한'입니다.","x":["lavar: 씻다로, 가위로 하는 일이 아닙니다 ✗","cortar: 자르다, 가위로 하는 일 → 정답 ✓","alisar: (머리를) 펴다로, 가위로 하지 않습니다 ✗","rizar: (머리를) 곱슬하게 말다로, 가위로 하지 않습니다 ✗"]},{"id":"V59","q":"Le gusta mucho la música, por eso pasa horas y horas en la tienda de ____.","o":["bebidas","decoración","electrodomésticos","discos"],"a":3,"k":"가게 어휘","t":"그는 음악을 아주 좋아해서 음반 가게에서 몇 시간이고 보낸다.","e":"disco는 '음반, 레코드'입니다. 음악을 좋아해서 가는 가게이므로 'tienda de discos(음반 가게)'가 정답입니다. 'pasar horas y horas'는 '몇 시간이고 계속 보내다'라는 강조 표현입니다.","x":["bebidas: 음료로, 음악과 관련이 없습니다 ✗","decoración: 인테리어 소품으로, 음악과 관련이 없습니다 ✗","electrodomésticos: 가전제품으로, 음악과 직접 관련이 없습니다 ✗","discos: 음반, 음악과 연결 → 정답 ✓"]},{"id":"V60","q":"Eliana es una mujer ____ que siempre comparte lo que tiene.","o":["generosa","tonta","egoísta","cerrada"],"a":0,"k":"성격 형용사","t":"엘리아나는 가진 것을 늘 나누는 너그러운 여자다.","e":"generoso/a는 '너그러운, 인심 좋은'이라는 뜻입니다. 가진 것을 항상 나눈다(compartir)는 설명과 딱 맞습니다. 반대말은 egoísta(이기적인)입니다.","x":["generosa: 너그러운, 나누기를 좋아함 → 정답 ✓","tonta: 바보 같은으로, 나눔과 관련이 없습니다 ✗","egoísta: 이기적인으로, 나누는 성격과 반대입니다 ✗","cerrada: 폐쇄적인, 마음을 잘 안 여는으로, 문맥과 맞지 않습니다 ✗"]},{"id":"V61","q":"Disculpe, no veo ____ de esta camisa. ¿Puede decirme cuánto cuesta?","o":["la talla","el precio","el color","la tela"],"a":1,"k":"쇼핑 어휘","t":"실례합니다, 이 셔츠의 가격이 안 보이는데요. 얼마인지 알려 주실 수 있나요?","e":"precio는 '가격'입니다. 뒤에서 '얼마예요?(¿cuánto cuesta?)'라고 묻고 있으므로 안 보이는 것은 가격표입니다. 쇼핑할 때 '¿Cuál es el precio?'나 '¿Cuánto cuesta?'로 가격을 물어볼 수 있습니다.","x":["la talla: 옷 사이즈로, 얼마인지 묻는 것과 맞지 않습니다 ✗","el precio: 가격, 뒤의 ¿cuánto cuesta?와 연결 → 정답 ✓","el color: 색깔로, 눈으로 보면 알 수 있어 문맥과 맞지 않습니다 ✗","la tela: 옷감, 천으로, 가격 질문과 맞지 않습니다 ✗"]},{"id":"V62","q":"Durante aquel viaje perdí mi ____ fotográfica.","o":["cámara","lavadora","radio","televisión"],"a":0,"k":"전자기기 어휘","t":"그 여행 중에 나는 사진기를 잃어버렸다.","e":"'cámara fotográfica'는 '사진기, 카메라'입니다. fotográfica(사진의)와 어울리는 단어는 cámara뿐입니다. 'cámara de vídeo'는 비디오카메라입니다. 여행 중 잃어버릴 만한 휴대용 물건이라는 점도 힌트입니다.","x":["cámara: 카메라, 'cámara fotográfica'(사진기) → 정답 ✓","lavadora: 세탁기로, 여행에 가져가지 않습니다 ✗","radio: 라디오로, 'fotográfica'와 어울리지 않습니다 ✗","televisión: 텔레비전으로, 'fotográfica'와 어울리지 않습니다 ✗"]},{"id":"V63","q":"El padre de mi marido es mi ____.","o":["suegro","tío","primo","hijo"],"a":0,"k":"가족 어휘","t":"남편의 아버지는 나의 시아버지다.","e":"suegro는 배우자의 아버지, 즉 '시아버지·장인'입니다. 배우자의 어머니는 suegra(시어머니·장모)입니다. 한국어는 남편 쪽(시-)과 아내 쪽(장-)을 구분하지만 스페인어는 suegro 하나로 씁니다.","x":["suegro: 시아버지·장인(배우자의 아버지) → 정답 ✓","tío: 삼촌, 이모부 등으로, 부모의 형제입니다 ✗","primo: 사촌으로, 맞지 않습니다 ✗","hijo: 아들로, 맞지 않습니다 ✗"]},{"id":"V64","q":"Si no sabes lo que significa una palabra, puedes buscarla en el ____.","o":["lapicero","encerado","diccionario","mapa"],"a":2,"k":"학용품 어휘","t":"어떤 단어의 뜻을 모르면 사전에서 찾아볼 수 있다.","e":"diccionario는 '사전'입니다. 단어의 뜻(significado)을 찾는 곳이므로 diccionario가 정답입니다. 'buscar + 목적어 + en'은 '~에서 ~를 찾다'이고 buscarla의 la는 palabra(단어)를 가리킵니다.","x":["lapicero: 연필·펜(지역에 따라 다름)으로, 단어 뜻을 찾을 수 없습니다 ✗","encerado: 칠판(스페인 일부 지역)으로, 단어 뜻을 찾는 곳이 아닙니다 ✗","diccionario: 사전, 단어 뜻을 찾는 책 → 정답 ✓","mapa: 지도로, 단어 뜻과 관련이 없습니다 ✗"]},{"id":"V65","q":"Mis hijos gemelos tienen catorce años, es decir, son ____.","o":["ancianos","bebés","adolescentes","viejos"],"a":2,"k":"연령대 어휘","t":"우리 쌍둥이 아들들은 열네 살, 즉 청소년이다.","e":"adolescente는 '청소년, 사춘기 아이'로 보통 12~18세 정도를 말합니다. 14살이므로 adolescentes가 정답입니다. 'es decir'는 '즉, 다시 말해'라는 연결 표현입니다. gemelos는 '쌍둥이'입니다.","x":["ancianos: 노인들로, 14살과 맞지 않습니다 ✗","bebés: 아기들로, 14살과 맞지 않습니다 ✗","adolescentes: 청소년, 14살에 해당 → 정답 ✓","viejos: 늙은 사람들로, 14살과 맞지 않습니다 ✗"]},{"id":"V66","q":"¿Cuánto cuesta el ____ de tren de Málaga a Madrid?","o":["pasajero","billete","pasillo","vagón"],"a":1,"k":"교통 어휘","t":"말라가에서 마드리드까지 기차표는 얼마예요?","e":"billete는 스페인에서 '(교통) 표, 티켓'입니다. 'billete de tren'은 '기차표'입니다. 중남미에서는 같은 뜻으로 boleto를 주로 씁니다. billete는 '지폐'라는 뜻도 있습니다.","x":["pasajero: 승객으로, 가격을 묻는 대상이 아닙니다 ✗","billete: 표, 티켓(스페인식), 'billete de tren' → 정답 ✓","pasillo: 통로, 복도로, 가격을 묻지 않습니다 ✗","vagón: (기차의) 객차, 칸으로, 가격을 묻는 대상이 아닙니다 ✗"]},{"id":"V67","q":"A veces compro comida precocinada porque no tengo tiempo para ____.","o":["cocinar","barrer","planchar","limpiar"],"a":0,"k":"집안일 동사","t":"요리할 시간이 없어서 가끔 즉석식품을 산다.","e":"comida precocinada는 '미리 조리된 음식, 즉석식품'입니다. 이런 음식을 사는 이유는 요리할(cocinar) 시간이 없기 때문입니다. 'tener tiempo para + 동사원형'은 '~할 시간이 있다'입니다.","x":["cocinar: 요리하다, 즉석식품을 사는 이유 → 정답 ✓","barrer: 쓸다로, 음식과 관련이 없습니다 ✗","planchar: 다림질하다로, 음식과 관련이 없습니다 ✗","limpiar: 청소하다로, 음식과 관련이 없습니다 ✗"]},{"id":"V68","q":"Vamos a llegar ____ si seguimos en este atasco.","o":["rápido","pronto","tarde","antes"],"a":2,"k":"시간 부사","t":"이 교통 체증 속에 계속 있으면 우리는 늦게 도착할 거야.","e":"atasco는 '교통 체증'입니다. 차가 막히면 늦게(tarde) 도착하게 됩니다. 'llegar tarde'는 '늦게 도착하다, 지각하다'라는 자주 쓰는 표현입니다. 반대말은 'llegar pronto/temprano(일찍 도착하다)'입니다.","x":["rápido: 빨리로, 교통 체증과 반대입니다 ✗","pronto: 일찍, 곧으로, 교통 체증과 반대입니다 ✗","tarde: 늦게, 교통 체증의 결과 → 정답 ✓","antes: 더 먼저로, 교통 체증과 맞지 않습니다 ✗"]},{"id":"V69","q":"Mi abuela se quedó ____ muy joven y nunca volvió a casarse.","o":["sorprendida","viuda","parada","desempleada"],"a":1,"k":"결혼 상태 어휘","t":"우리 할머니는 아주 젊어서 과부가 되셨고 다시는 결혼하지 않으셨다.","e":"viuda는 '과부, 남편을 여읜 여자'입니다(남성형 viudo: 홀아비). 'quedarse + 형용사'는 '~한 상태가 되다'라는 뜻으로 'quedarse viuda'는 '과부가 되다'입니다. 다시 결혼하지 않았다는 말과 연결됩니다.","x":["sorprendida: 놀란으로, 결혼과 관련이 없습니다 ✗","viuda: 과부, 'quedarse viuda'(과부가 되다) → 정답 ✓","parada: 실직한(스페인 구어), 멈춘으로, 결혼과 연결되지 않습니다 ✗","desempleada: 실업 상태인으로, 결혼과 연결되지 않습니다 ✗"]},{"id":"V70","q":"Esa película es un ____. Me aburrí como una ostra.","o":["rollo","bollo","pollo","chollo"],"a":0,"k":"구어 표현 rollo","t":"그 영화는 지루하기 짝이 없어. 정말 따분했어.","e":"'ser un rollo'는 스페인 구어로 '지루한 것, 따분한 것'이라는 뜻입니다. 뒤에 나오는 'aburrirse como una ostra(굴처럼 지루해하다, 엄청 따분하다)'와 연결됩니다. 이 두 표현은 주로 스페인에서 쓰는 구어입니다.","x":["rollo: 지루한 것(스페인 구어) → 정답 ✓","bollo: 빵, 단과자로, 지루함과 관련이 없습니다 ✗","pollo: 닭, 닭고기로, 문맥과 맞지 않습니다 ✗","chollo: 싸고 좋은 물건, 횡재(스페인 구어)로, 지루함과 반대입니다 ✗"]},{"id":"V71","q":"Asia es un ____.","o":["continente","río","planeta","lago"],"a":0,"k":"지리 어휘","t":"아시아는 대륙이다.","e":"continente는 '대륙'입니다. 아시아(Asia)는 유럽(Europa), 아프리카(África), 아메리카(América), 오세아니아(Oceanía)와 같은 대륙입니다.","x":["continente: 대륙, 아시아는 대륙 → 정답 ✓","río: 강으로, 아시아가 아닙니다 ✗","planeta: 행성으로, 아시아가 아닙니다 ✗","lago: 호수로, 아시아가 아닙니다 ✗"]},{"id":"V72","q":"No bebo ____, prefiero beber agua y zumos naturales.","o":["macarrones","fideos","lentejas","refrescos"],"a":3,"k":"음료 어휘","t":"나는 탄산음료를 마시지 않고 물과 생과일 주스를 더 좋아한다.","e":"beber(마시다)의 목적어가 되려면 음료여야 합니다. refresco는 '청량음료, 탄산음료'로 콜라나 사이다 같은 것을 말합니다. 나머지 보기는 모두 먹는 음식입니다. zumo(주스)는 스페인에서 쓰고 중남미에서는 jugo를 씁니다.","x":["macarrones: 마카로니로, 마시는 것이 아닙니다 ✗","fideos: 국수, 면으로, 마시는 것이 아닙니다 ✗","lentejas: 렌틸콩으로, 마시는 것이 아닙니다 ✗","refrescos: 탄산음료, 마시는 것 → 정답 ✓"]},{"id":"V73","q":"Esta es una de las ciudades con mejor ____ de vida. Os recomiendo vivir aquí.","o":["especialidad","curiosidad","calidad","realidad"],"a":2,"k":"calidad de vida","t":"이곳은 삶의 질이 가장 좋은 도시 중 하나야. 너희에게 여기 살기를 추천해.","e":"'calidad de vida'는 '삶의 질'이라는 고정 표현입니다. calidad는 '질, 품질'이고 'mejor calidad de vida'는 '더 좋은 삶의 질'입니다. -dad로 끝나는 보기 중 vida와 어울리는 것은 calidad뿐입니다.","x":["especialidad: 전문 분야, 특산 요리로, vida와 어울리지 않습니다 ✗","curiosidad: 호기심으로, vida와 어울리지 않습니다 ✗","calidad: 질, 'calidad de vida'(삶의 질) → 정답 ✓","realidad: 현실로, vida와 고정 표현을 만들지 않습니다 ✗"]},{"id":"V74","q":"Hoy voy a ____ puré de patatas y pollo asado.","o":["tocar","comprobar","beber","almorzar"],"a":3,"k":"식사 동사","t":"오늘 나는 점심으로 감자 퓌레와 구운 닭고기를 먹을 거야.","e":"almorzar는 '점심을 먹다'입니다(일부 지역에서는 '오전 간식을 먹다'). 목적어로 음식이 오면 '점심으로 ~를 먹다'가 됩니다. 'ir a + 동사원형'은 가까운 미래(~할 것이다)를 나타냅니다. almorzar는 o→ue로 바뀌는 동사입니다(almuerzo).","x":["tocar: 만지다, 연주하다로, 음식에 쓰지 않습니다 ✗","comprobar: 확인하다로, 문맥과 맞지 않습니다 ✗","beber: 마시다로, 퓌레와 닭고기는 먹는 음식입니다 ✗","almorzar: 점심을 먹다 → 정답 ✓"]},{"id":"V75","q":"Aunque este edificio lleva siglos aquí, está en buen ____ de conservación.","o":["uso","estilo","estado","modo"],"a":2,"k":"estado de conservación","t":"이 건물은 수 세기 동안 여기 있었지만 보존 상태가 좋다.","e":"'estado de conservación'은 '보존 상태'라는 표현입니다. estado는 '상태'라는 뜻이고 'en buen estado'는 '좋은 상태로'입니다. 'llevar + 기간 + 장소'는 '~동안 ~에 있다'입니다.","x":["uso: 사용으로, 'buen uso'는 '올바른 사용'이라 문맥과 맞지 않습니다 ✗","estilo: 스타일, 양식으로, 'conservación'과 어울리지 않습니다 ✗","estado: 상태, 'en buen estado de conservación' → 정답 ✓","modo: 방식으로, 문맥과 맞지 않습니다 ✗"]},{"id":"V76","q":"El euro es la ____ de muchos países europeos.","o":["población","moneda","lengua","capital"],"a":1,"k":"화폐 어휘","t":"유로는 많은 유럽 국가의 화폐이다.","e":"moneda는 '화폐, 통화'입니다(동전이라는 뜻도 있습니다). 유로(euro)는 돈의 단위이므로 moneda가 정답입니다. 중남미의 화폐로는 peso(멕시코, 콜롬비아, 아르헨티나 등), sol(페루) 등이 있습니다.","x":["población: 인구로, 유로와 맞지 않습니다 ✗","moneda: 화폐, 통화, 유로는 화폐 → 정답 ✓","lengua: 언어로, 유로와 맞지 않습니다 ✗","capital: 수도로, 유로와 맞지 않습니다 ✗"]},{"id":"V77","q":"El ____ es una prenda interior femenina.","o":["sujetador","vestido","pijama","jersey"],"a":0,"k":"옷 어휘","t":"브래지어는 여성용 속옷이다.","e":"sujetador는 '브래지어'입니다. 'prenda interior'는 '속옷'이고 femenina는 '여성의'라는 뜻이므로 sujetador가 정답입니다. 중남미에서는 sostén, brasier 등으로 부르기도 합니다.","x":["sujetador: 브래지어, 여성 속옷 → 정답 ✓","vestido: 원피스로, 겉옷입니다 ✗","pijama: 잠옷으로, 속옷이 아닙니다 ✗","jersey: 스웨터(스페인식)로, 겉옷입니다 ✗"]},{"id":"V78","q":"¿Estás contento con tu ____? —No, gano poquísimo dinero.","o":["profesor","familia","sueldo","aspecto"],"a":2,"k":"일·급여 어휘","t":"네 월급에 만족해? —아니, 돈을 아주 조금 벌어.","e":"sueldo는 '월급, 급여'입니다. 대답에서 '돈을 아주 조금 번다(gano poquísimo dinero)'고 했으므로 질문은 급여에 관한 것입니다. poquísimo는 poco(적은)를 강조한 형태(아주 적은)입니다. 같은 뜻으로 salario도 씁니다.","x":["profesor: 선생님으로, 돈을 번다는 대답과 연결되지 않습니다 ✗","familia: 가족으로, 대답과 맞지 않습니다 ✗","sueldo: 월급, 대답과 연결 → 정답 ✓","aspecto: 외모, 측면으로, 대답과 맞지 않습니다 ✗"]},{"id":"V79","q":"¡Qué desordenado está este cuarto! ¿Me ayudas a ____?","o":["ensuciarlo","ventilarlo","ordenarlo","pintarlo"],"a":2,"k":"집안일 동사","t":"이 방 정말 어지럽네! 정리하는 것 좀 도와줄래?","e":"desordenado(어지러운)의 반대 행동은 ordenar(정리하다)입니다. ordenarlo의 lo는 cuarto(방)를 가리키는 직접목적격 대명사(~을/를)입니다. 동사원형 뒤에 대명사를 붙여 씁니다.","x":["ensuciarlo: 더럽히다로, 정리를 돕는 것과 반대입니다 ✗","ventilarlo: 환기하다로, 어지러운 방의 해결이 아닙니다 ✗","ordenarlo: 정리하다, desordenado의 해결 → 정답 ✓","pintarlo: 페인트칠하다로, 어지러운 방과 관련이 없습니다 ✗"]},{"id":"V80","q":"Dice que va a ____ a Jorge porque ya no está enamorada de él.","o":["amar","admirar","invitar","dejar"],"a":3,"k":"연애 관련 동사","t":"그녀는 이제 호르헤를 사랑하지 않아서 그와 헤어질 거라고 한다.","e":"dejar는 '두다, 남기다'라는 뜻이지만 사람을 목적어로 하면 '(연인과) 헤어지다, 차다'라는 뜻이 됩니다. 더 이상 사랑하지 않는다(ya no está enamorada)는 이유와 딱 맞습니다. 사람이 목적어라서 'a Jorge'처럼 a를 붙입니다.","x":["amar: 사랑하다로, 더 이상 사랑하지 않는다는 이유와 모순됩니다 ✗","admirar: 존경하다, 감탄하다로, 문맥과 맞지 않습니다 ✗","invitar: 초대하다로, 문맥과 맞지 않습니다 ✗","dejar: (연인과) 헤어지다 → 정답 ✓"]},{"id":"V81","q":"Nuestro hogar no está en el centro de la ciudad, está en las ____.","o":["calles","avenidas","carreteras","afueras"],"a":3,"k":"도시 공간 어휘","t":"우리 집은 시내 중심가가 아니라 교외에 있다.","e":"'las afueras'는 '교외, 도시 외곽'이라는 뜻으로 항상 복수형으로 씁니다. 중심(centro)이 아니라고 했으니 그 반대 개념인 afueras가 맞습니다. hogar는 '가정, 집'입니다.","x":["calles: 거리들로, 중심가와 대비되는 개념이 아닙니다 ✗","avenidas: 대로들로, 중심가와 대비되지 않습니다 ✗","carreteras: 도로, 고속도로로, 집이 있는 곳으로 어색합니다 ✗","afueras: 교외, 도시 외곽, centro의 반대 → 정답 ✓"]},{"id":"V82","q":"Mi esposo me regaló un ____ de oro.","o":["anillo","pañuelo","suéter","chaleco"],"a":0,"k":"액세서리 어휘","t":"남편이 나에게 금반지를 선물했다.","e":"anillo는 '반지'입니다. 'de oro'는 '금으로 된'이므로 금으로 만드는 물건이 와야 합니다. 보기 중 금으로 만드는 것은 반지뿐입니다. 결혼반지는 'anillo de boda' 또는 alianza라고 합니다.","x":["anillo: 반지, 'anillo de oro'(금반지) → 정답 ✓","pañuelo: 손수건, 스카프로, 보통 금으로 만들지 않습니다 ✗","suéter: 스웨터로, 금으로 만들지 않습니다 ✗","chaleco: 조끼로, 금으로 만들지 않습니다 ✗"]},{"id":"V83","q":"La harina está en la despensa, al lado del ____.","o":["detergente","jabón","gel","arroz"],"a":3,"k":"식료품 어휘","t":"밀가루는 식료품 저장고에, 쌀 옆에 있어.","e":"despensa는 '식료품 저장고(팬트리)'입니다. 밀가루(harina)와 함께 보관하는 식료품은 arroz(쌀)입니다. 나머지 보기는 세제와 비누 같은 청소·위생용품이라 식료품 옆에 두지 않습니다.","x":["detergente: 세제로, 식료품이 아닙니다 ✗","jabón: 비누로, 식료품이 아닙니다 ✗","gel: 샤워젤로, 식료품이 아닙니다 ✗","arroz: 쌀, 식료품 저장고에 있는 음식 → 정답 ✓"]},{"id":"V84","q":"Los hermanos de mis padres son mis ____.","o":["tíos","sobrinos","maridos","esposos"],"a":0,"k":"가족 어휘","t":"우리 부모님의 형제자매는 나의 삼촌·고모·이모 등이다.","e":"tío는 '삼촌, 고모부, 이모부' 등 부모의 형제이고 tía는 '고모, 이모'입니다. 남녀가 섞인 경우 남성 복수형 tíos로 씁니다. padres도 '아버지와 어머니'를 함께 가리키는 남성 복수입니다.","x":["tíos: 부모의 형제자매 → 정답 ✓","sobrinos: 조카들로, 나의 형제자매의 자녀입니다 ✗","maridos: 남편들로, 맞지 않습니다 ✗","esposos: 배우자들, 부부로, 맞지 않습니다 ✗"]},{"id":"V85","q":"Ir de ____ es una tradición española.","o":["viaje","tapas","compras","fiesta"],"a":1,"k":"ir de tapas","t":"타파스를 먹으러 다니는 것은 스페인의 전통이다.","e":"tapas는 술과 함께 먹는 작은 안주 요리입니다. 'ir de tapas'는 '여러 바를 돌며 타파스를 먹다'라는 스페인의 대표적인 문화입니다. 'ir de + 명사'는 활동을 나타냅니다: ir de compras(쇼핑하러 가다), ir de fiesta(파티하러 가다).","x":["viaje: 'ir de viaje'(여행 가다)로, 스페인만의 전통이 아닙니다 ✗","tapas: 'ir de tapas'(타파스 먹으러 다니기), 스페인 전통 → 정답 ✓","compras: 'ir de compras'(쇼핑하다)로, 스페인 고유 전통이 아닙니다 ✗","fiesta: 'ir de fiesta'(파티하러 가다)로, 스페인 고유 전통이라 하기 어렵습니다 ✗"]},{"id":"V86","q":"Este diccionario es muy ____. Puedo llevarlo a todas partes porque no pesa nada.","o":["antiguo","práctico","pesado","completo"],"a":1,"k":"물건 묘사 형용사","t":"이 사전은 아주 실용적이야. 무게가 하나도 안 나가서 어디든 가지고 다닐 수 있어.","e":"práctico는 '실용적인, 편리한'이라는 뜻입니다. 가볍고 어디든 들고 다닐 수 있다는 장점과 잘 맞습니다. 'no pesa nada'는 '전혀 무겁지 않다'이고, 'a todas partes'는 '어디든지'입니다.","x":["antiguo: 오래된으로, 가지고 다니기 편하다는 이유와 맞지 않습니다 ✗","práctico: 실용적인, 가볍고 편리함 → 정답 ✓","pesado: 무거운으로, 'no pesa nada'와 모순됩니다 ✗","completo: 내용이 완전한으로, 들고 다니기 편한 이유가 아닙니다 ✗"]},{"id":"V87","q":"Almudena trabaja como ____ en una tienda de ropa interior.","o":["ama de casa","dependienta","panadera","cocinera"],"a":1,"k":"직업 어휘","t":"알무데나는 속옷 가게에서 점원으로 일한다.","e":"dependiente/dependienta는 '(가게의) 점원, 판매원'입니다. 옷 가게(tienda de ropa)에서 일하는 사람이므로 dependienta가 맞습니다. 'trabajar como + 직업'은 '~로 일하다'입니다. 중남미에서는 vendedor/a라고도 합니다.","x":["ama de casa: 가정주부로, 가게에서 일하는 직업이 아닙니다 ✗","dependienta: 점원(여), 가게에서 일함 → 정답 ✓","panadera: 제빵사(여)로, 옷 가게와 맞지 않습니다 ✗","cocinera: 요리사(여)로, 옷 가게와 맞지 않습니다 ✗"]},{"id":"V88","q":"El ____ será rey en el futuro.","o":["capitán","príncipe","héroe","piloto"],"a":1,"k":"왕실 어휘","t":"왕자는 미래에 왕이 될 것이다.","e":"príncipe는 '왕자'입니다. 왕(rey)의 자리를 이어받는 사람은 왕자입니다. será는 ser의 미래형(~이 될 것이다)입니다. 여성형은 princesa(공주)입니다.","x":["capitán: 선장, 대위, 주장으로, 왕이 될 사람이 아닙니다 ✗","príncipe: 왕자, 미래의 왕 → 정답 ✓","héroe: 영웅으로, 왕위와 관련이 없습니다 ✗","piloto: 조종사로, 왕위와 관련이 없습니다 ✗"]},{"id":"V89","q":"No tengo ____ porque acabo de cenar.","o":["apetito","prisa","tiempo","frío"],"a":0,"k":"tener 표현","t":"방금 저녁을 먹어서 입맛이 없어.","e":"apetito는 '식욕, 입맛'입니다. 방금 저녁을 먹었다(acabo de cenar)는 이유로 '입맛이 없다(no tengo apetito)'가 자연스럽습니다. 'acabar de + 동사원형'은 '방금 ~했다'라는 표현입니다.","x":["apetito: 식욕, 방금 먹어서 없음 → 정답 ✓","prisa: 서두름으로, 저녁을 먹은 것과 이유가 맞지 않습니다 ✗","tiempo: 시간으로, 저녁을 먹은 것이 시간 없는 이유가 아닙니다 ✗","frío: 추위로, 식사와 관련이 없습니다 ✗"]},{"id":"V90","q":"¿Qué día es hoy? — ____.","o":["Martes","Veinte grados","Diez dólares","Las doce"],"a":0,"k":"요일 묻기","t":"오늘 무슨 요일이야? —화요일.","e":"'¿Qué día es hoy?'는 '오늘 무슨 요일(며칠)이야?'라는 질문입니다. 대답으로는 요일이나 날짜가 옵니다. martes는 '화요일'입니다. 스페인어 요일은 lunes, martes, miércoles, jueves, viernes, sábado, domingo이며 소문자로 씁니다(여기서는 문장 첫머리라 대문자).","x":["Martes: 화요일, 요일을 묻는 질문의 대답 → 정답 ✓","Veinte grados: 20도로, 온도에 대한 대답입니다 ✗","Diez dólares: 10달러로, 가격에 대한 대답입니다 ✗","Las doce: 12시로, 시간에 대한 대답입니다 ✗"]},{"id":"V91","q":"Estoy ____ a este horario de trabajo. No quiero cambiarlo.","o":["acostumbrado","obligado","desacostumbrado","invitado"],"a":0,"k":"estar acostumbrado","t":"나는 이 근무 시간에 익숙해. 바꾸고 싶지 않아.","e":"'estar acostumbrado a + 명사/동사원형'은 '~에 익숙하다'라는 표현입니다. 바꾸고 싶지 않다(No quiero cambiarlo)는 말에서 이 근무 시간에 익숙하고 만족한다는 것을 알 수 있습니다. 예: Estoy acostumbrada a madrugar.(나는 일찍 일어나는 데 익숙해.)","x":["acostumbrado: 익숙한, 바꾸고 싶지 않은 이유 → 정답 ✓","obligado: 억지로 하게 된으로, 바꾸고 싶지 않다는 말과 어울리지 않습니다 ✗","desacostumbrado: 익숙하지 않은으로, 바꾸고 싶지 않다는 말과 반대입니다 ✗","invitado: 초대받은으로, 근무 시간과 맞지 않습니다 ✗"]},{"id":"V92","q":"Aquí antes vivía mucha gente, pero ahora es simplemente un pueblo ____.","o":["bien comunicado","cercano","abandonado","alejado"],"a":2,"k":"마을 묘사 형용사","t":"예전에 여기에는 많은 사람이 살았지만 지금은 그저 버려진 마을일 뿐이다.","e":"abandonado는 '버려진, 사람이 떠난'이라는 뜻입니다. 예전에는 사람이 많이 살았지만(antes) 지금은(ahora) 그렇지 않다는 대비가 있으므로 abandonado가 정답입니다. 스페인에는 이런 '빈 마을(pueblos abandonados)'이 많습니다.","x":["bien comunicado: 교통이 편리한으로, 사람이 떠난 상황과 맞지 않습니다 ✗","cercano: 가까운으로, 대비가 되지 않습니다 ✗","abandonado: 버려진, 사람이 떠난 → 정답 ✓","alejado: 멀리 떨어진으로, 사람이 많이 살았다는 대비와 직접 연결되지 않습니다 ✗"]},{"id":"V93","q":"Carolina Herrera es una conocida ____ de moda.","o":["inventora","jefa","espectadora","diseñadora"],"a":3,"k":"직업 어휘","t":"카롤리나 에레라는 유명한 패션 디자이너다.","e":"diseñador/diseñadora는 '디자이너'입니다. 'diseñadora de moda'는 '패션 디자이너'입니다. 카롤리나 에레라는 베네수엘라 출신의 유명한 패션 디자이너입니다. diseñar(디자인하다)에서 나온 단어입니다.","x":["inventora: 발명가(여)로, 패션과 맞지 않습니다 ✗","jefa: 상사, 우두머리(여)로, 'de moda'와 어울리지 않습니다 ✗","espectadora: 관객(여)으로, 문맥과 맞지 않습니다 ✗","diseñadora: 디자이너(여), 'diseñadora de moda' → 정답 ✓"]},{"id":"V94","q":"____ compro ropa por internet porque necesito probármela antes.","o":["A menudo","Nunca","Siempre","Con frecuencia"],"a":1,"k":"빈도 부사","t":"옷은 먼저 입어 봐야 해서 나는 인터넷으로 옷을 절대 사지 않는다.","e":"nunca는 '절대 ~하지 않다, 한 번도 ~않다'입니다. 미리 입어 봐야 한다(probármela antes)는 이유 때문에 인터넷으로는 사지 않는다는 뜻이 됩니다. nunca가 동사 앞에 오면 no를 따로 쓰지 않습니다.","x":["A menudo: 자주로, 입어 봐야 한다는 이유와 모순됩니다 ✗","Nunca: 절대 ~않다, 입어 봐야 해서 안 삼 → 정답 ✓","Siempre: 항상으로, 이유와 모순됩니다 ✗","Con frecuencia: 자주로, 이유와 모순됩니다 ✗"]},{"id":"V95","q":"Sabe tocar el piano muy bien porque estudió varios años en un ____.","o":["teatro","observatorio","conservatorio","museo"],"a":2,"k":"음악 교육 장소","t":"그는 음악원에서 몇 년 공부해서 피아노를 아주 잘 친다.","e":"conservatorio는 '음악원, 음악 학교'입니다. 피아노를 배우는 곳이므로 conservatorio가 정답입니다. 'tocar el piano'는 '피아노를 치다'로, 악기 연주에는 tocar를 씁니다. observatorio(천문대)와 생김새가 비슷하니 주의하세요.","x":["teatro: 극장으로, 공부하는 곳이 아닙니다 ✗","observatorio: 천문대, 관측소로, 피아노와 관련이 없습니다 ✗","conservatorio: 음악원, 피아노를 배우는 곳 → 정답 ✓","museo: 박물관, 미술관으로, 피아노를 배우는 곳이 아닙니다 ✗"]},{"id":"V96","q":"No quiero ir sola al evento. ¿Me ____?","o":["visitas","esperas","acompañas","atiendes"],"a":2,"k":"부탁하기 acompañar","t":"행사에 혼자 가고 싶지 않아. 나랑 같이 가 줄래?","e":"acompañar는 '동행하다, 같이 가 주다'입니다. 혼자(sola) 가고 싶지 않다고 했으므로 같이 가 달라는 부탁이 자연스럽습니다. '¿Me acompañas?'는 '나랑 같이 가 줄래?'라는 아주 자주 쓰는 표현입니다.","x":["visitas: visitar(방문하다)로, 혼자 가기 싫다는 말과 맞지 않습니다 ✗","esperas: esperar(기다리다)로, 같이 가는 것이 아닙니다 ✗","acompañas: acompañar(같이 가 주다) → 정답 ✓","atiendes: atender(응대하다, 돌보다)로, 문맥과 맞지 않습니다 ✗"]},{"id":"V97","q":"Gritar a una persona es una ____ de respeto.","o":["señal","causa","falta","muestra"],"a":2,"k":"falta de respeto","t":"사람에게 소리 지르는 것은 무례한 행동(존중의 부족)이다.","e":"'falta de respeto'는 '존중이 없음, 무례'라는 고정 표현입니다. falta는 '부족, 결여'입니다. 'muestra de respeto'는 반대로 '존중의 표시'라서 소리 지르기와 맞지 않습니다. 예: Llegar tarde es una falta de respeto.(늦게 오는 것은 무례한 일이다.)","x":["señal: 신호, 표시로, 'señal de respeto'는 존중의 표시라 반대 의미입니다 ✗","causa: 원인으로, 문맥과 맞지 않습니다 ✗","falta: 부족, 'falta de respeto'(무례) → 정답 ✓","muestra: 표시, 'muestra de respeto'는 존중의 표시라 반대 의미입니다 ✗"]},{"id":"V98","q":"El queso es un producto ____.","o":["cárnico","vegetal","dulce","lácteo"],"a":3,"k":"식품 분류 어휘","t":"치즈는 유제품이다.","e":"lácteo는 '우유의, 유제품의'라는 뜻입니다. 치즈(queso)는 우유로 만들므로 'producto lácteo(유제품)'입니다. 우유는 leche, 요구르트는 yogur입니다.","x":["cárnico: 고기의, 육류의로, 치즈와 맞지 않습니다 ✗","vegetal: 식물성의로, 치즈는 동물성입니다 ✗","dulce: 단, 달콤한으로, 치즈의 분류가 아닙니다 ✗","lácteo: 유제품의, 치즈는 우유로 만듦 → 정답 ✓"]},{"id":"V99","q":"La figura principal de un ____ es el alcalde o la alcaldesa.","o":["hospital","bufete","ayuntamiento","centro comercial"],"a":2,"k":"공공기관 어휘","t":"시청의 최고 책임자는 시장이다.","e":"ayuntamiento는 '시청, 시의회'입니다. 그곳의 대표는 alcalde(시장, 남)/alcaldesa(시장, 여)입니다. 중남미에서는 시청을 municipalidad, alcaldía라고도 부릅니다.","x":["hospital: 병원으로, 시장이 이끄는 곳이 아닙니다 ✗","bufete: 법률 사무소로, 시장이 이끄는 곳이 아닙니다 ✗","ayuntamiento: 시청, 시장이 대표 → 정답 ✓","centro comercial: 쇼핑센터로, 시장이 이끄는 곳이 아닙니다 ✗"]},{"id":"V100","q":"¡Qué ____ está esta comida! Cocinas muy bien.","o":["rica","bonita","mala","hermosa"],"a":0,"k":"맛 형용사","t":"이 음식 정말 맛있다! 너 요리 진짜 잘한다.","e":"rico/rica는 '부유한'이라는 뜻도 있지만 음식에 쓰면 '맛있는'이라는 뜻입니다. 'estar rico'는 음식을 먹고 맛을 평가할 때 씁니다. comida가 여성명사라서 rica가 됩니다. 같은 뜻으로 'está delicioso/buenísimo'도 씁니다.","x":["rica: 맛있는(음식에 쓸 때) → 정답 ✓","bonita: 예쁜으로, 음식 맛을 칭찬할 때 쓰지 않습니다 ✗","mala: 맛없는, 나쁜으로, '요리 잘한다'는 칭찬과 모순됩니다 ✗","hermosa: 아름다운으로, 음식 맛에 쓰지 않습니다 ✗"]},{"id":"V101","q":"Los ____ de mi madre son mis tíos.","o":["hermanos","nietos","padres","primos"],"a":0,"k":"가족 어휘","t":"우리 어머니의 형제자매는 나의 외삼촌·이모다.","e":"어머니의 hermanos(형제자매)는 나에게 tíos(외삼촌, 이모)가 됩니다. 앞의 V84 문제와 같은 관계를 반대 방향으로 묻는 문제입니다. 남녀를 함께 말할 때 남성 복수형 hermanos를 씁니다.","x":["hermanos: 형제자매, 어머니의 형제자매는 나의 tíos → 정답 ✓","nietos: 손주들로, 어머니의 손주는 나 또는 내 형제의 자녀입니다 ✗","padres: 부모로, 어머니의 부모는 나의 조부모(abuelos)입니다 ✗","primos: 사촌으로, 어머니의 사촌은 나의 tíos가 아닙니다 ✗"]},{"id":"V102","q":"Este programa de radio tiene miles de ____.","o":["oyentes","observadores","asistentes","espectadores"],"a":0,"k":"방송 관련 어휘","t":"이 라디오 프로그램은 청취자가 수천 명이다.","e":"oyente는 '청취자, 듣는 사람'으로 oír(듣다)에서 나온 말입니다. 라디오는 듣는 매체이므로 oyentes가 정답입니다. TV나 영화를 보는 사람은 espectador/televidente라고 합니다. 'miles de'는 '수천의'입니다.","x":["oyentes: 청취자, 라디오를 듣는 사람 → 정답 ✓","observadores: 관찰자로, 라디오와 맞지 않습니다 ✗","asistentes: 참석자, 조수로, 라디오 청취자가 아닙니다 ✗","espectadores: 관객, 시청자로, 보는 사람이라 라디오와 맞지 않습니다 ✗"]},{"id":"V103","q":"Creo que tengo gripe. Tengo los ____ típicos.","o":["sentimientos","resultados","pensamientos","síntomas"],"a":3,"k":"건강 어휘","t":"나 독감에 걸린 것 같아. 전형적인 증상이 있어.","e":"síntoma는 '증상'입니다. 독감(gripe)의 열, 기침 같은 것을 말하므로 síntomas가 맞습니다. síntoma는 -a로 끝나지만 남성명사(el síntoma)라서 'los síntomas típicos'가 됩니다.","x":["sentimientos: 감정, 느낌으로, 병의 증상이 아닙니다 ✗","resultados: 결과로, 문맥상 어색합니다 ✗","pensamientos: 생각으로, 병과 관련이 없습니다 ✗","síntomas: 증상(남성명사), 독감과 연결 → 정답 ✓"]},{"id":"V104","q":"Me encantan las ____ de arena blanca y agua turquesa.","o":["plantas","montañas","playas","flores"],"a":2,"k":"자연·지형 어휘","t":"나는 하얀 모래와 청록색 바다가 있는 해변을 정말 좋아한다.","e":"playa는 '해변, 바닷가'입니다. 'arena blanca(하얀 모래)'와 'agua turquesa(청록색 물)'는 해변을 묘사하는 말입니다. 'me encantan + 복수명사'는 '~을 정말 좋아한다'이며 좋아하는 대상이 복수라서 encantan이 됩니다.","x":["plantas: 식물로, 모래와 바다가 있지 않습니다 ✗","montañas: 산으로, 바다와 모래와 맞지 않습니다 ✗","playas: 해변, 모래와 바다 → 정답 ✓","flores: 꽃으로, 모래와 바다와 맞지 않습니다 ✗"]},{"id":"V105","q":"¿Podrías recoger la ropa del ____?","o":["espejo","tendedero","horno","frigorífico"],"a":1,"k":"집안 물건 어휘","t":"빨래 건조대에서 옷 좀 걷어 줄래?","e":"tendedero는 '빨래 건조대, 빨랫줄'입니다. 마른 빨래를 걷는(recoger la ropa) 곳이므로 tendedero가 정답입니다. 'tender la ropa'는 '빨래를 널다'입니다. '¿Podrías~?'는 poder의 가정형으로 정중한 부탁(~해 줄 수 있어?)입니다.","x":["espejo: 거울로, 옷을 걷는 곳이 아닙니다 ✗","tendedero: 빨래 건조대, 옷을 널고 걷는 곳 → 정답 ✓","horno: 오븐으로, 옷과 관련이 없습니다 ✗","frigorífico: 냉장고로, 옷과 관련이 없습니다 ✗"]},{"id":"V106","q":"No veo bien de lejos, por eso uso ____.","o":["gafas","calcetines","guantes","bermudas"],"a":0,"k":"착용 물건 어휘","t":"나는 멀리 있는 것이 잘 안 보여서 안경을 쓴다.","e":"gafas는 스페인에서 '안경'이라는 뜻이고 항상 복수형으로 씁니다. 'ver bien de lejos'는 '멀리 있는 것을 잘 보다'입니다. 중남미에서는 안경을 lentes 또는 anteojos라고 많이 부릅니다.","x":["gafas: 안경, 잘 안 보일 때 씀 → 정답 ✓","calcetines: 양말로, 시력과 관련이 없습니다 ✗","guantes: 장갑으로, 시력과 관련이 없습니다 ✗","bermudas: 반바지로, 시력과 관련이 없습니다 ✗"]},{"id":"V107","q":"Actualmente, todos los teléfonos móviles tienen ____.","o":["bolsa","cámara","bolígrafo","lápiz"],"a":1,"k":"전자기기 어휘","t":"요즘은 모든 휴대폰에 카메라가 있다.","e":"cámara는 '카메라'입니다. 휴대폰(teléfono móvil)에 기본으로 달려 있는 기능입니다. actualmente는 '현재, 요즘'이라는 뜻으로, 영어 actually(사실은)와 뜻이 다르니 주의하세요. 중남미에서는 휴대폰을 celular라고 합니다.","x":["bolsa: 봉지, 가방으로, 휴대폰에 없습니다 ✗","cámara: 카메라, 휴대폰 기능 → 정답 ✓","bolígrafo: 볼펜으로, 휴대폰에 없습니다 ✗","lápiz: 연필로, 휴대폰에 없습니다 ✗"]},{"id":"V108","q":"Disculpe, ¿puede decirme cómo ____ al centro de la ciudad?","o":["traer","tardar","llegar","llevar"],"a":2,"k":"길 묻기 llegar","t":"실례합니다, 시내 중심가에 어떻게 가는지 알려 주실 수 있나요?","e":"'¿Cómo llego a~?'나 '¿cómo llegar a~?'는 '~에 어떻게 가나요?'라는 길 묻기 표현입니다. llegar는 '도착하다'이고 목적지 앞에 a를 씁니다. 'al centro'는 a + el이 합쳐진 형태입니다.","x":["traer: 가져오다로, 길을 묻는 표현이 아닙니다 ✗","tardar: (시간이) 걸리다로, 'cuánto tardar'처럼 써야 합니다 ✗","llegar: 도착하다, '¿cómo llegar a~?'(~에 어떻게 가나요) → 정답 ✓","llevar: 가져가다, 데려가다로, 목적어가 필요해 문장이 맞지 않습니다 ✗"]},{"id":"V109","q":"Una de las características de un buen profesor es la ____.","o":["incomprensión","paciencia","antipatía","timidez"],"a":1,"k":"성격 명사","t":"좋은 선생님의 특징 중 하나는 인내심이다.","e":"paciencia는 '인내심, 참을성'입니다. 좋은 선생님에게 필요한 긍정적인 자질이므로 paciencia가 정답입니다. 나머지 보기는 모두 부정적이거나 선생님의 장점이 아닙니다. 형용사는 paciente(참을성 있는)입니다.","x":["incomprensión: 이해 부족으로, 좋은 선생님의 특징이 아닙니다 ✗","paciencia: 인내심, 좋은 선생님의 자질 → 정답 ✓","antipatía: 반감, 불친절함으로, 장점이 아닙니다 ✗","timidez: 수줍음으로, 선생님의 대표적 장점이 아닙니다 ✗"]},{"id":"V110","q":"No te tomes la sopa todavía, se tiene que ____ un poco.","o":["congelar","enfriar","cortar","freír"],"a":1,"k":"요리 동사","t":"수프 아직 먹지 마. 조금 식어야 해.","e":"enfriar는 '식히다'이고 enfriarse는 '식다'입니다. 'se tiene que enfriar'는 '식어야 한다'라는 뜻으로, 수프가 뜨거우니 기다리라는 상황입니다. frío(차가운)에서 나온 말입니다.","x":["congelar: 얼리다로, 먹기 전에 기다리는 이유가 아닙니다 ✗","enfriar: 식다(식히다), 뜨거운 수프 → 정답 ✓","cortar: 자르다로, 수프에 쓰지 않습니다 ✗","freír: 튀기다로, 수프와 맞지 않습니다 ✗"]},{"id":"V111","q":"En una docena hay ____ unidades.","o":["once","doce","dos","diez"],"a":1,"k":"수량 어휘","t":"한 다스에는 열두 개가 있다.","e":"docena는 '다스, 12개 묶음'입니다. 그래서 doce(12)가 정답입니다. 달걀을 살 때 'una docena de huevos(달걀 한 판/12개)'처럼 자주 씁니다. 'media docena'는 '반 다스(6개)'입니다.","x":["once: 11로, 다스가 아닙니다 ✗","doce: 12, docena(다스)는 12개 → 정답 ✓","dos: 2로, 다스가 아닙니다 ✗","diez: 10으로, 다스가 아닙니다 ✗"]},{"id":"V112","q":"Esta novela ____ la vida de un famoso inventor.","o":["narra","calcula","compone","canta"],"a":0,"k":"이야기 동사","t":"이 소설은 한 유명한 발명가의 삶을 이야기한다.","e":"narrar는 '이야기하다, 서술하다'입니다. 소설(novela)이 누군가의 삶을 들려준다는 의미이므로 narra가 맞습니다. narrador(화자, 내레이터)도 같은 어원입니다.","x":["narra: narrar(이야기하다)의 3인칭 단수 → 정답 ✓","calcula: calcular(계산하다)로, 소설과 맞지 않습니다 ✗","compone: componer(작곡하다, 구성하다)로, 삶을 들려주는 뜻이 아닙니다 ✗","canta: cantar(노래하다)로, 소설과 맞지 않습니다 ✗"]},{"id":"V113","q":"En mi ____ hay dos lápices, un bolígrafo, una goma y un sacapuntas.","o":["estuche","joyero","vaso","monedero"],"a":0,"k":"학용품 어휘","t":"내 필통에는 연필 두 자루, 볼펜 하나, 지우개 하나, 연필깎이 하나가 있다.","e":"estuche는 '필통'입니다. 연필(lápices), 볼펜(bolígrafo), 지우개(goma), 연필깎이(sacapuntas)를 넣는 곳이므로 estuche가 정답입니다. estuche는 원래 '케이스, 상자'라는 뜻으로 안경집(estuche de gafas)에도 씁니다.","x":["estuche: 필통, 학용품을 넣음 → 정답 ✓","joyero: 보석함으로, 학용품을 넣지 않습니다 ✗","vaso: 컵으로, 학용품을 넣는 곳이 아닙니다 ✗","monedero: 동전 지갑으로, 학용품을 넣지 않습니다 ✗"]},{"id":"V114","q":"Un poco de silencio; vuestro padre está ____.","o":["vistiéndose","durmiendo","sonriendo","cocinando"],"a":1,"k":"현재진행형","t":"좀 조용히 해. 너희 아빠 주무시고 계셔.","e":"'estar + 현재분사(-ando/-iendo)'는 '~하고 있다'(현재진행형)입니다. 조용히 하라는 이유로 가장 자연스러운 것은 아빠가 자고 있다(durmiendo)는 것입니다. dormir의 현재분사는 o가 u로 바뀌어 durmiendo가 됩니다.","x":["vistiéndose: 옷을 입고 있는으로, 조용히 해야 할 이유가 아닙니다 ✗","durmiendo: 자고 있는(dormir 현재분사), 조용히 해야 할 이유 → 정답 ✓","sonriendo: 미소 짓고 있는으로, 조용히 해야 할 이유가 아닙니다 ✗","cocinando: 요리하고 있는으로, 조용히 해야 할 이유가 아닙니다 ✗"]},{"id":"V115","q":"Van a bautizar a su hijo en esta ____.","o":["academia","escuela","iglesia","plaza"],"a":2,"k":"종교 장소 어휘","t":"그들은 이 성당에서 아들에게 세례를 줄 것이다.","e":"bautizar는 '세례를 주다'라는 종교 의식입니다. 세례는 보통 iglesia(교회, 성당)에서 하므로 iglesia가 정답입니다. bautizo는 '세례식'입니다.","x":["academia: 학원으로, 세례를 하지 않습니다 ✗","escuela: 학교로, 세례를 하지 않습니다 ✗","iglesia: 성당, 교회, 세례를 하는 곳 → 정답 ✓","plaza: 광장으로, 세례를 하는 곳이 아닙니다 ✗"]},{"id":"V116","q":"Ana tuvo un accidente, por eso está en el ____.","o":["hospital","centro comercial","colegio","parque"],"a":0,"k":"장소 어휘","t":"아나는 사고가 나서 병원에 있다.","e":"hospital은 '병원'입니다. 사고(accidente)를 당하면 병원에 가므로 hospital이 정답입니다. 'estar en + 장소'는 '~에 있다'입니다. 스페인어 hospital의 h는 소리 나지 않습니다(오스피탈).","x":["hospital: 병원, 사고 후 가는 곳 → 정답 ✓","centro comercial: 쇼핑센터로, 사고와 관련이 없습니다 ✗","colegio: 학교로, 사고 때문에 있는 곳이 아닙니다 ✗","parque: 공원으로, 사고 때문에 있는 곳이 아닙니다 ✗"]},{"id":"V117","q":"Debemos ____ las manos antes de comer.","o":["lavarnos","bañarnos","secarnos","mojarnos"],"a":0,"k":"재귀동사 어휘","t":"우리는 밥 먹기 전에 손을 씻어야 한다.","e":"'lavarse las manos'는 '손을 씻다'입니다. 자기 몸을 씻을 때는 재귀동사(자기 자신에게 하는 동작) lavarse를 쓰고, 신체 부위 앞에는 소유사 대신 정관사 las를 씁니다. 주어가 nosotros라서 lavarnos가 됩니다.","x":["lavarnos: 씻다(우리 자신의 손을), 식사 전 위생 → 정답 ✓","bañarnos: 목욕하다로, 손에만 쓰지 않습니다 ✗","secarnos: 말리다로, 식사 전에 하는 기본 행동은 씻기입니다 ✗","mojarnos: 적시다로, 식사 전 위생 행동이 아닙니다 ✗"]},{"id":"V118","q":"¿Ya estáis ____? ¿Por qué no dormís un poco más?","o":["acostados","despiertos","sorprendidos","aburridos"],"a":1,"k":"상태 형용사","t":"벌써 깼니? 왜 좀 더 자지 않니?","e":"despierto는 '깨어 있는'이라는 뜻입니다. '좀 더 자지 않니?'라고 묻는 걸 보면 상대가 이미 일어나 있다는 뜻이므로 despiertos가 정답입니다. estáis/dormís는 vosotros 형태로 스페인에서 씁니다(중남미: están/duermen).","x":["acostados: 누워 있는으로, '좀 더 자라'는 말과 맞지 않습니다 ✗","despiertos: 깨어 있는, 좀 더 자라는 말과 연결 → 정답 ✓","sorprendidos: 놀란으로, 잠과 관련이 없습니다 ✗","aburridos: 지루한으로, 잠과 직접 관련이 없습니다 ✗"]},{"id":"V119","q":"José toca la guitarra y el ____.","o":["piano","tenis","béisbol","golf"],"a":0,"k":"악기 어휘","t":"호세는 기타와 피아노를 친다.","e":"tocar는 악기를 '연주하다'라는 뜻입니다. 기타(guitarra)와 함께 연주하는 악기는 piano입니다. 운동은 tocar가 아니라 jugar(al tenis, al golf)를 씁니다.","x":["piano: 피아노, tocar(연주하다)와 어울림 → 정답 ✓","tenis: 테니스로, 운동은 jugar를 씁니다 ✗","béisbol: 야구로, 운동은 jugar를 씁니다 ✗","golf: 골프로, 운동은 jugar를 씁니다 ✗"]},{"id":"V120","q":"No podemos comprar una casa porque los ____ son muy altos.","o":["premios","bloques","precios","edificios"],"a":2,"k":"가격 어휘","t":"가격이 너무 높아서 우리는 집을 살 수 없다.","e":"precio는 '가격'입니다. 집을 못 사는 이유로 '가격이 비싸다(los precios son muy altos)'가 자연스럽습니다. 가격이 높다/낮다는 alto/bajo로 표현합니다.","x":["premios: 상, 상금으로, 집을 못 사는 이유가 아닙니다 ✗","bloques: 블록, 건물 동으로, 문맥과 맞지 않습니다 ✗","precios: 가격, 가격이 비싸서 못 삼 → 정답 ✓","edificios: 건물로, '높다'는 말과 어울리지만 못 사는 이유가 되지 않습니다 ✗"]},{"id":"V121","q":"Juan me hace ____ mal con sus comentarios irónicos.","o":["saber","ver","decir","sentir"],"a":3,"k":"hacer + 동사원형","t":"후안은 비꼬는 말로 나를 기분 나쁘게 만든다.","e":"'hacer + 동사원형'은 '(누군가에게) ~하게 만들다'라는 사역 표현입니다. 'sentirse mal'은 '기분이 나쁘다'이므로 'me hace sentir mal'은 '나를 기분 나쁘게 만든다'가 됩니다. 예: Esta canción me hace sentir feliz.(이 노래는 나를 행복하게 해.)","x":["saber: 알다로, 'hacer saber'는 '알리다'라서 mal과 어울리지 않습니다 ✗","ver: 보다로, 'hacer ver mal'은 의미가 통하지 않습니다 ✗","decir: 말하다로, 'hacer decir mal'은 문맥과 맞지 않습니다 ✗","sentir: 느끼다, 'hacer sentir mal'(기분 나쁘게 하다) → 정답 ✓"]},{"id":"V122","q":"No sé ____, pero el año que viene quiero sacarme el carné.","o":["pintar","conducir","nadar","dibujar"],"a":1,"k":"운전 관련 어휘","t":"나는 운전할 줄 모르지만, 내년에 면허를 따고 싶다.","e":"conducir는 '운전하다'입니다(중남미에서는 manejar를 많이 씁니다). 'sacarse el carné (de conducir)'는 '운전면허를 따다'라는 뜻이므로 운전과 연결됩니다. 'saber + 동사원형'은 '~할 줄 알다'입니다.","x":["pintar: 그림 그리다, 칠하다로, 면허와 관련이 없습니다 ✗","conducir: 운전하다, 면허(carné)와 연결 → 정답 ✓","nadar: 수영하다로, 면허와 관련이 없습니다 ✗","dibujar: (선으로) 그리다로, 면허와 관련이 없습니다 ✗"]},{"id":"V123","q":"Tristemente, hay algunos animales en ____ de extinción.","o":["evento","caso","episodio","peligro"],"a":3,"k":"peligro de extinción","t":"슬프게도 멸종 위기에 처한 동물들이 있다.","e":"'en peligro de extinción'은 '멸종 위기에 처한'이라는 고정 표현입니다. peligro는 '위험'이고 extinción은 '멸종'입니다. 환경이나 동물 이야기에서 아주 자주 나오는 표현입니다.","x":["evento: 행사, 이벤트로, 고정 표현을 만들지 않습니다 ✗","caso: 경우로, 'en caso de'는 '~의 경우에'라서 의미가 맞지 않습니다 ✗","episodio: 에피소드, 일화로, 문맥과 맞지 않습니다 ✗","peligro: 위험, 'en peligro de extinción'(멸종 위기) → 정답 ✓"]},{"id":"V124","q":"Si no puedes salir, este supermercado te ____ la compra a casa.","o":["conecta","regala","tira","lleva"],"a":3,"k":"배달 동사","t":"외출할 수 없으면, 이 슈퍼마켓이 장 본 것을 집까지 가져다준다.","e":"llevar는 '가져가다, 가져다주다'입니다. 'llevar la compra a casa'는 '장 본 물건을 집으로 배달하다'라는 뜻입니다. la compra는 '장보기, 산 물건'입니다. te는 '너에게'라는 간접목적격입니다.","x":["conecta: conectar(연결하다)로, 문맥과 맞지 않습니다 ✗","regala: regalar(선물하다)로, 공짜로 준다는 뜻이 되어 어색합니다 ✗","tira: tirar(던지다, 버리다)로, 문맥과 맞지 않습니다 ✗","lleva: llevar(가져다주다), 집까지 배달 → 정답 ✓"]},{"id":"V125","q":"Todos tenemos que ____ las señales de tráfico.","o":["olvidar","respetar","evitar","ignorar"],"a":1,"k":"규칙 관련 동사","t":"우리 모두 교통 표지판을 지켜야 한다.","e":"respetar는 '존중하다'라는 뜻 외에 규칙이나 신호를 '지키다, 준수하다'라는 뜻도 있습니다. 'respetar las señales de tráfico'는 '교통 표지판을 지키다'입니다. 'tener que + 동사원형'은 '~해야 한다'입니다.","x":["olvidar: 잊다로, 지켜야 할 의무와 반대입니다 ✗","respetar: 지키다, 준수하다 → 정답 ✓","evitar: 피하다로, 표지판을 피한다는 것은 어색합니다 ✗","ignorar: 무시하다로, 지켜야 할 의무와 반대입니다 ✗"]},{"id":"V126","q":"Antes de ser ____ de esta escuela, era maestra.","o":["azafata","periodista","vendedora","directora"],"a":3,"k":"직업 어휘","t":"이 학교의 교장이 되기 전에 그녀는 교사였다.","e":"director/directora는 '교장, 원장, 감독, 이사' 등 '책임자'를 뜻합니다. 'directora de esta escuela'는 '이 학교의 교장'입니다. 교사(maestra)에서 교장으로 올라간 경력이라 자연스럽습니다.","x":["azafata: 승무원(여)으로, 'de esta escuela'와 맞지 않습니다 ✗","periodista: 기자로, 학교와 맞지 않습니다 ✗","vendedora: 판매원(여)으로, 학교와 맞지 않습니다 ✗","directora: 교장(여), 학교의 책임자 → 정답 ✓"]},{"id":"V127","q":"Sara y Carlota ____. Se llevan como el perro y el gato.","o":["se ayudan","se adoran","se necesitan","se odian"],"a":3,"k":"관용 표현","t":"사라와 카를로타는 서로 싫어한다. 개와 고양이처럼 사이가 나쁘다.","e":"'llevarse como el perro y el gato'는 '개와 고양이처럼 사이가 나쁘다(앙숙이다)'라는 관용 표현입니다. 그래서 'se odian(서로 미워한다)'이 정답입니다. 여기서 se는 '서로'라는 뜻의 상호 대명사입니다.","x":["se ayudan: 서로 돕는다로, 사이가 나쁘다는 표현과 반대입니다 ✗","se adoran: 서로 무척 사랑한다로, 반대 의미입니다 ✗","se necesitan: 서로 필요로 한다로, 사이가 나쁘다는 것과 맞지 않습니다 ✗","se odian: 서로 미워한다, 개와 고양이 같은 사이 → 정답 ✓"]},{"id":"V128","q":"Te veo esta tarde, Jorge. —Sí, ____.","o":["hasta mañana","hasta el lunes","hasta luego","hasta siempre"],"a":2,"k":"작별 인사","t":"오늘 오후에 보자, 호르헤. —응, 이따 봐.","e":"'hasta luego'는 '이따 봐, 나중에 봐'라는 인사로, 같은 날 다시 만날 때 자연스럽습니다. 오늘 오후(esta tarde)에 만나기로 했으므로 hasta luego가 정답입니다. 'hasta + 시간'으로 다음 만날 때를 말할 수 있습니다.","x":["hasta mañana: 내일 봐로, 오늘 오후에 만나는 것과 맞지 않습니다 ✗","hasta el lunes: 월요일에 봐로, 오늘 오후와 맞지 않습니다 ✗","hasta luego: 이따 봐, 같은 날 다시 만남 → 정답 ✓","hasta siempre: 영원히 안녕으로, 오래 못 볼 때 쓰는 작별입니다 ✗"]},{"id":"V129","q":"Me encanta ____. He estado en más de cincuenta países.","o":["bailar","escribir","leer","viajar"],"a":3,"k":"취미 동사","t":"나는 여행을 정말 좋아해. 50개국 넘게 가 봤어.","e":"viajar는 '여행하다'입니다. 50개국 이상을 가 봤다(He estado en más de cincuenta países)는 말과 연결됩니다. 'me encanta + 동사원형'은 '~하는 것을 정말 좋아한다'입니다. 'he estado'는 현재완료(~해 본 적 있다)입니다.","x":["bailar: 춤추다로, 여러 나라에 가 본 것과 연결되지 않습니다 ✗","escribir: 쓰다로, 여러 나라 방문과 연결되지 않습니다 ✗","leer: 읽다로, 여러 나라 방문과 연결되지 않습니다 ✗","viajar: 여행하다, 50개국 방문과 연결 → 정답 ✓"]},{"id":"V130","q":"No podemos salir hasta que ____ la tormenta.","o":["entre","pase","llegue","empiece"],"a":1,"k":"날씨 관련 동사","t":"폭풍이 지나갈 때까지 우리는 나갈 수 없다.","e":"pasar는 '지나가다'입니다. 폭풍이 지나가야 밖에 나갈 수 있으므로 pase가 정답입니다. 'hasta que + 미래의 일'에는 접속법(아직 일어나지 않은 일을 나타내는 동사 형태)을 써서 pasar → pase가 됩니다.","x":["entre: entrar(들어오다)로, 폭풍이 들어올 때까지 못 나간다는 것은 어색합니다 ✗","pase: pasar(지나가다)의 접속법, 폭풍이 지나가야 나감 → 정답 ✓","llegue: llegar(도착하다)로, 폭풍이 온 뒤 나가는 것은 맞지 않습니다 ✗","empiece: empezar(시작하다)로, 폭풍이 시작될 때까지 못 나간다는 것은 어색합니다 ✗"]},{"id":"V131","q":"Elvira es muy ____, no tiene pájaros en la cabeza.","o":["leal","realista","egoísta","puntual"],"a":1,"k":"관용 표현","t":"엘비라는 아주 현실적이어서 엉뚱한 생각을 하지 않는다.","e":"'tener pájaros en la cabeza(머릿속에 새가 있다)'는 '엉뚱한 생각을 하다, 비현실적이다'라는 관용 표현입니다. 이것이 없다(no tiene)는 것은 '현실적이다'라는 뜻이므로 realista가 정답입니다. realista는 남녀 모두 같은 형태입니다.","x":["leal: 충실한, 의리 있는으로, 관용 표현의 뜻과 연결되지 않습니다 ✗","realista: 현실적인, 'no tener pájaros en la cabeza'와 같은 의미 → 정답 ✓","egoísta: 이기적인으로, 관용 표현과 연결되지 않습니다 ✗","puntual: 시간을 잘 지키는으로, 관용 표현과 연결되지 않습니다 ✗"]},{"id":"V132","q":"Quiero aprender español e inglés para ____ un trabajo mejor.","o":["comparar","dejar","conseguir","enviar"],"a":2,"k":"conseguir 얻다","t":"더 좋은 일자리를 얻으려고 스페인어와 영어를 배우고 싶다.","e":"conseguir는 '얻다, 구하다, 이루다'입니다. 'conseguir un trabajo'는 '일자리를 구하다'라는 자주 쓰는 표현입니다. 'para + 동사원형'은 '~하기 위해'라는 목적을 나타냅니다.","x":["comparar: 비교하다로, 언어를 배우는 목적으로 어색합니다 ✗","dejar: 그만두다, 남기다로, 더 좋은 일을 그만둔다는 것은 맞지 않습니다 ✗","conseguir: 얻다, 구하다, 'conseguir un trabajo' → 정답 ✓","enviar: 보내다로, 일자리와 맞지 않습니다 ✗"]},{"id":"V133","q":"¿Cuántos pasajeros caben en su ____?","o":["bar","cafetería","taxi","frutería"],"a":2,"k":"교통수단 어휘","t":"당신의 택시에는 승객이 몇 명 탈 수 있나요?","e":"pasajero는 '승객'입니다. 승객이 타는 것은 교통수단이므로 taxi가 정답입니다. caber는 '들어가다, 수용되다'로 'caben'은 3인칭 복수입니다. 나머지 보기는 모두 가게입니다.","x":["bar: 술집, 바로, 승객이 타는 곳이 아닙니다 ✗","cafetería: 카페로, 승객이 타는 곳이 아닙니다 ✗","taxi: 택시, 승객이 탐 → 정답 ✓","frutería: 과일 가게로, 승객이 타는 곳이 아닙니다 ✗"]},{"id":"V134","q":"Tenemos ____. ¿Cuándo vamos a comer?","o":["frío","calor","hambre","sueño"],"a":2,"k":"tener 표현","t":"우리 배고파. 언제 밥 먹어?","e":"'tener hambre'는 '배고프다'입니다. 언제 먹냐고 묻는 것으로 보아 배가 고픈 상황입니다. 스페인어는 신체 상태를 tener로 말합니다: tener frío(춥다), tener calor(덥다), tener sueño(졸리다).","x":["frío: 'tener frío'(춥다)로, 밥 먹는 질문과 연결되지 않습니다 ✗","calor: 'tener calor'(덥다)로, 밥 먹는 질문과 연결되지 않습니다 ✗","hambre: 'tener hambre'(배고프다), 밥 먹는 질문과 연결 → 정답 ✓","sueño: 'tener sueño'(졸리다)로, 밥 먹는 질문과 연결되지 않습니다 ✗"]},{"id":"V135","q":"Esta plaza es un importante ____ de encuentro para la gente de la ciudad.","o":["lugar","pueblo","barrio","país"],"a":0,"k":"lugar de encuentro","t":"이 광장은 도시 사람들에게 중요한 만남의 장소이다.","e":"'lugar de encuentro'는 '만남의 장소, 모이는 곳'입니다. lugar는 '장소'이고 encuentro는 '만남'입니다. 광장(plaza)을 설명하는 말로 lugar가 가장 자연스럽습니다. 나머지 보기는 광장보다 큰 단위입니다.","x":["lugar: 장소, 'lugar de encuentro'(만남의 장소) → 정답 ✓","pueblo: 마을로, 광장을 설명하는 말이 아닙니다 ✗","barrio: 동네로, 광장보다 큰 단위입니다 ✗","país: 나라로, 광장과 맞지 않습니다 ✗"]},{"id":"V136","q":"Me gusta leer una ____ mientras tomo té o café.","o":["goma","revista","maleta","mochila"],"a":1,"k":"읽을거리 어휘","t":"나는 차나 커피를 마시면서 잡지 읽는 것을 좋아한다.","e":"revista는 '잡지'입니다. leer(읽다)의 목적어가 될 수 있는 것은 revista뿐입니다. mientras는 '~하는 동안'이라는 뜻입니다.","x":["goma: 지우개, 고무로, 읽을 수 없습니다 ✗","revista: 잡지, 읽는 것 → 정답 ✓","maleta: 여행 가방으로, 읽을 수 없습니다 ✗","mochila: 배낭으로, 읽을 수 없습니다 ✗"]},{"id":"V137","q":"Deberías beber bastante ____ para estar hidratado.","o":["vino","café","agua","champán"],"a":2,"k":"음료 어휘","t":"수분을 유지하려면 물을 충분히 마셔야 한다.","e":"hidratado는 '수분이 충분한'이라는 뜻입니다. 몸에 수분을 공급하는 가장 좋은 음료는 agua(물)입니다. agua는 여성명사지만 강세가 있는 a로 시작해서 단수에서는 el agua라고 씁니다. deberías는 deber의 가정형으로 부드러운 조언(~해야 해)입니다.","x":["vino: 와인으로, 술은 수분 보충에 좋지 않습니다 ✗","café: 커피로, 수분 보충의 대표 음료가 아닙니다 ✗","agua: 물, 수분 보충 → 정답 ✓","champán: 샴페인으로, 술이라 맞지 않습니다 ✗"]},{"id":"V138","q":"Marcelo juega muy bien al tenis; es su ____ favorito.","o":["equipo","deporte","programa","postre"],"a":1,"k":"스포츠 어휘","t":"마르셀로는 테니스를 아주 잘 친다. 그가 가장 좋아하는 스포츠다.","e":"deporte는 '스포츠, 운동 경기'입니다. 테니스(tenis)는 스포츠이므로 deporte가 맞습니다. 운동을 할 때는 'jugar a + 스포츠'를 쓰고, a + el은 al이 됩니다(jugar al tenis).","x":["equipo: 팀으로, 테니스는 팀이 아닙니다 ✗","deporte: 스포츠, 테니스는 스포츠 → 정답 ✓","programa: 프로그램으로, 테니스와 맞지 않습니다 ✗","postre: 디저트로, 테니스와 맞지 않습니다 ✗"]},{"id":"V139","q":"Me gustaría ir a Barcelona porque no la ____.","o":["sé","conozco","veo","comprendo"],"a":1,"k":"saber vs conocer","t":"나는 바르셀로나에 가 본 적이 없어서 가 보고 싶다.","e":"장소나 사람을 '알다, 가 본 적이 있다'고 할 때는 conocer를 씁니다. 'no la conozco'는 '그곳(바르셀로나)을 모른다, 가 본 적이 없다'라는 뜻입니다. saber는 정보나 방법을 알 때 씁니다(Sé nadar: 수영할 줄 안다). conozco는 conocer의 1인칭 불규칙형입니다.","x":["sé: saber(알다)로, 정보·방법을 알 때 쓰고 장소에는 쓰지 않습니다 ✗","conozco: conocer(알다, 가 보다), 장소를 경험으로 알 때 → 정답 ✓","veo: ver(보다)로, '가 본 적 없다'는 의미가 되지 않습니다 ✗","comprendo: comprender(이해하다)로, 장소에 쓰지 않습니다 ✗"]},{"id":"V140","q":"Siempre me lavo las manos con agua y ____.","o":["jabón","jarrón","jarabe","jamón"],"a":0,"k":"위생 용품 어휘","t":"나는 항상 물과 비누로 손을 씻는다.","e":"jabón은 '비누'입니다. 손을 씻을 때 물과 함께 쓰는 것은 비누입니다. 'agua y jabón(물과 비누)'은 자주 함께 쓰는 짝 표현입니다. 비슷한 발음의 단어들이 보기에 있으니 뜻을 정확히 구분하세요.","x":["jabón: 비누, 손 씻을 때 씀 → 정답 ✓","jarrón: 꽃병으로, 손 씻는 데 쓰지 않습니다 ✗","jarabe: 시럽, 물약으로, 손 씻는 데 쓰지 않습니다 ✗","jamón: 햄(하몬)으로, 손 씻는 데 쓰지 않습니다 ✗"]},{"id":"V141","q":"Estoy ____, ya podemos salir.","o":["cansado","contento","listo","estresado"],"a":2,"k":"estar listo","t":"나 준비됐어, 이제 나가도 돼.","e":"'estar listo'는 '준비가 되다'입니다. 이제 나갈 수 있다(ya podemos salir)는 말과 연결됩니다. listo는 ser와 쓰면 '똑똑한'이라는 다른 뜻이 됩니다(Es listo: 그는 영리하다). ser/estar에 따라 뜻이 바뀌는 형용사이니 기억하세요.","x":["cansado: 피곤한으로, 나갈 수 있다는 말과 연결되지 않습니다 ✗","contento: 기쁜으로, 나갈 준비와 직접 연결되지 않습니다 ✗","listo: (estar와 함께) 준비된 → 정답 ✓","estresado: 스트레스 받은으로, 나갈 준비와 연결되지 않습니다 ✗"]},{"id":"V142","q":"Esa directora de cine va a ____ una película en su propia ciudad.","o":["fotografiar","fallar","fabricar","filmar"],"a":3,"k":"영화 관련 동사","t":"그 영화감독은 자신의 고향 도시에서 영화를 촬영할 것이다.","e":"filmar는 '(영화를) 촬영하다'입니다. 영화감독(directora de cine)이 영화(película)를 만드는 행동이므로 filmar가 정답입니다. 같은 뜻으로 rodar도 씁니다. 'su propia ciudad'는 '자기 자신의 도시'입니다.","x":["fotografiar: 사진을 찍다로, 영화에는 쓰지 않습니다 ✗","fallar: 실패하다, 틀리다로, 문맥과 맞지 않습니다 ✗","fabricar: (공장에서) 제조하다로, 영화에 쓰지 않습니다 ✗","filmar: (영화를) 촬영하다 → 정답 ✓"]},{"id":"V143","q":"En invierno me pongo ____ gordos porque suelo tener los pies fríos.","o":["calzones","calcetines","pantalones","abrigos"],"a":1,"k":"옷 어휘","t":"나는 보통 발이 차가워서 겨울에는 두꺼운 양말을 신는다.","e":"calcetín은 '양말'이고 복수형은 calcetines입니다. 발(pies)이 차갑다고 했으므로 양말이 맞습니다. gordo는 '뚱뚱한'이지만 옷에 쓰면 '두꺼운'이라는 뜻이 됩니다. 'soler + 동사원형'은 '보통 ~하다'입니다.","x":["calzones: 속바지, 팬티(지역에 따라 다름)로, 발과 관련이 없습니다 ✗","calcetines: 양말, 발을 따뜻하게 함 → 정답 ✓","pantalones: 바지로, 발을 위한 옷이 아닙니다 ✗","abrigos: 외투로, 발을 위한 옷이 아닙니다 ✗"]},{"id":"V144","q":"Beber demasiado alcohol es un mal ____.","o":["hábito","ejercicio","objetivo","fin"],"a":0,"k":"습관 어휘","t":"술을 너무 많이 마시는 것은 나쁜 습관이다.","e":"hábito는 '습관'입니다. 'mal hábito'는 '나쁜 습관'이고 반대는 'buen hábito(좋은 습관)'입니다. malo가 남성 단수 명사 앞에 오면 o가 빠져서 mal이 됩니다(un mal hábito).","x":["hábito: 습관, 'mal hábito'(나쁜 습관) → 정답 ✓","ejercicio: 운동, 연습으로, 술 마시기를 설명하지 않습니다 ✗","objetivo: 목표로, 문맥과 맞지 않습니다 ✗","fin: 끝, 목적으로, 문맥과 맞지 않습니다 ✗"]},{"id":"V145","q":"Disculpe, somos vegetarianos. ¿Tienen platos sin ____?","o":["carne","cereales","soja","verdura"],"a":0,"k":"식단 어휘","t":"실례합니다, 저희는 채식주의자예요. 고기 없는 요리가 있나요?","e":"vegetariano는 '채식주의자'로 고기(carne)를 먹지 않습니다. 그래서 'platos sin carne(고기 없는 요리)'를 찾는 것이 자연스럽습니다. sin은 '~없이'라는 전치사입니다.","x":["carne: 고기, 채식주의자는 먹지 않음 → 정답 ✓","cereales: 곡물, 시리얼로, 채식주의자도 먹습니다 ✗","soja: 콩(대두)으로, 채식주의자가 즐겨 먹습니다 ✗","verdura: 채소로, 채식주의자가 먹는 음식입니다 ✗"]},{"id":"V146","q":"En esa heladería hay una gran ____ de helados. Hay para todos los gustos.","o":["unidad","desigualdad","variedad","porción"],"a":2,"k":"양·종류 어휘","t":"그 아이스크림 가게에는 아이스크림 종류가 아주 많다. 모든 취향에 맞는 게 있다.","e":"variedad는 '다양성, 여러 종류'입니다. 'una gran variedad de~'는 '아주 다양한 ~'이라는 표현입니다. '모든 취향에 맞는 게 있다(Hay para todos los gustos)'는 말과 잘 어울립니다.","x":["unidad: 단위, 한 개로, '다양하다'는 뜻이 아닙니다 ✗","desigualdad: 불평등으로, 문맥과 맞지 않습니다 ✗","variedad: 다양성, 'gran variedad de'(아주 다양한) → 정답 ✓","porción: 1인분, 조각으로, 다양함을 나타내지 않습니다 ✗"]},{"id":"V147","q":"Estoy ____, no sé si Pedro vive en el segundo o en el tercer piso.","o":["ocupado","seguro","confundido","enfadado"],"a":2,"k":"감정 형용사","t":"헷갈려. 페드로가 2층에 사는지 3층에 사는지 모르겠어.","e":"confundido는 '헷갈리는, 혼란스러운'이라는 뜻입니다. 2층인지 3층인지 모르겠다(no sé si~)는 상황과 딱 맞습니다. 'estar + 형용사'는 지금의 상태를 나타냅니다. 'no sé si~'는 '~인지 모르겠다'입니다.","x":["ocupado: 바쁜으로, 모른다는 상황과 맞지 않습니다 ✗","seguro: 확실한으로, '모르겠다'와 모순됩니다 ✗","confundido: 헷갈리는, 혼란스러운 → 정답 ✓","enfadado: 화난으로, 모른다는 상황과 맞지 않습니다 ✗"]},{"id":"V148","q":"Estoy en paro. Llevo dos meses buscando ____.","o":["espacio","tiempo","alegría","trabajo"],"a":3,"k":"일 관련 어휘","t":"나는 실직 상태야. 두 달째 일자리를 찾고 있어.","e":"'estar en paro'는 스페인에서 '실직 상태이다'라는 표현입니다(중남미에서는 'estar desempleado'를 주로 씁니다). 실직했으니 trabajo(일자리)를 찾는 것입니다. 'llevar + 기간 + 현재분사'는 '~째 ~하고 있다'라는 표현입니다.","x":["espacio: 공간으로, 실직 상태와 연결되지 않습니다 ✗","tiempo: 시간으로, 실직 상태와 연결되지 않습니다 ✗","alegría: 기쁨으로, 실직 상태와 직접 연결되지 않습니다 ✗","trabajo: 일, 일자리, 실직해서 찾음 → 정답 ✓"]},{"id":"V149","q":"Van a casarse en ____ del pueblo.","o":["la escuela","el bar","la iglesia","la cafetería"],"a":2,"k":"결혼식 장소","t":"그들은 마을 성당에서 결혼할 것이다.","e":"casarse는 '결혼하다'입니다. 스페인어권에서 전통적인 결혼식은 iglesia(성당, 교회)에서 합니다. 'del pueblo'는 '마을의'이고 de + el이 합쳐진 형태입니다.","x":["la escuela: 학교로, 결혼식을 하는 곳이 아닙니다 ✗","el bar: 술집으로, 결혼식 장소로 어색합니다 ✗","la iglesia: 성당, 교회, 결혼식 장소 → 정답 ✓","la cafetería: 카페로, 결혼식 장소로 어색합니다 ✗"]},{"id":"V150","q":"Vamos a caminar mucho, así que es mejor llevar ____ cómodos.","o":["guantes","relojes","gorros","zapatos"],"a":3,"k":"신발 어휘","t":"많이 걸을 거니까 편한 신발을 신는 게 좋다.","e":"zapato는 '신발, 구두'입니다. 많이 걷는다(caminar mucho)고 했으니 편한 신발이 필요합니다. 'zapatos cómodos'는 '편한 신발'입니다. 운동화는 zapatillas(스페인) 또는 tenis(중남미 일부)라고 합니다.","x":["guantes: 장갑으로, 걷기와 관련이 없습니다 ✗","relojes: 시계로, 걷기와 관련이 없습니다 ✗","gorros: 털모자로, 걷기와 직접 관련이 없습니다 ✗","zapatos: 신발, 많이 걸을 때 필요 → 정답 ✓"]},{"id":"V151","q":"Voy a reservar una ____ para tres en el restaurante chino.","o":["silla","ventana","puerta","mesa"],"a":3,"k":"식당 어휘","t":"중국 음식점에 세 명 자리 테이블을 예약할 거야.","e":"식당에서 자리를 예약할 때는 'reservar una mesa(테이블을 예약하다)'라고 합니다. 'una mesa para tres'는 '세 명용 테이블'이라는 뜻으로, 'para + 숫자'로 인원을 나타냅니다. 예: Una mesa para dos, por favor.(두 명 자리 부탁해요.)","x":["silla: 의자 — 의자 하나를 세 명이 쓸 수는 없고, 식당 예약에 쓰지 않습니다 ✗","ventana: 창문 — 예약하는 대상이 아닙니다 ✗","puerta: 문 — 식당 예약과 관계없습니다 ✗","mesa: 테이블, 식탁 — 'reservar una mesa(테이블 예약)'로 딱 맞습니다 ✓"]},{"id":"V152","q":"Mi desayuno consiste en dos rebanadas de ____ con mantequilla y un zumo.","o":["pan","plátano","ajo","aceite"],"a":0,"k":"아침 식사 어휘","t":"내 아침 식사는 버터를 바른 빵 두 조각과 주스 한 잔이야.","e":"'rebanada'는 빵 등을 얇게 썬 '한 조각'을 뜻하고, 'rebanada de pan(빵 한 조각)'이 가장 대표적인 짝입니다. 버터(mantequilla)를 바르는 것도 빵이라 pan이 정답입니다. 참고로 'zumo(주스)'는 스페인 표현이고, 중남미에서는 'jugo'라고 합니다.","x":["pan: 빵 — 'rebanadas de pan con mantequilla(버터 바른 빵 조각)'으로 자연스럽습니다 ✓","plátano: 바나나 — 썰어 버터를 바르는 음식이 아닙니다 ✗","ajo: 마늘 — 아침 식사로 버터와 함께 먹지 않습니다 ✗","aceite: 기름, 올리브유 — 액체라 'rebanada(조각)'로 셀 수 없습니다 ✗"]},{"id":"V153","q":"¿Podría ponerme dos cubitos de ____ en mi bebida?","o":["azúcar","hielo","sal","sacarina"],"a":1,"k":"음료·식재료 어휘","t":"제 음료에 얼음 두 조각 넣어 주시겠어요?","e":"'cubito'는 작은 정육면체를 뜻하며, 'cubito de hielo'는 '각얼음'입니다. 음료에 얼음을 넣어 달라고 할 때 자주 쓰는 표현입니다. '¿Podría...?'는 poder의 조건법으로 '~해 주시겠어요?'라는 공손한 부탁입니다.","x":["azúcar: 설탕 — 'cubito de azúcar'도 있긴 하지만 보통 'terrón de azúcar(각설탕)'라고 하며, 음료에 넣는 '작은 정육면체'의 대표는 얼음입니다 ✗","hielo: 얼음 — 'cubitos de hielo(각얼음)'로 딱 맞습니다 ✓","sal: 소금 — 음료에 넣지 않고 조각 형태도 아닙니다 ✗","sacarina: 사카린(인공 감미료) — 알약이나 가루로 쓰며 'cubito'와 어울리지 않습니다 ✗"]},{"id":"V154","q":"No me gustó nada la exposición de pintura. ¡Qué ____!","o":["maravilla","hermosura","belleza","horror"],"a":3,"k":"감탄 표현 ¡Qué...!","t":"그 미술 전시회는 전혀 마음에 들지 않았어. 정말 끔찍했어!","e":"'¡Qué + 명사!'는 '정말 ~하다!'라는 감탄 표현입니다. 앞 문장에서 'No me gustó nada(전혀 마음에 들지 않았다)'라고 했으므로 부정적인 감탄인 '¡Qué horror!(정말 끔찍해!)'가 어울립니다. 반대로 좋을 때는 '¡Qué maravilla!(정말 멋지다!)'라고 합니다.","x":["maravilla: 경이, 멋진 것 — '¡Qué maravilla!'는 칭찬이라 앞 문장과 반대입니다 ✗","hermosura: 아름다움 — 긍정적인 감탄이라 맞지 않습니다 ✗","belleza: 아름다움 — 마찬가지로 긍정적인 뜻이라 ✗","horror: 공포, 끔찍함 — '¡Qué horror!(정말 끔찍해!)'로 부정적 평가와 일치합니다 ✓"]},{"id":"V155","q":"Julián está malo, por eso está ____ al trabajo.","o":["faltando","yendo","andando","viniendo"],"a":0,"k":"faltar 동사","t":"훌리안은 아파서 회사에 결근하고 있어.","e":"'faltar a + 장소/모임'은 '~에 빠지다, 결석·결근하다'라는 뜻입니다. 'estar malo'는 '아프다'이므로 아파서 출근을 못 하는 상황이 됩니다. 'estar + 현재분사(-ando/-iendo)'는 '~하고 있다'는 진행형입니다. 예: Faltó a clase ayer.(그는 어제 수업에 결석했다.)","x":["faltando: faltar(빠지다, 결근하다)의 현재분사 — 'faltar al trabajo(결근하다)'로 아픈 상황과 맞습니다 ✓","yendo: ir(가다)의 현재분사 — 아픈데 회사에 간다는 것은 'por eso(그래서)'와 논리가 맞지 않습니다 ✗","andando: andar(걷다)의 현재분사 — 'andar al trabajo'는 어색하고 의미도 맞지 않습니다 ✗","viniendo: venir(오다)의 현재분사 — 아파서 회사에 온다는 것은 논리에 맞지 않습니다 ✗"]},{"id":"V156","q":"Nuestro domicilio no es ni grande ni pequeño, es ____.","o":["diminuto","enorme","inmenso","mediano"],"a":3,"k":"크기 형용사","t":"우리 집은 크지도 작지도 않아, 중간 크기야.","e":"'ni A ni B'는 'A도 B도 아니다'라는 뜻입니다. 크지도(grande) 작지도(pequeño) 않다면 '중간 크기'인 mediano가 논리적으로 맞습니다. mediano는 옷 사이즈 'talla mediana(M 사이즈)'처럼 자주 쓰입니다.","x":["diminuto: 아주 작은 — 'pequeño'보다 더 작다는 뜻이라 문맥과 반대입니다 ✗","enorme: 거대한 — 크지 않다고 했으므로 ✗","inmenso: 엄청나게 큰 — 역시 크다는 뜻이라 ✗","mediano: 중간 크기의 — '크지도 작지도 않다'와 정확히 맞습니다 ✓"]},{"id":"V157","q":"Sandra y Adela son idénticas porque son ____.","o":["conocidas","gemelas","primas","compañeras"],"a":1,"k":"가족 어휘","t":"산드라와 아델라는 쌍둥이라서 똑같이 생겼어.","e":"'idéntico'는 '똑같은'이라는 뜻이고, 얼굴이 똑같은 이유로 가장 자연스러운 것은 'gemelas(쌍둥이)'입니다. 남자 쌍둥이는 gemelos라고 합니다. 참고로 'mellizos'는 이란성 쌍둥이를 가리킬 때 많이 씁니다.","x":["conocidas: 아는 사이(지인) — 아는 사이라고 똑같이 생기지 않습니다 ✗","gemelas: (여자) 쌍둥이 — 똑같이 생긴 이유로 딱 맞습니다 ✓","primas: (여자) 사촌 — 사촌은 닮을 수는 있어도 똑같지는 않습니다 ✗","compañeras: (여자) 동료, 반 친구 — 외모와 관계없습니다 ✗"]},{"id":"V158","q":"Antes compraba el ____ en el quiosco, pero ahora lo leo en mi tableta.","o":["pescado","periódico","pan","queso"],"a":1,"k":"신문·매체 어휘","t":"예전에는 가판대에서 신문을 샀지만, 지금은 태블릿으로 읽어.","e":"'quiosco'는 길가의 신문·잡지 가판대이고, 뒤에 'lo leo(그것을 읽는다)'가 나오므로 읽는 것인 'periódico(신문)'가 정답입니다. 여기서 lo는 남성 단수 직접목적격 대명사(~을/를)로 el periódico를 가리킵니다.","x":["pescado: 생선 — 가판대에서 팔지 않고 읽을 수도 없습니다 ✗","periódico: 신문 — 가판대에서 사고, 태블릿으로도 읽을 수 있어 정답입니다 ✓","pan: 빵 — 읽는 것이 아닙니다 ✗","queso: 치즈 — 읽는 것이 아닙니다 ✗"]},{"id":"V159","q":"Mi ____ favorita es la pera.","o":["carne","bebida","fruta","hortaliza"],"a":2,"k":"음식 분류 어휘","t":"내가 제일 좋아하는 과일은 배야.","e":"'pera'는 '배'로 과일(fruta)에 속합니다. 빈칸 뒤의 'favorita'가 여성형이므로 여성 명사가 와야 하는데, 보기 대부분이 여성 명사라 의미로 골라야 합니다. 예: Mi fruta favorita es la manzana.(내가 좋아하는 과일은 사과야.)","x":["carne: 고기 — 배는 고기가 아닙니다 ✗","bebida: 음료 — 배는 마시는 것이 아닙니다 ✗","fruta: 과일 — 배는 과일이므로 정답입니다 ✓","hortaliza: 채소 — 배는 채소가 아니라 과일입니다 ✗"]},{"id":"V160","q":"Por aquí no pasan ____ porque es una zona peatonal.","o":["turistas","personas","animales","vehículos"],"a":3,"k":"교통 어휘","t":"여기는 보행자 전용 구역이라 차량이 지나다니지 않아.","e":"'zona peatonal'은 '보행자 전용 구역'으로, 사람(peatón)만 걸어 다니고 차는 다닐 수 없는 곳입니다. 그래서 다니지 않는 것은 'vehículos(차량)'입니다. 'peatón(보행자)'라는 단어도 함께 알아 두세요.","x":["turistas: 관광객 — 관광객은 걸어서 다닐 수 있습니다 ✗","personas: 사람들 — 보행자 구역은 오히려 사람이 다니는 곳입니다 ✗","animales: 동물 — 보행자 구역의 정의와 관계없습니다 ✗","vehículos: 차량 — 보행자 구역에서는 차량 통행이 금지되므로 정답입니다 ✓"]},{"id":"V161","q":"Estoy ____ mucho para tener buenas notas.","o":["disfrutando","olvidando","andando","estudiando"],"a":3,"k":"학교 생활 동사","t":"좋은 성적을 받으려고 열심히 공부하고 있어.","e":"'tener buenas notas'는 '좋은 성적을 받다'라는 뜻입니다. 좋은 성적을 위해 하는 행동은 당연히 공부(estudiar)이므로 'estoy estudiando(공부하고 있다)'가 맞습니다. 'nota'는 시험 '점수, 성적'을 뜻합니다.","x":["disfrutando: disfrutar(즐기다) — 즐긴다고 성적이 오르지는 않습니다 ✗","olvidando: olvidar(잊다) — 좋은 성적과 반대되는 행동입니다 ✗","andando: andar(걷다) — 성적과 관계없습니다 ✗","estudiando: estudiar(공부하다) — 좋은 성적을 위한 행동으로 정답입니다 ✓"]},{"id":"V162","q":"Ana y Daniel ____ bien, son buenos amigos.","o":["se llevan","se lavan","se llaman","se levantan"],"a":0,"k":"재귀동사 llevarse","t":"아나와 다니엘은 사이가 좋아, 좋은 친구들이야.","e":"'llevarse bien/mal (con alguien)'은 '(누구와) 사이가 좋다/나쁘다'라는 관용 표현입니다. 뒤 문장 'son buenos amigos(좋은 친구다)'와 연결되므로 'se llevan bien'이 정답입니다. 예: Me llevo bien con mi hermano.(나는 형이랑 사이가 좋아.)","x":["se llevan: llevarse(사이가 ~하다) — 'llevarse bien(사이가 좋다)'로 정답입니다 ✓","se lavan: lavarse(씻다) — '잘 씻는다'는 친구 사이와 관계없습니다 ✗","se llaman: llamarse(이름이 ~이다) — 'se llaman bien'은 의미가 통하지 않습니다 ✗","se levantan: levantarse(일어나다) — '잘 일어난다'는 친구 관계와 맞지 않습니다 ✗"]},{"id":"V163","q":"¿Puedes darme otro tenedor, por favor? Este está ____.","o":["nuevo","lavado","limpio","sucio"],"a":3,"k":"상태 형용사","t":"포크 하나 더 줄 수 있어요? 이건 더러워요.","e":"포크를 바꿔 달라는 이유가 필요하므로 'sucio(더러운)'가 맞습니다. 이처럼 일시적인 상태는 'estar + 형용사'로 표현합니다. 반대말은 'limpio(깨끗한)'입니다.","x":["nuevo: 새것인 — 새 포크라면 바꿀 이유가 없습니다 ✗","lavado: 씻은 — 씻은 포크는 쓸 수 있으니 ✗","limpio: 깨끗한 — 깨끗하면 바꿀 필요가 없습니다 ✗","sucio: 더러운 — 다른 포크를 달라는 이유로 딱 맞습니다 ✓"]},{"id":"V164","q":"No podemos usar el horno porque no ____.","o":["cuenta","cuesta","vale","funciona"],"a":3,"k":"funcionar 동사","t":"오븐이 작동하지 않아서 쓸 수 없어.","e":"'funcionar'는 기계나 장치가 '작동하다, 돌아가다'라는 뜻입니다. 'no funciona'는 '고장 나서 안 된다'는 말로 일상에서 아주 많이 씁니다. 예: El ascensor no funciona.(엘리베이터가 고장 났어요.)","x":["cuenta: contar(세다, 이야기하다) — 오븐이 '세지 않는다'는 의미가 통하지 않습니다 ✗","cuesta: costar(값이 ~이다, 힘들다) — 오븐 사용 불가 이유가 되지 않습니다 ✗","vale: valer(값어치가 있다, 유효하다) — 기계 작동에는 쓰지 않습니다 ✗","funciona: funcionar(작동하다) — 'no funciona(작동하지 않는다)'로 정답입니다 ✓"]},{"id":"V165","q":"La depresión es una enfermedad ____.","o":["digestiva","de la piel","del corazón","mental"],"a":3,"k":"건강·질병 어휘","t":"우울증은 정신 질환이다.","e":"'depresión'은 '우울증'으로, 마음과 정신에 관련된 병이므로 'enfermedad mental(정신 질환)'입니다. 'mental'은 남녀 형태가 같아 enfermedad(여성 명사)에도 그대로 씁니다. 'salud mental(정신 건강)'도 자주 쓰는 표현입니다.","x":["digestiva: 소화기의 — 위장 질환에 쓰는 말입니다 ✗","de la piel: 피부의 — 피부병에 쓰는 말입니다 ✗","del corazón: 심장의 — 심장병에 쓰는 말입니다 ✗","mental: 정신의 — 우울증은 정신 질환이므로 정답입니다 ✓"]},{"id":"V166","q":"Carlos es ____, pero hoy está muy callado.","o":["divertido","hablador","amable","grosero"],"a":1,"k":"성격 형용사","t":"카를로스는 수다스러운 사람인데, 오늘은 아주 조용해.","e":"'pero(하지만)'로 대비를 이루므로, 빈칸에는 'callado(조용한, 말이 없는)'와 반대되는 성격이 와야 합니다. 그래서 'hablador(말이 많은, 수다스러운)'가 정답입니다. 'ser'는 평소 성격, 'estar'는 오늘의 일시적 상태를 나타내는 점도 눈여겨보세요.","x":["divertido: 재미있는 — 'callado(조용한)'의 직접적인 반대말이 아닙니다 ✗","hablador: 말이 많은 — 'callado(조용한)'와 정확히 대비되어 정답입니다 ✓","amable: 친절한 — 말수와 관련된 대비가 아닙니다 ✗","grosero: 무례한 — 조용함과 대비되는 성격이 아닙니다 ✗"]},{"id":"V167","q":"Hablar español con nativos es una idea ____.","o":["malísima","excelente","terrible","pésima"],"a":1,"k":"평가 형용사","t":"원어민과 스페인어로 말하는 것은 아주 좋은 생각이야.","e":"원어민과 말하는 것은 언어 학습에 도움이 되므로 긍정적인 평가인 'excelente(훌륭한)'가 맞습니다. 'excelente'는 남녀 형태가 같아 'idea(여성 명사)'에도 그대로 씁니다. 'Es una idea excelente/genial'은 상대 제안에 맞장구칠 때도 유용합니다.","x":["malísima: 아주 나쁜(mala의 최상급) — 부정적인 평가라 ✗","excelente: 훌륭한 — 원어민과의 대화를 긍정적으로 평가하므로 정답입니다 ✓","terrible: 끔찍한 — 부정적인 평가라 ✗","pésima: 최악의 — 부정적인 평가라 ✗"]},{"id":"V168","q":"Suelo hacer los deberes de la escuela en mi ____.","o":["cajón","escritorio","perchero","estante"],"a":1,"k":"가구 어휘","t":"나는 보통 학교 숙제를 내 책상에서 해.","e":"'soler + 동사원형'은 '보통 ~하다, ~하곤 하다'입니다. 숙제를 하는 장소로 가장 알맞은 가구는 'escritorio(책상)'입니다. 참고로 'mesa'는 식탁·테이블을 포함한 넓은 의미의 탁자입니다.","x":["cajón: 서랍 — 서랍 안에서 숙제를 할 수는 없습니다 ✗","escritorio: 책상 — 숙제를 하는 곳으로 정답입니다 ✓","perchero: 옷걸이(행거) — 옷을 거는 가구입니다 ✗","estante: 선반, 책장 칸 — 물건을 올려 두는 곳입니다 ✗"]},{"id":"V169","q":"Esta semana todos nuestros productos están ____ de precio. ¡Aproveche la oportunidad!","o":["a mitad","al doble","al triple","a medio"],"a":0,"k":"쇼핑·가격 표현","t":"이번 주 저희 모든 상품이 반값입니다. 기회를 놓치지 마세요!","e":"'a mitad de precio'는 '반값에, 50% 할인된'이라는 고정 표현입니다. 'mitad'는 '절반'이라는 명사라 'a mitad de'로 씁니다. 'Aproveche la oportunidad(기회를 활용하세요)'라는 광고 문구와 함께 할인이라는 것을 알 수 있습니다.","x":["a mitad: '반값에(a mitad de precio)' — 할인 광고에 맞는 고정 표현이라 정답입니다 ✓","al doble: 두 배로 — 가격이 두 배면 좋은 기회가 아닙니다 ✗","al triple: 세 배로 — 가격이 오르는 것이라 광고와 맞지 않습니다 ✗","a medio: 'medio'는 형용사(반의)로 'a medio precio'처럼 명사 앞에 붙어야 하며 'a medio de precio'는 틀린 형태입니다 ✗"]},{"id":"V170","q":"Siempre les doy propina a los ____ que me atienden bien.","o":["camareros","estudiantes","clientes","alumnos"],"a":0,"k":"직업 어휘","t":"나는 서비스를 잘해 주는 웨이터들에게 항상 팁을 줘.","e":"'propina'는 '팁'이고, 식당에서 서비스를 해 주는 'camareros(웨이터)'에게 줍니다. 'atender'는 손님을 '응대하다, 시중들다'라는 뜻입니다. 중남미에서는 웨이터를 'meseros'라고 많이 합니다.","x":["camareros: 웨이터 — 손님을 응대하고 팁을 받는 사람이라 정답입니다 ✓","estudiantes: 학생들 — 팁을 받는 직업이 아닙니다 ✗","clientes: 손님들 — 오히려 팁을 주는 쪽입니다 ✗","alumnos: (학교의) 학생들 — 팁과 관계없습니다 ✗"]},{"id":"V171","q":"Tengo una mala ____ para ti: no van a darte la beca de estudios.","o":["nota","novela","novia","noticia"],"a":3,"k":"noticia 어휘","t":"너한테 나쁜 소식이 있어. 장학금을 못 받게 됐어.","e":"'una mala noticia'는 '나쁜 소식'으로, 'Tengo una buena/mala noticia para ti(너한테 좋은/나쁜 소식이 있어)'는 자주 쓰는 표현입니다. 뒤의 콜론(:) 다음에 소식의 내용이 나옵니다. 'beca'는 '장학금'입니다.","x":["nota: 성적, 메모 — '나쁜 성적'은 될 수 있지만 장학금 소식을 전하는 표현이 아닙니다 ✗","novela: 소설 — 소식을 전하는 상황과 맞지 않습니다 ✗","novia: 여자친구, 약혼녀 — 의미가 통하지 않습니다 ✗","noticia: 소식, 뉴스 — 장학금 탈락을 알리는 '나쁜 소식'으로 정답입니다 ✓"]},{"id":"V172","q":"Julieta no se controla fácilmente, es muy ____.","o":["comprensiva","impulsiva","paciente","estudiosa"],"a":1,"k":"성격 형용사","t":"훌리에타는 자기 조절이 쉽지 않아, 아주 충동적이야.","e":"'no se controla fácilmente(쉽게 자제하지 못한다)'를 설명하는 성격은 'impulsiva(충동적인)'입니다. 생각보다 행동이 먼저 나가는 사람을 말합니다. 남성형은 'impulsivo'입니다.","x":["comprensiva: 이해심 많은 — 자제력 부족과 관계없습니다 ✗","impulsiva: 충동적인 — 자기 조절을 못하는 성격이라 정답입니다 ✓","paciente: 참을성 있는 — 오히려 반대 성격입니다 ✗","estudiosa: 공부를 열심히 하는 — 자제력과 관계없습니다 ✗"]},{"id":"V173","q":"¿Puedes ____ las cortinas para que entre la luz?","o":["pegar","echar","romper","abrir"],"a":3,"k":"집안 동작 동사","t":"빛이 들어오게 커튼 좀 열어 줄래?","e":"'abrir las cortinas'는 '커튼을 열다(걷다)'입니다. 'para que + 접속법(바람·목적을 나타내는 동사 형태)'은 '~하도록'이라는 뜻이라 'para que entre la luz(빛이 들어오도록)'가 됩니다. 반대로 '커튼을 치다'는 'cerrar las cortinas'입니다.","x":["pegar: 붙이다, 때리다 — 커튼과 함께 쓰지 않습니다 ✗","echar: 던지다, (커튼을) 치다 — 'echar las cortinas'는 보통 커튼을 '치다(닫다)'라는 뜻이라 빛이 들어오는 것과 반대입니다 ✗","romper: 부수다, 찢다 — 커튼을 찢는 것은 목적에 맞지 않습니다 ✗","abrir: 열다 — 커튼을 열어 빛이 들어오게 하므로 정답입니다 ✓"]},{"id":"V174","q":"¿A qué os dedicáis? —Somos ____.","o":["venezolanos","ecuatorianos","bomberos","cubanos"],"a":2,"k":"직업 묻기","t":"너희는 무슨 일을 하니? — 우리는 소방관이야.","e":"'¿A qué os dedicáis?'는 '너희는 무슨 일을 하니?'라는 직업을 묻는 질문입니다(dedicarse a: ~에 종사하다). 그래서 직업인 'bomberos(소방관)'가 답이 됩니다. 'os dedicáis'는 vosotros(너희) 형태로 스페인에서 쓰고, 중남미에서는 '¿A qué se dedican (ustedes)?'라고 합니다.","x":["venezolanos: 베네수엘라 사람들 — 국적이지 직업이 아닙니다 ✗","ecuatorianos: 에콰도르 사람들 — 국적이라 ✗","bomberos: 소방관들 — 직업을 묻는 질문에 맞는 답이라 정답입니다 ✓","cubanos: 쿠바 사람들 — 국적이라 ✗"]},{"id":"V175","q":"Están ____ porque, por fin, van a ser abuelos.","o":["emocionados","infelices","amargados","desesperados"],"a":0,"k":"감정 형용사","t":"드디어 할아버지 할머니가 된다며 그들은 감격해 있어.","e":"'por fin(드디어)'이라는 말에서 오래 기다린 기쁜 일임을 알 수 있습니다. 그래서 'emocionados(감격한, 설레는)'가 맞습니다. 'estar emocionado'는 기쁘거나 감동받아 들뜬 상태를 말합니다.","x":["emocionados: 감격한, 설레는 — 손주가 생기는 기쁜 소식에 맞아 정답입니다 ✓","infelices: 불행한 — 기쁜 소식과 반대입니다 ✗","amargados: 비통한, 씁쓸한 — 부정적인 감정이라 ✗","desesperados: 절망한 — 부정적인 감정이라 ✗"]},{"id":"V176","q":"¿Cuál es su ____? —Soy cristiano.","o":["dirección","nación","expresión","religión"],"a":3,"k":"신상 정보 어휘","t":"당신의 종교는 무엇입니까? — 저는 기독교인입니다.","e":"'cristiano(기독교인)'는 종교를 나타내므로 질문은 'religión(종교)'을 묻는 것입니다. '¿Cuál es su...?'는 '당신의 ~은 무엇입니까?'라는 정중한 질문입니다. 다른 종교 예: budista(불교도), musulmán(무슬림).","x":["dirección: 주소 — '기독교인'은 주소에 대한 답이 아닙니다 ✗","nación: 국가 — 국적을 묻는 말과도 다르고 답과 맞지 않습니다 ✗","expresión: 표현 — 의미가 통하지 않습니다 ✗","religión: 종교 — '기독교인입니다'라는 답과 맞아 정답입니다 ✓"]},{"id":"V177","q":"Raquel es muy ____, pero su hermana es todo lo contrario, es vanidosa.","o":["hortera","elegante","respetada","modesta"],"a":3,"k":"반의어 성격","t":"라켈은 아주 겸손한데, 그녀의 언니는 정반대로 허영심이 많아.","e":"'todo lo contrario(정반대)'라고 했으므로 빈칸에는 'vanidosa(허영심 많은, 잘난 체하는)'의 반대말이 들어갑니다. 그 반대말은 'modesta(겸손한)'입니다. 남성형은 modesto입니다.","x":["hortera: 촌스러운, 천박한 취향의(스페인 구어) — vanidosa의 반대말이 아닙니다 ✗","elegante: 우아한 — 허영심의 반대 개념이 아닙니다 ✗","respetada: 존경받는 — 반대말 관계가 아닙니다 ✗","modesta: 겸손한 — 'vanidosa(허영심 많은)'의 반대말이라 정답입니다 ✓"]},{"id":"V178","q":"¿Cuál es vuestro ____ de vacaciones preferido? —La costa.","o":["paquete","empleo","juego","destino"],"a":3,"k":"여행 어휘","t":"너희가 가장 좋아하는 휴가지는 어디야? — 해안이야.","e":"'destino'는 여행의 '목적지'라는 뜻이며, 'destino de vacaciones'는 '휴가지'입니다. 답이 'la costa(해안)'라는 장소이므로 장소를 묻는 말이 와야 합니다. 'vuestro'는 vosotros(너희)의 소유사로 스페인에서 씁니다.","x":["paquete: 패키지 — '패키지 여행'은 'paquete turístico'이고 장소 답과 맞지 않습니다 ✗","empleo: 일자리 — 휴가와 관계없습니다 ✗","juego: 놀이, 게임 — 장소를 묻는 말이 아닙니다 ✗","destino: 목적지 — '해안'이라는 장소 답과 맞아 정답입니다 ✓"]},{"id":"V179","q":"El Nilo es uno de los ____ más largos del mundo.","o":["lagos","ríos","monumentos","montes"],"a":1,"k":"지리 어휘","t":"나일강은 세계에서 가장 긴 강 중 하나이다.","e":"나일강(el Nilo)은 강(río)입니다. 'uno de los + 복수 명사 + más...'는 '가장 ~한 것 중 하나'라는 표현입니다. 강 이름 앞에는 보통 남성 관사 el을 붙입니다: el Amazonas(아마존강).","x":["lagos: 호수 — 나일은 호수가 아닙니다 ✗","ríos: 강 — 나일강은 세계에서 가장 긴 강 중 하나라 정답입니다 ✓","monumentos: 기념물 — 자연 지형이 아닙니다 ✗","montes: 산 — 나일은 산이 아니고 '길다'는 표현과도 어울리지 않습니다 ✗"]},{"id":"V180","q":"No puedo subir las escaleras con facilidad, así que voy a usar el ____.","o":["tren","yate","auto","ascensor"],"a":3,"k":"건물 시설 어휘","t":"계단을 쉽게 오를 수 없어서 엘리베이터를 탈 거야.","e":"계단(escaleras) 대신 위층으로 올라가는 수단은 'ascensor(엘리베이터)'입니다. 'así que'는 '그래서'라는 뜻의 접속사입니다. 'subir en ascensor(엘리베이터로 올라가다)'도 함께 기억하세요.","x":["tren: 기차 — 건물 위층으로 가는 수단이 아닙니다 ✗","yate: 요트 — 계단 대신 쓰는 것이 아닙니다 ✗","auto: 자동차(주로 중남미) — 계단 대신 쓸 수 없습니다 ✗","ascensor: 엘리베이터 — 계단 대신 오르내리는 수단이라 정답입니다 ✓"]},{"id":"V181","q":"Hago ____ en la piscina del gimnasio.","o":["atletismo","ciclismo","natación","parapente"],"a":2,"k":"스포츠 어휘","t":"나는 헬스장 수영장에서 수영을 해.","e":"'piscina(수영장)'에서 하는 운동은 'natación(수영)'입니다. 운동을 한다고 할 때는 'hacer + 운동 이름'을 많이 씁니다: hacer natación, hacer yoga. 동사로는 'nadar(수영하다)'라고도 합니다.","x":["atletismo: 육상 — 수영장에서 하는 운동이 아닙니다 ✗","ciclismo: 사이클 — 자전거 운동이라 수영장과 맞지 않습니다 ✗","natación: 수영 — 수영장에서 하는 운동이라 정답입니다 ✓","parapente: 패러글라이딩 — 하늘에서 하는 운동입니다 ✗"]},{"id":"V182","q":"En esta casa hay cuatro ____.","o":["panaderías","carnicerías","habitaciones","estancos"],"a":2,"k":"집 구조 어휘","t":"이 집에는 방이 네 개 있어.","e":"집 안에 있는 것은 'habitaciones(방)'입니다. 'hay'는 '~이 있다'라는 뜻으로 단수·복수 모두 같은 형태를 씁니다. 참고로 'dormitorio'는 '침실'을 가리킵니다.","x":["panaderías: 빵집 — 집 안에 있는 공간이 아닙니다 ✗","carnicerías: 정육점 — 집 안에 있지 않습니다 ✗","habitaciones: 방 — 집 안의 공간이라 정답입니다 ✓","estancos: (스페인의) 담배 가게 — 상점이라 집 안에 있지 않습니다 ✗"]},{"id":"V183","q":"En este restaurante se come ____. Te lo recomiendo.","o":["muy bien","mal","poco","fatal"],"a":0,"k":"평가 부사","t":"이 식당은 음식이 아주 맛있어. 추천해.","e":"'Te lo recomiendo(너에게 그것을 추천해)'라고 했으므로 긍정적인 평가가 와야 합니다. 'se come muy bien'은 '음식이 아주 잘 나온다, 맛있게 먹을 수 있다'는 무인칭 표현(주어 없이 일반적인 사실을 말하는 형태)입니다. 'Aquí se come bien'은 식당을 칭찬할 때 자주 쓰는 말입니다.","x":["muy bien: 아주 잘 — 추천하는 이유로 맞아 정답입니다 ✓","mal: 나쁘게 — 맛없는 식당을 추천하지 않습니다 ✗","poco: 적게 — 양이 적다는 뜻이라 추천 이유가 되기 어렵습니다 ✗","fatal: 형편없이 — 매우 부정적인 평가라 ✗"]},{"id":"V184","q":"Me encanta dormir en una ____ grande.","o":["cortina","bañera","papelera","cama"],"a":3,"k":"침실 가구 어휘","t":"나는 큰 침대에서 자는 게 정말 좋아.","e":"잠을 자는(dormir) 곳은 'cama(침대)'입니다. 'Me encanta + 동사원형'은 '~하는 것을 정말 좋아한다'라는 뜻으로, gustar보다 강한 표현입니다. 'cama doble(더블 침대)'도 알아 두세요.","x":["cortina: 커튼 — 잠을 자는 곳이 아닙니다 ✗","bañera: 욕조 — 목욕하는 곳입니다 ✗","papelera: 휴지통 — 잠과 관계없습니다 ✗","cama: 침대 — 잠을 자는 곳이라 정답입니다 ✓"]},{"id":"V185","q":"No quiero ____ en mi bocadillo. Soy vegetariano.","o":["tomate","jamón","pepino","lechuga"],"a":1,"k":"음식 어휘(채식)","t":"내 샌드위치에 햄은 넣고 싶지 않아. 나는 채식주의자야.","e":"'vegetariano(채식주의자)'는 고기를 먹지 않으므로 빼야 할 재료는 고기 가공품인 'jamón(햄)'입니다. 'bocadillo'는 스페인식 바게트 샌드위치를 말합니다. 나머지 보기는 모두 채소입니다.","x":["tomate: 토마토 — 채소라 채식주의자도 먹습니다 ✗","jamón: 햄 — 고기라서 채식주의자가 먹지 않으므로 정답입니다 ✓","pepino: 오이 — 채소라 문제없습니다 ✗","lechuga: 상추 — 채소라 문제없습니다 ✗"]},{"id":"V186","q":"En general, Paula ____ mucho, pero hoy está muy seria.","o":["bebe","sale","sonríe","trabaja"],"a":2,"k":"표정 동사","t":"보통 파울라는 많이 웃는데, 오늘은 아주 심각한 표정이야.","e":"'pero(하지만)'로 'seria(진지한, 무표정한)'와 대비되는 평소 모습이 필요합니다. 'sonreír(미소 짓다)'가 'seria'의 반대 이미지라 정답입니다. sonreír는 'sonrío, sonríes, sonríe'처럼 í에 악센트가 붙습니다.","x":["bebe: beber(마시다) — 'seria'와 대비되지 않습니다 ✗","sale: salir(나가다, 놀러 나가다) — 표정과 관계없습니다 ✗","sonríe: sonreír(미소 짓다) — 진지한 표정과 대비되어 정답입니다 ✓","trabaja: trabajar(일하다) — 표정과의 대비가 아닙니다 ✗"]},{"id":"V187","q":"Ernesto es tan sociable que incluso saluda a los ____.","o":["amigos","compañeros","desconocidos","vecinos"],"a":2,"k":"사람 관계 어휘","t":"에르네스토는 너무 사교적이라서 모르는 사람에게도 인사해.","e":"'incluso(심지어)'는 예상 밖의 일을 강조합니다. 친구나 이웃에게 인사하는 것은 당연하지만, 'desconocidos(모르는 사람들)'에게까지 인사하는 것은 아주 사교적이라는 증거입니다. 'tan + 형용사 + que...'는 '너무 ~해서 ...하다'라는 구조입니다.","x":["amigos: 친구들 — 친구에게 인사하는 건 당연해서 'incluso'와 맞지 않습니다 ✗","compañeros: 동료들 — 역시 평범한 일이라 ✗","desconocidos: 모르는 사람들 — '심지어'와 어울리는 놀라운 대상이라 정답입니다 ✓","vecinos: 이웃들 — 이웃에게 인사하는 것은 흔한 일이라 ✗"]},{"id":"V188","q":"No me corto el pelo a menudo, por eso lo tengo tan ____.","o":["largo","castaño","negro","rubio"],"a":0,"k":"외모(머리) 어휘","t":"나는 머리를 자주 자르지 않아서 이렇게 길어.","e":"머리를 자주 안 자르면(no me corto el pelo) 결과는 '긴 머리'입니다. 그래서 'largo(긴)'가 정답입니다. 'tener el pelo + 형용사'로 머리 모양·색을 말합니다: tener el pelo corto(짧은 머리).","x":["largo: 긴 — 머리를 안 자른 결과라 정답입니다 ✓","castaño: 갈색의 — 머리색은 자르는 것과 관계없습니다 ✗","negro: 검은 — 색깔이라 이유와 맞지 않습니다 ✗","rubio: 금발의 — 색깔이라 맞지 않습니다 ✗"]},{"id":"V189","q":"La policía todavía no ha detenido al ____.","o":["periodista","agente","juez","ladrón"],"a":3,"k":"범죄·직업 어휘","t":"경찰은 아직 그 도둑을 체포하지 않았다.","e":"'detener'는 경찰이 '체포하다'라는 뜻입니다. 경찰이 체포하는 대상은 범죄자인 'ladrón(도둑)'입니다. 'ha detenido'는 현재완료(지금까지의 일을 말하는 시제)이고, 'todavía no(아직 ~않다)'와 잘 어울립니다.","x":["periodista: 기자 — 체포 대상이 아닙니다 ✗","agente: 경찰관, 요원 — 경찰 쪽 사람이라 ✗","juez: 판사 — 체포 대상이 아닙니다 ✗","ladrón: 도둑 — 경찰이 체포하는 범죄자라 정답입니다 ✓"]},{"id":"V190","q":"Me encanta ____ al ajedrez con mi padre.","o":["bailar","correr","saltar","jugar"],"a":3,"k":"jugar a + 게임","t":"나는 아빠랑 체스 두는 걸 정말 좋아해.","e":"게임이나 운동을 '하다'라고 할 때는 'jugar a + 게임/운동'을 씁니다. 'a + el = al'이 되어 'jugar al ajedrez(체스를 두다)'가 됩니다. 예: jugar al fútbol(축구하다). 중남미 일부에서는 'jugar fútbol'처럼 a 없이 쓰기도 합니다.","x":["bailar: 춤추다 — 체스와 함께 쓰지 않습니다 ✗","correr: 달리다 — 체스와 관계없습니다 ✗","saltar: 뛰다, 점프하다 — 체스와 관계없습니다 ✗","jugar: (게임·운동을) 하다 — 'jugar al ajedrez'로 정답입니다 ✓"]},{"id":"V191","q":"Para llegar allí, ____ todo recto y al final de esta calle gire a la derecha.","o":["haga","siga","toque","diga"],"a":1,"k":"길 안내 명령형","t":"거기에 가려면 쭉 직진하시고 이 길 끝에서 오른쪽으로 도세요.","e":"'seguir todo recto'는 '계속 직진하다'라는 길 안내 표현입니다. 'siga'는 seguir의 usted 명령형(존댓말 명령)이고, 'gire(도세요)'도 같은 형태입니다. 예: Siga recto y gire a la izquierda.(직진하시다가 왼쪽으로 도세요.)","x":["haga: hacer(하다)의 usted 명령형 — 'haga todo recto'는 길 안내 표현이 아닙니다 ✗","siga: seguir(계속 가다)의 usted 명령형 — 'siga todo recto(쭉 직진하세요)'로 정답입니다 ✓","toque: tocar(만지다, 연주하다)의 명령형 — 의미가 통하지 않습니다 ✗","diga: decir(말하다)의 명령형 — 길 안내와 맞지 않습니다 ✗"]},{"id":"V192","q":"En España eres ____ de edad cuando cumples dieciocho años.","o":["mejor","menor","peor","mayor"],"a":3,"k":"mayor de edad","t":"스페인에서는 18살이 되면 성인이 된다.","e":"'ser mayor de edad'는 '성인이다, 법적 성년이다'라는 고정 표현입니다. 반대로 미성년자는 'menor de edad'입니다. 'cumplir + 나이'는 '~살이 되다'라는 뜻입니다.","x":["mejor: 더 좋은 — 'mejor de edad'라는 표현은 없습니다 ✗","menor: 더 어린 — 'menor de edad'는 '미성년자'라서 18살이 되는 것과 반대입니다 ✗","peor: 더 나쁜 — 나이 표현에 쓰지 않습니다 ✗","mayor: 더 나이 많은 — 'mayor de edad(성인)'로 정답입니다 ✓"]},{"id":"V193","q":"¿Me ____ la sal, por favor?","o":["pasas","explicas","repites","haces"],"a":0,"k":"식탁 부탁 표현","t":"소금 좀 건네줄래?","e":"'pasar'는 '건네주다'라는 뜻으로, 식탁에서 '¿Me pasas la sal?(소금 좀 건네줄래?)'라고 아주 자주 씁니다. 'me'는 간접목적격 대명사(나에게)입니다. 현재형 의문문으로 부드러운 부탁을 할 수 있습니다.","x":["pasas: pasar(건네주다) — 'Me pasas la sal'로 정답입니다 ✓","explicas: explicar(설명하다) — 소금을 설명해 달라는 것은 어색합니다 ✗","repites: repetir(반복하다) — 소금과 어울리지 않습니다 ✗","haces: hacer(만들다, 하다) — 소금을 만들어 달라는 것은 맞지 않습니다 ✗"]},{"id":"V194","q":"La hija de mi hijo es mi ____.","o":["nieta","prima","cuñada","sobrina"],"a":0,"k":"가족 관계 어휘","t":"내 아들의 딸은 내 손녀다.","e":"아들(hijo)의 딸(hija)은 나에게 '손녀(nieta)'입니다. 손자는 'nieto', 손주들은 'nietos'라고 합니다. 반대로 나는 그녀의 'abuelo/abuela(할아버지/할머니)'가 됩니다.","x":["nieta: 손녀 — 아들의 딸이므로 정답입니다 ✓","prima: (여자) 사촌 — 삼촌·이모의 딸입니다 ✗","cuñada: 올케, 처제, 형수 등 — 배우자의 자매나 형제의 아내입니다 ✗","sobrina: 조카딸 — 형제자매의 딸입니다 ✗"]},{"id":"V195","q":"Mi hermano es ____ de helicópteros.","o":["guía","jinete","piloto","corredor"],"a":2,"k":"직업 어휘","t":"우리 형은 헬리콥터 조종사야.","e":"헬리콥터나 비행기를 조종하는 사람은 'piloto(조종사)'입니다. piloto는 남녀 같은 형태를 쓰고(el/la piloto), 카레이서도 'piloto'라고 합니다. 직업을 말할 때 ser 뒤에는 보통 관사를 쓰지 않습니다: Es piloto.","x":["guía: 가이드 — 헬리콥터를 조종하지 않습니다 ✗","jinete: 기수(말 타는 사람) — 말과 관련된 말입니다 ✗","piloto: 조종사 — 헬리콥터를 조종하는 사람이라 정답입니다 ✓","corredor: 달리기 선수, 중개인 — 헬리콥터와 관계없습니다 ✗"]},{"id":"V196","q":"José es un maleducado. No ____ de nosotros cuando se va.","o":["se escapa","se despide","se burla","se ríe"],"a":1,"k":"재귀동사 despedirse","t":"호세는 예의가 없어. 갈 때 우리에게 작별 인사를 안 해.","e":"'despedirse de + 사람'은 '~에게 작별 인사를 하다'라는 뜻입니다. 떠날 때(cuando se va) 인사를 안 하는 것이 'maleducado(예의 없는 사람)'의 이유가 됩니다. despedirse는 e→i로 바뀌어 'se despide'가 됩니다.","x":["se escapa: escaparse(도망치다) — 'escaparse de nosotros(우리에게서 도망치다)'는 예의 문제와 맞지 않습니다 ✗","se despide: despedirse(작별 인사하다) — 떠날 때 인사를 안 하는 것이라 정답입니다 ✓","se burla: burlarse(놀리다) — 놀리지 않는 것은 무례함이 아닙니다 ✗","se ríe: reírse(비웃다, 웃다) — 비웃지 않는 것은 예의 없는 행동이 아닙니다 ✗"]},{"id":"V197","q":"Es una buena estudiante. Lo aprende todo con ____.","o":["facilidad","dificultad","pena","lentitud"],"a":0,"k":"con + 명사 표현","t":"그녀는 좋은 학생이야. 뭐든 쉽게 배워.","e":"'con facilidad'는 '쉽게(fácilmente)'라는 뜻의 표현입니다. 좋은 학생이라는 앞 문장과 이어지려면 긍정적인 의미가 와야 합니다. 'con + 명사'로 방법·태도를 나타냅니다: con cuidado(조심해서).","x":["facilidad: 쉬움 — 'con facilidad(쉽게)'로 좋은 학생에 맞아 정답입니다 ✓","dificultad: 어려움 — '어렵게 배운다'는 좋은 학생과 맞지 않습니다 ✗","pena: 슬픔, 아쉬움 — 'con pena(슬프게)'는 문맥과 맞지 않습니다 ✗","lentitud: 느림 — '느리게 배운다'는 칭찬과 맞지 않습니다 ✗"]},{"id":"V198","q":"Seis ____ dos son cuatro.","o":["más","entre","menos","por"],"a":2,"k":"사칙연산 표현","t":"6 빼기 2는 4다.","e":"6과 2로 4가 나오려면 빼기(menos)를 해야 합니다. 스페인어 계산 표현: más(더하기), menos(빼기), por(곱하기), entre / dividido por(나누기). 결과는 'son(~이다)'으로 말합니다.","x":["más: 더하기 — 6+2=8이라 ✗","entre: 나누기 — 6÷2=3이라 ✗","menos: 빼기 — 6-2=4라 정답입니다 ✓","por: 곱하기 — 6×2=12라 ✗"]},{"id":"V199","q":"No soy nada ____, no me interesa la vida privada de los demás.","o":["prudente","cotilla","directo","discreto"],"a":1,"k":"성격 형용사","t":"나는 전혀 남의 일에 참견하는 사람이 아니야, 다른 사람의 사생활에 관심 없어.","e":"'cotilla'는 남의 사생활에 관심이 많고 소문을 퍼뜨리는 사람(수다쟁이, 참견쟁이)을 뜻하는 스페인 구어입니다. 'No soy nada + 형용사'는 '전혀 ~하지 않다'입니다. 남녀 형태가 같으며, 중남미에서는 'chismoso/a'를 더 많이 씁니다.","x":["prudente: 신중한 — '신중하지 않다'는 사생활에 관심 없다는 말과 맞지 않습니다 ✗","cotilla: 남 얘기 좋아하는, 참견쟁이 — '전혀 참견쟁이가 아니다'로 뒤 문장과 맞아 정답입니다 ✓","directo: 직설적인 — 사생활 관심과 관계없습니다 ✗","discreto: 신중한, 입이 무거운 — '전혀 신중하지 않다'면 오히려 남 일에 관심이 많다는 뜻이 되어 반대입니다 ✗"]},{"id":"V200","q":"Me ____ pánico las arañas; siento muchísimo miedo cuando las veo.","o":["tienen","dan","ponen","hacen"],"a":1,"k":"dar miedo 구문","t":"나는 거미가 정말 무서워. 거미를 보면 엄청 겁이 나.","e":"'dar miedo/pánico a alguien'은 '~에게 겁을/공포를 주다'라는 표현으로 gustar처럼 씁니다. 무서움을 주는 주어가 'las arañas(거미들, 복수)'이므로 동사도 복수형 'dan'이 됩니다. 예: Me da miedo la oscuridad.(나는 어둠이 무서워.)","x":["tienen: tener(가지다) — 'tener miedo'는 사람이 주어일 때 쓰므로 'Tengo pánico a las arañas'처럼 써야 합니다 ✗","dan: dar(주다) — 'Me dan pánico las arañas'로 정답입니다 ✓","ponen: poner(놓다, 만들다) — 'poner pánico'라는 표현은 쓰지 않습니다 ✗","hacen: hacer(하다) — 'hacer pánico'는 틀린 표현입니다 ✗"]},{"id":"V201","q":"Isa es una persona difícil que siempre está ____ con todos.","o":["peleando","colaborando","paseando","jugando"],"a":0,"k":"동사 어휘","t":"이사는 까다로운 사람이라 늘 모두와 싸우고 있어.","e":"'persona difícil(까다로운 사람)'이라는 설명과 어울리는 행동은 'pelear(싸우다)'입니다. 'pelear con + 사람'은 '~와 싸우다'라는 뜻입니다. 'estar siempre + 현재분사'는 '늘 ~하고 있다'는 반복적인 행동을 강조합니다.","x":["peleando: pelear(싸우다) — 까다로운 사람의 행동이라 정답입니다 ✓","colaborando: colaborar(협력하다) — 긍정적인 행동이라 맞지 않습니다 ✗","paseando: pasear(산책하다) — 까다로운 성격과 관계없습니다 ✗","jugando: jugar(놀다) — 까다로운 성격의 근거가 아닙니다 ✗"]},{"id":"V202","q":"El piso de Ana tiene unas vistas ____ de Córdoba. ¡Qué suerte!","o":["preciosas","raras","feísimas","horribles"],"a":0,"k":"평가 형용사","t":"아나의 아파트는 코르도바가 내려다보이는 경치가 아름다워. 정말 운이 좋아!","e":"'¡Qué suerte!(정말 운이 좋다!)'라는 감탄으로 보아 경치가 좋다는 긍정적인 말이 필요합니다. 'preciosas(아주 아름다운)'가 정답이며, 'vistas(경치, 여성 복수)'에 맞춰 여성 복수형입니다. 'piso'는 스페인에서 '아파트'를 뜻하고, 중남미에서는 'departamento/apartamento'를 많이 씁니다.","x":["preciosas: 아주 아름다운 — 운이 좋다는 감탄과 맞아 정답입니다 ✓","raras: 이상한 — 운이 좋은 이유가 되지 않습니다 ✗","feísimas: 아주 못생긴(추한) — 부정적이라 ✗","horribles: 끔찍한 — 부정적이라 ✗"]},{"id":"V203","q":"Alba piensa que le sobra peso, pero yo creo que está muy ____.","o":["delgada","gorda","guapa","bronceada"],"a":0,"k":"체형 형용사","t":"알바는 자기가 살이 쪘다고 생각하지만, 나는 그녀가 아주 날씬하다고 생각해.","e":"'le sobra peso'는 '몸무게가 남는다, 살이 쪘다'라는 뜻입니다. 'pero(하지만)'로 반대 의견을 말하므로 'delgada(날씬한)'가 맞습니다. 'estar delgado/a'는 지금의 체형 상태를 말할 때 씁니다.","x":["delgada: 날씬한 — '살쪘다'는 생각과 반대 의견이라 정답입니다 ✓","gorda: 뚱뚱한 — 알바의 생각과 같은 말이라 'pero'와 맞지 않습니다 ✗","guapa: 예쁜 — 체중에 대한 반대 의견이 아닙니다 ✗","bronceada: 햇볕에 그을린 — 체중과 관계없습니다 ✗"]},{"id":"V204","q":"Juan no hizo ningún comentario. Simplemente ____ callado.","o":["se hizo","se quedó","se tomó","se puso"],"a":1,"k":"quedarse + 형용사","t":"후안은 아무 말도 하지 않았어. 그냥 잠자코 있었어.","e":"'quedarse callado'는 '잠자코 있다, 말없이 가만히 있다'라는 고정 표현입니다. 'quedarse + 형용사'는 어떤 상태로 '남아 있다'는 뜻입니다. 예: Me quedé sorprendido.(나는 놀라서 멍해졌다.)","x":["se hizo: hacerse(~이 되다) — 직업·신분의 변화에 쓰며 'se hizo callado'는 어색합니다 ✗","se quedó: quedarse(~한 상태로 있다) — 'se quedó callado(잠자코 있었다)'로 정답입니다 ✓","se tomó: tomarse(먹다, 받아들이다) — 형용사 callado와 어울리지 않습니다 ✗","se puso: ponerse(~해지다) — 일시적 감정 변화에 쓰며 '조용히 있었다'는 뜻으로는 quedarse가 자연스럽습니다 ✗"]},{"id":"V205","q":"¿Nos ayudas a organizar ____ de cumpleaños de Joaquín?","o":["la procesión","el carnaval","la fiesta","el desfile"],"a":2,"k":"행사 어휘","t":"호아킨 생일 파티 준비하는 거 우리 좀 도와줄래?","e":"생일(cumpleaños)에 여는 것은 'la fiesta de cumpleaños(생일 파티)'입니다. 'organizar una fiesta'는 '파티를 준비하다(열다)'라는 뜻입니다. '¿Nos ayudas a + 동사원형?'은 '우리가 ~하는 걸 도와줄래?'라는 부탁입니다.","x":["la procesión: 행렬(종교 행진) — 생일과 관계없습니다 ✗","el carnaval: 카니발, 축제 — 한 사람의 생일 행사가 아닙니다 ✗","la fiesta: 파티 — 'fiesta de cumpleaños(생일 파티)'로 정답입니다 ✓","el desfile: 퍼레이드 — 생일 행사로 맞지 않습니다 ✗"]},{"id":"V206","q":"Este niño tiene un ____ muy bueno, se porta muy bien.","o":["peso","carácter","aspecto","apetito"],"a":1,"k":"성격 어휘","t":"이 아이는 성격이 아주 좋아, 아주 착하게 행동해.","e":"'portarse bien(착하게 행동하다)'을 보면 아이의 '성격, 기질'을 말하고 있으므로 'carácter(성격)'가 맞습니다. 'tener buen/mal carácter'는 '성격이 좋다/나쁘다'라는 표현입니다. 악센트 위치(cará-cter)에 주의하세요.","x":["peso: 몸무게 — 행동과 관계없습니다 ✗","carácter: 성격 — 착하게 행동하는 것과 연결되어 정답입니다 ✓","aspecto: 외모 — 'buen aspecto'는 겉모습이 좋다는 뜻이라 행동과 맞지 않습니다 ✗","apetito: 식욕 — '식욕이 좋다'는 착한 행동의 이유가 아닙니다 ✗"]},{"id":"V207","q":"Tengo falta de sueño; últimamente me cuesta ____ dormida.","o":["quedarme","volverme","hacerme","ponerme"],"a":0,"k":"quedarse dormido","t":"요즘 잠이 부족해. 최근에 잠드는 게 힘들어.","e":"'quedarse dormido/a'는 '잠들다'라는 고정 표현입니다. 'me cuesta + 동사원형'은 '~하기가 힘들다'라는 뜻이라 'me cuesta quedarme dormida(잠드는 게 힘들다)'가 됩니다. dormida가 여성형이므로 말하는 사람은 여성입니다.","x":["quedarme: quedarse(~한 상태가 되다) — 'quedarme dormida(잠들다)'로 정답입니다 ✓","volverme: volverse(~하게 변하다) — 성격 변화 등에 쓰며 dormida와 어울리지 않습니다 ✗","hacerme: hacerse(~이 되다) — 'hacerme dormida'는 쓰지 않는 표현입니다 ✗","ponerme: ponerse(~해지다) — 'ponerme dormida'는 틀린 표현입니다 ✗"]},{"id":"V208","q":"Manuel está ____ porque lleva meses buscando trabajo y no encuentra.","o":["desesperado","satisfecho","callado","calmado"],"a":0,"k":"감정 형용사","t":"마누엘은 몇 달째 일자리를 찾고 있는데 못 찾아서 절망하고 있어.","e":"'lleva meses buscando'는 '몇 달째 찾고 있다'라는 뜻으로, 오랫동안 일을 못 구한 상황입니다. 이럴 때의 감정은 'desesperado(절망한, 애가 타는)'입니다. 'llevar + 기간 + 현재분사'는 '~째 ~하고 있다'는 유용한 표현입니다.","x":["desesperado: 절망한 — 오랜 구직 실패에 맞는 감정이라 정답입니다 ✓","satisfecho: 만족한 — 상황과 반대입니다 ✗","callado: 조용한 — 이유(porque)와 논리적으로 연결되지 않습니다 ✗","calmado: 차분한 — 오랜 실패에 대한 감정과 맞지 않습니다 ✗"]},{"id":"V209","q":"Falsificar una firma es ____.","o":["imposible","ilegal","importante","improbable"],"a":1,"k":"법 관련 형용사","t":"서명을 위조하는 것은 불법이다.","e":"'falsificar una firma'는 '서명을 위조하다'로 법을 어기는 행위입니다. 그래서 'ilegal(불법인)'이 정답입니다. 반대말은 'legal(합법적인)'입니다. 동사원형이 주어로 쓰일 수 있다는 점도 기억하세요.","x":["imposible: 불가능한 — 위조는 불가능한 일이 아닙니다 ✗","ilegal: 불법인 — 서명 위조는 범죄라 정답입니다 ✓","importante: 중요한 — 의미가 맞지 않습니다 ✗","improbable: 일어날 것 같지 않은 — 의미가 맞지 않습니다 ✗"]},{"id":"V210","q":"Estas ____ son especiales para cortar el pelo.","o":["cucharas","llaves","cadenas","tijeras"],"a":3,"k":"도구 어휘","t":"이 가위는 머리카락 자르는 전용이야.","e":"머리카락을 자르는(cortar el pelo) 도구는 'tijeras(가위)'입니다. 스페인어에서 가위는 보통 복수형 'las tijeras'로 씁니다(두 날로 이루어져 있기 때문). 'Estas'가 여성 복수이므로 형태도 맞습니다.","x":["cucharas: 숟가락 — 자르는 도구가 아닙니다 ✗","llaves: 열쇠 — 자르는 도구가 아닙니다 ✗","cadenas: 사슬, 체인 — 자르는 도구가 아닙니다 ✗","tijeras: 가위 — 머리를 자르는 도구라 정답입니다 ✓"]},{"id":"V211","q":"Hace ejercicio físico regular y tiene una buena alimentación, por eso está ____.","o":["en control","de pena","de moda","en forma"],"a":3,"k":"estar en forma","t":"그는 규칙적으로 운동하고 식사를 잘해서 몸 상태가 좋아.","e":"'estar en forma'는 '컨디션이 좋다, 몸매·체력이 좋다'라는 고정 표현입니다. 운동과 좋은 식습관의 결과로 딱 맞습니다. 'ponerse en forma'는 '몸을 만들다'라는 뜻입니다.","x":["en control: '통제 중'이라는 뜻이지만 'estar en control'은 건강 상태 표현으로 쓰지 않습니다 ✗","de pena: 형편없는 — 'estar de pena'는 상태가 아주 나쁘다는 뜻이라 반대입니다 ✗","de moda: 유행하는 — 몸 상태와 관계없습니다 ✗","en forma: 몸 상태가 좋은 — 운동과 식습관의 결과라 정답입니다 ✓"]},{"id":"V212","q":"El ____ es una fruta muy nutritiva.","o":["cordero","filete","yogur","plátano"],"a":3,"k":"과일 어휘","t":"바나나는 영양가가 높은 과일이다.","e":"보기 중 과일(fruta)은 'plátano(바나나)'뿐입니다. 'plátano'는 스페인에서 바나나를 뜻하고, 중남미에서는 'banana/banano'라고 하며 'plátano'가 요리용 바나나를 가리키기도 합니다. 'nutritivo'는 '영양가 있는'이라는 뜻입니다.","x":["cordero: 양고기 — 고기라서 과일이 아닙니다 ✗","filete: 스테이크용 고기, 살코기 — 과일이 아닙니다 ✗","yogur: 요구르트 — 유제품입니다 ✗","plátano: 바나나 — 과일이라 정답입니다 ✓"]},{"id":"V213","q":"¿Cómo te va, Adrián? —Pues... ____, tengo bastantes problemas.","o":["de maravilla","muy bien","genial","así así"],"a":3,"k":"안부 대답 표현","t":"아드리안, 어떻게 지내? — 음... 그저 그래, 문제가 꽤 많아.","e":"'¿Cómo te va?'는 '어떻게 지내?'라는 안부 인사입니다. 뒤에 'tengo bastantes problemas(문제가 꽤 많다)'라고 했으므로 좋다는 대답은 맞지 않고, 'así así(그저 그래)'가 어울립니다. 비슷한 말로 'regular(그냥 그래)'도 있습니다.","x":["de maravilla: 아주 멋지게, 끝내주게 — 문제가 많다는 말과 모순됩니다 ✗","muy bien: 아주 잘 — 문제가 많다는 말과 맞지 않습니다 ✗","genial: 최고야 — 긍정적인 대답이라 ✗","así así: 그저 그래 — 문제가 많은 상황에 맞는 대답이라 정답입니다 ✓"]},{"id":"V214","q":"Mi abuela toma un ____ para el corazón.","o":["apartamento","campamento","medicamento","documento"],"a":2,"k":"건강 어휘","t":"우리 할머니는 심장약을 드셔.","e":"'tomar un medicamento'는 '약을 먹다'라는 뜻입니다. 'para el corazón'은 '심장을 위한'으로 심장약을 말합니다. 'medicamento'와 비슷한 말로 'medicina', 'pastilla(알약)'가 있습니다.","x":["apartamento: 아파트 — 먹는 것이 아닙니다 ✗","campamento: 캠프, 야영지 — 의미가 통하지 않습니다 ✗","medicamento: 약 — 심장을 위해 먹는 것이라 정답입니다 ✓","documento: 서류 — 먹는 것이 아닙니다 ✗"]},{"id":"V215","q":"Para mí es difícil tomar decisiones. Claramente soy un hombre ____.","o":["infeliz","experimentado","indeciso","valiente"],"a":2,"k":"성격 형용사","t":"나는 결정을 내리는 게 어려워. 분명히 우유부단한 남자야.","e":"'tomar decisiones(결정을 내리다)'가 어렵다는 사람은 'indeciso(우유부단한)'입니다. 접두사 'in-'이 '~하지 않은'이라는 뜻을 더해 'decidido(결단력 있는)'의 반대가 됩니다. 'Claramente(분명히)'는 강조하는 부사입니다.","x":["infeliz: 불행한 — 결정을 못 하는 것과 직접 관계없습니다 ✗","experimentado: 경험 많은 — 결정의 어려움과 맞지 않습니다 ✗","indeciso: 우유부단한 — 결정을 내리기 어렵다는 말과 딱 맞아 정답입니다 ✓","valiente: 용감한 — 오히려 결단력과 어울리는 말입니다 ✗"]},{"id":"V216","q":"Los ____ son productos lácteos.","o":["yogures","huevos","cereales","embutidos"],"a":0,"k":"음식 분류 어휘","t":"요구르트는 유제품이다.","e":"'productos lácteos'는 우유(leche)로 만든 '유제품'입니다. 요구르트(yogur)는 대표적인 유제품입니다. 'yogur'의 복수형은 'yogures'입니다.","x":["yogures: 요구르트 — 우유로 만든 유제품이라 정답입니다 ✓","huevos: 달걀 — 유제품이 아닙니다 ✗","cereales: 시리얼, 곡물 — 유제품이 아닙니다 ✗","embutidos: 소시지·햄 같은 육가공품 — 유제품이 아닙니다 ✗"]},{"id":"V217","q":"Lo siento, señor, está ____ hacer fotos en el interior del museo.","o":["permitido","prohibido","regular","bien"],"a":1,"k":"금지 표현","t":"죄송합니다, 손님, 박물관 내부에서는 사진 촬영이 금지되어 있습니다.","e":"'Lo siento(죄송합니다)'라고 사과하므로 할 수 없다는 말이 이어집니다. 'está prohibido + 동사원형'은 '~하는 것이 금지되어 있다'라는 표현입니다. 반대는 'está permitido(허용되어 있다)'입니다.","x":["permitido: 허용된 — 사과할 이유가 없어져 문맥과 맞지 않습니다 ✗","prohibido: 금지된 — 사과하며 안 된다고 알리는 문맥이라 정답입니다 ✓","regular: 그저 그런 — 'está regular hacer fotos'는 의미가 통하지 않습니다 ✗","bien: 괜찮은 — 사과할 이유가 없어 ✗"]},{"id":"V218","q":"Creo que voy a tener que hacer dieta porque ____ mucho últimamente.","o":["he cocinado","he salido","he jugado","he engordado"],"a":3,"k":"현재완료 동사 어휘","t":"요즘 살이 많이 쪄서 다이어트를 해야 할 것 같아.","e":"'hacer dieta(다이어트하다)'의 이유는 'engordar(살찌다)'입니다. 'he engordado'는 현재완료(최근까지 일어난 일)로 'últimamente(최근에)'와 잘 어울립니다. 반대말은 'adelgazar(살이 빠지다)'입니다.","x":["he cocinado: 요리했다 — 요리했다는 것만으로는 다이어트 이유가 되지 않습니다 ✗","he salido: 외출했다 — 다이어트와 직접 관계없습니다 ✗","he jugado: 놀았다 — 오히려 운동이 될 수 있어 이유가 아닙니다 ✗","he engordado: 살쪘다 — 다이어트의 직접적인 이유라 정답입니다 ✓"]},{"id":"V219","q":"Alfonso es muy ____; juega al baloncesto y hace natación.","o":["respetuoso","educado","deportista","cerrado"],"a":2,"k":"성격·특징 형용사","t":"알폰소는 운동을 아주 좋아해. 농구도 하고 수영도 해.","e":"농구를 하고 수영을 한다는 설명은 'deportista(운동을 좋아하는, 스포츠맨)'를 뒷받침합니다. 'deportista'는 남녀 같은 형태이며 명사(운동선수)로도 씁니다. 'jugar al baloncesto(농구하다)', 'hacer natación(수영하다)'도 함께 익히세요.","x":["respetuoso: 공손한, 남을 존중하는 — 운동 설명과 관계없습니다 ✗","educado: 예의 바른 — 운동과 관계없습니다 ✗","deportista: 운동을 좋아하는 — 농구·수영 설명과 맞아 정답입니다 ✓","cerrado: 내성적인, 폐쇄적인 — 운동 설명과 관계없습니다 ✗"]},{"id":"V220","q":"Esta película está basada en un caso ____, o sea, la historia ocurrió de verdad.","o":["inventado","real","ideal","imaginado"],"a":1,"k":"real vs inventado","t":"이 영화는 실화를 바탕으로 했어. 즉, 이야기가 실제로 일어났어.","e":"'o sea(즉, 다시 말해)' 뒤에 '이야기가 실제로 일어났다(ocurrió de verdad)'고 설명하므로 'real(실제의)'이 맞습니다. 'basado en un caso real / una historia real'은 '실화를 바탕으로 한'이라는 뜻입니다. 'real'은 '왕실의'라는 뜻도 있습니다(Real Madrid).","x":["inventado: 지어낸 — 실제로 일어났다는 설명과 반대입니다 ✗","real: 실제의 — 실화라는 설명과 일치해 정답입니다 ✓","ideal: 이상적인 — 실제로 일어났는지와 관계없습니다 ✗","imaginado: 상상한 — 실제와 반대입니다 ✗"]},{"id":"V221","q":"La comida rápida no es tan ____ como la verdura.","o":["pesada","dulce","sana","salada"],"a":2,"k":"비교 tan...como","t":"패스트푸드는 채소만큼 건강하지 않다.","e":"'no es tan + 형용사 + como...'는 '~만큼 ~하지 않다'라는 비교 표현입니다. 채소에 비해 패스트푸드가 부족한 점은 'sana(건강에 좋은)'입니다. 'comida sana'는 '건강식'이라는 뜻입니다.","x":["pesada: 무거운, 소화가 잘 안 되는 — 패스트푸드는 오히려 채소보다 더 무겁습니다 ✗","dulce: 단 — 채소가 패스트푸드보다 더 단 것은 아니라 비교가 어색합니다 ✗","sana: 건강에 좋은 — 패스트푸드가 채소만큼 건강하지 않다는 뜻으로 정답입니다 ✓","salada: 짠 — 패스트푸드가 채소보다 더 짜므로 비교가 맞지 않습니다 ✗"]},{"id":"V222","q":"La tarea ____ que más me gusta es planchar la ropa.","o":["escolar","musical","artística","doméstica"],"a":3,"k":"집안일 어휘","t":"내가 가장 좋아하는 집안일은 옷 다림질이야.","e":"'planchar la ropa(옷을 다리다)'는 집에서 하는 일이므로 'tarea doméstica(집안일)'입니다. 'doméstico'는 '가정의'라는 뜻이며, 'tareas domésticas'는 'tareas del hogar'라고도 합니다. 다른 집안일: fregar los platos(설거지하다), barrer(쓸다).","x":["escolar: 학교의 — 'tarea escolar'는 학교 숙제라 다림질과 맞지 않습니다 ✗","musical: 음악의 — 다림질과 관계없습니다 ✗","artística: 예술의 — 다림질은 예술 활동이 아닙니다 ✗","doméstica: 가정의 — 다림질은 집안일이라 정답입니다 ✓"]},{"id":"V223","q":"Ocho ____ cinco son cuarenta.","o":["por","entre","menos","más"],"a":0,"k":"사칙연산 표현","t":"8 곱하기 5는 40이다.","e":"8과 5로 40이 되려면 곱하기를 해야 합니다. 스페인어로 곱하기는 'por'입니다: 'ocho por cinco son cuarenta'. 기억하기: más(+), menos(-), por(×), entre(÷).","x":["por: 곱하기 — 8×5=40이라 정답입니다 ✓","entre: 나누기 — 8÷5=1.6이라 ✗","menos: 빼기 — 8-5=3이라 ✗","más: 더하기 — 8+5=13이라 ✗"]},{"id":"V224","q":"Lo siento, no ____ entrar aquí con animales. Está prohibido.","o":["puede","cuenta","cuesta","sabe"],"a":0,"k":"poder 허가 표현","t":"죄송합니다, 여기는 동물과 함께 들어오실 수 없습니다. 금지되어 있어요.","e":"'poder + 동사원형'은 '~할 수 있다', 'no puede'는 '~하면 안 된다(허가되지 않는다)'라는 뜻입니다. 'Está prohibido(금지되어 있다)'와 연결되므로 'no puede entrar(들어오실 수 없다)'가 맞습니다. 여기서 주어는 usted(당신)입니다.","x":["puede: poder(~할 수 있다) — 'no puede entrar(들어올 수 없다)'로 정답입니다 ✓","cuenta: contar(세다, 이야기하다) — 동사원형 entrar와 어울리지 않습니다 ✗","cuesta: costar(~하기 어렵다) — 'no cuesta entrar'는 '들어가기 어렵지 않다'는 뜻이라 금지와 맞지 않습니다 ✗","sabe: saber(~할 줄 알다) — 능력을 말하므로 금지 상황과 맞지 않습니다 ✗"]},{"id":"V225","q":"Voy a ponerme una camiseta de manga ____ porque hoy hace bastante calor.","o":["larga","ancha","grande","corta"],"a":3,"k":"옷 어휘","t":"오늘 꽤 더우니까 반팔 티셔츠를 입을 거야.","e":"'manga'는 옷의 '소매'이고, 'manga corta'는 '반팔', 'manga larga'는 '긴팔'입니다. 더운 날(hace calor)에는 반팔을 입으므로 'corta'가 정답입니다. 'ponerse'는 옷을 '입다'라는 뜻입니다.","x":["larga: 긴 — 'manga larga(긴팔)'는 더운 날에 맞지 않습니다 ✗","ancha: 넓은, 헐렁한 — 'manga ancha'는 소매 길이 표현이 아닙니다 ✗","grande: 큰 — 소매 길이를 나타내지 않습니다 ✗","corta: 짧은 — 'manga corta(반팔)'로 더운 날에 맞아 정답입니다 ✓"]},{"id":"V226","q":"No puede enviar una carta sin ____.","o":["anillo","felicitación","sello","regalo"],"a":2,"k":"우편 어휘","t":"우표 없이 편지를 보낼 수 없어요.","e":"편지를 보내려면 'sello(우표)'가 필요합니다. 'enviar una carta'는 '편지를 보내다'라는 뜻입니다. 중남미에서는 우표를 'estampilla' 또는 'timbre(멕시코)'라고도 합니다.","x":["anillo: 반지 — 편지 발송과 관계없습니다 ✗","felicitación: 축하 카드, 축하 인사 — 편지에 꼭 필요한 것이 아닙니다 ✗","sello: 우표 — 편지를 보내는 데 꼭 필요해 정답입니다 ✓","regalo: 선물 — 편지 발송에 필요하지 않습니다 ✗"]},{"id":"V227","q":"Mi profesor de yoga es buenísimo. Tiene mucha ____.","o":["impaciencia","experiencia","riqueza","maldad"],"a":1,"k":"tener + 명사","t":"내 요가 선생님은 정말 훌륭해. 경험이 아주 많아.","e":"'tener mucha experiencia'는 '경험이 많다'라는 뜻입니다. 'buenísimo(아주 훌륭한)'인 이유로 긍정적인 명사가 필요합니다. 'experiencia'는 여성 명사라 'mucha'를 씁니다.","x":["impaciencia: 조급함 — 좋은 선생님의 이유가 아닙니다 ✗","experiencia: 경험 — 'mucha experiencia(많은 경험)'로 훌륭한 선생님의 이유라 정답입니다 ✓","riqueza: 부, 재산 — 선생님의 실력과 관계없습니다 ✗","maldad: 악함, 못된 마음 — 부정적인 특성입니다 ✗"]},{"id":"V228","q":"Mario es un hombre ____ que siempre está de buen humor.","o":["alegre","odiado","triste","infeliz"],"a":0,"k":"성격 형용사","t":"마리오는 항상 기분이 좋은 쾌활한 사람이야.","e":"'estar de buen humor'는 '기분이 좋다'라는 뜻입니다. 항상 기분이 좋은 사람은 'alegre(쾌활한, 명랑한)'입니다. 'alegre'는 남녀 같은 형태이고 반대말은 'triste(슬픈)'입니다.","x":["alegre: 쾌활한, 명랑한 — 항상 기분 좋은 사람과 맞아 정답입니다 ✓","odiado: 미움받는 — 기분과 관계없고 부정적입니다 ✗","triste: 슬픈 — 기분 좋은 것과 반대입니다 ✗","infeliz: 불행한 — 기분 좋은 것과 반대입니다 ✗"]},{"id":"V229","q":"¿Te gusta mi bolso nuevo? —Sí, es muy ____.","o":["tierno","afectuoso","dulce","bonito"],"a":3,"k":"외모 평가 형용사","t":"내 새 가방 마음에 들어? — 응, 정말 예쁘다.","e":"물건(가방)의 모양을 칭찬할 때는 'bonito(예쁜)'를 씁니다. 'bolso'가 남성 명사라 'bonito'입니다. 'tierno, afectuoso, dulce'는 주로 사람의 성격이나 태도를 묘사합니다.","x":["tierno: 다정한, 부드러운 — 주로 사람·동물이나 음식의 부드러움에 씁니다 ✗","afectuoso: 애정이 많은 — 사람의 성격에 쓰는 말입니다 ✗","dulce: 달콤한, 상냥한 — 맛이나 성격에 쓰며 가방 칭찬에는 맞지 않습니다 ✗","bonito: 예쁜 — 물건의 외모를 칭찬하는 말이라 정답입니다 ✓"]},{"id":"V230","q":"¿Cuánto vale la entrada para el concierto de Juanes? —Treinta ____.","o":["euros","décadas","puntos","días"],"a":0,"k":"화폐 단위","t":"후아네스 콘서트 입장권은 얼마예요? — 30유로예요.","e":"'¿Cuánto vale...?'는 '~은 얼마예요?'라는 가격 질문입니다(costar와 같은 뜻). 가격은 돈의 단위로 대답하므로 'euros(유로)'가 정답입니다. 중남미 나라에서는 'pesos(페소)'나 'dólares(달러)' 등을 씁니다.","x":["euros: 유로(화폐) — 가격을 묻는 질문의 답이라 정답입니다 ✓","décadas: 10년(들) — 시간 단위입니다 ✗","puntos: 점수 — 가격 단위가 아닙니다 ✗","días: 날(일) — 시간 단위입니다 ✗"]},{"id":"V231","q":"¿Me ____ ese restaurante? —Sí, se come bien y el servicio es perfecto.","o":["prestas","desaconsejas","recomiendas","regalas"],"a":2,"k":"recomendar 동사","t":"그 식당 나한테 추천해? — 응, 음식도 맛있고 서비스도 완벽해.","e":"뒤의 대답이 식당의 장점을 말하므로 질문은 '추천하느냐'는 뜻이 되어야 합니다. 'recomendar'는 e→ie로 바뀌어 'recomiendas'가 됩니다. 예: Te recomiendo este libro.(이 책 추천해.)","x":["prestas: prestar(빌려주다) — 식당을 빌려준다는 것은 어색합니다 ✗","desaconsejas: desaconsejar(권하지 않다) — 대답 'Sí'와 칭찬이 어울리지 않습니다 ✗","recomiendas: recomendar(추천하다) — 칭찬하는 대답과 맞아 정답입니다 ✓","regalas: regalar(선물하다) — 식당을 선물한다는 것은 의미가 맞지 않습니다 ✗"]},{"id":"V232","q":"Los ladrones robaron objetos ____, sobre todo joyas y cuadros carísimos.","o":["valiosos","baratos","prácticos","útiles"],"a":0,"k":"가치 형용사","t":"도둑들은 값비싼 물건들, 특히 보석과 아주 비싼 그림들을 훔쳤다.","e":"'joyas(보석)'와 'cuadros carísimos(아주 비싼 그림)'를 예로 들었으므로 'valiosos(값비싼, 귀중한)'가 맞습니다. 'objetos(남성 복수)'에 맞춰 남성 복수형입니다. 'sobre todo'는 '특히'라는 뜻입니다.","x":["valiosos: 귀중한, 값비싼 — 보석과 비싼 그림 예시와 맞아 정답입니다 ✓","baratos: 싼 — 'carísimos(아주 비싼)'와 모순됩니다 ✗","prácticos: 실용적인 — 보석·그림의 특징이 아닙니다 ✗","útiles: 유용한 — 보석·그림을 설명하는 말이 아닙니다 ✗"]},{"id":"V233","q":"Le ____ una tarjeta postal a María Luisa, pero todavía no la ha recibido.","o":["mandé","di","tiré","quité"],"a":0,"k":"mandar 동사","t":"마리아 루이사에게 엽서를 보냈는데, 그녀는 아직 받지 못했어.","e":"'mandar'는 '보내다'라는 뜻으로 'enviar'와 같습니다. 뒤에 '아직 받지 못했다(no la ha recibido)'고 했으므로 우편으로 '보낸' 상황입니다. 'mandé'는 단순과거(과거의 한 시점에 끝난 일) 1인칭 형태입니다.","x":["mandé: mandar(보내다)의 과거형 — 아직 받지 못했다는 말과 맞아 정답입니다 ✓","di: dar(주다)의 과거형 — 직접 줬다면 '아직 못 받았다'는 말과 모순됩니다 ✗","tiré: tirar(버리다, 던지다)의 과거형 — 의미가 맞지 않습니다 ✗","quité: quitar(빼앗다, 치우다)의 과거형 — 의미가 맞지 않습니다 ✗"]},{"id":"V234","q":"No olvidéis la ____ de la playa. No podemos estar todo el tiempo al sol.","o":["sombrilla","bolsa","nevera","toalla"],"a":0,"k":"해변 용품 어휘","t":"해변용 파라솔 잊지 마. 계속 햇볕 아래 있을 수는 없잖아.","e":"햇볕(sol)을 피하기 위한 해변 용품은 'sombrilla(파라솔)'입니다. 'sombra(그늘)'에서 나온 단어라 기억하기 쉽습니다. 'No olvidéis'는 vosotros(너희)에게 하는 부정 명령으로 스페인식 표현입니다(중남미: No olviden).","x":["sombrilla: 파라솔 — 햇볕을 피하게 해 주므로 정답입니다 ✓","bolsa: 가방, 봉지 — 그늘을 만들지 않습니다 ✗","nevera: 아이스박스, 냉장고 — 햇볕을 막아 주지 않습니다 ✗","toalla: 수건 — 햇볕을 막아 주지 않습니다 ✗"]},{"id":"V235","q":"Tiene un nivel ____ de griego porque vivió treinta años en Atenas.","o":["inicial","básico","bajo","avanzado"],"a":3,"k":"수준 형용사","t":"그는 아테네에서 30년 살았기 때문에 그리스어 실력이 상급이야.","e":"30년을 그리스에 살았다면 언어 실력이 높을 것이므로 'avanzado(상급의)'가 맞습니다. 언어 수준은 'nivel básico(초급) → intermedio(중급) → avanzado(상급)'로 말합니다. 'tener un nivel + 형용사'로 표현합니다.","x":["inicial: 초기의, 입문의 — 30년 산 사람의 수준이 아닙니다 ✗","básico: 기초의 — 수준이 너무 낮아 ✗","bajo: 낮은 — 30년 살았다는 이유와 맞지 않습니다 ✗","avanzado: 상급의 — 오래 산 결과로 맞아 정답입니다 ✓"]},{"id":"V236","q":"En esta tienda ____ ropa muy barata.","o":["doblan","tienden","lavan","venden"],"a":3,"k":"상점 동사","t":"이 가게는 아주 싼 옷을 팔아.","e":"가게(tienda)가 옷에 대해 하는 일은 'vender(팔다)'입니다. 주어 없이 3인칭 복수 'venden'을 쓰면 '(가게 사람들이) 판다'는 일반적인 의미가 됩니다. 반대말은 'comprar(사다)'입니다.","x":["doblan: doblar(접다) — 옷을 접는 것은 가게의 주된 일을 설명하지 않습니다 ✗","tienden: tender(널다) — 빨래를 너는 것이라 ✗","lavan: lavar(빨다) — 세탁소의 일입니다 ✗","venden: vender(팔다) — 가게에서 싼 옷을 판다는 뜻으로 정답입니다 ✓"]},{"id":"V237","q":"Uno de mis ____ preferidos es el arroz con leche.","o":["animales","libros","colores","postres"],"a":3,"k":"음식 분류 어휘","t":"내가 좋아하는 디저트 중 하나는 아로스 콘 레체(우유 쌀 푸딩)야.","e":"'arroz con leche'는 쌀을 우유와 설탕, 계피로 끓인 스페인·중남미의 대표적인 디저트입니다. 그래서 'postres(디저트, 후식)'가 정답입니다. 'de postre(후식으로)'라는 표현도 자주 씁니다.","x":["animales: 동물 — 음식이 아닙니다 ✗","libros: 책 — 음식이 아닙니다 ✗","colores: 색깔 — 음식이 아닙니다 ✗","postres: 디저트 — 아로스 콘 레체는 디저트라 정답입니다 ✓"]},{"id":"V238","q":"Mi moto está en el taller porque la tienen que ____.","o":["romper","curar","reparar","averiar"],"a":2,"k":"reparar 동사","t":"내 오토바이는 수리해야 해서 정비소에 있어.","e":"'taller'는 차나 오토바이를 고치는 '정비소'입니다. 정비소에서 하는 일은 'reparar(수리하다)'입니다. 'tener que + 동사원형'은 '~해야 한다'이고, 'la'는 la moto를 가리키는 직접목적격 대명사(그것을)입니다.","x":["romper: 부수다 — 정비소에서 하는 일이 아닙니다 ✗","curar: (병을) 치료하다 — 사람이나 동물에 씁니다 ✗","reparar: 수리하다 — 정비소에서 오토바이를 고치므로 정답입니다 ✓","averiar: 고장 내다 — 수리와 반대입니다 ✗"]},{"id":"V239","q":"Mi ____ favorito es la lectura. Leo siempre que tengo tiempo libre.","o":["deber","pasatiempo","empleo","oficio"],"a":1,"k":"취미 어휘","t":"내가 가장 좋아하는 취미는 독서야. 시간 날 때마다 책을 읽어.","e":"'tiempo libre(자유 시간)'에 하는 것은 'pasatiempo(취미)'입니다. 'pasar el tiempo(시간을 보내다)'에서 나온 말로, 'afición'이나 'hobby'라고도 합니다. 'siempre que + 동사'는 '~할 때마다'입니다.","x":["deber: 의무 — 좋아서 하는 일이 아닙니다 ✗","pasatiempo: 취미 — 여가 시간에 즐기는 독서라 정답입니다 ✓","empleo: 일자리 — 직업이라 맞지 않습니다 ✗","oficio: 직업, 기술직 — 여가 활동이 아닙니다 ✗"]},{"id":"V240","q":"Tengo que ____ una cita con mi médico de cabecera.","o":["olvidar","perder","pedir","tocar"],"a":2,"k":"pedir cita","t":"주치의에게 진료 예약을 잡아야 해.","e":"'pedir (una) cita'는 병원 등에 '예약을 잡다(신청하다)'라는 고정 표현입니다. 'médico de cabecera'는 동네의 '주치의, 가정의'를 뜻합니다. 예: Quiero pedir cita para el dentista.(치과 예약하고 싶어요.)","x":["olvidar: 잊다 — '예약을 잊어야 한다'는 말이 어색합니다 ✗","perder: 잃다, 놓치다 — 예약을 놓쳐야 한다는 것은 의미가 맞지 않습니다 ✗","pedir: 요청하다 — 'pedir una cita(예약을 잡다)'로 정답입니다 ✓","tocar: 만지다, 차례이다 — cita와 함께 쓰지 않습니다 ✗"]},{"id":"V241","q":"Fernando ____ muy bien. Ayer hizo unas croquetas deliciosas.","o":["canta","pinta","dibuja","cocina"],"a":3,"k":"동사 어휘(활동)","t":"페르난도는 요리를 아주 잘해. 어제 맛있는 크로케타를 만들었어.","e":"'croquetas deliciosas(맛있는 크로케타)'를 만들었다는 근거가 있으므로 'cocinar(요리하다)'가 맞습니다. 'cocinar bien'은 '요리를 잘한다'는 뜻입니다. 크로케타는 스페인에서 즐겨 먹는 튀김 요리입니다.","x":["canta: cantar(노래하다) — 요리 근거와 맞지 않습니다 ✗","pinta: pintar(그림을 그리다, 칠하다) — 요리와 관계없습니다 ✗","dibuja: dibujar(선으로 그리다) — 요리와 관계없습니다 ✗","cocina: cocinar(요리하다) — 크로케타를 만든 것과 맞아 정답입니다 ✓"]},{"id":"V242","q":"¿Le importa dejarme pasar? Es que ____ prisa.","o":["doy","tengo","pongo","hago"],"a":1,"k":"tener prisa","t":"지나가도 될까요? 제가 좀 급해서요.","e":"'tener prisa'는 '급하다, 서두르다'라는 tener 관용 표현입니다. 한국어로는 '~하다'지만 스페인어는 'tener(가지다)'를 쓴다는 점에 주의하세요: tener hambre(배고프다), tener sueño(졸리다). 'Es que...'는 '사실은 ~라서요'라고 이유를 댈 때 씁니다.","x":["doy: dar(주다) — 'dar prisa'는 '남을 재촉하다'라는 뜻이라 맞지 않습니다 ✗","tengo: tener(가지다) — 'tengo prisa(급해요)'로 정답입니다 ✓","pongo: poner(놓다) — 'poner prisa'라는 표현은 쓰지 않습니다 ✗","hago: hacer(하다) — 'hacer prisa'는 틀린 표현입니다 ✗"]},{"id":"V243","q":"Baja el volumen de la ____, por favor.","o":["bañera","silla","tele","lámpara"],"a":2,"k":"가전 어휘","t":"텔레비전 소리 좀 줄여 줘.","e":"'volumen(음량)'이 있는 것은 'tele(텔레비전)'입니다. 'tele'는 'televisión'을 줄인 구어 표현입니다. 'bajar el volumen'은 '소리를 줄이다', 'subir el volumen'은 '소리를 키우다'입니다.","x":["bañera: 욕조 — 음량이 없습니다 ✗","silla: 의자 — 음량이 없습니다 ✗","tele: 텔레비전 — 소리를 줄일 수 있어 정답입니다 ✓","lámpara: 램프, 조명 — 소리가 나지 않습니다 ✗"]},{"id":"V244","q":"Me gusta vivir solo. No me agrada ____ mi casa con nadie.","o":["arreglar","construir","compartir","limpiar"],"a":2,"k":"compartir 동사","t":"나는 혼자 사는 게 좋아. 누구와도 집을 함께 쓰고 싶지 않아.","e":"'compartir A con B'는 'A를 B와 함께 쓰다(나누다)'라는 뜻입니다. 혼자 사는 게 좋다는 말과 연결되려면 '집을 함께 쓰고 싶지 않다'가 자연스럽습니다. 'compartir piso(집을 함께 쓰다, 셰어하다)'는 스페인에서 흔한 표현입니다.","x":["arreglar: 고치다, 정리하다 — 혼자 사는 이유와 맞지 않습니다 ✗","construir: 짓다 — 혼자 산다는 내용과 관계없습니다 ✗","compartir: 함께 쓰다, 나누다 — 혼자 사는 것을 좋아하는 이유라 정답입니다 ✓","limpiar: 청소하다 — 혼자 사는 이유로 어색합니다 ✗"]},{"id":"V245","q":"Me gustaría verte. ¿Cuándo puedes ____?","o":["quedar","elegir","mirar","decidir"],"a":0,"k":"quedar 동사","t":"너 보고 싶어. 언제 만날 수 있어?","e":"'quedar'는 친구와 '만날 약속을 하다, 만나다'라는 뜻으로 스페인에서 아주 많이 씁니다. 예: ¿Quedamos el sábado?(토요일에 만날까?) 'quedar con + 사람'은 '~와 만나기로 하다'입니다.","x":["quedar: (약속해서) 만나다 — '언제 만날 수 있어?'로 정답입니다 ✓","elegir: 고르다 — 무엇을 고를지 대상이 없어 어색합니다 ✗","mirar: 보다 — 'cuándo puedes mirar'는 만남 약속과 맞지 않습니다 ✗","decidir: 결정하다 — 만나자는 말에 대한 질문으로 어색합니다 ✗"]},{"id":"V246","q":"¿Puedes ____ el documento por correo electrónico?","o":["doblar","tirar","echar","enviar"],"a":3,"k":"이메일 동사","t":"그 서류를 이메일로 보내 줄 수 있어?","e":"'por correo electrónico(이메일로)'와 함께 쓰는 동사는 'enviar(보내다)'입니다. 'mandar'도 같은 뜻으로 쓸 수 있습니다. 예: Te envío el archivo ahora.(지금 파일 보낼게.)","x":["doblar: 접다 — 이메일과 관계없습니다 ✗","tirar: 버리다, 던지다 — 의미가 맞지 않습니다 ✗","echar: 던지다, (우편함에) 넣다 — 'echar una carta'는 우편에 쓰지만 이메일에는 쓰지 않습니다 ✗","enviar: 보내다 — 이메일로 서류를 보내는 것이라 정답입니다 ✓"]},{"id":"V247","q":"Mi hermana tiene el pelo rubio, pero quiere tenerlo ____.","o":["corto","liso","castaño","largo"],"a":2,"k":"머리색 어휘","t":"우리 언니는 머리가 금발인데, 갈색으로 하고 싶어 해.","e":"'pero(하지만)'로 금발(rubio)과 대비되는 것은 다른 머리 '색깔'이어야 합니다. 그래서 'castaño(갈색의)'가 정답입니다. 나머지 보기는 길이(corto, largo)나 모양(liso)이라 색깔 비교가 아닙니다.","x":["corto: 짧은 — 길이라 금발(색)과 대비되지 않습니다 ✗","liso: 생머리의 — 모양이라 색깔 대비가 아닙니다 ✗","castaño: 갈색의 — 금발과 대비되는 머리색이라 정답입니다 ✓","largo: 긴 — 길이라 색깔 대비가 아닙니다 ✗"]},{"id":"V248","q":"No deberías perder más peso; ya estás bastante ____.","o":["interesada","delgada","contenta","concentrada"],"a":1,"k":"체형 형용사","t":"더 이상 살 빼면 안 돼. 이미 꽤 날씬하잖아.","e":"'perder peso'는 '살을 빼다'라는 뜻입니다. 더 빼지 말라는 이유는 이미 'delgada(날씬한)'하기 때문입니다. 'deberías + 동사원형'은 '~하는 게 좋겠어'라는 부드러운 충고입니다.","x":["interesada: 관심 있는 — 체중과 관계없습니다 ✗","delgada: 날씬한 — 살을 더 빼지 말라는 이유라 정답입니다 ✓","contenta: 기쁜 — 체중 이유가 아닙니다 ✗","concentrada: 집중한 — 체중과 관계없습니다 ✗"]},{"id":"V249","q":"Alberto es mi ____. Vamos a casarnos en octubre.","o":["prometido","esposo","suegro","marido"],"a":0,"k":"관계 어휘","t":"알베르토는 내 약혼자야. 우리는 10월에 결혼할 거야.","e":"아직 결혼 전이고 곧 결혼할 사람은 'prometido(약혼자)'입니다. 'esposo, marido'는 이미 결혼한 남편이라 '결혼할 것이다'와 맞지 않습니다. 여자 약혼자는 'prometida'입니다.","x":["prometido: 약혼자 — 결혼을 앞둔 사람이라 정답입니다 ✓","esposo: 남편 — 이미 결혼한 사이라 '결혼할 것'과 맞지 않습니다 ✗","suegro: 시아버지, 장인 — 결혼할 상대가 아닙니다 ✗","marido: 남편 — 이미 결혼한 사람이라 ✗"]},{"id":"V250","q":"La ____ es un serio problema para el planeta.","o":["compasión","contaminación","pasión","expresión"],"a":1,"k":"환경 어휘","t":"오염은 지구에 심각한 문제이다.","e":"지구(planeta)에 심각한 문제가 되는 것은 'contaminación(오염)'입니다. 동사 'contaminar(오염시키다)'에서 나온 말입니다. 'contaminación del aire(대기 오염)'도 자주 씁니다.","x":["compasión: 연민 — 지구의 문제가 아닙니다 ✗","contaminación: 오염 — 지구의 심각한 문제라 정답입니다 ✓","pasión: 열정 — 문제가 아닙니다 ✗","expresión: 표현 — 의미가 통하지 않습니다 ✗"]},{"id":"V251","q":"No puedo comprar muchas cosas en esta tienda porque los precios son ____.","o":["riquísimos","buenísimos","altísimos","bajísimos"],"a":2,"k":"가격 형용사","t":"이 가게에서는 가격이 너무 비싸서 많이 살 수 없어.","e":"많이 살 수 없는 이유는 가격이 'altísimos(아주 높은)'하기 때문입니다. '-ísimo'는 '아주 ~한'이라는 최상급 어미입니다(alto → altísimo). 'precios altos/bajos'는 '비싼/싼 가격'입니다.","x":["riquísimos: 아주 맛있는 — 가격에는 쓰지 않습니다 ✗","buenísimos: 아주 좋은 — 좋은 가격이면 오히려 많이 살 수 있습니다 ✗","altísimos: 아주 높은(비싼) — 많이 살 수 없는 이유라 정답입니다 ✓","bajísimos: 아주 낮은(싼) — 싸면 많이 살 수 있어 반대입니다 ✗"]},{"id":"V252","q":"Necesito ____ una habitación en un hotel céntrico.","o":["renovar","reservar","recoger","recordar"],"a":1,"k":"reservar 동사","t":"시내 중심가 호텔에 방을 예약해야 해.","e":"호텔 방은 'reservar(예약하다)'합니다. 'céntrico'는 '시내 중심에 있는'이라는 뜻입니다. 명사형은 'reserva(예약)'로, 'Tengo una reserva(예약했어요)'라고 씁니다.","x":["renovar: 갱신하다, 새로 고치다 — 호텔 방에는 어울리지 않습니다 ✗","reservar: 예약하다 — 호텔 방 예약이라 정답입니다 ✓","recoger: 줍다, 가지러 가다 — 방과 어울리지 않습니다 ✗","recordar: 기억하다 — 방을 기억해야 한다는 것은 어색합니다 ✗"]},{"id":"V253","q":"Antes vivía sola, pero ahora comparto ____ con tres personas.","o":["piso","aula","profesión","dinero"],"a":0,"k":"compartir piso","t":"전에는 혼자 살았는데, 지금은 세 사람과 집을 함께 써.","e":"'vivía sola(혼자 살았다)'와 대비되므로 지금은 집을 함께 쓴다는 뜻이 되어야 합니다. 'compartir piso'는 '집(아파트)을 셰어하다'라는 스페인식 표현입니다. 중남미에서는 'compartir departamento/apartamento'라고 많이 합니다.","x":["piso: 아파트, 집(스페인) — 'compartir piso(집을 함께 쓰다)'로 정답입니다 ✓","aula: 교실 — 사는 곳이 아닙니다 ✗","profesión: 직업 — 혼자 살았다는 대비와 맞지 않습니다 ✗","dinero: 돈 — 사는 방식의 대비가 아닙니다 ✗"]},{"id":"V254","q":"No quiero que sigas hablando. ¡____!","o":["Duérmete","Cállate","Levántate","Acuéstate"],"a":1,"k":"재귀동사 명령형","t":"네가 계속 말하는 거 싫어. 조용히 해!","e":"계속 말하지 말라는 뜻이므로 'callarse(입을 다물다)'의 tú 명령형 '¡Cállate!(조용히 해!)'가 맞습니다. 긍정 명령에서 재귀대명사 te는 동사 뒤에 붙고, 악센트가 추가됩니다(calla + te → cállate). 'sigas'는 'seguir'의 접속법(바람을 나타내는 동사 형태)입니다.","x":["Duérmete: 자라! — 말하지 말라는 것과 맞지 않습니다 ✗","Cállate: 조용히 해! — 말을 그만하라는 뜻이라 정답입니다 ✓","Levántate: 일어나! — 말과 관계없습니다 ✗","Acuéstate: 누워 자라! — 말과 관계없습니다 ✗"]},{"id":"V255","q":"¿Cuántas ____ tiene esta palabra?","o":["frases","letras","páginas","preposiciones"],"a":1,"k":"언어 어휘","t":"이 단어는 글자가 몇 개야?","e":"단어(palabra)를 이루는 것은 'letras(글자, 철자)'입니다. '¿Cuántas...?'는 여성 복수 명사의 개수를 묻는 말입니다. 크기 순서: letra(글자) < palabra(단어) < frase(문장) < página(쪽).","x":["frases: 문장 — 단어가 문장을 포함하지 않습니다 ✗","letras: 글자 — 단어를 이루는 단위라 정답입니다 ✓","páginas: 페이지 — 단어 하나에 페이지는 없습니다 ✗","preposiciones: 전치사 — 단어 하나가 전치사를 여러 개 가지지 않습니다 ✗"]},{"id":"V256","q":"La doctora me ha recetado un jarabe porque no dejo de ____.","o":["correr","dormir","toser","beber"],"a":2,"k":"건강 동사","t":"내가 기침을 멈추지 않아서 의사 선생님이 시럽을 처방해 줬어.","e":"'jarabe(시럽 약)'는 주로 기침약입니다. 'no dejar de + 동사원형'은 '~하는 것을 멈추지 않다, 계속 ~하다'라는 뜻이라 'no dejo de toser(계속 기침한다)'가 됩니다. 'recetar'는 '처방하다'입니다.","x":["correr: 달리다 — 시럽 처방 이유가 아닙니다 ✗","dormir: 자다 — 계속 자는 것은 기침약 처방 이유가 아닙니다 ✗","toser: 기침하다 — 기침 시럽을 처방받는 이유라 정답입니다 ✓","beber: 마시다 — 처방 이유가 아닙니다 ✗"]},{"id":"V257","q":"¿Sabes ____? Se me ha roto el vestido y lo necesito para esta noche.","o":["coser","esquiar","cocinar","dibujar"],"a":0,"k":"능력 동사 어휘","t":"너 바느질할 줄 알아? 드레스가 찢어졌는데 오늘 밤에 필요하거든.","e":"찢어진 드레스(se me ha roto el vestido)를 고치려면 'coser(바느질하다)'가 필요합니다. 'saber + 동사원형'은 '~할 줄 안다'는 능력 표현입니다. 'se me ha roto'는 '(나도 모르게) 찢어졌다'는 뜻의 표현입니다.","x":["coser: 바느질하다 — 찢어진 옷을 고치는 일이라 정답입니다 ✓","esquiar: 스키 타다 — 드레스 수선과 관계없습니다 ✗","cocinar: 요리하다 — 드레스와 관계없습니다 ✗","dibujar: 그림 그리다 — 수선과 관계없습니다 ✗"]},{"id":"V258","q":"Este ____ empezó actuando en el teatro.","o":["actor","compositor","locutor","futbolista"],"a":0,"k":"직업 어휘","t":"이 배우는 연극 무대에서 연기를 시작했다.","e":"'actuar en el teatro(연극에서 연기하다)'를 하는 사람은 'actor(배우)'입니다. 여자 배우는 'actriz'입니다. 'empezar + 현재분사'는 '~하면서 시작하다'라는 뜻입니다.","x":["actor: 배우 — 연기(actuar)를 하는 사람이라 정답입니다 ✓","compositor: 작곡가 — 연기하는 사람이 아닙니다 ✗","locutor: 아나운서, 라디오 진행자 — 연극 연기와 관계없습니다 ✗","futbolista: 축구 선수 — 연기와 관계없습니다 ✗"]},{"id":"V259","q":"Mi ____ favorito de la casa es el salón.","o":["lugar","objeto","plato","aparato"],"a":0,"k":"장소 어휘","t":"우리 집에서 내가 제일 좋아하는 곳은 거실이야.","e":"'salón(거실)'은 집 안의 공간이므로 'lugar(장소, 곳)'가 맞습니다. 'lugar favorito'는 '좋아하는 장소'라는 뜻입니다. 집의 공간: salón(거실), cocina(부엌), baño(욕실).","x":["lugar: 장소, 곳 — 거실은 장소라 정답입니다 ✓","objeto: 물건 — 거실은 물건이 아닙니다 ✗","plato: 요리, 접시 — 거실과 관계없습니다 ✗","aparato: 기기, 기계 — 거실은 기계가 아닙니다 ✗"]},{"id":"V260","q":"¡Cuidado! Esos champiñones son ____.","o":["venenosos","especiales","apetitosos","peculiares"],"a":0,"k":"위험 형용사","t":"조심해! 그 버섯들은 독이 있어.","e":"'¡Cuidado!(조심해!)'라는 경고로 보아 위험한 특성이 와야 합니다. 'venenoso(독이 있는)'는 'veneno(독)'에서 나온 형용사입니다. 'champiñones(남성 복수)'에 맞춰 'venenosos'입니다.","x":["venenosos: 독이 있는 — 조심하라는 경고와 맞아 정답입니다 ✓","especiales: 특별한 — 조심할 이유가 되지 않습니다 ✗","apetitosos: 먹음직스러운 — 위험하지 않습니다 ✗","peculiares: 독특한 — 경고의 이유로 약합니다 ✗"]},{"id":"V261","q":"Una ____ es más grande que una manzana.","o":["sandía","naranja","pera","ciruela"],"a":0,"k":"과일 크기 비교","t":"수박은 사과보다 크다.","e":"'más + 형용사 + que'는 '~보다 더 ~하다'라는 비교 표현입니다. 보기 중 사과보다 확실히 큰 과일은 'sandía(수박)'입니다. 나머지(오렌지, 배, 자두)는 사과와 비슷하거나 작습니다.","x":["sandía: 수박 — 사과보다 훨씬 커서 정답입니다 ✓","naranja: 오렌지 — 사과와 크기가 비슷합니다 ✗","pera: 배(서양배) — 사과와 비슷한 크기입니다 ✗","ciruela: 자두 — 사과보다 작습니다 ✗"]},{"id":"V262","q":"Mi abuela es ____ porque mi abuelo murió.","o":["esposa","madre","viuda","mujer"],"a":2,"k":"가족 관계 어휘","t":"할아버지가 돌아가셔서 우리 할머니는 과부(미망인)야.","e":"남편이 세상을 떠난 여성은 'viuda(과부, 미망인)'라고 합니다. 아내를 잃은 남성은 'viudo'입니다. 'quedarse viudo/a'는 '배우자를 여의다'라는 표현입니다.","x":["esposa: 아내 — 남편이 돌아가신 상황을 설명하지 않습니다 ✗","madre: 어머니 — 할아버지의 죽음과 직접 관계없습니다 ✗","viuda: 과부, 미망인 — 남편을 여읜 여성이라 정답입니다 ✓","mujer: 여자, 아내 — 이유(porque)와 맞지 않습니다 ✗"]},{"id":"V263","q":"¿Puede traernos una botella de ____ mineral, por favor?","o":["agua","aceite","vino","leche"],"a":0,"k":"음료 어휘","t":"생수 한 병 가져다주시겠어요?","e":"'agua mineral'은 '생수(미네랄워터)'입니다. 'agua'는 여성 명사지만 첫 음절에 강세가 있는 a로 시작해 단수 정관사는 'el agua'를 씁니다. 식당에서 'con gas(탄산)' 또는 'sin gas(무탄산)'를 묻기도 합니다.","x":["agua: 물 — 'agua mineral(생수)'로 정답입니다 ✓","aceite: 기름 — 'mineral'과 함께 쓰지 않습니다 ✗","vino: 와인 — 'vino mineral'이라는 말은 없습니다 ✗","leche: 우유 — 'leche mineral'이라는 말은 없습니다 ✗"]},{"id":"V264","q":"El gris está de ____. Las tiendas están llenas de ropa de este color.","o":["moda","camino","oferta","suerte"],"a":0,"k":"estar de moda","t":"회색이 유행이야. 가게마다 이 색 옷이 가득해.","e":"'estar de moda'는 '유행하다'라는 고정 표현입니다. 가게들이 회색 옷으로 가득하다는 설명이 근거입니다. 반대로 '유행이 지나다'는 'pasar de moda'입니다.","x":["moda: 유행 — 'estar de moda(유행하다)'로 정답입니다 ✓","camino: 길 — 'estar de camino'는 '가는 중이다'라는 뜻이라 맞지 않습니다 ✗","oferta: 할인 — 'estar de oferta'는 '할인 중'이라 회색이라는 색깔과 맞지 않습니다 ✗","suerte: 운 — 'estar de suerte'는 '운이 좋다'로 사람에게 씁니다 ✗"]},{"id":"V265","q":"Soy ____ del doctor López. Es mi médico desde hace muchos años.","o":["compañera","colega","amiga","paciente"],"a":3,"k":"병원 어휘","t":"저는 로페스 박사님의 환자예요. 오래전부터 제 담당 의사셨어요.","e":"의사(médico)에게 진료를 받는 사람은 'paciente(환자)'입니다. 'paciente'는 남녀 같은 형태입니다. 'desde hace + 기간'은 '~ 전부터'라는 뜻으로 현재형과 함께 씁니다.","x":["compañera: (여자) 동료 — '내 의사'라는 말과 맞지 않습니다 ✗","colega: 동료(같은 직업) — 의사가 '내 의사'라면 동료 관계가 아닙니다 ✗","amiga: (여자) 친구 — '내 의사'라는 진료 관계 설명과 맞지 않습니다 ✗","paciente: 환자 — 의사에게 진료받는 사람이라 정답입니다 ✓"]},{"id":"V266","q":"Mi ____ y yo vamos a casarnos en octubre.","o":["esposo","novio","marido","amigo"],"a":1,"k":"관계 어휘","t":"내 남자친구와 나는 10월에 결혼할 거야.","e":"아직 결혼하지 않은 연인은 'novio(남자친구, 약혼자)'입니다. 'esposo, marido'는 이미 결혼한 남편이라 '결혼할 것이다'와 맞지 않습니다. 참고로 결혼식 날 신랑·신부도 'los novios'라고 합니다.","x":["esposo: 남편 — 이미 결혼한 사이라 ✗","novio: 남자친구 — 결혼을 앞둔 연인이라 정답입니다 ✓","marido: 남편 — 이미 결혼한 사이라 ✗","amigo: 친구 — 결혼할 상대로는 'novio'가 자연스럽습니다 ✗"]},{"id":"V267","q":"Están ____ porque van a volver a la ciudad que tanto les gusta.","o":["ilusionados","ansiosos","devastados","habituados"],"a":0,"k":"감정 형용사","t":"그들은 아주 좋아하는 도시로 돌아가게 되어 들떠 있어.","e":"좋아하는 도시로 돌아간다는 기쁜 이유이므로 'ilusionados(기대에 부푼, 들뜬)'가 맞습니다. 'estar ilusionado'는 좋은 일을 기대하며 설레는 마음을 나타냅니다. 'ilusión'은 스페인어에서 '착각'보다는 '설렘, 기대'라는 뜻으로 많이 씁니다.","x":["ilusionados: 기대에 부푼, 설레는 — 좋아하는 도시로 가는 기쁨이라 정답입니다 ✓","ansiosos: 불안한, 몹시 바라는 — 주로 걱정·초조함을 나타내 기쁜 이유와 덜 어울립니다 ✗","devastados: 망연자실한 — 부정적인 감정이라 ✗","habituados: 익숙해진 — 'estar habituado a'로 쓰며 감정이 아닙니다 ✗"]},{"id":"V268","q":"Paco, te presento a Lucía. — ____.","o":["Felicidades","Estoy bien","Enhorabuena","Mucho gusto"],"a":3,"k":"소개 인사 표현","t":"파코, 루시아를 소개할게. — 반가워요.","e":"누군가를 소개받았을 때는 'Mucho gusto(만나서 반가워요)'라고 합니다. 비슷한 표현으로 'Encantado/a'가 있습니다. 'Te presento a + 사람'은 '너에게 ~를 소개할게'라는 표현입니다.","x":["Felicidades: 축하해 — 생일 등을 축하할 때 씁니다 ✗","Estoy bien: 잘 지내요 — '어떻게 지내?'에 대한 대답입니다 ✗","Enhorabuena: 축하해요 — 성공·합격 등을 축하할 때 씁니다 ✗","Mucho gusto: 만나서 반가워요 — 소개받을 때 하는 인사라 정답입니다 ✓"]},{"id":"V269","q":"Manolo va a casarse el mes que viene con su ____ de toda la vida.","o":["señora","novia","esposa","ama de casa"],"a":1,"k":"관계 어휘","t":"마놀로는 다음 달에 오랜 여자친구와 결혼할 거야.","e":"결혼 전의 연인은 'novia(여자친구, 약혼녀)'입니다. 'de toda la vida'는 '평생의, 아주 오랜'이라는 뜻입니다. 'esposa(아내)'는 이미 결혼한 사이라 '결혼할 것'과 맞지 않습니다.","x":["señora: 부인, 숙녀 — 결혼 전 연인을 가리키는 말이 아닙니다 ✗","novia: 여자친구 — 결혼을 앞둔 오랜 연인이라 정답입니다 ✓","esposa: 아내 — 이미 결혼한 사이라 ✗","ama de casa: 가정주부 — 결혼 상대를 가리키는 말이 아닙니다 ✗"]},{"id":"V270","q":"Quiero cenar algo ligero, por ejemplo ____.","o":["carne con patatas","paella","ensalada","tarta"],"a":2,"k":"음식 어휘","t":"가벼운 걸로 저녁을 먹고 싶어, 예를 들면 샐러드.","e":"'algo ligero(가벼운 것)'의 예로 가장 알맞은 것은 'ensalada(샐러드)'입니다. 'ligero'는 음식이 '가벼운, 소화가 잘 되는'이라는 뜻이고 반대말은 'pesado(무거운)'입니다. 'por ejemplo'는 '예를 들어'입니다.","x":["carne con patatas: 고기와 감자 요리 — 든든한(무거운) 음식입니다 ✗","paella: 파에야 — 쌀 요리로 가벼운 저녁이 아닙니다 ✗","ensalada: 샐러드 — 가벼운 음식이라 정답입니다 ✓","tarta: 케이크 — 디저트이고 가벼운 저녁으로 맞지 않습니다 ✗"]},{"id":"V271","q":"Un rascacielos es un edificio muy ____.","o":["raro","alto","bajo","ancho"],"a":1,"k":"건물 어휘","t":"마천루는 아주 높은 건물이다.","e":"'rascacielos(마천루)'는 'rascar(긁다) + cielos(하늘)'로 '하늘을 긁을 만큼 높은 건물'이라는 뜻입니다. 그래서 'alto(높은)'가 정답입니다. 단수·복수 형태가 같아 'un rascacielos'로 씁니다.","x":["raro: 이상한 — 마천루의 정의가 아닙니다 ✗","alto: 높은 — 하늘에 닿을 듯 높은 건물이라 정답입니다 ✓","bajo: 낮은 — 정반대입니다 ✗","ancho: 넓은 — 마천루의 핵심 특징은 높이입니다 ✗"]},{"id":"V272","q":"¿Qué tipo de ____ prefieres escuchar?","o":["dibujo","música","pintura","poesía"],"a":1,"k":"취미 어휘","t":"어떤 종류의 음악을 즐겨 들어?","e":"'escuchar(듣다)'의 대상으로 알맞은 것은 'música(음악)'입니다. '¿Qué tipo de...?'는 '어떤 종류의 ~?'라는 질문입니다. 예: Prefiero escuchar música pop.(나는 팝 음악 듣는 게 좋아.)","x":["dibujo: 그림 — 듣는 것이 아니라 보는 것입니다 ✗","música: 음악 — 듣는 대상이라 정답입니다 ✓","pintura: 회화 — 보는 것입니다 ✗","poesía: 시 — 들을 수도 있지만 보통 읽는 것이고 '즐겨 듣는 종류'로는 음악이 자연스럽습니다 ✗"]},{"id":"V273","q":"¿Puede contestar a mi ____?","o":["respuesta","sensación","pregunta","deseo"],"a":2,"k":"질문·대답 어휘","t":"제 질문에 대답해 주실 수 있나요?","e":"'contestar a + 질문'은 '~에 대답하다'라는 뜻입니다. 대답하는 대상은 'pregunta(질문)'입니다. 'respuesta(대답)'와 헷갈리지 마세요: hacer una pregunta(질문하다), dar una respuesta(대답하다).","x":["respuesta: 대답 — 대답에 대답한다는 것은 어색합니다 ✗","sensación: 느낌 — 대답하는 대상이 아닙니다 ✗","pregunta: 질문 — 'contestar a mi pregunta(내 질문에 답하다)'로 정답입니다 ✓","deseo: 소원, 바람 — 대답하는 대상이 아닙니다 ✗"]},{"id":"V274","q":"Para una entrevista formal de trabajo te recomiendo llevar traje y ____.","o":["deportivas","chanclas","corbata","camiseta"],"a":2,"k":"옷 어휘","t":"공식 면접에는 정장과 넥타이를 하고 가는 걸 추천해.","e":"'entrevista formal(공식 면접)'에는 'traje(정장)'와 'corbata(넥타이)'가 어울립니다. 'llevar'는 옷을 '입고 있다, 착용하다'라는 뜻입니다. 'traje y corbata'는 정장 차림을 말하는 짝 표현입니다.","x":["deportivas: 운동화 — 공식 면접 복장이 아닙니다 ✗","chanclas: 슬리퍼, 조리 — 격식 있는 자리에 맞지 않습니다 ✗","corbata: 넥타이 — 정장과 함께 하는 공식 복장이라 정답입니다 ✓","camiseta: 티셔츠 — 캐주얼 복장입니다 ✗"]},{"id":"V275","q":"¿Qué desea beber? —Una ____, por favor.","o":["tortilla","cerveza","croqueta","ensalada"],"a":1,"k":"음료 주문 표현","t":"뭐 마시겠어요? — 맥주 한 잔 주세요.","e":"'¿Qué desea beber?'는 '무엇을 마시겠어요?'라는 질문이므로 음료가 답이 됩니다. 보기 중 음료는 'cerveza(맥주)'뿐입니다. 나머지는 모두 먹는 음식입니다.","x":["tortilla: 토르티야(스페인식 감자 오믈렛) — 음식이라 ✗","cerveza: 맥주 — 마시는 것이라 정답입니다 ✓","croqueta: 크로케타(튀김) — 음식이라 ✗","ensalada: 샐러드 — 음식이라 ✗"]},{"id":"V276","q":"No me gusta este ____ porque las comisiones son altísimas.","o":["hotel","colegio","banco","restaurante"],"a":2,"k":"금융 어휘","t":"수수료가 너무 높아서 이 은행이 마음에 들지 않아.","e":"'comisiones(수수료)'를 받는 곳은 'banco(은행)'입니다. 'altísimas'는 'alto(높은)'의 최상급으로 '아주 높은'입니다. 'cuenta bancaria(은행 계좌)'도 함께 기억하세요.","x":["hotel: 호텔 — 수수료가 주된 특징이 아닙니다 ✗","colegio: 학교 — 수수료와 관계없습니다 ✗","banco: 은행 — 수수료를 받는 곳이라 정답입니다 ✓","restaurante: 식당 — 수수료와 관계없습니다 ✗"]},{"id":"V277","q":"Aquí el clima es muy ____, apenas llueve.","o":["seco","húmedo","lluvioso","variable"],"a":0,"k":"날씨·기후 어휘","t":"여기 기후는 아주 건조해, 비가 거의 안 와.","e":"'apenas llueve(비가 거의 오지 않는다)'는 'seco(건조한)' 기후의 특징입니다. 'apenas'는 '거의 ~않다'라는 뜻입니다. 반대말은 'húmedo(습한)', 'lluvioso(비가 많은)'입니다.","x":["seco: 건조한 — 비가 거의 안 온다는 설명과 맞아 정답입니다 ✓","húmedo: 습한 — 비가 안 오는 것과 반대입니다 ✗","lluvioso: 비가 많은 — 정반대입니다 ✗","variable: 변덕스러운 — 비가 거의 안 온다는 설명과 맞지 않습니다 ✗"]},{"id":"V278","q":"En España tienen la ____ de comer turrón en Navidad.","o":["costumbre","finalidad","manía","esperanza"],"a":0,"k":"문화 어휘","t":"스페인에서는 크리스마스에 투론을 먹는 풍습이 있다.","e":"'tener la costumbre de + 동사원형'은 '~하는 풍습(습관)이 있다'라는 표현입니다. 'turrón'은 아몬드와 꿀로 만든 스페인의 크리스마스 전통 과자입니다. 개인의 습관에도 쓰입니다: Tengo la costumbre de leer antes de dormir.(나는 자기 전에 책 읽는 습관이 있어.)","x":["costumbre: 풍습, 관습 — 크리스마스 전통을 설명해 정답입니다 ✓","finalidad: 목적 — 'tener la finalidad de'는 '~할 목적이 있다'로 문맥에 맞지 않습니다 ✗","manía: 이상한 버릇, 집착 — 나라 전체의 전통을 말할 때 쓰지 않습니다 ✗","esperanza: 희망 — 의미가 맞지 않습니다 ✗"]},{"id":"V279","q":"Esta calle está llena de ____. No puedo aparcar aquí.","o":["plazas de aparcamiento","estacionamientos","aparcamientos","autos"],"a":3,"k":"교통·주차 어휘","t":"이 길은 차로 가득해. 여기에 주차할 수 없어.","e":"주차할 수 없는 이유는 길에 'autos(자동차)'가 가득하기 때문입니다. 'auto'는 중남미에서 많이 쓰는 말이고 스페인에서는 'coche'를 주로 씁니다. 'aparcar'는 스페인식이고 중남미에서는 'estacionar'를 씁니다.","x":["plazas de aparcamiento: 주차 공간 — 주차 공간이 많으면 오히려 주차할 수 있습니다 ✗","estacionamientos: 주차장 — 주차장이 많으면 주차가 가능하므로 ✗","aparcamientos: 주차장 — 역시 주차할 수 없는 이유가 되지 않습니다 ✗","autos: 자동차 — 차로 꽉 차서 주차할 수 없으므로 정답입니다 ✓"]},{"id":"V280","q":"¿Cuál es tu asignatura preferida? —La ____.","o":["pelota","geografía","calculadora","mochila"],"a":1,"k":"학교 과목 어휘","t":"네가 가장 좋아하는 과목은 뭐야? — 지리야.","e":"'asignatura'는 학교의 '과목'이고, 보기 중 과목은 'geografía(지리)'뿐입니다. 다른 과목: matemáticas(수학), historia(역사), inglés(영어). 나머지 보기는 학교 용품이나 물건입니다.","x":["pelota: 공 — 과목이 아니라 물건입니다 ✗","geografía: 지리 — 학교 과목이라 정답입니다 ✓","calculadora: 계산기 — 학용품입니다 ✗","mochila: 책가방 — 학용품입니다 ✗"]},{"id":"V281","q":"¿Cuál es para usted el principal ____ de comunicación? —La radio.","o":["medio","caso","asunto","tema"],"a":0,"k":"매체 어휘","t":"당신에게 가장 중요한 통신(소통) 수단은 무엇인가요? — 라디오입니다.","e":"'medio de comunicación'은 '(대중) 매체, 미디어'라는 고정 표현입니다. 라디오, 텔레비전, 신문 등이 해당됩니다. 'medio de transporte(교통수단)'도 같은 구조입니다.","x":["medio: 수단, 매체 — 'medio de comunicación(매체)'로 정답입니다 ✓","caso: 경우, 사건 — 'caso de comunicación'은 쓰지 않습니다 ✗","asunto: 일, 문제 — 라디오를 가리키는 말이 아닙니다 ✗","tema: 주제 — 라디오라는 답과 맞지 않습니다 ✗"]},{"id":"V282","q":"Pedro tiene celos del nuevo novio de su ex. De hecho, lo ____.","o":["odia","adora","admira","respeta"],"a":0,"k":"감정 동사","t":"페드로는 전 여자친구의 새 남자친구를 질투해. 사실 그를 싫어해.","e":"'tener celos(질투하다)'와 이어지는 부정적인 감정은 'odiar(미워하다, 싫어하다)'입니다. 'De hecho(사실, 실제로)'는 앞 내용을 강조할 때 씁니다. 'lo'는 새 남자친구를 가리키는 직접목적격 대명사(그를)입니다.","x":["odia: odiar(미워하다) — 질투와 이어지는 부정적 감정이라 정답입니다 ✓","adora: adorar(아주 좋아하다) — 질투와 반대 감정입니다 ✗","admira: admirar(존경하다) — 질투와 맞지 않습니다 ✗","respeta: respetar(존중하다) — 질투를 강조하는 말이 아닙니다 ✗"]},{"id":"V283","q":"¿Puedes poner ____ de cerveza en la nevera para que se enfríen?","o":["los platos","las cucharas","los tenedores","las latas"],"a":3,"k":"용기 어휘","t":"맥주 캔들을 냉장고에 넣어서 시원하게 해 줄래?","e":"'de cerveza'와 함께 쓰여 맥주를 담은 용기는 'latas(캔)'입니다. 'lata de cerveza'는 '맥주 캔', 'botella de cerveza'는 '맥주 병'입니다. 'para que se enfríen'은 '차가워지도록'이라는 뜻입니다.","x":["los platos: 접시 — 맥주를 담는 것이 아닙니다 ✗","las cucharas: 숟가락 — 맥주와 관계없습니다 ✗","los tenedores: 포크 — 맥주와 관계없습니다 ✗","las latas: 캔 — 'latas de cerveza(맥주 캔)'로 정답입니다 ✓"]},{"id":"V284","q":"¿Cuál es la ____ de la cantante Thalía? —Mexicana.","o":["profesión","nacionalidad","edad","dirección"],"a":1,"k":"신상 정보 어휘","t":"가수 탈리아의 국적은 뭐예요? — 멕시코예요.","e":"답이 'Mexicana(멕시코인)'이므로 질문은 'nacionalidad(국적)'를 묻는 것입니다. 국적 형용사는 여성형으로 맞춰 쓰며 첫 글자를 소문자로 씁니다(mexicano/mexicana). 탈리아(Thalía)는 멕시코의 유명 가수입니다.","x":["profesión: 직업 — 'Mexicana'는 직업이 아닙니다 ✗","nacionalidad: 국적 — '멕시코인'이라는 답과 맞아 정답입니다 ✓","edad: 나이 — 답이 숫자가 아닙니다 ✗","dirección: 주소 — 답과 맞지 않습니다 ✗"]},{"id":"V285","q":"Somos cinco personas y aquí solo hay cuatro sillas; ____ una.","o":["tiene","falta","es","debe"],"a":1,"k":"faltar 동사","t":"우리는 다섯 명인데 여기에는 의자가 네 개뿐이야. 하나가 모자라.","e":"'faltar'는 '부족하다, 모자라다'라는 뜻으로, 모자라는 것이 주어가 됩니다(Falta una silla). 다섯 명에 의자가 네 개라 하나가 부족합니다. 예: Me falta dinero.(나는 돈이 부족해.)","x":["tiene: tener(가지다) — 주어가 없어 '하나를 가진다'는 의미가 통하지 않습니다 ✗","falta: faltar(모자라다) — 의자 하나가 부족하다는 뜻이라 정답입니다 ✓","es: ser(~이다) — 'es una'는 의미가 통하지 않습니다 ✗","debe: deber(~해야 한다) — 뒤에 동사원형이 필요해 문장이 성립하지 않습니다 ✗"]},{"id":"V286","q":"Vamos a ____ los errores de vuestros ejercicios de gramática.","o":["deshacer","corregir","componer","devolver"],"a":1,"k":"교실 동사","t":"너희 문법 연습 문제의 오류를 고쳐 보자.","e":"'errores(오류, 실수)'와 함께 쓰는 동사는 'corregir(고치다, 바로잡다)'입니다. 'Vamos a + 동사원형'은 '~하자' 또는 '~할 것이다'라는 뜻입니다. 'vuestros'는 vosotros(너희)의 소유사로 스페인식이며, 중남미에서는 'sus'를 씁니다.","x":["deshacer: (한 것을) 풀다, 되돌리다 — 오류를 고친다는 뜻이 아닙니다 ✗","corregir: 고치다, 바로잡다 — 'corregir los errores(오류를 고치다)'로 정답입니다 ✓","componer: 작곡하다, 구성하다 — 오류와 함께 쓰지 않습니다 ✗","devolver: 돌려주다 — 오류를 돌려준다는 것은 어색합니다 ✗"]},{"id":"V287","q":"La ____ sirve para tostar pan y alimentos similares.","o":["tostadora","lavadora","cazuela","cafetera"],"a":0,"k":"가전 어휘","t":"토스터는 빵과 비슷한 음식을 굽는 데 쓴다.","e":"'tostar(굽다, 토스트하다)'에서 나온 'tostadora(토스터)'가 정답입니다. '-dora'는 기계 이름에 자주 붙는 어미입니다: lavadora(세탁기), cafetera(커피메이커). 'servir para + 동사원형'은 '~하는 데 쓰이다'입니다.","x":["tostadora: 토스터 — 빵을 굽는 기계라 정답입니다 ✓","lavadora: 세탁기 — 옷을 빠는 기계입니다 ✗","cazuela: 냄비(뚝배기) — 요리하는 그릇이지 빵을 굽는 기계가 아닙니다 ✗","cafetera: 커피메이커 — 커피를 만드는 기계입니다 ✗"]},{"id":"V288","q":"Mi ordenador no ____. ¡Así no puedo trabajar!","o":["anda","funciona","camina","apaga"],"a":1,"k":"funcionar 동사","t":"내 컴퓨터가 작동하지 않아. 이래서는 일을 할 수 없어!","e":"기계가 '작동하다'는 'funcionar'입니다. 'No funciona'는 '고장 났다'는 뜻으로 가장 많이 씁니다. 'ordenador(컴퓨터)'는 스페인식이고, 중남미에서는 'computadora'를 씁니다.","x":["anda: andar(걷다, (기계가) 돌아가다) — 구어로 'no anda'도 쓰긴 하지만 표준적인 정답은 funciona입니다 ✗","funciona: funcionar(작동하다) — 'no funciona(작동하지 않는다)'로 정답입니다 ✓","camina: caminar(걷다) — 기계에는 쓰지 않습니다 ✗","apaga: apagar(끄다) — 목적어가 필요하고 '컴퓨터가 끄지 않는다'는 의미가 맞지 않습니다 ✗"]},{"id":"V289","q":"Esta ____ ha diseñado algunos edificios famosísimos.","o":["pintora","escultora","arquitecta","modelo"],"a":2,"k":"직업 어휘","t":"이 건축가는 아주 유명한 건물 몇 채를 설계했다.","e":"건물(edificios)을 설계하는(diseñar) 사람은 'arquitecta(여자 건축가)'입니다. 남자는 'arquitecto'입니다. 'famosísimos'는 'famoso'의 최상급으로 '아주 유명한'입니다.","x":["pintora: (여자) 화가 — 그림을 그리는 사람입니다 ✗","escultora: (여자) 조각가 — 조각을 만드는 사람입니다 ✗","arquitecta: (여자) 건축가 — 건물을 설계하는 사람이라 정답입니다 ✓","modelo: 모델 — 건물 설계와 관계없습니다 ✗"]},{"id":"V290","q":"Mi padre siempre me ____ su coche, pero hoy lo necesita.","o":["vende","compra","presta","regala"],"a":2,"k":"prestar 동사","t":"우리 아빠는 늘 나에게 차를 빌려주시는데, 오늘은 아빠가 필요하셔.","e":"'prestar'는 '빌려주다'라는 뜻입니다. '늘 빌려주지만 오늘은 아빠가 필요하다'는 문맥이라, 차는 여전히 아빠의 것이어야 합니다. 그래서 팔거나 선물한 것이 아니라 'presta(빌려준다)'가 맞습니다.","x":["vende: vender(팔다) — 팔았다면 아빠 차가 아니게 되어 '늘'과 맞지 않습니다 ✗","compra: comprar(사다) — 의미가 통하지 않습니다 ✗","presta: prestar(빌려주다) — 아빠 차를 잠시 빌려주는 것이라 정답입니다 ✓","regala: regalar(선물하다) — 선물하면 아빠가 다시 쓸 수 없어 문맥과 맞지 않습니다 ✗"]},{"id":"V291","q":"Ana tiene muchos amigos ____. Le gusta conocer a personas de otros países.","o":["expertos","estúpidos","extranjeros","externos"],"a":2,"k":"extranjero 어휘","t":"아나는 외국인 친구가 많아. 다른 나라 사람들 만나는 걸 좋아하거든.","e":"'personas de otros países(다른 나라 사람들)'는 'extranjeros(외국인)'입니다. 'extranjero'는 형용사(외국의)와 명사(외국인) 둘 다로 쓰입니다. 'en el extranjero'는 '외국에서'라는 뜻입니다.","x":["expertos: 전문가 — 다른 나라 사람과 관계없습니다 ✗","estúpidos: 어리석은 — 의미가 맞지 않습니다 ✗","extranjeros: 외국인의 — 다른 나라 사람들이라 정답입니다 ✓","externos: 외부의 — 사람의 국적을 나타내지 않습니다 ✗"]},{"id":"V292","q":"No deberías manejar hoy. Con tanta niebla no se ve bien la ____.","o":["foto","casa","carretera","habitación"],"a":2,"k":"도로 어휘","t":"오늘은 운전하지 않는 게 좋겠어. 안개가 너무 짙어서 도로가 잘 안 보여.","e":"운전(manejar)할 때 보여야 하는 것은 'carretera(도로)'입니다. 'manejar'는 중남미에서 '운전하다'로 쓰고, 스페인에서는 'conducir'를 씁니다. 'niebla'는 '안개'입니다.","x":["foto: 사진 — 운전과 관계없습니다 ✗","casa: 집 — 운전 중에 봐야 하는 대상이 아닙니다 ✗","carretera: 도로 — 운전할 때 잘 보여야 하므로 정답입니다 ✓","habitación: 방 — 운전과 관계없습니다 ✗"]},{"id":"V293","q":"Quiero ____ para comprarme un coche.","o":["deber","ahorrar","gastar","consumir"],"a":1,"k":"돈 관련 동사","t":"차를 사려고 돈을 모으고 싶어.","e":"'ahorrar'는 '저축하다, 돈을 모으다'라는 뜻입니다. 'para + 동사원형'은 '~하기 위해'라는 목적을 나타냅니다. 반대말은 'gastar(쓰다)'입니다.","x":["deber: ~해야 한다, 빚지다 — 목적어 없이 쓰면 의미가 통하지 않습니다 ✗","ahorrar: 저축하다 — 차를 사기 위해 돈을 모으는 것이라 정답입니다 ✓","gastar: (돈을) 쓰다 — 돈을 써서 차를 사려면 먼저 모아야 하므로 문맥에 맞지 않습니다 ✗","consumir: 소비하다 — 차 구매 준비와 맞지 않습니다 ✗"]},{"id":"V294","q":"Estas tartas las hacen en la ____ de la esquina.","o":["copistería","tintorería","pastelería","lavandería"],"a":2,"k":"가게 어휘","t":"이 케이크들은 모퉁이 제과점에서 만들어.","e":"'tartas(케이크)'를 만드는 가게는 'pastelería(제과점)'입니다. 스페인어의 '-ería'는 가게 이름을 만드는 어미입니다: panadería(빵집), frutería(과일 가게). 'de la esquina'는 '모퉁이에 있는'이라는 뜻입니다.","x":["copistería: 복사 가게 — 케이크를 만들지 않습니다 ✗","tintorería: 세탁소(드라이클리닝) — 옷을 세탁하는 곳입니다 ✗","pastelería: 제과점 — 케이크를 만드는 곳이라 정답입니다 ✓","lavandería: 빨래방 — 옷을 빠는 곳입니다 ✗"]},{"id":"V295","q":"Estoy muy ____ con mi nueva vida. Tengo un buen trabajo en una ciudad fantástica.","o":["frustrado","insatisfecho","contento","triste"],"a":2,"k":"감정 형용사","t":"나는 새로운 삶에 아주 만족해. 멋진 도시에서 좋은 직장을 다니고 있어.","e":"좋은 직장과 멋진 도시라는 긍정적인 이유가 이어지므로 'contento(기쁜, 만족한)'가 맞습니다. 'estar contento con + 대상'은 '~에 만족하다'라는 뜻입니다. 나머지 보기는 모두 부정적인 감정입니다.","x":["frustrado: 좌절한 — 좋은 상황과 반대입니다 ✗","insatisfecho: 불만족한 — 긍정적인 이유와 반대입니다 ✗","contento: 기쁜, 만족한 — 좋은 직장과 도시를 이유로 정답입니다 ✓","triste: 슬픈 — 문맥과 반대입니다 ✗"]},{"id":"V296","q":"La única estación del año que realmente odio es ____.","o":["el carnaval","el invierno","la Navidad","enero"],"a":1,"k":"계절 어휘","t":"1년 중 내가 정말 싫어하는 유일한 계절은 겨울이야.","e":"'estación del año'는 '계절'이고, 보기 중 계절은 'el invierno(겨울)'뿐입니다. 사계절: la primavera(봄), el verano(여름), el otoño(가을), el invierno(겨울). 'carnaval'과 'Navidad'는 축제·명절이고 'enero'는 달(1월)입니다.","x":["el carnaval: 카니발 — 축제라 계절이 아닙니다 ✗","el invierno: 겨울 — 계절이라 정답입니다 ✓","la Navidad: 크리스마스 — 명절이라 계절이 아닙니다 ✗","enero: 1월 — 달 이름이라 계절이 아닙니다 ✗"]},{"id":"V297","q":"Nadie ____ que Juan y yo salimos juntos. Es un secreto.","o":["explica","entiende","piensa","sabe"],"a":3,"k":"saber 동사","t":"후안과 내가 사귀는 걸 아무도 몰라. 비밀이야.","e":"'saber que...'는 '~라는 사실을 알다'라는 뜻입니다. 비밀(secreto)이라고 했으므로 '아무도 모른다(Nadie sabe)'가 맞습니다. 'salir juntos'는 '함께 다니다, 사귀다'라는 표현입니다.","x":["explica: explicar(설명하다) — 비밀이라는 말과 직접 이어지지 않습니다 ✗","entiende: entender(이해하다) — '아무도 이해 못 한다'는 비밀의 의미와 다릅니다 ✗","piensa: pensar(생각하다) — 비밀이라는 이유와 맞지 않습니다 ✗","sabe: saber(알다) — 비밀이라 아무도 모른다는 뜻이라 정답입니다 ✓"]},{"id":"V298","q":"Las ____ se mueven lentamente.","o":["mariposas","moscas","abejas","tortugas"],"a":3,"k":"동물 어휘","t":"거북이는 천천히 움직인다.","e":"천천히(lentamente) 움직이는 동물의 대표는 'tortugas(거북이)'입니다. 'lentamente'는 'lento(느린)'에 '-mente'를 붙인 부사입니다. 나머지는 날아다니는 빠른 곤충입니다.","x":["mariposas: 나비 — 날아다니는 곤충으로 느림의 상징이 아닙니다 ✗","moscas: 파리 — 아주 빨리 움직입니다 ✗","abejas: 벌 — 빠르게 날아다닙니다 ✗","tortugas: 거북이 — 느리게 움직이는 동물이라 정답입니다 ✓"]},{"id":"V299","q":"No me adapto fácilmente a los ____, prefiero la rutina.","o":["cambios","espacios","estilos","usos"],"a":0,"k":"변화 어휘","t":"나는 변화에 쉽게 적응하지 못해, 일상적인 생활을 더 좋아해.","e":"'rutina(일상, 반복되는 생활)'를 좋아한다는 말과 대비되는 것은 'cambios(변화)'입니다. 'adaptarse a + 명사'는 '~에 적응하다'라는 재귀동사 표현입니다. 예: Me adapto bien a los cambios.(나는 변화에 잘 적응해.)","x":["cambios: 변화 — 루틴과 반대되는 개념이라 정답입니다 ✓","espacios: 공간 — 루틴과의 대비가 아닙니다 ✗","estilos: 스타일 — 루틴과 직접 대비되지 않습니다 ✗","usos: 용도, 사용 — 문맥과 맞지 않습니다 ✗"]},{"id":"V300","q":"Se divorciaron porque su relación era demasiado ____.","o":["sana","agradable","complicada","buena"],"a":2,"k":"관계 형용사","t":"그들은 관계가 너무 복잡해서 이혼했다.","e":"이혼(divorciarse)한 이유가 되려면 부정적인 말이 필요하므로 'complicada(복잡한, 어려운)'가 맞습니다. 'demasiado'는 '너무, 지나치게'라는 뜻으로 부정적인 정도를 나타냅니다. 'relación(관계)'이 여성 명사라 'complicada'입니다.","x":["sana: 건강한 — 이혼 이유가 되지 않습니다 ✗","agradable: 즐거운 — 이혼 이유가 되지 않습니다 ✗","complicada: 복잡한 — 이혼의 이유로 맞아 정답입니다 ✓","buena: 좋은 — 이혼 이유와 반대입니다 ✗"]},{"id":"V301","q":"No vimos el principio de la ____ porque llegamos tarde al cine.","o":["competición","exposición","película","clase"],"a":2,"k":"영화관 어휘","t":"우리는 영화관에 늦게 도착해서 영화의 시작 부분을 보지 못했다.","e":"'cine(영화관)'에서 보는 것은 película(영화)입니다. 'el principio de la película'는 '영화의 시작 부분'이라는 뜻이에요. 참고로 'ir al cine'는 '영화 보러 가다'라는 자주 쓰는 표현입니다.","x":["competición: 대회·시합이라는 뜻으로 영화관과 어울리지 않습니다 ✗","exposición: 전시회라는 뜻으로 박물관·미술관에서 보는 것입니다 ✗","película: 영화라는 뜻으로 영화관(cine)과 딱 맞습니다 ✓","clase: 수업이라는 뜻으로 영화관에서 하는 것이 아닙니다 ✗"]},{"id":"V302","q":"Siempre tiro la basura en el mismo ____.","o":["estuche","baúl","cajón","contenedor"],"a":3,"k":"생활용품 어휘","t":"나는 항상 같은 수거함에 쓰레기를 버린다.","e":"contenedor는 길가에 있는 큰 쓰레기 수거함(컨테이너)을 말합니다. 'tirar la basura'는 '쓰레기를 버리다'라는 아주 자주 쓰는 표현이에요. 집 안의 작은 쓰레기통은 papelera 또는 cubo de la basura라고 합니다.","x":["estuche: 필통·케이스라는 뜻으로 쓰레기를 버리는 곳이 아닙니다 ✗","baúl: 큰 트렁크·궤짝이라는 뜻으로 물건을 보관하는 상자입니다 ✗","cajón: 서랍이라는 뜻으로 쓰레기를 버리는 곳이 아닙니다 ✗","contenedor: 쓰레기 수거함이라는 뜻으로 문맥에 맞습니다 ✓"]},{"id":"V303","q":"No me gusta nada el color de esa pared. ¡Es muy ____!","o":["pequeño","bonito","feo","interesante"],"a":2,"k":"형용사 반의어","t":"나는 저 벽 색깔이 전혀 마음에 안 들어. 정말 못생겼어!","e":"'No me gusta nada(전혀 마음에 안 든다)'라는 부정적인 말 뒤에는 부정적인 형용사가 와야 합니다. feo는 '못생긴, 보기 흉한'이라는 뜻으로 bonito(예쁜)의 반대말이에요. 여기서 생략된 주어는 el color(남성 명사)라서 남성형 feo를 씁니다.","x":["pequeño: 작은이라는 뜻으로 색깔을 묘사하는 말로는 어색합니다 ✗","bonito: 예쁜이라는 긍정적인 뜻이라 싫다는 앞 문장과 모순됩니다 ✗","feo: 못생긴·보기 흉한이라는 뜻으로 싫어하는 이유와 맞습니다 ✓","interesante: 흥미로운이라는 긍정적인 뜻이라 문맥과 반대입니다 ✗"]},{"id":"V304","q":"¡Qué mal ____ esta colonia!","o":["escucha","ve","sabe","huele"],"a":3,"k":"감각 동사 oler","t":"이 향수 냄새 정말 고약하다!","e":"colonia는 향수(오드콜로뉴)를 뜻하므로 '냄새가 나다'라는 동사 oler가 필요합니다. oler는 불규칙 동사로 3인칭 단수가 huele예요. 'oler bien/mal'은 '좋은/나쁜 냄새가 나다'라는 뜻입니다. 예: Huele a café.(커피 냄새가 난다.)","x":["escucha: escuchar(듣다)의 형태로 소리에 쓰는 동사입니다 ✗","ve: ver(보다)의 형태로 시각에 쓰는 동사입니다 ✗","sabe: saber(맛이 나다/알다)의 형태로 맛에 쓰며 향수와 맞지 않습니다 ✗","huele: oler(냄새가 나다)의 3인칭 단수로 향수에 딱 맞습니다 ✓"]},{"id":"V305","q":"Nunca voy a ____ lo que hiciste por mí; te estoy eternamente agradecido.","o":["recordar","memorizar","olvidar","reconocer"],"a":2,"k":"동사 olvidar","t":"네가 나를 위해 해 준 일을 나는 절대 잊지 않을 거야. 너에게 영원히 감사하고 있어.","e":"'Nunca voy a + 동사원형'은 '절대 ~하지 않을 것이다'라는 뜻입니다. 감사하다는 뒷 문장과 이어지려면 '잊다'라는 olvidar가 와야 '절대 잊지 않겠다'가 됩니다. 'ir a + 동사원형'은 가까운 미래를 나타내는 아주 기본적인 표현이에요.","x":["recordar: 기억하다라는 뜻이라 '절대 기억하지 않겠다'가 되어 의미가 반대입니다 ✗","memorizar: 암기하다라는 뜻으로 공부할 때 쓰는 말이라 어색합니다 ✗","olvidar: 잊다라는 뜻으로 '절대 잊지 않겠다'가 되어 자연스럽습니다 ✓","reconocer: 알아보다·인정하다라는 뜻으로 문맥에 맞지 않습니다 ✗"]},{"id":"V306","q":"¿Te gusta la música pop?—No, solo me gusta ____.","o":["el kétchup","la mayonesa","la mostaza","la salsa"],"a":3,"k":"다의어 salsa","t":"너 팝 음악 좋아해? —아니, 나는 살사만 좋아해.","e":"salsa는 '소스'라는 뜻도 있지만 중남미에서 유래한 라틴 음악·춤 장르 '살사'를 뜻하기도 합니다. 질문이 음악(música pop)에 관한 것이므로 음악 장르가 될 수 있는 la salsa가 정답이에요. 나머지 보기는 모두 소스·양념 이름이라 음악과 관련이 없습니다.","x":["el kétchup: 케첩이라는 소스로 음악 장르가 아닙니다 ✗","la mayonesa: 마요네즈라는 소스로 음악 장르가 아닙니다 ✗","la mostaza: 머스터드(겨자)라는 소스로 음악 장르가 아닙니다 ✗","la salsa: 소스이자 음악 장르 '살사'를 뜻해 질문과 맞습니다 ✓"]},{"id":"V307","q":"¿Podrías regar las ____ del balcón mientras estoy de vacaciones?","o":["estanterías","mesas","sillas","plantas"],"a":3,"k":"동사 regar","t":"내가 휴가 가 있는 동안 발코니의 식물에 물 좀 줄 수 있어?","e":"regar는 '(식물에) 물을 주다'라는 뜻이므로 물을 줄 대상은 plantas(식물)입니다. '¿Podrías + 동사원형?'은 '~해 줄 수 있어?'라는 공손한 부탁 표현이에요. 'estar de vacaciones'는 '휴가 중이다'라는 뜻입니다.","x":["estanterías: 선반·책장이라는 뜻으로 물을 주는 대상이 아닙니다 ✗","mesas: 탁자라는 뜻으로 물을 주는 대상이 아닙니다 ✗","sillas: 의자라는 뜻으로 물을 주는 대상이 아닙니다 ✗","plantas: 식물이라는 뜻으로 regar(물을 주다)와 딱 맞습니다 ✓"]},{"id":"V308","q":"¡Qué calor! Voy a ____ la chaqueta.","o":["quitarme","tirar","ponerme","planchar"],"a":0,"k":"재귀동사 quitarse","t":"너무 덥다! 재킷을 벗어야겠어.","e":"더울 때는 옷을 '벗는' 것이 자연스러우므로 quitarse(자기 몸에서 ~을 벗다)가 정답입니다. 'quitarse la ropa(옷을 벗다)'의 반대는 'ponerse la ropa(옷을 입다)'예요. 재귀 대명사 me가 붙어 '내 몸에서' 벗는다는 의미가 됩니다.","x":["quitarme: (내 몸에서) 벗다라는 뜻으로 더운 상황과 맞습니다 ✓","tirar: 버리다·던지다라는 뜻으로 덥다고 재킷을 버리는 것은 어색합니다 ✗","ponerme: (내가) 입다라는 뜻으로 더울 때와 반대입니다 ✗","planchar: 다림질하다라는 뜻으로 더위와 관련이 없습니다 ✗"]},{"id":"V309","q":"Eso no ____ sentido.","o":["hace","da","tiene","pone"],"a":2,"k":"tener sentido","t":"그건 말이 안 돼.","e":"'tener sentido'는 '의미가 있다, 말이 되다'라는 고정 표현입니다. 영어 'make sense'를 그대로 옮겨 hacer를 쓰기 쉬운데, 표준 스페인어에서는 tener를 씁니다. 예: Tu idea tiene sentido.(네 생각은 일리가 있어.)","x":["hace: hacer(하다·만들다)로 영어 make sense를 직역한 형태라 표준이 아닙니다 ✗","da: dar(주다)는 sentido와 이 의미로 함께 쓰지 않습니다 ✗","tiene: 'tener sentido(말이 되다)'라는 고정 표현이라 정답입니다 ✓","pone: poner(놓다)는 sentido와 어울리지 않습니다 ✗"]},{"id":"V310","q":"No te ____, eres un mentiroso.","o":["tranquilizo","veo","ayudo","creo"],"a":3,"k":"동사 creer","t":"난 너를 안 믿어, 너는 거짓말쟁이야.","e":"mentiroso(거짓말쟁이)라고 했으니 '너를 믿지 않는다'가 자연스럽습니다. creer는 '믿다'라는 뜻이고, 'creer a alguien'은 '누구의 말을 믿다'입니다. 여기서 te는 '너를/너에게'라는 대명사예요.","x":["tranquilizo: tranquilizar(진정시키다)로 거짓말쟁이라는 이유와 연결되지 않습니다 ✗","veo: ver(보다)로 '너를 안 본다'는 거짓말과 논리적으로 맞지 않습니다 ✗","ayudo: ayudar(돕다)로 '안 돕는다'는 이유와 어울리지 않습니다 ✗","creo: creer(믿다)로 거짓말쟁이를 믿지 않는다는 뜻이 되어 정답입니다 ✓"]},{"id":"V311","q":"Hay tantos ____ en esta confitería que no sé cuál elegir.","o":["juegos","pasteles","sombreros","bolsos"],"a":1,"k":"가게·음식 어휘","t":"이 제과점에는 케이크가 너무 많아서 어떤 걸 골라야 할지 모르겠어.","e":"confitería는 과자·케이크를 파는 제과점입니다. 그곳에서 고를 만한 것은 pasteles(케이크·페이스트리)예요. 'tantos ... que ~'는 '너무 많은 ...라서 ~하다'라는 구문입니다.","x":["juegos: 게임·놀이라는 뜻으로 제과점에서 파는 것이 아닙니다 ✗","pasteles: 케이크·페이스트리라는 뜻으로 제과점에 딱 맞습니다 ✓","sombreros: 모자라는 뜻으로 제과점과 관련이 없습니다 ✗","bolsos: 가방이라는 뜻으로 제과점과 관련이 없습니다 ✗"]},{"id":"V312","q":"Caterina, que vive desde hace mucho tiempo en España, es de ____ griego.","o":["origen","lugar","país","estado"],"a":0,"k":"출신 표현 de origen","t":"오래전부터 스페인에 살고 있는 카테리나는 그리스 출신이다.","e":"'ser de origen + 국적 형용사'는 '~ 출신이다, ~계이다'라는 표현입니다. origen은 '기원, 출신'이라는 뜻이에요. 'desde hace mucho tiempo'는 '오래전부터'라는 뜻으로 지금까지 이어지는 기간을 나타냅니다.","x":["origen: 출신·기원이라는 뜻으로 'de origen griego(그리스 출신)'가 됩니다 ✓","lugar: 장소라는 뜻으로 'de lugar griego'는 쓰지 않는 표현입니다 ✗","país: 나라라는 뜻으로 'de país griego'는 어색한 표현입니다 ✗","estado: 상태·국가(주)라는 뜻으로 출신을 말할 때 쓰지 않습니다 ✗"]},{"id":"V313","q":"¿____ os vais a casar? —En el ayuntamiento.","o":["Quiénes","Dónde","Por qué","Cuándo"],"a":1,"k":"의문사 dónde","t":"너희 어디서 결혼할 거야? —시청에서.","e":"대답 'En el ayuntamiento(시청에서)'가 장소이므로 장소를 묻는 의문사 dónde가 필요합니다. 의문사에는 항상 악센트를 찍어요(dónde, cuándo, quién). 'os vais a casar'는 vosotros(너희) 형태로 주로 스페인에서 쓰고, 중남미에서는 'se van a casar(ustedes)'라고 합니다.","x":["Quiénes: 누구들이라는 뜻으로 사람을 묻는 의문사라 장소 대답과 맞지 않습니다 ✗","Dónde: 어디서라는 뜻으로 장소를 묻는 의문사라 정답입니다 ✓","Por qué: 왜라는 뜻으로 이유를 묻는 의문사입니다 ✗","Cuándo: 언제라는 뜻으로 시간을 묻는 의문사입니다 ✗"]},{"id":"V314","q":"Daniela es muy maja. Es un ____ hablar con ella.","o":["desastre","lío","problema","placer"],"a":3,"k":"ser un placer","t":"다니엘라는 정말 괜찮은 사람이야. 그녀와 이야기하는 건 즐거운 일이야.","e":"maja는 스페인 구어로 '착하고 호감 가는'이라는 뜻입니다. 좋은 사람과 이야기하는 것은 'un placer(기쁨, 즐거움)'이에요. 'Es un placer + 동사원형'은 '~하는 것은 즐거운 일이다'라는 표현이고, 'Un placer'는 처음 만났을 때 '반갑습니다'라는 인사로도 씁니다.","x":["desastre: 재앙·엉망이라는 부정적인 뜻으로 문맥과 반대입니다 ✗","lío: 혼란·골칫거리라는 부정적인 뜻입니다 ✗","problema: 문제라는 부정적인 뜻으로 앞 문장과 맞지 않습니다 ✗","placer: 기쁨·즐거움이라는 뜻으로 호감 가는 사람과 어울립니다 ✓"]},{"id":"V315","q":"Ignacio y Carlos se llevan como el perro y el ____. No tienen buena relación.","o":["ratón","caballo","toro","gato"],"a":3,"k":"관용 표현(동물)","t":"이그나시오와 카를로스는 개와 고양이처럼 지낸다. 사이가 좋지 않다.","e":"'llevarse como el perro y el gato'는 '개와 고양이처럼 지내다', 즉 '사이가 아주 나쁘다'라는 관용 표현입니다. 한국어의 '견원지간(개와 원숭이)'과 비슷한데 스페인어는 고양이를 씁니다. 'llevarse bien/mal'은 '사이가 좋다/나쁘다'라는 뜻이에요.","x":["ratón: 쥐라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","caballo: 말이라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","toro: 황소라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","gato: 고양이라는 뜻으로 'como el perro y el gato'라는 관용 표현입니다 ✓"]},{"id":"V316","q":"No me gusta que me toquen el pelo. Me ____.","o":["relaja","encanta","molesta","calma"],"a":2,"k":"감정 동사 molestar","t":"나는 누가 내 머리카락을 만지는 게 싫어. 그게 거슬려.","e":"'No me gusta(싫다)' 뒤에는 부정적인 감정 동사가 와야 하므로 molestar(거슬리게 하다, 귀찮게 하다)가 정답입니다. molestar는 gustar처럼 'me molesta(나를 거슬리게 한다)' 구조로 써요. 예: Me molesta el ruido.(소음이 거슬려.)","x":["relaja: relajar(긴장을 풀어 주다)로 긍정적인 뜻이라 문맥과 반대입니다 ✗","encanta: encantar(아주 좋아하다)로 싫다는 앞 문장과 모순됩니다 ✗","molesta: molestar(거슬리게 하다)로 싫다는 이유와 맞습니다 ✓","calma: calmar(진정시키다)로 긍정적인 뜻이라 맞지 않습니다 ✗"]},{"id":"V317","q":"No hay suficiente ____ para freír las papas.","o":["aceite","soda","té","agua"],"a":0,"k":"요리 어휘","t":"감자를 튀길 기름이 충분하지 않아.","e":"freír(튀기다)에는 aceite(기름)가 필요합니다. papas는 중남미와 스페인 카나리아 제도에서 쓰는 '감자'이고, 스페인 본토에서는 보통 patatas라고 해요. 'papas fritas'는 감자튀김입니다.","x":["aceite: 기름이라는 뜻으로 튀기는 데 꼭 필요합니다 ✓","soda: 탄산음료라는 뜻으로 튀김에 쓰지 않습니다 ✗","té: 차라는 뜻으로 튀김에 쓰지 않습니다 ✗","agua: 물이라는 뜻으로 물로는 튀길 수 없습니다 ✗"]},{"id":"V318","q":"Voy a ponerme los ____ para salir a correr.","o":["botines","tacones","zuecos","tenis"],"a":3,"k":"신발 어휘","t":"달리기하러 나가려고 운동화를 신을 거야.","e":"달리기(correr)할 때 신는 신발은 운동화입니다. tenis는 중남미(특히 멕시코)에서 '운동화'라는 뜻으로 쓰고, 스페인에서는 보통 zapatillas (de deporte)라고 해요. 'ponerse los zapatos'는 '신발을 신다'입니다.","x":["botines: 앵클부츠라는 뜻으로 달리기에 적합하지 않습니다 ✗","tacones: 하이힐이라는 뜻으로 달리기에 적합하지 않습니다 ✗","zuecos: 나막신·클로그라는 뜻으로 달리기용이 아닙니다 ✗","tenis: (중남미) 운동화라는 뜻으로 달리기에 딱 맞습니다 ✓"]},{"id":"V319","q":"Mi novio es muy ____, me regala flores constantemente.","o":["celoso","romántico","serio","frío"],"a":1,"k":"성격 형용사","t":"내 남자 친구는 정말 로맨틱해. 나에게 계속 꽃을 선물해 줘.","e":"꽃을 자주 선물하는 사람은 romántico(로맨틱한, 낭만적인)라고 표현합니다. 주어 mi novio가 남성이라 남성형 romántico를 써요. 'regalar'는 '선물하다'라는 뜻입니다.","x":["celoso: 질투가 많은이라는 뜻으로 꽃 선물과 연결되지 않습니다 ✗","romántico: 로맨틱한이라는 뜻으로 꽃을 선물하는 행동과 맞습니다 ✓","serio: 진지한·심각한이라는 뜻으로 문맥과 거리가 있습니다 ✗","frío: 차가운·냉정한이라는 뜻으로 꽃을 선물하는 것과 반대입니다 ✗"]},{"id":"V320","q":"Se enamoraron en cuanto se conocieron. Fue amor a ____ vista.","o":["cuarta","primera","segunda","tercera"],"a":1,"k":"관용 표현","t":"그들은 만나자마자 사랑에 빠졌다. 첫눈에 반한 사랑이었다.","e":"'amor a primera vista'는 '첫눈에 반한 사랑'이라는 고정 표현입니다. primera는 '첫 번째(여성형)'로 vista(시선, 봄)가 여성 명사라서 여성형을 씁니다. 'en cuanto'는 '~하자마자'라는 뜻이에요.","x":["cuarta: 네 번째라는 뜻으로 이 표현에 쓰지 않습니다 ✗","primera: 첫 번째라는 뜻으로 'amor a primera vista(첫눈에 반한 사랑)'가 됩니다 ✓","segunda: 두 번째라는 뜻으로 이 표현에 쓰지 않습니다 ✗","tercera: 세 번째라는 뜻으로 이 표현에 쓰지 않습니다 ✗"]},{"id":"V321","q":"Va a llover, así que no olvides el ____.","o":["dinero","informe","chubasquero","monedero"],"a":2,"k":"날씨·의류 어휘","t":"비가 올 거니까 우비 잊지 마.","e":"비가 올 때 챙기는 것은 chubasquero(우비, 비옷)입니다. chubasquero는 주로 스페인에서 쓰고, 중남미에서는 impermeable라는 말을 더 많이 써요. 우산은 paraguas라고 합니다.","x":["dinero: 돈이라는 뜻으로 비와 직접 관련이 없습니다 ✗","informe: 보고서라는 뜻으로 비와 관련이 없습니다 ✗","chubasquero: 우비라는 뜻으로 비 오는 날에 딱 맞습니다 ✓","monedero: 동전 지갑이라는 뜻으로 비와 관련이 없습니다 ✗"]},{"id":"V322","q":"Después de dos años viviendo en el extranjero, decidí regresar a mi ____.","o":["país","posición","curso","situación"],"a":0,"k":"장소 어휘 país","t":"외국에서 2년 동안 산 후, 나는 내 나라로 돌아가기로 결심했다.","e":"extranjero(외국)와 대비되는 말은 'mi país(내 나라, 조국)'입니다. 'regresar a'는 '~로 돌아가다'라는 뜻이에요. 'vivir en el extranjero'는 '외국에서 살다'라는 자주 쓰는 표현입니다.","x":["país: 나라라는 뜻으로 외국에서 고국으로 돌아간다는 문맥과 맞습니다 ✓","posición: 위치·지위라는 뜻으로 돌아갈 장소가 아닙니다 ✗","curso: 과정·강좌라는 뜻으로 문맥에 맞지 않습니다 ✗","situación: 상황이라는 뜻으로 돌아갈 장소가 아닙니다 ✗"]},{"id":"V323","q":"Casi nunca me pongo nerviosa, soy bastante ____.","o":["tranquila","ambiciosa","dura","insensible"],"a":0,"k":"성격 형용사","t":"나는 거의 긴장하지 않아. 꽤 차분한 편이야.","e":"거의 긴장하지 않는(casi nunca me pongo nerviosa) 사람은 tranquila(차분한, 침착한)입니다. 말하는 사람이 여성(nerviosa)이라 여성형 tranquila를 써요. 'ponerse nervioso/a'는 '긴장하다, 초조해지다'라는 뜻입니다.","x":["tranquila: 차분한이라는 뜻으로 긴장하지 않는 성격과 맞습니다 ✓","ambiciosa: 야심 있는이라는 뜻으로 긴장과는 관련이 없습니다 ✗","dura: 단단한·엄한이라는 뜻으로 문맥과 맞지 않습니다 ✗","insensible: 무감각한·둔감한이라는 부정적 뜻으로 어색합니다 ✗"]},{"id":"V324","q":"Siempre digo la verdad, nunca ____.","o":["entiendo","miento","conozco","comento"],"a":1,"k":"동사 mentir","t":"나는 항상 진실을 말해. 절대 거짓말하지 않아.","e":"'decir la verdad(진실을 말하다)'의 반대는 mentir(거짓말하다)입니다. mentir는 e→ie로 바뀌는 불규칙 동사라 1인칭 단수가 miento예요. nunca가 동사 앞에 오면 no 없이도 '절대 ~않다'가 됩니다.","x":["entiendo: entender(이해하다)로 진실을 말하는 것과 대비되지 않습니다 ✗","miento: mentir(거짓말하다)의 1인칭으로 진실과 반대되는 말이라 정답입니다 ✓","conozco: conocer(알다)로 문맥에 맞지 않습니다 ✗","comento: comentar(언급하다)로 문맥에 맞지 않습니다 ✗"]},{"id":"V325","q":"Esta gata ____ constantemente, pero siempre vuelve a casa.","o":["se escapa","salta","se lava","corre"],"a":0,"k":"재귀동사 escaparse","t":"이 고양이는 자꾸 도망가지만, 항상 집으로 돌아와.","e":"'pero siempre vuelve a casa(하지만 항상 집으로 돌아온다)'와 대비되려면 '도망가다, 빠져나가다'라는 escaparse가 와야 합니다. 재귀 대명사 se와 함께 'se escapa'로 써요. gata는 암고양이입니다.","x":["se escapa: 도망가다라는 뜻으로 집에 돌아온다는 뒷말과 자연스럽게 이어집니다 ✓","salta: 뛰어오르다라는 뜻으로 집에 돌아온다는 말과 대비되지 않습니다 ✗","se lava: 몸을 씻다(그루밍하다)라는 뜻으로 문맥과 맞지 않습니다 ✗","corre: 달리다라는 뜻으로 '집으로 돌아온다'와 대비되지 않습니다 ✗"]},{"id":"V326","q":"No me gusta este salón, tiene una ____ fea.","o":["pasión","decoración","acción","exposición"],"a":1,"k":"집 어휘","t":"이 거실은 마음에 안 들어. 인테리어가 별로야.","e":"salón(거실)의 꾸밈새를 말할 때는 decoración(장식, 인테리어)을 씁니다. fea(못생긴)가 여성형인 것은 decoración이 여성 명사이기 때문이에요. -ción으로 끝나는 명사는 대부분 여성입니다.","x":["pasión: 열정이라는 뜻으로 거실을 묘사하지 않습니다 ✗","decoración: 장식·인테리어라는 뜻으로 거실과 잘 어울립니다 ✓","acción: 행동·액션이라는 뜻으로 문맥에 맞지 않습니다 ✗","exposición: 전시회라는 뜻으로 거실과 관련이 없습니다 ✗"]},{"id":"V327","q":"¿De qué ____ es esta silla? —De madera.","o":["tamaño","color","material","estilo"],"a":2,"k":"재료 묻기","t":"이 의자는 무슨 재료로 만들어졌어? —나무로요.","e":"대답 'De madera(나무로)'는 재료를 나타내므로 질문은 material(재료)을 물어야 합니다. 'ser de + 재료'는 '~로 만들어졌다'라는 표현이에요. 예: La mesa es de cristal.(탁자는 유리로 되어 있다.)","x":["tamaño: 크기라는 뜻으로 '나무로'라는 대답과 맞지 않습니다 ✗","color: 색깔이라는 뜻으로 '나무로'라는 대답과 맞지 않습니다 ✗","material: 재료라는 뜻으로 'De madera'라는 대답과 딱 맞습니다 ✓","estilo: 스타일이라는 뜻으로 재료를 묻는 질문이 아닙니다 ✗"]},{"id":"V328","q":"No quiero ningún ____, no fumo.","o":["bocadillo","cigarrillo","sándwich","emparedado"],"a":1,"k":"생활 어휘","t":"담배는 필요 없어요, 저는 담배를 안 피워요.","e":"'no fumo(담배를 피우지 않는다)'라고 했으니 거절하는 대상은 cigarrillo(담배 한 개비)입니다. 'ningún'은 남성 단수 명사 앞에서 '아무 ~도'라는 뜻이에요. fumar는 '담배를 피우다'라는 동사입니다.","x":["bocadillo: (스페인) 바게트 샌드위치라는 뜻으로 흡연과 관련이 없습니다 ✗","cigarrillo: 담배라는 뜻으로 담배를 안 피운다는 이유와 맞습니다 ✓","sándwich: 샌드위치라는 뜻으로 흡연과 관련이 없습니다 ✗","emparedado: 샌드위치라는 뜻으로 흡연과 관련이 없습니다 ✗"]},{"id":"V329","q":"Esta semana estoy ____. Volveré a mi trabajo el lunes.","o":["de vacaciones","de visita","de mal humor","de compras"],"a":0,"k":"estar de 표현","t":"이번 주에 나는 휴가 중이야. 월요일에 회사에 복귀할 거야.","e":"'estar de vacaciones'는 '휴가 중이다'라는 표현입니다. 월요일에 일터로 돌아간다고 했으니 지금은 일을 쉬고 있다는 뜻이에요. 'estar de + 명사' 구조로 'estar de viaje(여행 중이다)'도 자주 씁니다.","x":["de vacaciones: 휴가 중이라는 뜻으로 월요일 복귀와 자연스럽게 연결됩니다 ✓","de visita: 방문 중이라는 뜻으로 일터 복귀와 직접 연결되지 않습니다 ✗","de mal humor: 기분이 나쁜 상태라는 뜻으로 복귀 이유와 관련이 없습니다 ✗","de compras: 쇼핑 중이라는 뜻으로 일주일 동안의 상태로 어색합니다 ✗"]},{"id":"V330","q":"El Coliseo de Roma es uno de los ____ más famosos de Italia.","o":["monumentos","colegios","mercados","ayuntamientos"],"a":0,"k":"관광 어휘","t":"로마의 콜로세움은 이탈리아에서 가장 유명한 기념물 중 하나이다.","e":"콜로세움 같은 역사적 건축물은 monumento(기념물, 유적)라고 합니다. 'uno de los + 복수 명사 + más ...'는 '가장 ~한 것들 중 하나'라는 최상급 표현이에요. 그래서 monumentos처럼 복수형을 씁니다.","x":["monumentos: 기념물·유적이라는 뜻으로 콜로세움에 딱 맞습니다 ✓","colegios: 학교라는 뜻으로 콜로세움과 맞지 않습니다 ✗","mercados: 시장이라는 뜻으로 콜로세움과 맞지 않습니다 ✗","ayuntamientos: 시청이라는 뜻으로 콜로세움과 맞지 않습니다 ✗"]},{"id":"V331","q":"Soy ____; me encanta enseñarles mi ciudad a los visitantes.","o":["guía turístico","arquitecto","librero","obrero"],"a":0,"k":"직업 어휘","t":"나는 관광 가이드야. 방문객들에게 우리 도시를 보여 주는 걸 아주 좋아해.","e":"방문객에게 도시를 안내하는 직업은 guía turístico(관광 가이드)입니다. guía는 사람을 가리킬 때 남녀 모두 같은 형태(el/la guía)를 써요. 스페인어에서 'Soy + 직업'을 말할 때는 관사 un/una를 붙이지 않습니다.","x":["guía turístico: 관광 가이드라는 뜻으로 도시를 보여 주는 일과 맞습니다 ✓","arquitecto: 건축가라는 뜻으로 관광 안내와 직접 관련이 없습니다 ✗","librero: 서점 주인·책 판매원이라는 뜻으로 문맥과 맞지 않습니다 ✗","obrero: 노동자라는 뜻으로 관광 안내와 관련이 없습니다 ✗"]},{"id":"V332","q":"¡Qué cabeza! Siempre ____ el cepillo de dientes en casa.","o":["recuerdo","olvido","pongo","lavo"],"a":1,"k":"동사 olvidar","t":"정신머리하고는! 나는 항상 칫솔을 집에 두고 와.","e":"'¡Qué cabeza!'는 건망증을 탓할 때 쓰는 감탄 표현('내 정신 좀 봐!')입니다. 'olvidar algo en casa'는 '~을 집에 두고 오다(잊고 오다)'라는 뜻이에요. olvidar의 1인칭 현재형은 olvido입니다.","x":["recuerdo: recordar(기억하다)로 건망증을 탓하는 감탄과 맞지 않습니다 ✗","olvido: olvidar(잊다)로 '집에 두고 온다'는 뜻이 되어 정답입니다 ✓","pongo: poner(놓다)로 '¡Qué cabeza!'와 자연스럽게 연결되지 않습니다 ✗","lavo: lavar(씻다)로 문맥에 맞지 않습니다 ✗"]},{"id":"V333","q":"Ernesto quiere adelgazar porque piensa que está ____.","o":["calvo","flaco","sano","gordo"],"a":3,"k":"외모 형용사","t":"에르네스토는 자기가 뚱뚱하다고 생각해서 살을 빼고 싶어 한다.","e":"adelgazar는 '살을 빼다'라는 뜻이라 그 이유는 gordo(뚱뚱한)여야 합니다. 반대말은 flaco/delgado(마른)예요. 'pensar que + 직설법'은 '~라고 생각하다'라는 구조입니다.","x":["calvo: 대머리인이라는 뜻으로 살 빼는 이유가 아닙니다 ✗","flaco: 마른이라는 뜻으로 살을 뺄 이유와 반대입니다 ✗","sano: 건강한이라는 뜻으로 살 빼는 이유가 되지 않습니다 ✗","gordo: 뚱뚱한이라는 뜻으로 살을 빼려는 이유와 맞습니다 ✓"]},{"id":"V334","q":"Martina habla tres ____: inglés, español y alemán.","o":["frases","idiomas","cursos","clases"],"a":1,"k":"언어 어휘","t":"마르티나는 영어, 스페인어, 독일어 세 가지 언어를 한다.","e":"inglés, español, alemán은 모두 언어이므로 idiomas(언어들)가 정답입니다. idioma는 -a로 끝나지만 남성 명사(el idioma)라서 'tres idiomas'처럼 씁니다. 'hablar + 언어'는 '~어를 하다'라는 뜻이에요.","x":["frases: 문장들이라는 뜻으로 영어·스페인어·독일어를 가리키지 않습니다 ✗","idiomas: 언어들이라는 뜻으로 나열된 세 언어와 맞습니다 ✓","cursos: 과정·강좌라는 뜻으로 '말한다'와 어울리지 않습니다 ✗","clases: 수업이라는 뜻으로 '말한다'와 어울리지 않습니다 ✗"]},{"id":"V335","q":"Normalmente no estoy ____ los sábados, pero este sábado tengo que trabajar.","o":["contenta","libre","conectada","ocupada"],"a":3,"k":"상태 형용사","t":"보통 토요일에는 바쁘지 않은데, 이번 토요일에는 일해야 해.","e":"'pero este sábado tengo que trabajar(하지만 이번 토요일엔 일해야 한다)'와 대비되려면 '보통은 바쁘지 않다'가 되어야 하므로 ocupada(바쁜)가 정답입니다. 'estar ocupado/a'는 '바쁘다'라는 뜻이에요. 'tener que + 동사원형'은 '~해야 한다'입니다.","x":["contenta: 기쁜이라는 뜻으로 일하는 것과 대비되지 않습니다 ✗","libre: 한가한이라는 뜻으로 '보통 한가하지 않다'가 되어 '하지만'과 맞지 않습니다 ✗","conectada: 접속한·연결된이라는 뜻으로 문맥에 맞지 않습니다 ✗","ocupada: 바쁜이라는 뜻으로 '보통 안 바쁘지만 이번엔 일한다'가 되어 자연스럽습니다 ✓"]},{"id":"V336","q":"Este ejercicio está ____, tienes que terminarlo.","o":["bien","incompleto","fatal","mal"],"a":1,"k":"상태 형용사","t":"이 연습 문제는 다 안 했어. 끝내야 해.","e":"'tienes que terminarlo(그것을 끝내야 한다)'고 했으니 연습 문제가 incompleto(미완성인, 불완전한) 상태입니다. in-은 '안, 불(不)'이라는 부정 접두사로 completo(완전한)의 반대가 돼요. lo는 el ejercicio를 받는 대명사입니다.","x":["bien: 잘된이라는 뜻으로 끝내야 할 이유가 되지 않습니다 ✗","incompleto: 미완성인이라는 뜻으로 끝내야 한다는 말과 맞습니다 ✓","fatal: 아주 엉망인이라는 뜻으로 '끝내야 한다'보다 '고쳐야 한다'에 어울립니다 ✗","mal: 틀린이라는 뜻으로 '끝내야 한다'와 직접 연결되지 않습니다 ✗"]},{"id":"V337","q":"Mis padres todavía no han recibido la postal que les ____ desde Irlanda.","o":["pedí","presté","mandé","di"],"a":2,"k":"동사 mandar","t":"부모님은 내가 아일랜드에서 보낸 엽서를 아직 받지 못했다.","e":"postal(엽서)은 '보내는' 것이므로 mandar(보내다)의 과거형 mandé가 정답입니다. enviar도 같은 뜻이에요. les는 '부모님께'라는 간접목적격 대명사(~에게)입니다.","x":["pedí: pedir(요청하다)로 엽서를 받지 못했다는 말과 맞지 않습니다 ✗","presté: prestar(빌려주다)로 엽서와 어울리지 않습니다 ✗","mandé: mandar(보내다)의 과거형으로 아일랜드에서 엽서를 보냈다는 뜻이 됩니다 ✓","di: dar(주다)로 아일랜드에서 '준다'는 것은 어색합니다 ✗"]},{"id":"V338","q":"No está bien de salud, tiene una ____ rara.","o":["imaginación","enfermedad","actitud","fantasía"],"a":1,"k":"건강 어휘","t":"그는 건강이 좋지 않다. 희귀한 병을 앓고 있다.","e":"건강이 좋지 않다고 했으니 enfermedad(병, 질병)가 맞습니다. 'una enfermedad rara'는 '희귀한/이상한 병'이에요. enfermo/a(아픈)라는 형용사도 함께 알아 두세요.","x":["imaginación: 상상력이라는 뜻으로 건강과 관련이 없습니다 ✗","enfermedad: 병이라는 뜻으로 건강이 나쁘다는 말과 맞습니다 ✓","actitud: 태도라는 뜻으로 건강 문제가 아닙니다 ✗","fantasía: 환상이라는 뜻으로 건강과 관련이 없습니다 ✗"]},{"id":"V339","q":"¿En qué frutería has comprado estas deliciosas ____?","o":["galletas","sardinas","peras","aceitunas"],"a":2,"k":"과일 어휘","t":"이 맛있는 배는 어느 과일 가게에서 샀어?","e":"frutería는 과일 가게이므로 과일인 peras(배)가 정답입니다. 스페인어에서 가게 이름은 보통 '-ería'로 끝나요: panadería(빵집), carnicería(정육점), pescadería(생선 가게).","x":["galletas: 쿠키·비스킷이라는 뜻으로 과일 가게에서 파는 것이 아닙니다 ✗","sardinas: 정어리라는 뜻으로 생선 가게에서 팝니다 ✗","peras: 배라는 과일로 과일 가게에서 팝니다 ✓","aceitunas: 올리브라는 뜻으로 과일 가게의 대표 상품이 아닙니다 ✗"]},{"id":"V340","q":"Mi ____ preferida es la margarita.","o":["flor","comida","novela","ciudad"],"a":0,"k":"꽃 어휘","t":"내가 제일 좋아하는 꽃은 데이지야.","e":"margarita는 '데이지(꽃)'라는 뜻이므로 flor(꽃)가 정답입니다. preferida(가장 좋아하는)가 여성형인 것은 flor가 여성 명사(la flor)이기 때문이에요. 참고로 margarita는 칵테일 이름이나 여성 이름으로도 쓰입니다.","x":["flor: 꽃이라는 뜻으로 데이지(margarita)와 맞습니다 ✓","comida: 음식이라는 뜻으로 데이지와 맞지 않습니다 ✗","novela: 소설이라는 뜻으로 데이지와 맞지 않습니다 ✗","ciudad: 도시라는 뜻으로 데이지와 맞지 않습니다 ✗"]},{"id":"V341","q":"El hijo de mi tío es mi ____.","o":["hermano","padre","sobrino","primo"],"a":3,"k":"가족 어휘","t":"삼촌의 아들은 나의 사촌이다.","e":"tío(삼촌·외삼촌)의 아들은 primo(사촌)입니다. 여자 사촌은 prima예요. 함께 알아 둘 가족 어휘: sobrino(조카), nieto(손자), abuelo(할아버지).","x":["hermano: 형제라는 뜻으로 부모의 아들입니다 ✗","padre: 아버지라는 뜻으로 맞지 않습니다 ✗","sobrino: 조카라는 뜻으로 형제의 아들입니다 ✗","primo: 사촌이라는 뜻으로 삼촌의 아들과 맞습니다 ✓"]},{"id":"V342","q":"Llevar un bolso con mucho peso es malo para la ____.","o":["cara","cabeza","barriga","espalda"],"a":3,"k":"신체 어휘","t":"무거운 가방을 들고 다니는 것은 등(허리)에 좋지 않다.","e":"무거운 가방을 메면 espalda(등, 허리)가 아픕니다. 'ser malo para ~'는 '~에 나쁘다'라는 표현이에요. 예: Fumar es malo para la salud.(흡연은 건강에 나쁘다.)","x":["cara: 얼굴이라는 뜻으로 무거운 가방과 관련이 적습니다 ✗","cabeza: 머리라는 뜻으로 무거운 가방과 관련이 적습니다 ✗","barriga: 배라는 뜻으로 무거운 가방과 관련이 적습니다 ✗","espalda: 등이라는 뜻으로 무거운 가방을 메면 부담이 가는 곳입니다 ✓"]},{"id":"V343","q":"Voy a comprar un par de ____ nuevos para el sofá.","o":["roperos","espejos","cuadros","cojines"],"a":3,"k":"가구·소품 어휘","t":"소파에 놓을 새 쿠션을 두 개 살 거야.","e":"소파 위에 놓는 것은 cojines(쿠션들)입니다. 단수는 cojín이고 복수가 되면 악센트가 사라져 cojines가 돼요. 'un par de'는 '두 개의, 몇 개의'라는 뜻입니다.","x":["roperos: 옷장이라는 뜻으로 소파에 놓는 물건이 아닙니다 ✗","espejos: 거울이라는 뜻으로 소파에 놓는 물건이 아닙니다 ✗","cuadros: 그림·액자라는 뜻으로 벽에 거는 물건입니다 ✗","cojines: 쿠션이라는 뜻으로 소파에 딱 맞는 소품입니다 ✓"]},{"id":"V344","q":"Elena y Fernando ya no están ____; están separados desde el año pasado.","o":["enojados","nerviosos","juntos","solos"],"a":2,"k":"관계 형용사","t":"엘레나와 페르난도는 더 이상 함께하지 않는다. 작년부터 헤어진 상태이다.","e":"separados(헤어진)와 대비되는 말은 juntos(함께인, 사귀는)입니다. 'ya no'는 '더 이상 ~않다'라는 뜻이에요. 참고로 보기의 enojados(화난)는 중남미식이고, 스페인에서는 enfadados를 주로 씁니다.","x":["enojados: (중남미) 화난이라는 뜻으로 헤어졌다는 말과 대비되지 않습니다 ✗","nerviosos: 긴장한이라는 뜻으로 헤어짐과 관련이 없습니다 ✗","juntos: 함께인이라는 뜻으로 '더 이상 함께가 아니다 = 헤어졌다'가 됩니다 ✓","solos: 혼자인이라는 뜻으로 '더 이상 혼자가 아니다'는 헤어짐과 반대입니다 ✗"]},{"id":"V345","q":"No oigo bien. ¿Puedes hablar más ____?","o":["rápido","bajo","alto","despacio"],"a":2,"k":"부사 alto","t":"잘 안 들려. 좀 더 크게 말해 줄 수 있어?","e":"잘 들리지 않을 때는 '더 크게' 말해 달라고 하므로 alto가 정답입니다. 'hablar alto'는 '크게 말하다', 'hablar bajo'는 '작게 말하다'예요. 여기서 alto는 '키가 큰'이 아니라 '소리가 큰'이라는 부사로 쓰였습니다.","x":["rápido: 빠르게라는 뜻으로 들리지 않는 문제를 해결하지 못합니다 ✗","bajo: 작게라는 뜻으로 오히려 더 안 들립니다 ✗","alto: 크게라는 뜻으로 잘 안 들린다는 말과 맞습니다 ✓","despacio: 천천히라는 뜻으로 소리 크기와 관련이 없습니다 ✗"]},{"id":"V346","q":"Vivimos en una región ____, no llueve mucho.","o":["húmeda","seca","fría","calurosa"],"a":1,"k":"기후 형용사","t":"우리는 건조한 지역에 살아. 비가 많이 오지 않아.","e":"비가 많이 오지 않는 지역은 seca(건조한)입니다. región이 여성 명사라 여성형 seca를 써요. 반대말은 húmeda(습한)입니다.","x":["húmeda: 습한이라는 뜻으로 비가 적다는 말과 반대입니다 ✗","seca: 건조한이라는 뜻으로 비가 적다는 설명과 맞습니다 ✓","fría: 추운이라는 뜻으로 비의 양과 직접 관련이 없습니다 ✗","calurosa: 더운이라는 뜻으로 비의 양과 직접 관련이 없습니다 ✗"]},{"id":"V347","q":"Me ____ aprender otros idiomas; es bastante difícil para mí.","o":["cuesta","atrae","sorprende","fascina"],"a":0,"k":"동사 costar","t":"나는 다른 언어를 배우는 게 힘들어. 나에게는 꽤 어려워.","e":"'me cuesta + 동사원형'은 '나는 ~하는 것이 힘들다(어렵다)'라는 표현입니다. costar는 원래 '값이 ~이다'라는 뜻이지만 gustar처럼 'me cuesta' 구조로 쓰면 '힘이 들다'라는 뜻이 돼요. 예: Me cuesta levantarme temprano.(일찍 일어나는 게 힘들다.)","x":["cuesta: costar(힘이 들다)로 '어렵다'는 뒷말과 맞습니다 ✓","atrae: atraer(끌리다)로 긍정적 뜻이라 어렵다는 말과 맞지 않습니다 ✗","sorprende: sorprender(놀라게 하다)로 어렵다는 이유와 연결되지 않습니다 ✗","fascina: fascinar(매료시키다)로 긍정적 뜻이라 문맥과 맞지 않습니다 ✗"]},{"id":"V348","q":"Cuando llego a casa, me quito la ropa del trabajo y me pongo ropa ____.","o":["inapropiada","cómoda","pegada","apretada"],"a":1,"k":"의류 형용사","t":"집에 도착하면 나는 작업복을 벗고 편한 옷을 입는다.","e":"집에서 입는 옷은 보통 cómoda(편안한) 옷입니다. ropa가 여성 명사라 여성형 cómoda를 써요. 'quitarse(벗다)'와 'ponerse(입다)'가 짝을 이루는 문장입니다.","x":["inapropiada: 부적절한이라는 뜻으로 집에서 갈아입는 옷으로 어색합니다 ✗","cómoda: 편안한이라는 뜻으로 집에서 입는 옷과 맞습니다 ✓","pegada: 몸에 달라붙는이라는 뜻으로 편하게 쉬려는 문맥과 맞지 않습니다 ✗","apretada: 꽉 끼는이라는 뜻으로 편한 옷과 반대입니다 ✗"]},{"id":"V349","q":"Vamos a aliñar la ensalada con un poco de aceite, sal y ____.","o":["pimienta","fresa","melón","papa"],"a":0,"k":"양념 어휘","t":"샐러드에 올리브유 조금, 소금, 후추로 간을 하자.","e":"aliñar는 '(샐러드 등에) 양념하다, 드레싱하다'라는 뜻입니다. aceite(기름), sal(소금)과 함께 쓰는 양념은 pimienta(후추)예요. 'sal y pimienta(소금과 후추)'는 아주 자주 쓰는 짝입니다.","x":["pimienta: 후추라는 뜻으로 소금·기름과 함께 쓰는 양념입니다 ✓","fresa: 딸기라는 뜻으로 양념이 아닙니다 ✗","melón: 멜론이라는 뜻으로 양념이 아닙니다 ✗","papa: 감자라는 뜻으로 양념이 아닙니다 ✗"]},{"id":"V350","q":"Con la ____ de precios, no puedo comprar tantas cosas como antes.","o":["bajada","subida","reducción","salida"],"a":1,"k":"경제 어휘","t":"물가 상승 때문에 예전만큼 많은 것을 살 수 없다.","e":"예전만큼 살 수 없다는 것은 가격이 올랐다는 뜻이므로 subida(상승, 인상)가 정답입니다. 'subida de precios'는 '물가 상승'이에요. 반대말은 bajada(하락)입니다.","x":["bajada: 하락이라는 뜻으로 값이 내리면 더 많이 살 수 있어 반대입니다 ✗","subida: 상승이라는 뜻으로 덜 살 수 있다는 결과와 맞습니다 ✓","reducción: 감소·인하라는 뜻으로 문맥과 반대입니다 ✗","salida: 출구·출발이라는 뜻으로 가격과 어울리지 않습니다 ✗"]},{"id":"V351","q":"Ana María es muy ____. Si quiere decirte algo, te lo dice sin rodeos.","o":["directa","frágil","ambiciosa","elegante"],"a":0,"k":"성격 형용사","t":"아나 마리아는 아주 직설적이야. 너에게 뭔가 말하고 싶으면 돌려 말하지 않고 바로 말해.","e":"'sin rodeos(돌려 말하지 않고)'로 말하는 사람은 directa(직설적인)입니다. 주어가 여성이라 여성형 directa를 써요. 'te lo dice'에서 te는 '너에게', lo는 '그것을'이라는 뜻입니다.","x":["directa: 직설적인이라는 뜻으로 돌려 말하지 않는다는 설명과 맞습니다 ✓","frágil: 연약한이라는 뜻으로 말하는 방식과 관련이 없습니다 ✗","ambiciosa: 야심 있는이라는 뜻으로 말하는 방식과 관련이 없습니다 ✗","elegante: 우아한이라는 뜻으로 말하는 방식과 관련이 없습니다 ✗"]},{"id":"V352","q":"A esta ____ le faltan algunas hojas.","o":["papelera","libreta","goma","pizarra"],"a":1,"k":"학용품 어휘","t":"이 공책은 몇 장이 빠져 있다.","e":"hojas(종이 장)가 있는 물건은 libreta(공책, 수첩)입니다. 'faltar'는 '부족하다, 빠져 있다'라는 뜻으로 gustar처럼 'A esta libreta le faltan ~(이 공책에 ~가 없다)' 구조로 써요. hoja는 '나뭇잎'이라는 뜻도 있습니다.","x":["papelera: 휴지통이라는 뜻으로 종이 장이 있는 물건이 아닙니다 ✗","libreta: 공책이라는 뜻으로 종이 장(hojas)이 있는 물건입니다 ✓","goma: 지우개라는 뜻으로 종이 장이 없습니다 ✗","pizarra: 칠판이라는 뜻으로 종이 장이 없습니다 ✗"]},{"id":"V353","q":"Mi coche está averiado, por eso está en el ____.","o":["taller","banco","colegio","estanco"],"a":0,"k":"장소 어휘","t":"내 차가 고장 나서 정비소에 있다.","e":"고장 난(averiado) 차를 고치는 곳은 taller(정비소, 작업장)입니다. 'por eso'는 '그래서'라는 뜻이에요. coche는 스페인에서, carro·auto는 중남미에서 주로 쓰는 '자동차'입니다.","x":["taller: 정비소라는 뜻으로 고장 난 차를 고치는 곳입니다 ✓","banco: 은행이라는 뜻으로 차를 고치는 곳이 아닙니다 ✗","colegio: 학교라는 뜻으로 차를 고치는 곳이 아닙니다 ✗","estanco: (스페인) 담배·우표 판매점이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V354","q":"Las ____ son animales de cuatro patas.","o":["gallinas","ovejas","abejas","ballenas"],"a":1,"k":"동물 어휘","t":"양은 다리가 네 개인 동물이다.","e":"다리가 네 개(cuatro patas)인 동물은 보기 중 ovejas(양)뿐입니다. pata는 동물의 다리이고, 사람의 다리는 pierna라고 해요. 동물은 다리를 셀 때 꼭 pata를 씁니다.","x":["gallinas: 닭이라는 뜻으로 다리가 두 개입니다 ✗","ovejas: 양이라는 뜻으로 다리가 네 개인 동물입니다 ✓","abejas: 꿀벌이라는 뜻으로 다리가 여섯 개입니다 ✗","ballenas: 고래라는 뜻으로 다리가 없습니다 ✗"]},{"id":"V355","q":"Eva y su madre se parecen mucho, son como dos gotas de ____.","o":["agua","leche","aceite","jugo"],"a":0,"k":"관용 표현","t":"에바와 그녀의 엄마는 정말 많이 닮았다. 붕어빵이다.","e":"'ser como dos gotas de agua(물 두 방울 같다)'는 '똑 닮았다'라는 관용 표현입니다. 한국어의 '붕어빵이다'와 비슷해요. 'parecerse'는 '서로 닮다'라는 재귀동사입니다.","x":["agua: 물이라는 뜻으로 'dos gotas de agua(똑 닮음)'라는 관용 표현입니다 ✓","leche: 우유라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","aceite: 기름이라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","jugo: (중남미) 주스라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V356","q":"La miel es ____.","o":["ácida","amarga","dulce","picante"],"a":2,"k":"맛 형용사","t":"꿀은 달다.","e":"miel(꿀)의 맛은 dulce(단)입니다. miel은 여성 명사(la miel)지만 dulce는 남녀 형태가 같아요. 맛 형용사: ácido(신), amargo(쓴), salado(짠), picante(매운).","x":["ácida: 신이라는 뜻으로 꿀의 맛이 아닙니다 ✗","amarga: 쓴이라는 뜻으로 꿀의 맛이 아닙니다 ✗","dulce: 단이라는 뜻으로 꿀의 맛과 맞습니다 ✓","picante: 매운이라는 뜻으로 꿀의 맛이 아닙니다 ✗"]},{"id":"V357","q":"No se preocupe, vamos a ____ su problema lo antes posible.","o":["empeorar","crear","imaginar","solucionar"],"a":3,"k":"동사 solucionar","t":"걱정하지 마세요, 가능한 한 빨리 당신의 문제를 해결해 드리겠습니다.","e":"'No se preocupe(걱정 마세요)'와 이어지려면 문제를 solucionar(해결하다)해야 합니다. 'lo antes posible'은 '가능한 한 빨리'라는 자주 쓰는 표현이에요. se preocupe는 usted(당신)에게 쓰는 공손한 명령형입니다.","x":["empeorar: 악화시키다라는 뜻으로 걱정 말라는 말과 반대입니다 ✗","crear: 만들다라는 뜻으로 '문제를 만든다'는 문맥과 맞지 않습니다 ✗","imaginar: 상상하다라는 뜻으로 문맥과 맞지 않습니다 ✗","solucionar: 해결하다라는 뜻으로 걱정 말라는 말과 자연스럽게 이어집니다 ✓"]},{"id":"V358","q":"Este es un pueblo con encanto, por eso lo ____ tantas personas.","o":["detestan","critican","odian","visitan"],"a":3,"k":"동사 visitar","t":"이곳은 매력 있는 마을이라서 그렇게 많은 사람들이 방문한다.","e":"'con encanto(매력 있는)' 마을이니 사람들이 visitan(방문한다)이 자연스럽습니다. lo는 el pueblo를 받는 직접목적격 대명사(그것을)예요. 주어 tantas personas가 복수라 동사도 3인칭 복수입니다.","x":["detestan: 몹시 싫어하다라는 뜻으로 매력 있다는 말과 반대입니다 ✗","critican: 비판하다라는 뜻으로 매력 있다는 이유와 맞지 않습니다 ✗","odian: 미워하다라는 뜻으로 매력 있다는 말과 반대입니다 ✗","visitan: 방문하다라는 뜻으로 매력 있는 마을이라는 이유와 맞습니다 ✓"]},{"id":"V359","q":"Esta autora ____ libros para niños.","o":["borra","rompe","tira","escribe"],"a":3,"k":"동사 escribir","t":"이 작가는 어린이 책을 쓴다.","e":"autora(작가)가 책에 하는 일은 escribir(쓰다)입니다. autor/autora는 '저자, 작가'라는 뜻이에요. 'libros para niños'는 '어린이를 위한 책, 동화책'입니다.","x":["borra: borrar(지우다)로 작가가 책에 하는 일이 아닙니다 ✗","rompe: romper(찢다·부수다)로 작가의 일이 아닙니다 ✗","tira: tirar(버리다)로 작가의 일이 아닙니다 ✗","escribe: escribir(쓰다)로 작가가 책을 쓴다는 뜻이 되어 정답입니다 ✓"]},{"id":"V360","q":"Perdone, ¿qué ____ tienen estos pantalones? —Cincuenta dólares.","o":["talla","marca","tela","precio"],"a":3,"k":"쇼핑 어휘","t":"실례합니다, 이 바지는 가격이 얼마예요? —50달러입니다.","e":"대답이 'Cincuenta dólares(50달러)'이므로 precio(가격)를 묻는 질문입니다. 가격은 보통 '¿Cuánto cuesta(n)?'로도 물어요. pantalones는 바지 한 벌이라도 복수형을 씁니다.","x":["talla: 옷 사이즈라는 뜻으로 '50달러'라는 대답과 맞지 않습니다 ✗","marca: 브랜드라는 뜻으로 '50달러'라는 대답과 맞지 않습니다 ✗","tela: 천·옷감이라는 뜻으로 '50달러'라는 대답과 맞지 않습니다 ✗","precio: 가격이라는 뜻으로 '50달러'라는 대답과 딱 맞습니다 ✓"]},{"id":"V361","q":"Aquí no ____ fumar, está prohibido.","o":["pueden","requieren","saben","necesitan"],"a":0,"k":"동사 poder (허락)","t":"여기서는 담배를 피울 수 없어요. 금지되어 있습니다.","e":"poder + 동사원형은 '~할 수 있다'이며, 부정형 'no pueden'은 '~하면 안 된다(허락되지 않는다)'라는 뜻이 됩니다. 주어가 생략된 3인칭 복수(ustedes/사람들)라서 pueden을 써요. prohibido는 '금지된'이라는 뜻입니다.","x":["pueden: poder(~할 수 있다)로 '피우면 안 된다'는 금지의 뜻이 됩니다 ✓","requieren: requerir(요구하다)로 금지의 의미가 되지 않습니다 ✗","saben: saber(~할 줄 알다)로 능력을 말해 금지와 맞지 않습니다 ✗","necesitan: necesitar(필요하다)로 금지의 의미가 되지 않습니다 ✗"]},{"id":"V362","q":"¿Qué prefieres tomar? ¿Té o café? —Me ____ igual, las dos bebidas me gustan.","o":["hace","va","da","pone"],"a":2,"k":"관용 표현 dar igual","t":"차랑 커피 중 뭐 마실래? —아무거나 상관없어, 둘 다 좋아.","e":"'me da igual'은 '나는 상관없어, 아무래도 좋아'라는 고정 표현입니다. gustar처럼 '나에게(me)' 구조로 쓰며 동사는 dar(주다)를 써요. 비슷한 표현으로 'me da lo mismo'도 있습니다.","x":["hace: hacer는 igual과 함께 '상관없다'는 뜻으로 쓰지 않습니다 ✗","va: ir는 igual과 함께 이 뜻으로 쓰지 않습니다 ✗","da: 'me da igual(상관없어)'라는 고정 표현이라 정답입니다 ✓","pone: poner는 igual과 함께 이 뜻으로 쓰지 않습니다 ✗"]},{"id":"V363","q":"¿Qué ____ te gusta más? —El pop.","o":["color","ropa","estilo musical","género de cine"],"a":2,"k":"음악 어휘","t":"어떤 음악 스타일을 제일 좋아해? —팝이야.","e":"대답 'El pop(팝)'은 음악 장르이므로 estilo musical(음악 스타일)을 묻는 질문입니다. '¿Qué + 명사 + te gusta más?'는 '어떤 ~을 제일 좋아해?'라는 표현이에요. 대답의 관사 el은 남성 명사 estilo에 맞춘 것입니다.","x":["color: 색깔이라는 뜻으로 '팝'이라는 대답과 맞지 않습니다 ✗","ropa: 옷이라는 뜻으로 여성 명사라 대답의 el과도 맞지 않습니다 ✗","estilo musical: 음악 스타일이라는 뜻으로 '팝'이라는 대답과 맞습니다 ✓","género de cine: 영화 장르라는 뜻으로 '팝'은 영화 장르가 아닙니다 ✗"]},{"id":"V364","q":"Me encantaría ____ la vuelta al mundo.","o":["hacer","dar","tener","tomar"],"a":1,"k":"dar la vuelta","t":"세계 일주를 하고 싶어.","e":"'dar la vuelta al mundo'는 '세계 일주를 하다'라는 고정 표현입니다. vuelta는 '한 바퀴'라는 뜻이고 동사 dar와 함께 써요. 'dar una vuelta'는 '한 바퀴 돌다, 산책하다'라는 뜻으로도 자주 씁니다.","x":["hacer: hacer(하다)는 이 고정 표현에 쓰지 않습니다 ✗","dar: 'dar la vuelta al mundo(세계 일주하다)'라는 고정 표현입니다 ✓","tener: tener(가지다)는 vuelta와 이 뜻으로 쓰지 않습니다 ✗","tomar: tomar(잡다·마시다)는 vuelta와 이 뜻으로 쓰지 않습니다 ✗"]},{"id":"V365","q":"Mi ____ es vivir en Suiza; es un país precioso y muy avanzado.","o":["obligación","deber","sueño","tarea"],"a":2,"k":"명사 sueño","t":"내 꿈은 스위스에 사는 거야. 아주 아름답고 선진화된 나라거든.","e":"스위스가 아름답다고 하며 살고 싶어하는 것은 sueño(꿈, 소망)입니다. sueño는 '잠, 졸음'이라는 뜻도 있어 'tener sueño(졸리다)'로도 쓰여요. 'Mi sueño es + 동사원형'은 '내 꿈은 ~하는 것이다'입니다.","x":["obligación: 의무라는 뜻으로 원해서 하고 싶은 일과 맞지 않습니다 ✗","deber: 의무·숙제라는 뜻으로 소망과 맞지 않습니다 ✗","sueño: 꿈이라는 뜻으로 살고 싶은 소망과 맞습니다 ✓","tarea: 과제·일이라는 뜻으로 소망과 맞지 않습니다 ✗"]},{"id":"V366","q":"Hoy no he hecho nada especial. He tenido un día ____.","o":["raro","normal","único","inusual"],"a":1,"k":"형용사 normal","t":"오늘은 특별한 일을 하지 않았어. 평범한 하루였어.","e":"'nada especial(특별한 것 없음)'과 이어지려면 normal(평범한, 보통의)이 와야 합니다. 'He hecho', 'He tenido'는 현재완료(오늘처럼 아직 끝나지 않은 시간에 일어난 일)예요. 나머지 보기는 모두 '특별한'에 가까운 뜻입니다.","x":["raro: 이상한이라는 뜻으로 특별한 일이 없었다는 말과 맞지 않습니다 ✗","normal: 평범한이라는 뜻으로 특별한 일이 없었다는 말과 맞습니다 ✓","único: 유일한·특별한이라는 뜻으로 문맥과 반대입니다 ✗","inusual: 흔치 않은이라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V367","q":"No sé a qué partido voy a ____ en las próximas elecciones.","o":["cuidar","conservar","votar","proteger"],"a":2,"k":"정치 어휘","t":"다음 선거에서 어느 정당에 투표할지 모르겠어.","e":"elecciones(선거)에서 partido(정당)에 하는 것은 votar(투표하다)입니다. 'votar a + 정당/사람'은 '~에게 투표하다'예요. 여기서 a가 앞으로 나와 'a qué partido'가 되었습니다.","x":["cuidar: 돌보다라는 뜻으로 선거와 관련이 없습니다 ✗","conservar: 보존하다라는 뜻으로 선거와 관련이 없습니다 ✗","votar: 투표하다라는 뜻으로 선거·정당과 맞습니다 ✓","proteger: 보호하다라는 뜻으로 선거와 관련이 없습니다 ✗"]},{"id":"V368","q":"En esa biblioteca hay miles de ____.","o":["juegos","libros","caramelos","joyas"],"a":1,"k":"장소 어휘","t":"그 도서관에는 수천 권의 책이 있다.","e":"biblioteca(도서관)에 있는 것은 libros(책)입니다. 주의: librería는 '서점'이고 biblioteca가 '도서관'이에요. 'miles de'는 '수천의'라는 뜻입니다.","x":["juegos: 게임이라는 뜻으로 도서관의 대표적인 소장품이 아닙니다 ✗","libros: 책이라는 뜻으로 도서관에 딱 맞습니다 ✓","caramelos: 사탕이라는 뜻으로 도서관과 관련이 없습니다 ✗","joyas: 보석이라는 뜻으로 도서관과 관련이 없습니다 ✗"]},{"id":"V369","q":"Nunca voy a la ópera porque me ____.","o":["interesa","aburre","atrae","fascina"],"a":1,"k":"감정 동사 aburrir","t":"나는 오페라가 지루해서 절대 안 가.","e":"오페라에 절대 가지 않는 이유는 그것이 me aburre(나를 지루하게 한다)이기 때문입니다. aburrir는 gustar처럼 'me aburre' 구조로 써요. 형용사 'estar aburrido(지루하다)'도 함께 알아 두세요.","x":["interesa: interesar(관심을 끌다)로 안 간다는 이유가 되지 않습니다 ✗","aburre: aburrir(지루하게 하다)로 안 가는 이유와 맞습니다 ✓","atrae: atraer(끌어당기다)로 긍정적 뜻이라 반대입니다 ✗","fascina: fascinar(매료시키다)로 긍정적 뜻이라 반대입니다 ✗"]},{"id":"V370","q":"El ____ sirve para medir la temperatura.","o":["cable","termómetro","ventilador","enchufe"],"a":1,"k":"가전·도구 어휘","t":"온도계는 온도를 재는 데 쓰인다.","e":"temperatura(온도)를 medir(재다)하는 도구는 termómetro(온도계, 체온계)입니다. 'servir para + 동사원형'은 '~하는 데 쓰이다'라는 표현이에요. 예: Las tijeras sirven para cortar.(가위는 자르는 데 쓴다.)","x":["cable: 케이블·전선이라는 뜻으로 온도를 재지 않습니다 ✗","termómetro: 온도계라는 뜻으로 온도를 재는 도구입니다 ✓","ventilador: 선풍기라는 뜻으로 온도를 재지 않습니다 ✗","enchufe: 콘센트·플러그라는 뜻으로 온도를 재지 않습니다 ✗"]},{"id":"V371","q":"Los peatones deben ____ por la acera.","o":["cantar","saltar","caminar","correr"],"a":2,"k":"교통 어휘","t":"보행자는 인도로 걸어야 한다.","e":"peatones(보행자)는 acera(인도)로 caminar(걷다)해야 합니다. 'deber + 동사원형'은 '~해야 한다(의무)'라는 뜻이에요. caminar는 andar와 같은 뜻으로 중남미에서 특히 많이 씁니다.","x":["cantar: 노래하다라는 뜻으로 보행 규칙과 맞지 않습니다 ✗","saltar: 뛰어오르다라는 뜻으로 보행 규칙과 맞지 않습니다 ✗","caminar: 걷다라는 뜻으로 보행자가 인도에서 할 일과 맞습니다 ✓","correr: 달리다라는 뜻으로 보행자의 의무와는 거리가 있습니다 ✗"]},{"id":"V372","q":"Vamos a pasar unos días en una casa rural porque queremos estar en ____.","o":["el campo","la ciudad","el casco urbano","la capital"],"a":0,"k":"장소 어휘","t":"우리는 시골에 있고 싶어서 전원주택에서 며칠 보낼 거야.","e":"casa rural은 시골에 있는 전원주택(농촌 민박)이므로 'el campo(시골, 들판)'가 정답입니다. 'estar en el campo'는 '시골에 있다'라는 뜻이에요. 나머지 보기는 모두 도시를 뜻합니다.","x":["el campo: 시골이라는 뜻으로 전원주택과 맞습니다 ✓","la ciudad: 도시라는 뜻으로 전원주택과 반대입니다 ✗","el casco urbano: 시가지(도심)라는 뜻으로 전원주택과 맞지 않습니다 ✗","la capital: 수도라는 뜻으로 전원주택과 맞지 않습니다 ✗"]},{"id":"V373","q":"Esta zona es muy tranquila; ____ hay ruido.","o":["continuamente","apenas","todo el rato","siempre"],"a":1,"k":"부사 apenas","t":"이 지역은 아주 조용해서 소음이 거의 없다.","e":"apenas는 '거의 ~않다'라는 부정의 뜻을 가진 부사입니다. 조용한 동네이므로 '소음이 거의 없다'가 자연스러워요. 예: Apenas como carne.(나는 고기를 거의 안 먹는다.)","x":["continuamente: 끊임없이라는 뜻으로 조용하다는 말과 반대입니다 ✗","apenas: 거의 ~않다라는 뜻으로 조용한 지역과 맞습니다 ✓","todo el rato: 내내라는 뜻으로 조용하다는 말과 반대입니다 ✗","siempre: 항상이라는 뜻으로 조용하다는 말과 반대입니다 ✗"]},{"id":"V374","q":"No sé nada de la ____ porque hace días que no veo las noticias.","o":["verdad","actualidad","realidad","curiosidad"],"a":1,"k":"시사 어휘","t":"며칠째 뉴스를 안 봐서 최근 소식을 전혀 몰라.","e":"actualidad는 '시사, 최근 소식'이라는 뜻으로 noticias(뉴스)와 연결됩니다. 'hace días que no ~'는 '며칠째 ~하지 않았다'라는 표현이에요. 주의: actual은 영어 actual(실제의)이 아니라 '현재의'라는 뜻입니다.","x":["verdad: 진실이라는 뜻으로 뉴스를 안 본 것과 직접 연결되지 않습니다 ✗","actualidad: 시사·최근 소식이라는 뜻으로 뉴스와 맞습니다 ✓","realidad: 현실이라는 뜻으로 뉴스를 안 본 것과 연결되지 않습니다 ✗","curiosidad: 호기심이라는 뜻으로 문맥과 맞지 않습니다 ✗"]},{"id":"V375","q":"No pierdo el tiempo con la ropa; siempre llevo ____ vaqueros y una camiseta.","o":["paraguas","relojes","collares","pantalones"],"a":3,"k":"의류 어휘","t":"나는 옷에 시간을 낭비하지 않아. 항상 청바지와 티셔츠를 입어.","e":"vaqueros(청)와 함께 쓰는 옷은 pantalones(바지)로, 'pantalones vaqueros'는 '청바지'입니다. llevar는 여기서 '(옷을) 입고 있다'라는 뜻이에요. 'perder el tiempo'는 '시간을 낭비하다'입니다.","x":["paraguas: 우산이라는 뜻으로 vaqueros와 함께 쓰지 않습니다 ✗","relojes: 시계라는 뜻으로 vaqueros와 함께 쓰지 않습니다 ✗","collares: 목걸이라는 뜻으로 vaqueros와 함께 쓰지 않습니다 ✗","pantalones: 바지라는 뜻으로 'pantalones vaqueros(청바지)'가 됩니다 ✓"]},{"id":"V376","q":"Duerme tan profundamente que casi nunca ____ la alarma del móvil.","o":["entiende","escucha","conoce","levanta"],"a":1,"k":"동사 escuchar","t":"그는 너무 깊이 자서 휴대폰 알람을 거의 못 듣는다.","e":"alarma(알람)는 소리이므로 escuchar(듣다)가 정답입니다. 원래 oír가 '들리다', escuchar가 '귀 기울여 듣다'지만 일상에서는 escuchar도 '들리다'의 뜻으로 많이 써요. móvil은 스페인식, 중남미에서는 celular라고 합니다.","x":["entiende: entender(이해하다)로 알람 소리에 어울리지 않습니다 ✗","escucha: escuchar(듣다)로 알람 소리를 못 듣는다는 뜻이 됩니다 ✓","conoce: conocer(알다·알게 되다)로 알람과 어울리지 않습니다 ✗","levanta: levantar(들어 올리다)로 알람과 어울리지 않습니다 ✗"]},{"id":"V377","q":"¿A qué hora empieza la película? — ____.","o":["Esta noche","En una semana","A las dos","Mañana"],"a":2,"k":"시간 표현","t":"영화는 몇 시에 시작해? —2시에.","e":"'¿A qué hora?(몇 시에?)'라고 물으면 'A las + 시각'으로 대답합니다. 시각 앞에는 여성 관사 la/las를 써요(1시는 'a la una'). 나머지 보기는 정확한 시각이 아니라 날짜나 때를 말합니다.","x":["Esta noche: 오늘 밤이라는 뜻으로 '몇 시에'에 대한 정확한 답이 아닙니다 ✗","En una semana: 일주일 후라는 뜻으로 시각을 말하지 않습니다 ✗","A las dos: 2시에라는 뜻으로 '몇 시에'에 정확히 답합니다 ✓","Mañana: 내일이라는 뜻으로 시각을 말하지 않습니다 ✗"]},{"id":"V378","q":"Vengo a este supermercado porque todos sus productos son de ____.","o":["comodidad","cualidad","calidad","cantidad"],"a":2,"k":"혼동 어휘 calidad","t":"나는 모든 제품이 품질이 좋아서 이 슈퍼마켓에 와.","e":"'ser de calidad'는 '품질이 좋다, 고급이다'라는 표현입니다. calidad(품질)와 cualidad(특성, 자질), cantidad(양)는 철자가 비슷해 헷갈리기 쉬워요. 제품에 대해서는 calidad를 씁니다.","x":["comodidad: 편안함이라는 뜻으로 제품 품질을 나타내지 않습니다 ✗","cualidad: 사람·사물의 특성이라는 뜻으로 'de cualidad'라고 쓰지 않습니다 ✗","calidad: 품질이라는 뜻으로 'de calidad(품질 좋은)'가 됩니다 ✓","cantidad: 양이라는 뜻으로 'de cantidad'는 이 의미로 쓰지 않습니다 ✗"]},{"id":"V379","q":"Ángela tiene la misma ____ que yo. Las dos tenemos treinta años.","o":["profesión","edad","afición","nacionalidad"],"a":1,"k":"나이 어휘 edad","t":"앙헬라는 나와 나이가 같다. 우리 둘 다 서른 살이다.","e":"'treinta años(서른 살)'라는 설명은 edad(나이)에 관한 것입니다. 'tener la misma edad que ~'는 '~와 나이가 같다'라는 표현이에요. 나이는 동사 tener로 말합니다: Tengo treinta años.","x":["profesión: 직업이라는 뜻으로 서른 살이라는 설명과 맞지 않습니다 ✗","edad: 나이라는 뜻으로 둘 다 서른 살이라는 설명과 맞습니다 ✓","afición: 취미라는 뜻으로 나이와 관련이 없습니다 ✗","nacionalidad: 국적이라는 뜻으로 나이와 관련이 없습니다 ✗"]},{"id":"V380","q":"La ____ es una prenda que se pone en el cuello.","o":["pulsera","bufanda","diadema","falda"],"a":1,"k":"의류 어휘","t":"목도리는 목에 두르는 옷가지이다.","e":"cuello(목)에 두르는 것은 bufanda(목도리, 머플러)입니다. prenda는 '옷가지, 의류 한 점'이라는 뜻이에요. 'ponerse'는 '(옷 등을) 입다·두르다'입니다.","x":["pulsera: 팔찌라는 뜻으로 손목에 합니다 ✗","bufanda: 목도리라는 뜻으로 목에 두릅니다 ✓","diadema: 머리띠라는 뜻으로 머리에 합니다 ✗","falda: 치마라는 뜻으로 허리 아래에 입습니다 ✗"]},{"id":"V381","q":"No tengo un ____ propio, por eso aparco mi carro en la calle.","o":["garaje","jardín","despacho","trastero"],"a":0,"k":"집 어휘","t":"나는 내 차고가 없어서 차를 길에 주차한다.","e":"차를 aparcar(주차하다)하는 곳은 garaje(차고)입니다. carro는 중남미에서 쓰는 '자동차'로 스페인에서는 coche라고 해요. aparcar도 스페인식이고 중남미에서는 estacionar나 parquear를 씁니다.","x":["garaje: 차고라는 뜻으로 차를 주차하는 곳입니다 ✓","jardín: 정원이라는 뜻으로 차를 세우는 곳이 아닙니다 ✗","despacho: 사무실·서재라는 뜻으로 차와 관련이 없습니다 ✗","trastero: 창고(잡동사니 방)라는 뜻으로 차를 세우는 곳이 아닙니다 ✗"]},{"id":"V382","q":"¿Quieren un ____ antes de comer?","o":["postre","aperitivo","pastel","bizcocho"],"a":1,"k":"식사 어휘","t":"식사 전에 아페리티프(간단한 전채) 드실래요?","e":"'antes de comer(식사 전에)' 먹거나 마시는 것은 aperitivo(식전주·간단한 안주)입니다. postre(디저트)는 식사 후에 먹어요. 스페인에서는 점심 전에 aperitivo를 즐기는 문화가 있습니다.","x":["postre: 디저트라는 뜻으로 식사 후에 먹습니다 ✗","aperitivo: 식전주·전채라는 뜻으로 식사 전에 먹습니다 ✓","pastel: 케이크라는 뜻으로 보통 식사 전에 먹지 않습니다 ✗","bizcocho: 카스텔라 같은 스펀지케이크라는 뜻으로 식사 전에 먹는 것이 아닙니다 ✗"]},{"id":"V383","q":"Durante la tormenta, el ____ estaba casi negro.","o":["árbol","sol","arcoíris","cielo"],"a":3,"k":"날씨 어휘","t":"폭풍이 몰아치는 동안 하늘이 거의 검은색이었다.","e":"tormenta(폭풍우) 때 검게 변하는 것은 cielo(하늘)입니다. 'estaba casi negro'는 과거의 상태를 묘사하는 불완료 과거예요. 날씨 어휘: nube(구름), lluvia(비), trueno(천둥).","x":["árbol: 나무라는 뜻으로 폭풍 때 검게 변하는 것이 아닙니다 ✗","sol: 해라는 뜻으로 폭풍 때는 보이지 않습니다 ✗","arcoíris: 무지개라는 뜻으로 검은색이 아닙니다 ✗","cielo: 하늘이라는 뜻으로 폭풍 때 어두워지는 것과 맞습니다 ✓"]},{"id":"V384","q":"En esa playa hacen surf porque las ____ suelen ser altas.","o":["ondas","rocas","olas","temperaturas"],"a":2,"k":"혼동 어휘 ola","t":"그 해변은 파도가 보통 높아서 사람들이 서핑을 한다.","e":"서핑을 하려면 바다의 olas(파도)가 높아야 합니다. onda는 전파·음파 같은 '파동'이나 머리카락 웨이브를 말해 헷갈리기 쉬워요. 'soler + 동사원형'은 '보통 ~하다'라는 뜻입니다.","x":["ondas: 파동(전파·음파)이라는 뜻으로 바다 파도를 가리키지 않습니다 ✗","rocas: 바위라는 뜻으로 서핑의 조건이 아닙니다 ✗","olas: 파도라는 뜻으로 서핑과 딱 맞습니다 ✓","temperaturas: 기온이라는 뜻으로 '높다'와 쓸 수 있지만 서핑 이유로 맞지 않습니다 ✗"]},{"id":"V385","q":"Esta es la ____ que usamos para transportar las mercancías.","o":["goma","furgoneta","carpeta","pizarra"],"a":1,"k":"교통 어휘","t":"이것이 우리가 물건을 운반할 때 쓰는 승합차다.","e":"mercancías(상품, 화물)를 transportar(운반하다)하는 데 쓰는 것은 furgoneta(밴, 승합차)입니다. furgoneta는 스페인에서 주로 쓰고, 중남미에서는 camioneta나 van이라고도 해요. 'la que usamos'는 '우리가 사용하는 것'이라는 관계절입니다.","x":["goma: 지우개·고무라는 뜻으로 물건을 운반하지 않습니다 ✗","furgoneta: 밴·승합차라는 뜻으로 화물 운반에 쓰입니다 ✓","carpeta: 서류철이라는 뜻으로 화물 운반에 쓰지 않습니다 ✗","pizarra: 칠판이라는 뜻으로 화물 운반에 쓰지 않습니다 ✗"]},{"id":"V386","q":"En ese ____ hay varios leones.","o":["instituto","despacho","zoo","casino"],"a":2,"k":"장소 어휘","t":"그 동물원에는 사자가 여러 마리 있다.","e":"leones(사자들)가 있는 곳은 zoo(동물원)입니다. 'hay + 명사'는 '~이 있다'라는 존재 표현이에요. 사자 단수는 león이고 복수가 되면 악센트가 사라져 leones가 됩니다.","x":["instituto: 고등학교라는 뜻으로 사자가 있는 곳이 아닙니다 ✗","despacho: 사무실이라는 뜻으로 사자가 있는 곳이 아닙니다 ✗","zoo: 동물원이라는 뜻으로 사자가 있는 곳입니다 ✓","casino: 카지노라는 뜻으로 사자가 있는 곳이 아닙니다 ✗"]},{"id":"V387","q":"Te mereces este premio. ¡____!","o":["Enhorabuena","Lo siento","Disculpa","Perdón"],"a":0,"k":"축하 표현","t":"너는 이 상을 받을 자격이 있어. 축하해!","e":"premio(상)를 받은 사람에게는 '¡Enhorabuena!(축하해!)'라고 합니다. '¡Felicidades!'도 같은 뜻으로 쓸 수 있어요. merecer는 '~을 받을 자격이 있다'라는 동사입니다.","x":["Enhorabuena: 축하해라는 뜻으로 상을 받은 사람에게 맞는 말입니다 ✓","Lo siento: 미안해·유감이야라는 뜻으로 축하 상황에 맞지 않습니다 ✗","Disculpa: 실례해·미안해라는 뜻으로 축하 상황에 맞지 않습니다 ✗","Perdón: 죄송해요라는 뜻으로 축하 상황에 맞지 않습니다 ✗"]},{"id":"V388","q":"El viernes es el quinto ____ de la semana.","o":["siglo","día","año","mes"],"a":1,"k":"시간 어휘","t":"금요일은 일주일의 다섯 번째 날이다.","e":"viernes(금요일)는 semana(주)의 다섯 번째 día(날)입니다. 스페인어권 달력은 lunes(월요일)부터 시작해서 금요일이 다섯 번째예요. 요일 이름은 소문자로 씁니다.","x":["siglo: 세기(100년)라는 뜻으로 주와 맞지 않습니다 ✗","día: 날이라는 뜻으로 '일주일의 다섯 번째 날'이 됩니다 ✓","año: 해(년)라는 뜻으로 주와 맞지 않습니다 ✗","mes: 달(월)이라는 뜻으로 주와 맞지 않습니다 ✗"]},{"id":"V389","q":"No puede caminar todavía porque se rompió una ____ hace poco.","o":["muela","uña","pierna","mano"],"a":2,"k":"신체 어휘","t":"얼마 전에 다리가 부러져서 아직 걸을 수 없다.","e":"caminar(걷다)를 못 하는 이유가 되는 신체 부위는 pierna(다리)입니다. 'romperse + 신체 부위'는 '(자기의) ~가 부러지다'라는 재귀 표현이에요. 'hace poco'는 '얼마 전에'라는 뜻입니다.","x":["muela: 어금니라는 뜻으로 걷는 것과 관련이 없습니다 ✗","uña: 손톱·발톱이라는 뜻으로 부러져도 걸을 수 있습니다 ✗","pierna: 다리라는 뜻으로 걷지 못하는 이유와 맞습니다 ✓","mano: 손이라는 뜻으로 걷는 것과 관련이 없습니다 ✗"]},{"id":"V390","q":"No sé ____ salsa, pero quiero aprender.","o":["viajar","bailar","hablar","tomar"],"a":1,"k":"동사 bailar","t":"나는 살사를 출 줄 모르지만 배우고 싶어.","e":"salsa는 라틴 음악·춤 장르로 bailar(춤추다)와 함께 씁니다. 'saber + 동사원형'은 '~할 줄 알다'라는 능력 표현이에요. 예: Sé nadar.(나는 수영할 줄 알아.)","x":["viajar: 여행하다라는 뜻으로 살사와 어울리지 않습니다 ✗","bailar: 춤추다라는 뜻으로 'bailar salsa(살사를 추다)'가 됩니다 ✓","hablar: 말하다라는 뜻으로 살사와 어울리지 않습니다 ✗","tomar: 먹다·마시다라는 뜻으로 소스(salsa)라면 가능하지만 '배우고 싶다'와 맞지 않습니다 ✗"]},{"id":"V391","q":"En esta habitación hace frío porque no hay ningún ____.","o":["radiador","ventilador","despertador","hervidor"],"a":0,"k":"가전 어휘","t":"이 방은 라디에이터(난방기)가 하나도 없어서 춥다.","e":"방이 추운 이유는 난방 기구인 radiador(라디에이터, 방열기)가 없기 때문입니다. 'no hay ningún + 남성 단수 명사'는 '~이 하나도 없다'라는 뜻이에요. 'hace frío'는 '(날씨·공간이) 춥다'라는 표현입니다.","x":["radiador: 라디에이터(난방기)라는 뜻으로 없으면 추운 이유가 됩니다 ✓","ventilador: 선풍기라는 뜻으로 없다고 추워지지 않습니다 ✗","despertador: 자명종이라는 뜻으로 온도와 관련이 없습니다 ✗","hervidor: 전기 주전자라는 뜻으로 방 온도와 관련이 없습니다 ✗"]},{"id":"V392","q":"Estoy harto de lavar los platos a mano. Voy a comprar un ____.","o":["ordenador","teléfono","horno","lavaplatos"],"a":3,"k":"가전 어휘","t":"손으로 설거지하는 게 지긋지긋해. 식기세척기를 살 거야.","e":"'lavar los platos(설거지하다)'를 대신해 주는 기계는 lavaplatos(식기세척기)입니다. lava(씻다)+platos(접시)가 합쳐진 단어로 단수·복수 형태가 같아요. 'estar harto de ~'는 '~에 질리다, 지긋지긋하다'라는 표현입니다.","x":["ordenador: (스페인) 컴퓨터라는 뜻으로 설거지와 관련이 없습니다 ✗","teléfono: 전화기라는 뜻으로 설거지와 관련이 없습니다 ✗","horno: 오븐이라는 뜻으로 요리용이지 설거지용이 아닙니다 ✗","lavaplatos: 식기세척기라는 뜻으로 설거지를 대신해 줍니다 ✓"]},{"id":"V393","q":"Me hice daño en un dedo. ¡Qué ____!","o":["dolor","suerte","alegría","maravilla"],"a":0,"k":"감탄 표현 qué","t":"손가락을 다쳤어. 너무 아파!","e":"'hacerse daño'는 '다치다'라는 뜻이므로 '¡Qué dolor!(너무 아파!)'가 자연스럽습니다. '¡Qué + 명사!'는 감정을 나타내는 감탄문이에요. 예: ¡Qué pena!(안타깝다!), ¡Qué suerte!(운 좋다!)","x":["dolor: 통증이라는 뜻으로 '너무 아파!'가 되어 다친 상황에 맞습니다 ✓","suerte: 행운이라는 뜻으로 다친 상황과 반대입니다 ✗","alegría: 기쁨이라는 뜻으로 다친 상황과 반대입니다 ✗","maravilla: 경이로움·멋짐이라는 뜻으로 다친 상황과 반대입니다 ✗"]},{"id":"V394","q":"Perdone, ¿puede hablar ____? Mi español no es bueno.","o":["más","en voz baja","menos","despacio"],"a":3,"k":"부사 despacio","t":"실례합니다, 천천히 말씀해 주시겠어요? 제 스페인어가 좋지 않아서요.","e":"외국어를 잘 못할 때는 '천천히(despacio)' 말해 달라고 부탁합니다. '¿Puede hablar más despacio, por favor?'는 여행할 때 꼭 필요한 표현이에요. puede는 usted(당신)에게 쓰는 공손한 형태입니다.","x":["más: 더라는 뜻으로 혼자서는 무엇을 더 하라는지 불분명합니다 ✗","en voz baja: 작은 목소리로라는 뜻으로 알아듣기 더 어려워집니다 ✗","menos: 덜이라는 뜻으로 혼자서는 의미가 불분명합니다 ✗","despacio: 천천히라는 뜻으로 스페인어가 서툰 사람의 부탁과 맞습니다 ✓"]},{"id":"V395","q":"¿Cuántos ____ son necesarios para este juego de cartas?","o":["espectadores","vendedores","compradores","jugadores"],"a":3,"k":"놀이 어휘","t":"이 카드 게임에는 몇 명의 플레이어가 필요해요?","e":"juego de cartas(카드 게임)를 하는 사람은 jugadores(플레이어, 선수)입니다. jugar(놀다, 경기하다)에서 나온 단어예요. '-dor'로 끝나는 명사는 '~하는 사람'을 뜻합니다: vendedor(판매자), comprador(구매자).","x":["espectadores: 관객이라는 뜻으로 게임을 하는 사람이 아닙니다 ✗","vendedores: 판매자라는 뜻으로 게임과 관련이 없습니다 ✗","compradores: 구매자라는 뜻으로 게임과 관련이 없습니다 ✗","jugadores: 플레이어라는 뜻으로 게임을 하는 사람입니다 ✓"]},{"id":"V396","q":"Llevas muchas horas en la cama. ¡____ ya!","o":["Péinate","Báñate","Vístete","Levántate"],"a":3,"k":"재귀동사 명령형","t":"너 침대에 너무 오래 있었어. 이제 일어나!","e":"침대(cama)에 오래 있었으니 levantarse(일어나다)의 명령형 '¡Levántate!'가 자연스럽습니다. 긍정 명령에서는 재귀 대명사 te가 동사 뒤에 붙고, 강세 위치를 지키려고 악센트(á)를 찍어요. 'ya'는 '이제, 당장'이라는 뜻입니다.","x":["Péinate: 머리 빗어라는 뜻으로 침대에서 나오라는 말이 아닙니다 ✗","Báñate: 목욕해라는 뜻으로 문맥과 직접 연결되지 않습니다 ✗","Vístete: 옷 입어라는 뜻으로 침대에 오래 있었다는 말과 직접 연결되지 않습니다 ✗","Levántate: 일어나라는 뜻으로 침대에 오래 있었다는 말과 딱 맞습니다 ✓"]},{"id":"V397","q":"Esta ____ es famosa por sus historias de terror.","o":["azafata","cajera","novelista","pintora"],"a":2,"k":"직업 어휘","t":"이 소설가는 공포 이야기로 유명하다.","e":"historias(이야기)를 쓰는 사람은 novelista(소설가)입니다. -ista로 끝나는 직업명은 남녀 형태가 같아 관사(el/la)로 성별을 구분해요. 'ser famoso/a por ~'는 '~로 유명하다'입니다.","x":["azafata: 승무원이라는 뜻으로 이야기를 쓰는 직업이 아닙니다 ✗","cajera: 계산원이라는 뜻으로 이야기를 쓰는 직업이 아닙니다 ✗","novelista: 소설가라는 뜻으로 공포 이야기와 맞습니다 ✓","pintora: 화가라는 뜻으로 이야기보다 그림으로 유명합니다 ✗"]},{"id":"V398","q":"La fiesta fue un ____; todo el mundo se lo pasó genial.","o":["éxito","suceso","desastre","lío"],"a":0,"k":"명사 éxito","t":"파티는 대성공이었다. 모두가 아주 즐거운 시간을 보냈다.","e":"모두 즐거웠다면 파티는 éxito(성공)입니다. 주의: éxito는 영어 exit(출구)이 아니라 '성공'이고, 출구는 salida예요. suceso도 영어 success와 달리 '사건'이라는 뜻입니다.","x":["éxito: 성공이라는 뜻으로 모두 즐거웠다는 말과 맞습니다 ✓","suceso: 사건이라는 뜻으로 영어 success와 다르니 주의하세요 ✗","desastre: 재앙·엉망이라는 뜻으로 문맥과 반대입니다 ✗","lío: 혼란·소동이라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V399","q":"No puedo alojarme en un hotel ____ porque no tengo suficiente dinero.","o":["de lujo","viejo","del centro","rural"],"a":0,"k":"숙박 어휘","t":"돈이 충분하지 않아서 고급 호텔에 묵을 수 없어.","e":"돈이 부족해서 못 가는 곳은 hotel de lujo(고급 호텔, 럭셔리 호텔)입니다. lujo는 '사치, 호화로움'이라는 뜻이에요. alojarse는 '숙박하다, 묵다'라는 재귀동사입니다.","x":["de lujo: 고급의라는 뜻으로 돈이 부족해 못 가는 이유와 맞습니다 ✓","viejo: 오래된이라는 뜻으로 돈이 없다는 이유와 연결되지 않습니다 ✗","del centro: 시내의라는 뜻으로 비쌀 수는 있지만 가장 직접적인 이유가 아닙니다 ✗","rural: 시골의라는 뜻으로 돈이 없다는 이유와 연결되지 않습니다 ✗"]},{"id":"V400","q":"Nunca uso ____ de pelo porque me lo seco al aire.","o":["cepillo","peine","alisador","secador"],"a":3,"k":"생활용품 어휘","t":"나는 머리를 자연 바람에 말리기 때문에 헤어드라이어를 절대 안 써.","e":"'secar(말리다)'와 관련된 도구는 secador de pelo(헤어드라이어)입니다. 'secarse el pelo al aire'는 '머리를 자연 건조하다'라는 뜻이에요. lo는 el pelo를 받는 대명사입니다.","x":["cepillo: 빗(브러시)이라는 뜻으로 말리는 것과 직접 대비되지 않습니다 ✗","peine: 빗이라는 뜻으로 말리는 것과 직접 대비되지 않습니다 ✗","alisador: 고데기(스트레이트너)라는 뜻으로 머리를 말리는 도구가 아닙니다 ✗","secador: 헤어드라이어라는 뜻으로 자연 건조와 대비되어 정답입니다 ✓"]},{"id":"V401","q":"Después de comer, pasaron a la ____ para charlar y tomar café.","o":["cochera","pista de baile","despensa","sala de estar"],"a":3,"k":"집 어휘","t":"식사 후에 그들은 수다를 떨고 커피를 마시러 거실로 갔다.","e":"식사 후 charlar(수다 떨다)하고 커피를 마시는 곳은 sala de estar(거실)입니다. salón도 같은 뜻이에요. 'pasar a + 장소'는 '~로 옮겨 가다'라는 뜻입니다.","x":["cochera: 차고라는 뜻으로 커피를 마시며 이야기하는 곳이 아닙니다 ✗","pista de baile: 댄스 플로어라는 뜻으로 수다·커피와 어울리지 않습니다 ✗","despensa: 식료품 저장실이라는 뜻으로 머무는 공간이 아닙니다 ✗","sala de estar: 거실이라는 뜻으로 수다 떨며 커피 마시기에 맞습니다 ✓"]},{"id":"V402","q":"¿A qué se dedica su esposa? —Es ____.","o":["sociable","habladora","hermosa","empresaria"],"a":3,"k":"직업 묻기","t":"부인께서는 무슨 일을 하세요? —사업가예요.","e":"'¿A qué se dedica?'는 '무슨 일을 하세요?'라는 직업을 묻는 공손한 질문입니다. 그래서 대답은 직업인 empresaria(사업가, 기업가)여야 해요. 나머지 보기는 성격이나 외모를 나타내는 형용사입니다.","x":["sociable: 사교적인이라는 성격 형용사로 직업이 아닙니다 ✗","habladora: 수다스러운이라는 성격 형용사로 직업이 아닙니다 ✗","hermosa: 아름다운이라는 외모 형용사로 직업이 아닙니다 ✗","empresaria: 사업가라는 직업명으로 질문에 맞습니다 ✓"]},{"id":"V403","q":"¿Qué prefieres para tus hijos? ¿Un colegio público o uno ____?","o":["nuevo","gratis","famoso","privado"],"a":3,"k":"교육 어휘","t":"자녀분들에게 어떤 걸 원하세요? 공립 학교요, 아니면 사립 학교요?","e":"público(공립의)와 대비되는 말은 privado(사립의)입니다. uno는 앞의 colegio를 반복하지 않으려고 쓴 대명사예요. 'colegio público/privado'는 '공립/사립 학교'입니다.","x":["nuevo: 새로운이라는 뜻으로 공립과 대비되지 않습니다 ✗","gratis: 무료의라는 뜻으로 오히려 공립 학교의 특징입니다 ✗","famoso: 유명한이라는 뜻으로 공립과 대비되지 않습니다 ✗","privado: 사립의라는 뜻으로 공립(público)과 짝을 이룹니다 ✓"]},{"id":"V404","q":"Me gustaría ____ un buen trabajo justo al terminar mis estudios.","o":["abrir","servir","seguir","conseguir"],"a":3,"k":"동사 conseguir","t":"학업을 마치자마자 좋은 직장을 구하고 싶어.","e":"'conseguir un trabajo'는 '일자리를 구하다(얻다)'라는 자주 쓰는 표현입니다. conseguir는 '얻다, 이루다'라는 뜻이에요. 'Me gustaría + 동사원형'은 '~하고 싶다'라는 공손한 소망 표현입니다.","x":["abrir: 열다라는 뜻으로 '일자리를 연다'는 맞지 않습니다 ✗","servir: 봉사하다·제공하다라는 뜻으로 일자리와 어울리지 않습니다 ✗","seguir: 계속하다·따라가다라는 뜻으로 일자리를 얻는다는 뜻이 아닙니다 ✗","conseguir: 얻다라는 뜻으로 'conseguir un trabajo(일자리를 구하다)'가 됩니다 ✓"]},{"id":"V405","q":"No pueden darte ese ____ en la farmacia sin una receta médica.","o":["monumento","medicamento","documento","invento"],"a":1,"k":"약국 어휘","t":"처방전 없이는 약국에서 그 약을 줄 수 없어.","e":"farmacia(약국)에서 receta médica(처방전)가 필요한 것은 medicamento(약)입니다. -mento로 끝나는 비슷한 단어들(monumento, documento, invento)과 헷갈리지 않도록 주의하세요. receta는 '요리법'이라는 뜻도 있습니다.","x":["monumento: 기념물이라는 뜻으로 약국과 관련이 없습니다 ✗","medicamento: 약이라는 뜻으로 약국·처방전과 맞습니다 ✓","documento: 서류라는 뜻으로 약국에서 받는 것이 아닙니다 ✗","invento: 발명품이라는 뜻으로 약국과 관련이 없습니다 ✗"]},{"id":"V406","q":"El ____ es un deporte de equipo.","o":["baloncesto","buceo","ciclismo","surf"],"a":0,"k":"스포츠 어휘","t":"농구는 단체 스포츠이다.","e":"deporte de equipo(단체 스포츠)는 팀을 이뤄 하는 운동으로 보기 중 baloncesto(농구)입니다. 중남미에서는 básquetbol이라고도 해요. 축구(fútbol), 배구(voleibol)도 단체 스포츠입니다.","x":["baloncesto: 농구라는 뜻으로 팀을 이뤄 하는 운동입니다 ✓","buceo: 다이빙(잠수)이라는 뜻으로 개인 활동입니다 ✗","ciclismo: 사이클이라는 뜻으로 보통 개인 종목으로 봅니다 ✗","surf: 서핑이라는 뜻으로 개인 스포츠입니다 ✗"]},{"id":"V407","q":"Soy ____ habitual de este café porque me tratan bien y está cerca.","o":["invitado","turista","visitante","cliente"],"a":3,"k":"상점 어휘","t":"나는 이 카페의 단골손님이야. 친절하게 대해 주고 가깝거든.","e":"'cliente habitual'은 '단골손님'이라는 표현입니다. cliente는 가게·카페에서 물건이나 서비스를 사는 '손님, 고객'이에요. habitual은 '평소의, 늘 하는'이라는 뜻입니다.","x":["invitado: 초대 손님이라는 뜻으로 카페 단골을 말할 때 쓰지 않습니다 ✗","turista: 관광객이라는 뜻으로 '늘 오는 손님'과 맞지 않습니다 ✗","visitante: 방문객이라는 뜻으로 카페 단골을 말할 때 쓰지 않습니다 ✗","cliente: 손님·고객이라는 뜻으로 'cliente habitual(단골손님)'이 됩니다 ✓"]},{"id":"V408","q":"Paolo habla muy bien español; tiene una ____ perfecta.","o":["alimentación","salud","pronunciación","emoción"],"a":2,"k":"언어 어휘","t":"파올로는 스페인어를 정말 잘한다. 발음이 완벽하다.","e":"말을 잘한다는 것과 연결되는 것은 pronunciación(발음)입니다. -ción으로 끝나는 명사는 여성이라 perfecta와 성이 맞아요. 동사 pronunciar는 '발음하다'입니다.","x":["alimentación: 식생활이라는 뜻으로 스페인어 실력과 관련이 없습니다 ✗","salud: 건강이라는 뜻으로 스페인어 실력과 관련이 없습니다 ✗","pronunciación: 발음이라는 뜻으로 스페인어를 잘한다는 말과 맞습니다 ✓","emoción: 감정이라는 뜻으로 스페인어 실력과 관련이 없습니다 ✗"]},{"id":"V409","q":"Todos los ____ de mi casa son de madera.","o":["felpudos","computadores","muebles","aparatos"],"a":2,"k":"가구 어휘","t":"우리 집 가구는 모두 나무로 되어 있다.","e":"집 안의 탁자·의자·장 등을 통틀어 muebles(가구)라고 합니다. 'ser de madera'는 '나무로 되어 있다'라는 재료 표현이에요. 보기의 computadores는 콜롬비아·칠레 등에서 쓰는 '컴퓨터'로, 스페인은 ordenador, 멕시코는 computadora라고 합니다.","x":["felpudos: 현관 매트라는 뜻으로 나무로 만들지 않습니다 ✗","computadores: (중남미) 컴퓨터라는 뜻으로 나무로 만들지 않습니다 ✗","muebles: 가구라는 뜻으로 나무로 된 것이 자연스럽습니다 ✓","aparatos: 기기·장치라는 뜻으로 보통 나무로 만들지 않습니다 ✗"]},{"id":"V410","q":"Últimamente ____ poco, por eso estoy cansado.","o":["duermo","fumo","hablo","me ducho"],"a":0,"k":"일상 동사","t":"요즘 잠을 적게 자서 피곤해.","e":"피곤한(cansado) 이유는 잠을 적게 자기 때문이므로 dormir(자다)가 맞습니다. dormir는 o→ue로 바뀌는 불규칙 동사라 1인칭이 duermo예요. 'últimamente'는 '요즘, 최근에'라는 뜻입니다.","x":["duermo: dormir(자다)의 1인칭으로 적게 자서 피곤하다는 뜻이 됩니다 ✓","fumo: fumar(담배 피우다)로 적게 피워서 피곤하다는 것은 어색합니다 ✗","hablo: hablar(말하다)로 적게 말해서 피곤하다는 것은 어색합니다 ✗","me ducho: ducharse(샤워하다)로 피곤함의 이유가 되지 않습니다 ✗"]},{"id":"V411","q":"Me gusta la ____ de Raúl. Es un hombre respetuoso y servicial.","o":["personalidad","cara","voz","apariencia"],"a":0,"k":"성격 어휘","t":"나는 라울의 성격이 마음에 들어. 예의 바르고 남을 잘 돕는 사람이야.","e":"respetuoso(예의 바른)와 servicial(남을 잘 돕는)은 성격을 설명하므로 personalidad(성격, 인격)가 정답입니다. 외모를 말할 때는 apariencia나 físico를 써요. 'Me gusta + 단수 명사'는 '~이 마음에 든다'입니다.","x":["personalidad: 성격이라는 뜻으로 예의 바르고 친절하다는 설명과 맞습니다 ✓","cara: 얼굴이라는 뜻으로 성격 설명과 맞지 않습니다 ✗","voz: 목소리라는 뜻으로 성격 설명과 맞지 않습니다 ✗","apariencia: 외모라는 뜻으로 성격 설명과 맞지 않습니다 ✗"]},{"id":"V412","q":"____ es el tercer mes del año.","o":["Marzo","Junio","Octubre","Noviembre"],"a":0,"k":"월 이름","t":"3월은 일 년의 세 번째 달이다.","e":"tercer(세 번째) 달은 marzo(3월)입니다. tercero는 남성 단수 명사 앞에서 o가 빠져 tercer가 돼요(primer도 마찬가지). 월 이름은 문장 처음이 아니면 소문자로 씁니다.","x":["Marzo: 3월이라는 뜻으로 세 번째 달입니다 ✓","Junio: 6월이라는 뜻으로 여섯 번째 달입니다 ✗","Octubre: 10월이라는 뜻으로 열 번째 달입니다 ✗","Noviembre: 11월이라는 뜻으로 열한 번째 달입니다 ✗"]},{"id":"V413","q":"Cuando vamos a la playa, yo prefiero ____ el sol y mi marido prefiere nadar.","o":["hacer","tener","tomar","dar"],"a":2,"k":"tomar el sol","t":"해변에 가면 나는 일광욕하는 걸 좋아하고 남편은 수영하는 걸 좋아한다.","e":"'tomar el sol'은 '햇볕을 쬐다, 일광욕하다'라는 고정 표현입니다. tomar는 '마시다, 잡다' 외에도 이런 표현에 많이 쓰여요. 예: tomar el aire(바람 쐬다).","x":["hacer: 'hace sol(해가 난다)'처럼 날씨에 쓰지만 '일광욕하다'는 아닙니다 ✗","tener: tener와 sol은 이 뜻으로 함께 쓰지 않습니다 ✗","tomar: 'tomar el sol(일광욕하다)'라는 고정 표현입니다 ✓","dar: 'dar el sol'은 해가 비친다는 뜻으로 주어가 해일 때 씁니다 ✗"]},{"id":"V414","q":"Juan es ____. Escribe para un diario deportivo.","o":["cineasta","periodista","contable","actor"],"a":1,"k":"직업 어휘","t":"후안은 기자다. 스포츠 신문에 글을 쓴다.","e":"diario(신문)에 글을 쓰는 사람은 periodista(기자)입니다. periódico도 '신문'이라는 뜻으로 periodista와 같은 어원이에요. -ista 직업명은 남녀 형태가 같습니다.","x":["cineasta: 영화감독·영화인이라는 뜻으로 신문에 쓰는 직업이 아닙니다 ✗","periodista: 기자라는 뜻으로 신문에 글을 쓰는 직업입니다 ✓","contable: 회계사라는 뜻으로 신문에 쓰는 직업이 아닙니다 ✗","actor: 배우라는 뜻으로 신문에 쓰는 직업이 아닙니다 ✗"]},{"id":"V415","q":"Ese hombre está más loco que una ____.","o":["rata","vaca","cabra","serpiente"],"a":2,"k":"관용 표현(동물)","t":"저 남자는 완전히 미쳤어.","e":"'estar más loco que una cabra(염소보다 더 미쳤다)'는 '완전히 제정신이 아니다'라는 관용 표현입니다. 염소가 갑자기 뛰어다니는 모습에서 나온 말이에요. 'estar como una cabra'도 같은 뜻으로 자주 씁니다.","x":["rata: 쥐라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","vaca: 암소라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","cabra: 염소라는 뜻으로 'más loco que una cabra(완전히 미친)'라는 관용 표현입니다 ✓","serpiente: 뱀이라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V416","q":"Antes del test de vocabulario, voy a ____ mi lista de palabras.","o":["responder","repasar","tirar","cometer"],"a":1,"k":"학습 동사 repasar","t":"어휘 시험 전에 단어 목록을 복습할 거야.","e":"시험 전에 단어 목록을 하는 것은 repasar(복습하다)입니다. 'repasar la lección'은 '수업 내용을 복습하다'라는 뜻이에요. 'ir a + 동사원형'은 가까운 미래(~할 것이다)를 나타냅니다.","x":["responder: 대답하다라는 뜻으로 단어 목록과 맞지 않습니다 ✗","repasar: 복습하다라는 뜻으로 시험 준비와 맞습니다 ✓","tirar: 버리다라는 뜻으로 시험 전에 할 일이 아닙니다 ✗","cometer: (잘못을) 저지르다라는 뜻으로 문맥에 맞지 않습니다 ✗"]},{"id":"V417","q":"Te recomiendo estas ____ para caminar por el campo.","o":["bragas","camisas","blusas","botas"],"a":3,"k":"의류 어휘","t":"시골길을 걸을 때 신을 이 부츠를 추천해.","e":"caminar por el campo(시골길을 걷다)할 때 신는 것은 botas(부츠)입니다. 'recomendar'는 e→ie로 바뀌어 1인칭이 recomiendo예요. 등산화는 'botas de montaña'라고 합니다.","x":["bragas: (스페인) 여성 속옷이라는 뜻으로 걷는 것과 관련이 없습니다 ✗","camisas: 셔츠라는 뜻으로 걷기용 신발이 아닙니다 ✗","blusas: 블라우스라는 뜻으로 걷기용 신발이 아닙니다 ✗","botas: 부츠라는 뜻으로 시골길을 걸을 때 신기에 맞습니다 ✓"]},{"id":"V418","q":"Los continuos cambios políticos provocan ____.","o":["inestabilidad","afecto","cariño","imposibilidad"],"a":0,"k":"사회 어휘","t":"계속되는 정치적 변화는 불안정을 초래한다.","e":"정치 변화가 계속되면 생기는 것은 inestabilidad(불안정)입니다. in-은 부정 접두사로 estabilidad(안정)의 반대말을 만들어요. provocar는 '일으키다, 초래하다'라는 뜻입니다.","x":["inestabilidad: 불안정이라는 뜻으로 계속되는 정치 변화의 결과와 맞습니다 ✓","afecto: 애정이라는 뜻으로 정치 변화의 결과가 아닙니다 ✗","cariño: 사랑·애정이라는 뜻으로 정치 변화의 결과가 아닙니다 ✗","imposibilidad: 불가능이라는 뜻으로 문맥에 맞지 않습니다 ✗"]},{"id":"V419","q":"Barcelona es una de las ____ más famosas de España.","o":["montañas","islas","ciudades","playas"],"a":2,"k":"지리 어휘","t":"바르셀로나는 스페인에서 가장 유명한 도시 중 하나이다.","e":"Barcelona는 ciudad(도시)입니다. 'una de las + 복수 명사 + más ~'는 '가장 ~한 것들 중 하나'라는 최상급 표현이에요. ciudad가 여성 명사라서 una, las, famosas처럼 여성형을 씁니다.","x":["montañas: 산이라는 뜻으로 바르셀로나는 산이 아닙니다 ✗","islas: 섬이라는 뜻으로 바르셀로나는 섬이 아닙니다 ✗","ciudades: 도시라는 뜻으로 바르셀로나와 맞습니다 ✓","playas: 해변이라는 뜻으로 바르셀로나는 해변이 아니라 도시입니다 ✗"]},{"id":"V420","q":"En otoño el tiempo aquí es muy ____, por eso no sé qué ropa ponerme.","o":["frío","caluroso","estable","variable"],"a":3,"k":"날씨 형용사","t":"가을에 이곳 날씨는 아주 변덕스러워서 무슨 옷을 입어야 할지 모르겠어.","e":"어떤 옷을 입을지 모르겠다는 것은 날씨가 variable(변하기 쉬운, 변덕스러운)하기 때문입니다. 여기서 tiempo는 '시간'이 아니라 '날씨'라는 뜻이에요. 'no sé qué + 동사원형'은 '무엇을 ~할지 모르겠다'입니다.","x":["frío: 추운이라는 뜻으로 그러면 따뜻하게 입으면 되니 고민할 이유가 없습니다 ✗","caluroso: 더운이라는 뜻으로 그러면 가볍게 입으면 되니 고민할 이유가 없습니다 ✗","estable: 안정된이라는 뜻으로 옷 고민의 이유와 반대입니다 ✗","variable: 변덕스러운이라는 뜻으로 무엇을 입을지 모르는 이유와 맞습니다 ✓"]},{"id":"V421","q":"Dígame, señora López, ¿qué le ____? —Me duele mucho el cuello.","o":["interesa","pasa","aburre","emociona"],"a":1,"k":"¿Qué le pasa?","t":"말씀해 보세요, 로페스 부인, 어디가 불편하세요? —목이 많이 아파요.","e":"'¿Qué le pasa?'는 '무슨 일이세요? 어디가 안 좋으세요?'라는 뜻으로 병원에서 의사가 자주 묻는 질문입니다. le는 usted(당신)에게라는 간접목적격 대명사예요. 대답의 'me duele(아프다)'도 gustar처럼 쓰는 동사입니다.","x":["interesa: interesar(관심을 끌다)로 아픈 곳을 묻는 질문이 아닙니다 ✗","pasa: pasar(일어나다)로 '어디가 불편하세요?'라는 질문이 됩니다 ✓","aburre: aburrir(지루하게 하다)로 아픈 곳을 묻는 질문이 아닙니다 ✗","emociona: emocionar(감동시키다)로 아픈 곳을 묻는 질문이 아닙니다 ✗"]},{"id":"V422","q":"Me apasionan los libros, por eso trabajo en una ____.","o":["lavandería","taberna","librería","discoteca"],"a":2,"k":"가게 어휘","t":"나는 책을 정말 좋아해서 서점에서 일해.","e":"libros(책)를 파는 가게는 librería(서점)입니다. 도서관(biblioteca)과 헷갈리지 마세요. 'me apasionan'은 '나를 열광시키다'라는 뜻으로 gustar처럼 씁니다.","x":["lavandería: 세탁소라는 뜻으로 책과 관련이 없습니다 ✗","taberna: 선술집이라는 뜻으로 책과 관련이 없습니다 ✗","librería: 서점이라는 뜻으로 책을 좋아하는 사람의 직장과 맞습니다 ✓","discoteca: 나이트클럽이라는 뜻으로 책과 관련이 없습니다 ✗"]},{"id":"V423","q":"Verónica va a todas las fiestas a las que la invitan. Es muy ____.","o":["juerguista","cuidadosa","sensible","presumida"],"a":0,"k":"성격 형용사","t":"베로니카는 초대받은 파티에는 모두 가. 정말 노는 걸 좋아해.","e":"모든 파티에 가는 사람은 juerguista(파티·노는 것을 좋아하는 사람)입니다. juerga는 '흥청망청 노는 것, 파티'라는 뜻이에요. -ista로 끝나서 남녀 형태가 같습니다.","x":["juerguista: 노는 것을 좋아하는이라는 뜻으로 파티마다 가는 사람과 맞습니다 ✓","cuidadosa: 조심성 있는이라는 뜻으로 파티와 관련이 없습니다 ✗","sensible: 예민한·감수성 있는이라는 뜻으로 파티와 관련이 없습니다 ✗","presumida: 잘난 척하는·멋 부리는이라는 뜻으로 파티에 가는 이유와 맞지 않습니다 ✗"]},{"id":"V424","q":"Me gustaría hacer un intercambio lingüístico para ____ los idiomas que estoy aprendiendo.","o":["olvidar","practicar","decir","ordenar"],"a":1,"k":"학습 동사 practicar","t":"배우고 있는 언어들을 연습하기 위해 언어 교환을 하고 싶어.","e":"intercambio lingüístico(언어 교환)의 목적은 언어를 practicar(연습하다)하는 것입니다. 'para + 동사원형'은 '~하기 위해서'라는 목적 표현이에요. 'Me gustaría'는 '~하고 싶다'는 공손한 표현입니다.","x":["olvidar: 잊다라는 뜻으로 언어 교환의 목적과 반대입니다 ✗","practicar: 연습하다라는 뜻으로 언어 교환의 목적과 맞습니다 ✓","decir: 말하다라는 뜻으로 '언어를 말한다'는 hablar를 씁니다 ✗","ordenar: 정리하다·명령하다라는 뜻으로 문맥에 맞지 않습니다 ✗"]},{"id":"V425","q":"Cada ____ que visito a mi abuela, me prepara mi comida preferida.","o":["tiempo","vez","minuto","instante"],"a":1,"k":"표현 cada vez","t":"할머니를 찾아갈 때마다 할머니는 내가 제일 좋아하는 음식을 만들어 주신다.","e":"'cada vez que ~'는 '~할 때마다'라는 고정 표현입니다. vez는 '번, 회'라는 뜻이에요. 비슷한 표현: una vez(한 번), a veces(가끔), muchas veces(여러 번).","x":["tiempo: 시간이라는 뜻으로 'cada tiempo que'라고 쓰지 않습니다 ✗","vez: 번이라는 뜻으로 'cada vez que(~할 때마다)'가 됩니다 ✓","minuto: 분이라는 뜻으로 '방문할 때마다'의 의미가 되지 않습니다 ✗","instante: 순간이라는 뜻으로 이 표현에 쓰지 않습니다 ✗"]},{"id":"V426","q":"Es la primera vez que ____ la paella. ¡Qué rica!","o":["recuerdo","comento","pruebo","toco"],"a":2,"k":"동사 probar","t":"파에야를 먹어 보는 건 처음이야. 정말 맛있다!","e":"처음으로 음식을 맛보는 것은 probar(맛보다, 먹어 보다)입니다. probar는 o→ue로 바뀌어 1인칭이 pruebo예요. 'probarse'는 '옷을 입어 보다'라는 뜻도 있습니다.","x":["recuerdo: recordar(기억하다)로 처음 먹는다는 말과 맞지 않습니다 ✗","comento: comentar(언급하다)로 '맛있다'와 이어지지 않습니다 ✗","pruebo: probar(맛보다)의 1인칭으로 처음 먹어 본다는 뜻이 됩니다 ✓","toco: tocar(만지다)로 음식을 맛보는 행동이 아닙니다 ✗"]},{"id":"V427","q":"El agua de la piscina está ____, tenemos que limpiarla.","o":["caliente","templada","sucia","fría"],"a":2,"k":"상태 형용사","t":"수영장 물이 더러워서 청소해야 해.","e":"limpiar(청소하다)해야 하는 이유는 물이 sucia(더러운)이기 때문입니다. agua는 여성 명사라 형용사도 여성형 sucia를 써요(관사만 el agua). 반대말은 limpia(깨끗한)입니다.","x":["caliente: 뜨거운이라는 뜻으로 청소할 이유가 되지 않습니다 ✗","templada: 미지근한이라는 뜻으로 청소할 이유가 되지 않습니다 ✗","sucia: 더러운이라는 뜻으로 청소해야 하는 이유와 맞습니다 ✓","fría: 차가운이라는 뜻으로 청소할 이유가 되지 않습니다 ✗"]},{"id":"V428","q":"Tengo que ____ estas pastillas cada seis horas.","o":["tomar","probar","beber","comer"],"a":0,"k":"동사 tomar","t":"나는 이 알약을 6시간마다 먹어야 해.","e":"약(pastillas)을 먹을 때는 tomar를 씁니다. 한국어로는 '약을 먹다'지만 스페인어는 comer가 아니라 tomar예요. 'cada seis horas'는 '6시간마다'라는 뜻입니다.","x":["tomar: (약을) 먹다·복용하다라는 뜻으로 약에 쓰는 동사입니다 ✓","probar: 맛보다라는 뜻으로 약을 복용할 때 쓰지 않습니다 ✗","beber: 마시다라는 뜻으로 알약에는 쓰지 않습니다 ✗","comer: 먹다라는 뜻이지만 약에는 쓰지 않습니다 ✗"]},{"id":"V429","q":"Soy profesora de canto; ____ en una escuela de música.","o":["enseño","aprendo","entiendo","respondo"],"a":0,"k":"동사 enseñar","t":"나는 노래 선생님이야. 음악 학교에서 가르쳐.","e":"profesora(선생님)가 학교에서 하는 일은 enseñar(가르치다)입니다. 반대로 학생은 aprender(배우다)를 해요. canto는 '노래(부르기)'라는 뜻입니다.","x":["enseño: enseñar(가르치다)의 1인칭으로 선생님이 하는 일과 맞습니다 ✓","aprendo: aprender(배우다)로 학생이 하는 일입니다 ✗","entiendo: entender(이해하다)로 직업 설명과 맞지 않습니다 ✗","respondo: responder(대답하다)로 직업 설명과 맞지 않습니다 ✗"]},{"id":"V430","q":"Las cebras se parecen a los ____.","o":["búhos","camaleones","caballos","cangrejos"],"a":2,"k":"동물 어휘","t":"얼룩말은 말과 닮았다.","e":"cebras(얼룩말)와 생김새가 비슷한 동물은 caballos(말)입니다. 'parecerse a ~'는 '~와 닮다'라는 재귀동사 표현이에요. 예: Me parezco a mi padre.(나는 아빠를 닮았다.)","x":["búhos: 부엉이라는 뜻으로 얼룩말과 닮지 않았습니다 ✗","camaleones: 카멜레온이라는 뜻으로 얼룩말과 닮지 않았습니다 ✗","caballos: 말이라는 뜻으로 얼룩말과 생김새가 비슷합니다 ✓","cangrejos: 게라는 뜻으로 얼룩말과 닮지 않았습니다 ✗"]},{"id":"V431","q":"¿Cuántos años ____ tu compañera de piso?","o":["toma","deja","es","tiene"],"a":3,"k":"나이 표현 tener","t":"네 룸메이트는 몇 살이야?","e":"스페인어로 나이는 tener(가지다) 동사로 말합니다: '¿Cuántos años tiene?(몇 살이에요?)'. 영어처럼 ser(be)를 쓰면 틀려요. compañera de piso는 '(스페인) 같은 집에 사는 룸메이트'입니다.","x":["toma: tomar(먹다·잡다)로 나이에 쓰지 않습니다 ✗","deja: dejar(남기다)로 나이에 쓰지 않습니다 ✗","es: ser(~이다)는 영어식으로 나이에 쓰지 않습니다 ✗","tiene: tener로 나이를 말하는 정확한 표현입니다 ✓"]},{"id":"V432","q":"Ese hombre insulta a las personas. ¡Qué ____!","o":["guapo","maleducado","gracioso","considerado"],"a":1,"k":"성격 형용사","t":"저 남자는 사람들을 모욕해. 정말 무례하다!","e":"사람들을 insultar(모욕하다)하는 사람은 maleducado(무례한, 버릇없는)입니다. mal(나쁘게)+educado(교육받은)가 합쳐진 말로, educado는 '공부 많이 한'이 아니라 '예의 바른'이라는 뜻이에요. '¡Qué + 형용사!'는 '정말 ~하다!'라는 감탄문입니다.","x":["guapo: 잘생긴이라는 뜻으로 모욕하는 행동과 관련이 없습니다 ✗","maleducado: 무례한이라는 뜻으로 사람을 모욕하는 행동과 맞습니다 ✓","gracioso: 재미있는이라는 뜻으로 모욕하는 행동과 맞지 않습니다 ✗","considerado: 배려심 있는이라는 뜻으로 모욕하는 행동과 반대입니다 ✗"]},{"id":"V433","q":"Si llegamos tarde a clase, el profesor nos va a ____.","o":["reñir","registrar","multar","recordar"],"a":0,"k":"동사 reñir","t":"우리가 수업에 늦게 가면 선생님이 우리를 혼낼 거야.","e":"수업에 늦으면 선생님이 하는 일은 reñir(꾸짖다, 혼내다)입니다. reñir는 주로 스페인에서 쓰고, 중남미에서는 regañar를 더 많이 써요. nos는 '우리를'이라는 직접목적격 대명사입니다.","x":["reñir: 꾸짖다라는 뜻으로 지각한 학생에게 선생님이 할 일과 맞습니다 ✓","registrar: 기록하다·수색하다라는 뜻으로 문맥과 맞지 않습니다 ✗","multar: 벌금을 물리다라는 뜻으로 경찰 등이 하는 일입니다 ✗","recordar: 기억하다·상기시키다라는 뜻으로 지각에 대한 반응이 아닙니다 ✗"]},{"id":"V434","q":"Nuestro ____ sale del mayor puerto de la isla.","o":["barco","tranvía","autocar","trolebús"],"a":0,"k":"교통 어휘","t":"우리 배는 섬에서 가장 큰 항구에서 출발한다.","e":"puerto(항구)에서 출발하는 교통수단은 barco(배)입니다. 'salir de + 장소'는 '~에서 출발하다'라는 뜻이에요. 나머지 보기는 모두 육지 교통수단입니다.","x":["barco: 배라는 뜻으로 항구에서 출발합니다 ✓","tranvía: 트램(노면 전차)이라는 뜻으로 항구에서 출발하는 교통수단이 아닙니다 ✗","autocar: (스페인) 장거리 버스라는 뜻으로 항구와 맞지 않습니다 ✗","trolebús: 무궤도 전차라는 뜻으로 항구와 맞지 않습니다 ✗"]},{"id":"V435","q":"Esa casa está ____. Nadie vive en ella desde hace años.","o":["escondida","nueva","abandonada","habitada"],"a":2,"k":"상태 형용사","t":"그 집은 버려져 있다. 몇 년째 아무도 살지 않는다.","e":"수년간 아무도 살지 않는 집은 abandonada(버려진, 방치된)입니다. casa가 여성 명사라 여성형을 써요. 'desde hace años'는 '몇 년 전부터'라는 기간 표현입니다.","x":["escondida: 숨겨진이라는 뜻으로 아무도 살지 않는다는 설명과 맞지 않습니다 ✗","nueva: 새로운이라는 뜻으로 몇 년째 비어 있다는 말과 맞지 않습니다 ✗","abandonada: 버려진이라는 뜻으로 아무도 살지 않는 집과 맞습니다 ✓","habitada: 사람이 사는이라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V436","q":"Aquellos ____ vuelan muy alto.","o":["caracoles","pájaros","pingüinos","ratones"],"a":1,"k":"동물 어휘","t":"저 새들은 아주 높이 난다.","e":"volar(날다)하는 동물은 pájaros(새들)입니다. pingüinos(펭귄)도 새이지만 날지 못해요. aquellos는 '저(멀리 있는)'라는 지시 형용사입니다.","x":["caracoles: 달팽이라는 뜻으로 날지 못합니다 ✗","pájaros: 새라는 뜻으로 높이 나는 동물입니다 ✓","pingüinos: 펭귄이라는 뜻으로 새지만 날지 못합니다 ✗","ratones: 쥐라는 뜻으로 날지 못합니다 ✗"]},{"id":"V437","q":"Si no ____ bien, deberías ir al otorrino.","o":["comes","oyes","caminas","ves"],"a":1,"k":"감각 동사 oír","t":"잘 안 들리면 이비인후과에 가 봐야 해.","e":"otorrino(이비인후과 의사)는 귀·코·목을 진료하므로 oír(듣다, 들리다)가 정답입니다. oír는 불규칙 동사로 tú 형태가 oyes예요(oigo, oyes, oye...). 'deberías + 동사원형'은 '~하는 게 좋겠다'는 조언입니다.","x":["comes: comer(먹다)로 이비인후과와 직접 관련이 없습니다 ✗","oyes: oír(듣다)의 tú 형태로 이비인후과와 맞습니다 ✓","caminas: caminar(걷다)로 이비인후과와 관련이 없습니다 ✗","ves: ver(보다)로 안과(oculista)에 갈 문제입니다 ✗"]},{"id":"V438","q":"____ el pimiento, no me gusta nada.","o":["Me interesa","Me encanta","Adoro","Odio"],"a":3,"k":"감정 동사 odiar","t":"나는 피망이 싫어. 정말 하나도 안 좋아해.","e":"'no me gusta nada(전혀 좋아하지 않는다)'와 이어지려면 odiar(싫어하다, 미워하다)가 와야 합니다. odiar는 일반 동사처럼 '(Yo) odio + 대상'으로 써요. 반대로 adorar는 '아주 좋아하다'입니다.","x":["Me interesa: 관심이 있다라는 뜻으로 싫다는 뒷말과 맞지 않습니다 ✗","Me encanta: 아주 좋아한다라는 뜻으로 싫다는 뒷말과 모순됩니다 ✗","Adoro: 아주 좋아한다라는 뜻으로 싫다는 뒷말과 모순됩니다 ✗","Odio: 싫어한다라는 뜻으로 전혀 좋아하지 않는다는 말과 맞습니다 ✓"]},{"id":"V439","q":"Soy ____, es decir, tengo un empleo público.","o":["programador","decorador","pintor","funcionario"],"a":3,"k":"직업 어휘","t":"나는 공무원이야. 즉, 공공 기관에서 일해.","e":"'empleo público(공직)'을 가진 사람은 funcionario(공무원)입니다. 'es decir'는 '즉, 다시 말해'라는 뜻으로 앞말을 풀어 설명할 때 써요. 여성 공무원은 funcionaria입니다.","x":["programador: 프로그래머라는 뜻으로 공직을 뜻하지 않습니다 ✗","decorador: 인테리어 디자이너라는 뜻으로 공직을 뜻하지 않습니다 ✗","pintor: 화가·도장공이라는 뜻으로 공직을 뜻하지 않습니다 ✗","funcionario: 공무원이라는 뜻으로 공공 기관 근무와 맞습니다 ✓"]},{"id":"V440","q":"Echo de ____ a Julia. Espero verla pronto.","o":["mucho","más","menos","poco"],"a":2,"k":"echar de menos","t":"나는 훌리아가 그리워. 곧 만나길 바라.","e":"'echar de menos a alguien'은 '~를 그리워하다'라는 고정 표현입니다. 중남미에서는 같은 뜻으로 'extrañar'를 더 많이 써요. 예: Te echo de menos. / Te extraño.(네가 보고 싶어.)","x":["mucho: 많이라는 뜻으로 'echar de mucho'라는 표현은 없습니다 ✗","más: 더라는 뜻으로 'echar de más'는 '남다, 지나치다'라는 다른 뜻입니다 ✗","menos: 'echar de menos(그리워하다)'라는 고정 표현입니다 ✓","poco: 적게라는 뜻으로 이 표현에 쓰지 않습니다 ✗"]},{"id":"V441","q":"Me dedico a la ____. Soy profesor de lengua.","o":["gastronomía","enseñanza","moda","construcción"],"a":1,"k":"직업 분야 어휘","t":"나는 교육 분야에서 일해. 국어 선생님이야.","e":"profesor(선생님)의 분야는 enseñanza(교육, 가르치는 일)입니다. 'dedicarse a ~'는 '~에 종사하다, ~일을 하다'라는 뜻이에요. 여기서 lengua는 '언어·국어 과목'을 뜻합니다.","x":["gastronomía: 요리·미식 분야라는 뜻으로 선생님과 맞지 않습니다 ✗","enseñanza: 교육이라는 뜻으로 선생님의 분야와 맞습니다 ✓","moda: 패션이라는 뜻으로 선생님과 맞지 않습니다 ✗","construcción: 건설이라는 뜻으로 선생님과 맞지 않습니다 ✗"]},{"id":"V442","q":"¿Qué edad tiene? — ____.","o":["Quince años","Boliviano","Electricista","Estudiante"],"a":0,"k":"나이 묻고 답하기","t":"몇 살이에요? —열다섯 살이요.","e":"'¿Qué edad tiene?'는 '몇 살이에요?(나이가 어떻게 되세요?)'라는 질문이므로 나이로 대답해야 합니다. '¿Cuántos años tiene?'와 같은 뜻이에요. 대답은 'Tengo quince años'를 줄여 'Quince años'라고 할 수 있습니다.","x":["Quince años: 열다섯 살이라는 뜻으로 나이를 묻는 질문에 맞습니다 ✓","Boliviano: 볼리비아 사람이라는 국적으로 나이가 아닙니다 ✗","Electricista: 전기 기사라는 직업으로 나이가 아닙니다 ✗","Estudiante: 학생이라는 신분으로 나이가 아닙니다 ✗"]},{"id":"V443","q":"¿Cómo sueles pagar tus compras? —Con ____.","o":["papel","tarjeta","sobre","carta"],"a":1,"k":"결제 어휘","t":"보통 장 본 걸 어떻게 계산하세요? —카드로요.","e":"결제 수단을 물었으니 tarjeta(카드)가 정답입니다. 'pagar con tarjeta'는 '카드로 계산하다', 'pagar en efectivo'는 '현금으로 계산하다'예요. 'soler + 동사원형'은 '보통 ~하다'입니다.","x":["papel: 종이라는 뜻으로 결제 수단이 아닙니다 ✗","tarjeta: 카드라는 뜻으로 'pagar con tarjeta(카드로 계산하다)'가 됩니다 ✓","sobre: 봉투라는 뜻으로 결제 수단이 아닙니다 ✗","carta: 편지라는 뜻으로 결제 수단이 아닙니다 ✗"]},{"id":"V444","q":"Perdone, no he escuchado la pregunta. ¿Puede ____?","o":["continuar","repetir","volver","pensar"],"a":1,"k":"동사 repetir","t":"죄송해요, 질문을 못 들었어요. 다시 말씀해 주시겠어요?","e":"질문을 못 들었을 때는 repetir(반복하다, 다시 말하다)를 부탁합니다. '¿Puede repetir, por favor?'는 수업이나 여행에서 아주 유용한 표현이에요. puede는 usted에게 쓰는 공손한 형태입니다.","x":["continuar: 계속하다라는 뜻으로 못 들은 질문을 다시 듣는 것이 아닙니다 ✗","repetir: 반복하다라는 뜻으로 다시 말해 달라는 부탁이 됩니다 ✓","volver: 돌아오다라는 뜻으로 단독으로는 '다시 말하다'가 되지 않습니다 ✗","pensar: 생각하다라는 뜻으로 문맥과 맞지 않습니다 ✗"]},{"id":"V445","q":"Almudena usa muletas porque se ha roto una ____.","o":["uña","muela","mano","pierna"],"a":3,"k":"신체 어휘","t":"알무데나는 다리가 부러져서 목발을 짚는다.","e":"muletas(목발)는 다리를 다쳤을 때 쓰므로 pierna(다리)가 정답입니다. 'se ha roto'는 romperse(부러지다)의 현재완료형이에요. 'usar muletas'는 '목발을 짚다'라는 뜻입니다.","x":["uña: 손톱·발톱이라는 뜻으로 목발을 쓸 이유가 아닙니다 ✗","muela: 어금니라는 뜻으로 목발을 쓸 이유가 아닙니다 ✗","mano: 손이라는 뜻으로 목발을 쓸 이유가 아닙니다 ✗","pierna: 다리라는 뜻으로 목발을 쓰는 이유와 맞습니다 ✓"]},{"id":"V446","q":"¿Cuál es su ____ civil? —Estoy casado.","o":["tema","situación","estado","asunto"],"a":2,"k":"개인정보 어휘","t":"결혼 여부가 어떻게 되세요? —결혼했습니다.","e":"'estado civil'은 서류 등에 쓰는 '혼인 상태(결혼 여부)'라는 고정 표현입니다. 대답으로는 soltero(미혼), casado(기혼), divorciado(이혼), viudo(사별) 등이 와요. su는 usted(당신)의 소유사입니다.","x":["tema: 주제라는 뜻으로 혼인 상태를 묻는 표현이 아닙니다 ✗","situación: 상황이라는 뜻으로 'situación civil'은 쓰지 않습니다 ✗","estado: 상태라는 뜻으로 'estado civil(혼인 상태)'이 됩니다 ✓","asunto: 문제·용건이라는 뜻으로 혼인 상태를 묻는 표현이 아닙니다 ✗"]},{"id":"V447","q":"Mi abuelo está sordo; aunque grites, no te ____.","o":["oye","mira","habla","toca"],"a":0,"k":"감각 동사 oír","t":"우리 할아버지는 귀가 안 들리셔서 네가 소리를 질러도 못 들으셔.","e":"sordo(귀가 먹은)인 사람은 소리를 oír(듣다, 들리다)하지 못합니다. oye는 oír의 3인칭 단수예요. 'aunque + 직설법/접속법'은 '~해도'라는 양보 표현입니다.","x":["oye: oír(들리다)의 3인칭으로 귀가 안 들린다는 말과 맞습니다 ✓","mira: mirar(보다)로 귀가 먹은 것과 관련이 없습니다 ✗","habla: hablar(말하다)로 소리를 질러도 못 듣는다는 말과 맞지 않습니다 ✗","toca: tocar(만지다)로 귀가 먹은 것과 관련이 없습니다 ✗"]},{"id":"V448","q":"____ en ti, sé que me dices la verdad.","o":["Creo","Pienso","Me fijo","Insisto"],"a":0,"k":"표현 creer en","t":"나는 너를 믿어. 네가 나에게 진실을 말한다는 걸 알아.","e":"'creer en alguien'은 '~를 믿다(신뢰하다)'라는 표현입니다. 전치사 en과 함께 쓰는 동사이므로 '~ en ti'와 어울려요. pensar en은 '~를 생각하다'로 뜻이 다릅니다.","x":["Creo: 'creer en(~를 믿다)'로 진실을 말한다는 뒷말과 맞습니다 ✓","Pienso: 'pensar en(~를 생각하다)'으로 진실과 직접 연결되지 않습니다 ✗","Me fijo: 'fijarse en(~를 주목하다)'으로 믿음과 관련이 없습니다 ✗","Insisto: 'insistir en(~를 고집하다)'으로 문맥과 맞지 않습니다 ✗"]},{"id":"V449","q":"¡Qué bien ____ tu perfume!","o":["sabe","se ve","huele","queda"],"a":2,"k":"감각 동사 oler","t":"네 향수 냄새 정말 좋다!","e":"perfume(향수)은 냄새로 느끼므로 oler(냄새가 나다)의 3인칭 단수 huele가 정답입니다. '¡Qué bien huele!'는 '냄새 정말 좋다!'라는 감탄 표현이에요. 맛이 좋을 때는 '¡Qué bien sabe!'라고 합니다.","x":["sabe: saber(맛이 나다)로 향수에는 쓰지 않습니다 ✗","se ve: verse(~해 보이다)로 냄새를 나타내지 않습니다 ✗","huele: oler(냄새가 나다)로 향수에 딱 맞습니다 ✓","queda: quedar(어울리다)로 옷에는 쓰지만 향수 냄새에는 맞지 않습니다 ✗"]},{"id":"V450","q":"No voy a las ____ de viajes porque organizo mis viajes yo sola.","o":["agencias","comisarías","aulas","academias"],"a":0,"k":"장소 어휘","t":"나는 여행을 혼자 계획하기 때문에 여행사에 가지 않아.","e":"'agencia de viajes'는 '여행사'라는 표현입니다. 여행을 직접 계획한다고 했으니 여행사에 갈 필요가 없다는 뜻이에요. sola는 말하는 사람이 여성임을 보여 줍니다.","x":["agencias: 대리점·기관이라는 뜻으로 'agencias de viajes(여행사)'가 됩니다 ✓","comisarías: 경찰서라는 뜻으로 여행 계획과 관련이 없습니다 ✗","aulas: 교실이라는 뜻으로 여행과 관련이 없습니다 ✗","academias: 학원이라는 뜻으로 'academias de viajes'라는 말은 없습니다 ✗"]},{"id":"V451","q":"¿Cuántos idiomas ____? —Dos, español e italiano.","o":["comunicas","hablas","expresas","dices"],"a":1,"k":"hablar 언어","t":"너는 몇 개 언어를 하니? —두 개, 스페인어와 이탈리아어.","e":"'언어를 할 줄 안다'고 말할 때 스페인어는 hablar(말하다) + 언어 이름을 씁니다. ¿Cuántos idiomas hablas?는 상대에게 몇 개 언어를 하는지 묻는 가장 기본적인 표현입니다. 예: Hablo coreano e inglés.(나는 한국어와 영어를 해요.)","x":["comunicas: comunicar(전달하다, 알리다)는 '언어를 구사하다'라는 뜻으로 쓰지 않습니다 ✗","hablas: hablar(말하다)의 2인칭 단수, '언어를 하다'라는 뜻 → 정답 ✓","expresas: expresar(표현하다)는 감정·생각을 표현할 때 쓰며 언어 구사에는 쓰지 않습니다 ✗","dices: decir(말하다, 이야기하다)는 '무엇을 말하다'일 때 쓰고 언어 이름과 함께 쓰지 않습니다 ✗"]},{"id":"V452","q":"Me ____ el corazón ver a perros y gatos abandonados.","o":["saca","aparta","parte","quita"],"a":2,"k":"관용 표현","t":"버려진 개와 고양이를 보면 가슴이 찢어진다.","e":"partir el corazón(마음을 찢다, 가슴 아프게 하다)은 매우 슬프거나 안타까운 감정을 나타내는 관용 표현입니다. 'ver a perros y gatos abandonados(버려진 개·고양이를 보는 것)'가 주어이고 me는 '나에게'입니다. 예: Me parte el corazón tu historia.(네 이야기에 가슴이 미어진다.)","x":["saca: sacar(꺼내다)는 corazón과 함께 이런 관용 표현을 만들지 않습니다 ✗","aparta: apartar(떼어 놓다, 치우다)는 의미가 맞지 않습니다 ✗","parte: partir(쪼개다)로 partir el corazón '가슴이 찢어지다' → 정답 ✓","quita: quitar(빼앗다, 없애다)는 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V453","q":"Grecia ____ muchos visitantes porque tiene bastantes lugares de interés turístico.","o":["recibe","envía","contiene","da"],"a":0,"k":"관광 어휘","t":"그리스는 관광 명소가 꽤 많아서 많은 방문객을 맞이한다.","e":"recibir는 '받다'라는 뜻으로, 나라나 도시가 관광객을 '맞이하다, 유치하다'라고 할 때도 씁니다. recibir visitantes/turistas는 아주 자주 쓰는 표현입니다. 예: España recibe millones de turistas.(스페인은 수백만 명의 관광객을 맞는다.)","x":["recibe: recibir(받다, 맞이하다) → 관광객을 맞이하다 → 정답 ✓","envía: enviar(보내다)는 반대 방향의 의미라 ✗","contiene: contener(포함하다, 담다)는 그릇·내용물에 쓰는 말로 방문객과 어울리지 않습니다 ✗","da: dar(주다)는 visitantes와 함께 쓰지 않습니다 ✗"]},{"id":"V454","q":"¿Podrías poner estos tulipanes en ese ____?","o":["joyero","cajón","florero","baúl"],"a":2,"k":"생활용품 어휘","t":"이 튤립들을 저 꽃병에 꽂아 줄 수 있어?","e":"florero는 flor(꽃)에서 나온 말로 '꽃병'이라는 뜻입니다. 튤립(tulipanes)을 꽂는 곳이니 florero가 알맞습니다. 스페인어에서 -ero로 끝나는 단어는 '~을 담는 물건'인 경우가 많습니다(예: joyero 보석함, cenicero 재떨이).","x":["joyero: 보석함(또는 보석상)이라서 꽃을 꽂지 않습니다 ✗","cajón: 서랍이라서 꽃을 꽂는 곳이 아닙니다 ✗","florero: 꽃병 → 정답 ✓","baúl: 큰 궤짝, 트렁크라서 꽃과 맞지 않습니다 ✗"]},{"id":"V455","q":"No podemos ir a ____ porque todavía no hay nieve en la sierra.","o":["navegar","esquiar","nadar","bailar"],"a":1,"k":"스포츠 어휘","t":"산에 아직 눈이 없어서 우리는 스키를 타러 갈 수 없다.","e":"esquiar는 '스키를 타다'라는 동사입니다. 문장에서 눈(nieve)이 아직 없다고 했으니 눈이 필요한 활동인 esquiar가 정답입니다. sierra는 '산맥, 산악 지대'를 뜻합니다.","x":["navegar: 항해하다, 배를 타다(인터넷 서핑도 됨)라서 눈과 관계없습니다 ✗","esquiar: 스키를 타다 → 눈이 필요하므로 정답 ✓","nadar: 수영하다라서 눈과 관계없습니다 ✗","bailar: 춤추다라서 눈과 관계없습니다 ✗"]},{"id":"V456","q":"No tienes ____, estás equivocado.","o":["corazón","razón","ganas","suerte"],"a":1,"k":"tener 관용 표현","t":"넌 틀렸어, 네 말이 맞지 않아.","e":"tener razón은 '(말이) 옳다, 맞다'라는 뜻이고, no tener razón은 '틀리다'입니다. 뒤에 'estás equivocado(너는 잘못 알고 있다)'가 이어지므로 의미가 자연스럽게 연결됩니다. 예: Tienes razón.(네 말이 맞아.)","x":["corazón: 심장, 마음이라서 no tener corazón은 '무정하다'는 뜻이 되어 문맥과 맞지 않습니다 ✗","razón: 이유, 이성 → tener razón '옳다' → 정답 ✓","ganas: tener ganas는 '~하고 싶다'라서 뒤에 동사가 필요하고 문맥과 맞지 않습니다 ✗","suerte: 운이라서 no tener suerte는 '운이 없다'가 되어 '틀렸다'와 연결되지 않습니다 ✗"]},{"id":"V457","q":"Ya no cabe más ropa en este ____.","o":["enchufe","armario","televisor","ordenador"],"a":1,"k":"가구 어휘","t":"이 옷장에는 더 이상 옷이 들어가지 않는다.","e":"armario는 '옷장'입니다. caber는 '(공간에) 들어가다'라는 뜻으로, ya no cabe más ropa는 '옷이 더 들어갈 자리가 없다'는 의미입니다. 옷을 넣는 가구는 armario이므로 정답입니다.","x":["enchufe: 콘센트, 플러그라서 옷을 넣을 수 없습니다 ✗","armario: 옷장 → 정답 ✓","televisor: 텔레비전이라서 옷과 관계없습니다 ✗","ordenador: 컴퓨터(스페인식 표현)라서 옷과 관계없습니다 ✗"]},{"id":"V458","q":"Voy a llevar estos abrigos a la ____.","o":["tintorería","herboristería","pescadería","carnicería"],"a":0,"k":"상점 어휘","t":"이 코트들을 세탁소에 가져갈 거야.","e":"tintorería는 '세탁소(드라이클리닝 가게)'입니다. 코트(abrigos)처럼 집에서 빨기 어려운 옷은 tintorería에 맡깁니다. 스페인어에서 -ería로 끝나는 단어는 가게 이름인 경우가 많습니다.","x":["tintorería: 세탁소 → 코트를 맡기는 곳이라 정답 ✓","herboristería: 약초·허브 가게라서 옷과 관계없습니다 ✗","pescadería: 생선 가게라서 옷과 관계없습니다 ✗","carnicería: 정육점이라서 옷과 관계없습니다 ✗"]},{"id":"V459","q":"Para poder trabajar con nosotros, debe tener ____ para viajar.","o":["disponibilidad","especialidad","familiaridad","sinceridad"],"a":0,"k":"구직 어휘","t":"저희와 함께 일하려면 출장을 다닐 수 있어야 합니다.","e":"disponibilidad는 '시간·상황상 가능한 상태, 가용성'을 뜻합니다. tener disponibilidad para viajar는 구인 광고에서 자주 보이는 표현으로 '출장(이동)이 가능하다'는 뜻입니다. 형용사 disponible(이용 가능한, 시간이 되는)과 함께 기억하세요.","x":["disponibilidad: 가능성, 가용성 → '출장 가능'이라는 의미로 정답 ✓","especialidad: 전공, 전문 분야라서 para viajar와 어울리지 않습니다 ✗","familiaridad: 친숙함이라서 문맥과 맞지 않습니다 ✗","sinceridad: 성실함, 진심이라서 문맥과 맞지 않습니다 ✗"]},{"id":"V460","q":"Los dos equipos están empatados, es decir, tienen los mismos ____.","o":["espectadores","entrenadores","jugadores","puntos"],"a":3,"k":"스포츠 어휘","t":"두 팀은 동점이다, 즉 같은 점수를 가지고 있다.","e":"empatados는 '비긴, 동점인'이라는 뜻입니다. es decir(즉, 다시 말해)로 설명을 덧붙이므로 '같은 점수(puntos)'가 알맞습니다. punto는 '점, 점수'입니다.","x":["espectadores: 관중이라서 동점과 관계없습니다 ✗","entrenadores: 코치, 감독이라서 동점과 관계없습니다 ✗","jugadores: 선수라서 동점의 의미가 아닙니다 ✗","puntos: 점수 → 동점 = 같은 점수 → 정답 ✓"]},{"id":"V461","q":"No me gustan los sitios ruidosos, prefiero los espacios ____.","o":["tranquilos","urbanos","cerrados","grandes"],"a":0,"k":"형용사 반의어","t":"나는 시끄러운 곳을 좋아하지 않아, 조용한 공간을 더 좋아해.","e":"ruidoso(시끄러운)의 반대말은 tranquilo(조용한, 평온한)입니다. 앞 문장과 반대되는 선호를 말하고 있으므로 tranquilos가 정답입니다. espacios가 남성 복수라서 형용사도 남성 복수 -os 형태가 됩니다.","x":["tranquilos: 조용한 → 시끄러운 곳의 반대 → 정답 ✓","urbanos: 도시의라서 '시끄럽다'의 반대가 아닙니다 ✗","cerrados: 닫힌, 실내의라서 문맥과 맞지 않습니다 ✗","grandes: 큰이라서 '시끄럽다'의 반대가 아닙니다 ✗"]},{"id":"V462","q":"____ tiene diez años.","o":["Un siglo","Una semana","Un mes","Una década"],"a":3,"k":"시간 단위 어휘","t":"10년 단위(데케이드)는 10년으로 이루어진다.","e":"década는 '10년(십 년 단위)'을 뜻합니다. 'Una década tiene diez años'는 단어의 뜻을 설명하는 정의 문장입니다. 함께 기억할 단위: siglo(세기, 100년), semana(주), mes(달).","x":["Un siglo: 한 세기, 100년이라서 ✗","Una semana: 일주일, 7일이라서 ✗","Un mes: 한 달이라서 ✗","Una década: 10년 → 정답 ✓"]},{"id":"V463","q":"¿Me ____ algo de dinero? Te lo devolveré lo antes posible.","o":["robas","regalas","quitas","prestas"],"a":3,"k":"돈 관련 동사","t":"나한테 돈 좀 빌려줄래? 최대한 빨리 갚을게.","e":"prestar는 '빌려주다'입니다. 뒤 문장 'Te lo devolveré(돌려줄게)'로 보아 나중에 갚는 상황이므로 prestar가 알맞습니다. 참고로 '빌리다'는 pedir prestado라고 합니다.","x":["robas: robar(훔치다)라서 부탁하는 상황과 맞지 않습니다 ✗","regalas: regalar(선물하다)는 돌려줄 필요가 없어서 ✗","quitas: quitar(빼앗다, 치우다)라서 ✗","prestas: prestar(빌려주다) → 갚을 것이므로 정답 ✓"]},{"id":"V464","q":"Antes de ayer fui a un concierto de la ____ mexicana Julieta Venegas.","o":["diseñadora","pintora","cantante","modelo"],"a":2,"k":"직업 어휘","t":"그저께 나는 멕시코 가수 훌리에타 베네가스의 콘서트에 갔다.","e":"concierto(콘서트)에 나오는 사람은 cantante(가수)입니다. cantante는 남녀 모두 같은 형태이고 관사(la/el)로 성별을 나타냅니다. 훌리에타 베네가스는 실제 멕시코 출신 가수입니다.","x":["diseñadora: 여성 디자이너라서 콘서트와 맞지 않습니다 ✗","pintora: 여성 화가라서 콘서트와 맞지 않습니다 ✗","cantante: 가수 → 콘서트와 연결되므로 정답 ✓","modelo: 모델이라서 콘서트와 맞지 않습니다 ✗"]},{"id":"V465","q":"Me ____ daño en un hombro jugando al voleibol.","o":["di","puse","hice","quise"],"a":2,"k":"hacerse daño","t":"나는 배구를 하다가 어깨를 다쳤다.","e":"hacerse daño는 '다치다'라는 고정 표현입니다. 여기서는 hacer의 단순과거 1인칭 hice와 재귀대명사 me를 써서 me hice daño(내가 다쳤다)가 됩니다. 예: Me hice daño en la rodilla.(무릎을 다쳤어.)","x":["di: dar(주다)의 과거형, dar daño라는 표현은 '다치다'로 쓰지 않습니다 ✗","puse: poner(놓다)의 과거형이라 daño와 결합하지 않습니다 ✗","hice: hacer의 과거형 → hacerse daño '다치다' → 정답 ✓","quise: querer(원하다)의 과거형이라 의미가 맞지 않습니다 ✗"]},{"id":"V466","q":"Mi abuela es bastante ____. Tiene noventa años.","o":["joven","alta","chica","mayor"],"a":3,"k":"나이 형용사","t":"우리 할머니는 꽤 연세가 많으시다. 아흔 살이시다.","e":"mayor는 사람에게 쓸 때 '나이가 많은, 연세가 드신'이라는 공손한 표현입니다. 90세라고 했으므로 mayor가 정답입니다. viejo(늙은)보다 mayor가 더 정중하게 들립니다.","x":["joven: 젊은이라서 90세와 반대입니다 ✗","alta: 키가 큰이라서 나이와 관계없습니다 ✗","chica: 작은, 어린(여자아이)이라서 ✗","mayor: 나이가 많은 → 정답 ✓"]},{"id":"V467","q":"No tengo ganas de ____ esta noche. Prefiero quedarme en casa.","o":["salir","bajar","entrar","subir"],"a":0,"k":"이동 동사","t":"오늘 밤에는 외출하고 싶지 않아. 집에 있는 게 더 좋아.","e":"salir는 '나가다, 외출하다, 놀러 나가다'라는 뜻입니다. 뒤에 'quedarme en casa(집에 머무르다)'와 대조되므로 salir가 알맞습니다. tener ganas de + 동사원형은 '~하고 싶다'입니다.","x":["salir: 외출하다 → 집에 머무르는 것과 반대라 정답 ✓","bajar: 내려가다라서 문맥과 맞지 않습니다 ✗","entrar: 들어가다라서 문맥과 맞지 않습니다 ✗","subir: 올라가다라서 문맥과 맞지 않습니다 ✗"]},{"id":"V468","q":"Deseo encontrar trabajo en mi ____, que es el comercio.","o":["lugar","espacio","sector","hogar"],"a":2,"k":"직업 어휘","t":"나는 내 분야인 상업 쪽에서 일자리를 찾고 싶다.","e":"sector는 '부문, 분야, 업계'라는 뜻입니다. 'que es el comercio(그것은 상업이다)'로 산업 분야를 설명하므로 sector가 알맞습니다. 예: el sector turístico(관광 업계).","x":["lugar: 장소라서 '상업'이라는 분야를 가리키지 않습니다 ✗","espacio: 공간이라서 ✗","sector: 분야, 업계 → 정답 ✓","hogar: 가정, 집이라서 ✗"]},{"id":"V469","q":"Manolito no fue al colegio ayer porque estaba ____.","o":["relajado","malo","bien","sano"],"a":1,"k":"estar malo","t":"마놀리토는 어제 아파서 학교에 가지 않았다.","e":"malo는 estar와 함께 쓰면 '아프다'라는 뜻이 됩니다(스페인에서 특히 자주 씀). ser malo는 '나쁘다'이므로 ser/estar에 따라 뜻이 달라집니다. 학교에 가지 못한 이유이므로 estaba malo(아팠다)가 정답입니다.","x":["relajado: 편안한이라서 결석 이유가 되지 않습니다 ✗","malo: estar malo '아프다' → 정답 ✓","bien: 괜찮은, 좋은이라서 결석 이유가 아닙니다 ✗","sano: 건강한이라서 결석 이유와 반대입니다 ✗"]},{"id":"V470","q":"Suelo mirar la hora en mi móvil, por eso no me hace falta un ____.","o":["teléfono","reloj","estuche","boli"],"a":1,"k":"소지품 어휘","t":"나는 보통 휴대폰으로 시간을 봐서 손목시계가 필요 없다.","e":"reloj는 '시계'입니다. 휴대폰으로 시간을 확인하니 시계가 필요 없다는 내용이므로 reloj가 정답입니다. hacer falta는 '필요하다'라는 표현입니다.","x":["teléfono: 전화기라서 이미 휴대폰을 쓰고 있다는 문장과 맞지 않습니다 ✗","reloj: 시계 → 시간을 보는 물건이라 정답 ✓","estuche: 필통, 케이스라서 시간과 관계없습니다 ✗","boli: 볼펜(bolígrafo의 줄임말)이라서 ✗"]},{"id":"V471","q":"Cuando vi el ____, llamé a una ambulancia inmediatamente.","o":["mar","bosque","lago","accidente"],"a":3,"k":"사고 어휘","t":"사고를 보고 나는 즉시 구급차를 불렀다.","e":"accidente는 '사고'입니다. 구급차(ambulancia)를 부르게 된 이유가 되는 것은 사고이므로 accidente가 정답입니다. 예: un accidente de tráfico(교통사고).","x":["mar: 바다라서 구급차를 부를 이유가 되지 않습니다 ✗","bosque: 숲이라서 ✗","lago: 호수라서 ✗","accidente: 사고 → 정답 ✓"]},{"id":"V472","q":"Voy a desayunar dos tostadas con mantequilla, un ____ de naranja y un café solo.","o":["batido","zumo","té","vino"],"a":1,"k":"음식 어휘","t":"나는 아침으로 버터 바른 토스트 두 장, 오렌지 주스 한 잔, 블랙커피 한 잔을 먹을 거야.","e":"zumo는 스페인에서 '과일 주스'를 뜻하며, zumo de naranja는 '오렌지 주스'입니다. 중남미에서는 보통 jugo라고 합니다. café solo는 '우유 없는 블랙커피(에스프레소)'입니다.","x":["batido: 밀크셰이크로 de naranja와는 잘 쓰지 않습니다 ✗","zumo: 과일 주스 → zumo de naranja 정답 ✓","té: 차라서 de naranja와 어울리지 않습니다 ✗","vino: 와인이라서 아침 식사와 de naranja에 맞지 않습니다 ✗"]},{"id":"V473","q":"No estoy de acuerdo contigo. Tengo una ____ muy diferente.","o":["formación","conversación","educación","opinión"],"a":3,"k":"의견 어휘","t":"나는 너와 생각이 달라. 나는 매우 다른 의견을 가지고 있어.","e":"opinión은 '의견'입니다. no estar de acuerdo(동의하지 않다)와 이어지므로 '다른 의견'이 자연스럽습니다. 예: En mi opinión…(내 생각에는…).","x":["formación: 교육 과정, 양성이라서 ✗","conversación: 대화라서 '다른 대화를 가지다'는 어색합니다 ✗","educación: 교육, 예의라서 ✗","opinión: 의견 → 정답 ✓"]},{"id":"V474","q":"No olvides que debes conducir con ____.","o":["precaución","intención","emoción","tensión"],"a":0,"k":"명사 어휘","t":"조심해서 운전해야 한다는 것을 잊지 마.","e":"precaución은 '조심, 주의'입니다. conducir con precaución은 '조심해서 운전하다'라는 자주 쓰는 표현입니다. con + 명사는 '~하게'라는 부사 역할을 합니다.","x":["precaución: 조심, 주의 → 정답 ✓","intención: 의도라서 운전 방식과 맞지 않습니다 ✗","emoción: 감정, 감동이라서 ✗","tensión: 긴장이라서 '긴장해서 운전하라'는 조언이 되지 않습니다 ✗"]},{"id":"V475","q":"Alfredo tiene muchos amigos porque es una persona muy ____.","o":["sincera","sociable","introvertida","solitaria"],"a":1,"k":"성격 형용사","t":"알프레도는 사교성이 아주 좋아서 친구가 많다.","e":"sociable은 '사교적인'입니다. 친구가 많은 이유를 설명하므로 sociable이 알맞습니다. -able로 끝나는 형용사는 남녀 형태가 같습니다.","x":["sincera: 솔직한이라는 뜻으로 좋은 성격이지만 친구가 많은 직접적인 이유는 아닙니다 ✗","sociable: 사교적인 → 정답 ✓","introvertida: 내성적인이라서 친구가 많은 것과 반대입니다 ✗","solitaria: 고독한, 혼자 있기 좋아하는이라서 반대입니다 ✗"]},{"id":"V476","q":"Amelia es una chica muy divertida. Nunca ____ con ella.","o":["te aburres","te encuentras","sales","te peleas"],"a":0,"k":"재귀동사 aburrirse","t":"아멜리아는 아주 재미있는 아이야. 그녀와 함께 있으면 절대 지루하지 않아.","e":"aburrirse는 '지루해하다, 심심해하다'라는 재귀동사(행동이 자기 자신에게 돌아오는 동사)입니다. divertida(재미있는)와 대조되어 nunca te aburres(절대 지루하지 않다)가 자연스럽습니다. 여기서 te는 특정한 '너'가 아니라 '누구든'이라는 일반적인 뜻으로 쓰였습니다.","x":["te aburres: 지루해하다 → 재미있는 사람이라 지루하지 않다 → 정답 ✓","te encuentras: 마주치다, (몸 상태가) ~하다라서 문맥과 맞지 않습니다 ✗","sales: 나가다, (con과 함께) 사귀다라서 '재미있다'와 연결되지 않습니다 ✗","te peleas: 싸우다라서 '재미있는 아이'라는 이유와 맞지 않습니다 ✗"]},{"id":"V477","q":"Solo los mejores ____ pueden llegar al pico de esa montaña.","o":["escaladores","ascensores","elevadores","repartidores"],"a":0,"k":"직업·사람 어휘","t":"최고의 등반가들만 저 산의 정상에 오를 수 있다.","e":"escalador는 '등반가, 클라이머'입니다. 동사 escalar(오르다, 등반하다)에서 나온 단어로 -dor는 '~하는 사람'을 뜻합니다. pico는 '산봉우리, 정상'입니다.","x":["escaladores: 등반가들 → 산 정상에 오르는 사람이라 정답 ✓","ascensores: 엘리베이터들이라서 사람이 아닙니다 ✗","elevadores: 엘리베이터, 승강기(중남미)라서 ✗","repartidores: 배달원들이라서 산 등반과 관계없습니다 ✗"]},{"id":"V478","q":"Julián está de camarero en el ____ de la esquina.","o":["estanco","café","banco","taller"],"a":1,"k":"장소 어휘","t":"훌리안은 모퉁이에 있는 카페에서 웨이터로 일하고 있다.","e":"camarero(웨이터)가 일하는 곳은 café(카페)입니다. estar de + 직업은 '(임시로) ~로 일하고 있다'는 표현입니다. 예: Está de profesor este año.(올해 선생님으로 일하고 있다.)","x":["estanco: 담배·우표 파는 가게(스페인)라서 웨이터가 없습니다 ✗","café: 카페 → 웨이터가 일하는 곳 → 정답 ✓","banco: 은행이라서 웨이터가 일하지 않습니다 ✗","taller: 정비소, 작업장이라서 ✗"]},{"id":"V479","q":"Tus llaves están en el ____ de tu pantalón.","o":["gorro","bolso","cinturón","bolsillo"],"a":3,"k":"의류 어휘","t":"네 열쇠는 바지 주머니에 있어.","e":"bolsillo는 '주머니'입니다. bolso(가방)에 '작은'을 뜻하는 -illo가 붙은 형태로 기억하면 쉽습니다. 바지(pantalón)에 달린 것이므로 bolsillo가 정답입니다.","x":["gorro: 털모자라서 바지에 없습니다 ✗","bolso: 핸드백, 가방이라서 바지의 일부가 아닙니다 ✗","cinturón: 허리띠라서 열쇠를 넣을 수 없습니다 ✗","bolsillo: 주머니 → 정답 ✓"]},{"id":"V480","q":"¿Vivís en el centro de la ____ o a las afueras?","o":["ciudad","nación","vivienda","patria"],"a":0,"k":"도시 어휘","t":"너희는 도시 중심에 사니, 아니면 교외에 사니?","e":"ciudad는 '도시'입니다. centro de la ciudad(도심)와 afueras(교외, 변두리)는 짝으로 자주 쓰입니다. vivís는 vosotros(너희, 스페인에서 쓰는 2인칭 복수)의 형태이며, 중남미에서는 ustedes viven을 씁니다.","x":["ciudad: 도시 → 도심/교외 대비가 자연스러워 정답 ✓","nación: 국가라서 '국가의 중심'은 어색합니다 ✗","vivienda: 주택이라서 집의 '중심'과 교외는 맞지 않습니다 ✗","patria: 조국이라서 ✗"]},{"id":"V481","q":"Este examen tiene una duración de 60 ____.","o":["dólares","minutos","años","céntimos"],"a":1,"k":"시간 단위 어휘","t":"이 시험은 시험 시간이 60분이다.","e":"duración은 '지속 시간'이므로 시간 단위가 와야 합니다. 시험 시간으로 60 minutos(60분)가 자연스럽습니다.","x":["dólares: 달러(돈)라서 시간이 아닙니다 ✗","minutos: 분 → 정답 ✓","años: 년이라서 시험 시간으로 말이 안 됩니다 ✗","céntimos: 센트(돈)라서 ✗"]},{"id":"V482","q":"____ con mis amigas para ir de compras.","o":["He quedado","He tomado","He pasado","He hecho"],"a":0,"k":"quedar 약속","t":"나는 쇼핑하러 가려고 친구들과 약속을 잡았다.","e":"quedar con + 사람은 '~와 만나기로 하다, 약속하다'라는 뜻입니다(스페인에서 특히 자주 씀). He quedado는 현재완료(가까운 과거나 지금과 관련된 일을 말하는 시제)입니다. 예: ¿Quedamos a las cinco?(5시에 만날까?)","x":["He quedado: quedar con '~와 약속하다' → 정답 ✓","He tomado: tomar(잡다, 먹다)는 con mis amigas와 이런 뜻을 만들지 않습니다 ✗","He pasado: pasar(지나가다, 보내다)라서 문맥과 맞지 않습니다 ✗","He hecho: hacer(하다)는 목적어 없이 이 의미가 되지 않습니다 ✗"]},{"id":"V483","q":"Un día tiene veinticuatro ____.","o":["segundos","milisegundos","minutos","horas"],"a":3,"k":"시간 단위 어휘","t":"하루는 24시간이다.","e":"hora는 '시간(60분 단위)'입니다. 하루(un día)는 24시간이므로 horas가 정답입니다. 함께: segundo(초), minuto(분), hora(시간).","x":["segundos: 초라서 하루는 24초가 아닙니다 ✗","milisegundos: 밀리초라서 ✗","minutos: 분이라서 ✗","horas: 시간 → 정답 ✓"]},{"id":"V484","q":"No tengo ganas de comer ____ porque comí hace poco.","o":["siempre","nunca","todavía","mientras"],"a":2,"k":"todavía 부사","t":"조금 전에 먹었기 때문에 아직은 먹고 싶지 않다.","e":"todavía는 '아직'이라는 뜻의 부사로 부정문에서 '아직 ~않다'를 나타냅니다. 조금 전에 먹었다는 이유가 있으니 '아직 먹고 싶지 않다'가 자연스럽습니다. 예: Todavía no he terminado.(아직 끝내지 않았어.)","x":["siempre: 항상이라서 '조금 전에 먹었다'는 이유와 맞지 않습니다 ✗","nunca: 절대 ~않다라서 이미 no가 있는 문장에 의미가 어색합니다 ✗","todavía: 아직 → 정답 ✓","mientras: ~하는 동안(접속사)이라서 문장 끝에 단독으로 쓰지 않습니다 ✗"]},{"id":"V485","q":"Se ha tomado una ____ porque le duele mucho la cabeza.","o":["sopa","aspirina","tila","golosina"],"a":1,"k":"약·건강 어휘","t":"그는 머리가 너무 아파서 아스피린을 먹었다.","e":"aspirina는 '아스피린(진통제)'입니다. 두통(le duele la cabeza) 때문에 먹는 것이므로 aspirina가 정답입니다. 약을 먹을 때도 tomar(복용하다)를 씁니다.","x":["sopa: 수프라서 두통약이 아닙니다 ✗","aspirina: 아스피린 → 두통에 먹는 약이라 정답 ✓","tila: 보리수꽃 차(진정용 허브차)로 두통약은 아닙니다 ✗","golosina: 사탕, 군것질거리라서 ✗"]},{"id":"V486","q":"Buenos Aires es la ____ de Argentina.","o":["capital","calle","ciudad","avenida"],"a":0,"k":"지리 어휘","t":"부에노스아이레스는 아르헨티나의 수도이다.","e":"capital은 '수도'입니다. 'X es la capital de 나라' 형태로 수도를 말합니다. 예: Madrid es la capital de España.(마드리드는 스페인의 수도다.)","x":["capital: 수도 → 정답 ✓","calle: 거리라서 ✗","ciudad: 도시라서 la ciudad de Argentina는 '아르헨티나의 그 도시'로 어색합니다 ✗","avenida: 대로, 큰길이라서 ✗"]},{"id":"V487","q":"Mi hijo es muy generoso. ____ sus juguetes con otros niños sin problema.","o":["Compra","Comparte","Completa","Comprende"],"a":1,"k":"동사 어휘","t":"우리 아들은 아주 너그러워. 다른 아이들과 장난감을 아무 문제 없이 나눠 가져.","e":"compartir는 '함께 쓰다, 나누다'입니다. generoso(너그러운, 인심 좋은)와 연결되어 장난감을 나눈다는 뜻이 자연스럽습니다. compartir algo con alguien(~와 무엇을 나누다) 구조로 씁니다.","x":["Compra: comprar(사다)라서 con otros niños와 맞지 않습니다 ✗","Comparte: compartir(나누다, 공유하다) → 정답 ✓","Completa: completar(완성하다)라서 ✗","Comprende: comprender(이해하다)라서 ✗"]},{"id":"V488","q":"Patricia no habla mucho en clase porque es ____.","o":["amable","impaciente","tímida","puntual"],"a":2,"k":"성격 형용사","t":"파트리시아는 수줍음이 많아서 수업 시간에 말을 많이 하지 않는다.","e":"tímido/tímida는 '수줍은, 소심한'입니다. 말을 많이 하지 않는 이유로 가장 적절합니다. Patricia가 여성이므로 tímida입니다.","x":["amable: 친절한이라서 말을 안 하는 이유가 아닙니다 ✗","impaciente: 참을성 없는이라서 ✗","tímida: 수줍은 → 정답 ✓","puntual: 시간을 잘 지키는이라서 ✗"]},{"id":"V489","q":"En este programa, los concursantes tienen que responder a ____ difíciles.","o":["soluciones","errores","datos","preguntas"],"a":3,"k":"명사 어휘","t":"이 프로그램에서 참가자들은 어려운 질문에 답해야 한다.","e":"pregunta는 '질문'입니다. responder a(~에 답하다)와 자연스럽게 어울립니다. 동사 preguntar(묻다)와 함께 기억하세요.","x":["soluciones: 해결책, 정답이라서 '정답에 답하다'는 어색합니다 ✗","errores: 실수들이라서 ✗","datos: 데이터, 정보라서 ✗","preguntas: 질문들 → 정답 ✓"]},{"id":"V490","q":"Vamos a dar un paseo en barca en ese ____.","o":["lago","monte","bosque","campo"],"a":0,"k":"자연 어휘","t":"저 호수에서 보트 타고 산책하자.","e":"lago는 '호수'입니다. barca(작은 배, 보트)를 탈 수 있는 곳은 물이 있는 곳이므로 lago가 정답입니다. dar un paseo en barca는 '보트를 타고 한 바퀴 돌다'입니다.","x":["lago: 호수 → 배를 탈 수 있어 정답 ✓","monte: 산이라서 배를 탈 수 없습니다 ✗","bosque: 숲이라서 ✗","campo: 들판, 시골이라서 ✗"]},{"id":"V491","q":"El día de San Valentín mi marido me regaló un ramo de ____.","o":["joyas","bombones","viajes","rosas"],"a":3,"k":"선물 어휘","t":"밸런타인데이에 남편이 나에게 장미 꽃다발을 선물했다.","e":"ramo는 '꽃다발'이므로 꽃 이름이 와야 합니다. un ramo de rosas는 '장미 꽃다발'입니다. 예: un ramo de flores(꽃다발).","x":["joyas: 보석이라서 ramo(꽃다발)와 맞지 않습니다 ✗","bombones: 초콜릿 봉봉이라서 보통 caja(상자)와 씁니다 ✗","viajes: 여행이라서 다발로 줄 수 없습니다 ✗","rosas: 장미 → 장미 꽃다발 → 정답 ✓"]},{"id":"V492","q":"No podría vivir en una calle con tanto tráfico. ¡Es ____!","o":["horrible","estupendo","genial","maravilloso"],"a":0,"k":"감정 형용사","t":"이렇게 교통이 혼잡한 거리에서는 살 수 없을 거야. 끔찍해!","e":"horrible은 '끔찍한, 지독한'입니다. 그런 곳에서는 살 수 없다는 부정적인 내용이므로 부정적인 형용사가 와야 합니다. 나머지 보기는 모두 긍정적인 뜻입니다.","x":["horrible: 끔찍한 → 부정적 문맥과 맞아 정답 ✓","estupendo: 훌륭한이라서 긍정적이라 ✗","genial: 끝내주는, 멋진이라서 ✗","maravilloso: 놀라운, 멋진이라서 ✗"]},{"id":"V493","q":"La casa está ____. Tenemos que limpiarla.","o":["sucia","ordenada","alquilada","vacía"],"a":0,"k":"상태 형용사","t":"집이 더러워. 청소해야 해.","e":"sucio/sucia는 '더러운'입니다. 청소해야 한다는 이유가 되므로 sucia가 정답입니다. 반대말은 limpio/limpia(깨끗한)입니다. 상태를 말하므로 estar를 씁니다.","x":["sucia: 더러운 → 청소할 이유라 정답 ✓","ordenada: 정돈된이라서 청소할 이유와 반대입니다 ✗","alquilada: 임대된이라서 청소와 관계없습니다 ✗","vacía: 비어 있는이라서 청소의 이유가 되기 어렵습니다 ✗"]},{"id":"V494","q":"No soporto las situaciones estresantes porque me hacen sentir ____.","o":["ansiedad","bondad","maldad","habilidad"],"a":0,"k":"감정 명사","t":"스트레스 받는 상황은 나를 불안하게 해서 견딜 수가 없다.","e":"ansiedad는 '불안'입니다. sentir ansiedad는 '불안을 느끼다'입니다. 스트레스(estresantes)와 가장 잘 연결되는 감정입니다. 참고: no soportar는 '참을 수 없다'입니다.","x":["ansiedad: 불안 → 정답 ✓","bondad: 선함, 친절이라서 ✗","maldad: 악함, 악의라서 ✗","habilidad: 능력, 솜씨라서 ✗"]},{"id":"V495","q":"¿Me pone un café para ____, por favor?","o":["llevar","salir","entrar","andar"],"a":0,"k":"주문 표현","t":"커피 한 잔 포장해 주시겠어요?","e":"para llevar는 카페나 식당에서 '포장해서 가져가는(테이크아웃)'이라는 뜻의 고정 표현입니다. 매장에서 먹을 때는 para tomar aquí라고 합니다. ¿Me pone…?는 스페인에서 주문할 때 흔히 쓰는 말입니다.","x":["llevar: para llevar '테이크아웃' → 정답 ✓","salir: para salir는 주문 표현이 아닙니다 ✗","entrar: 들어가다라서 ✗","andar: 걷다라서 ✗"]},{"id":"V496","q":"Si le interesa este trabajo, mande su ____ a nuestra dirección de correo electrónico.","o":["currículum","informe","entrevista","carrera"],"a":0,"k":"구직 어휘","t":"이 일자리에 관심이 있으시면 저희 이메일 주소로 이력서를 보내 주세요.","e":"currículum은 '이력서'입니다. 구인 광고에서 mande/envíe su currículum(이력서를 보내세요)은 아주 자주 나오는 표현입니다. 줄여서 CV라고도 합니다.","x":["currículum: 이력서 → 정답 ✓","informe: 보고서라서 구직 지원과 맞지 않습니다 ✗","entrevista: 면접이라서 이메일로 보낼 수 없습니다 ✗","carrera: (대학) 전공, 경력이라서 보내는 서류가 아닙니다 ✗"]},{"id":"V497","q":"¿Cuántas ____ de azúcar quieres en tu café?","o":["cacerolas","cucharaditas","ollas","tazas"],"a":1,"k":"주방 어휘","t":"커피에 설탕 몇 스푼 넣어 줄까?","e":"cucharadita는 '찻숟가락 하나 분량'입니다. cuchara(숟가락) → cucharada(한 숟가락) → cucharadita(작은 한 숟가락)로 기억하세요. 커피에 넣는 설탕의 양으로 가장 자연스럽습니다.","x":["cacerolas: 냄비라서 커피에 넣는 양이 아닙니다 ✗","cucharaditas: 찻숟가락 분량 → 정답 ✓","ollas: 솥, 냄비라서 ✗","tazas: 컵이라서 설탕 몇 컵은 지나치게 많습니다 ✗"]},{"id":"V498","q":"Un minuto tiene sesenta ____.","o":["horas","tiempos","segundos","días"],"a":2,"k":"시간 단위 어휘","t":"1분은 60초이다.","e":"segundo는 '초'입니다. 1분(un minuto)은 60초이므로 segundos가 정답입니다. 참고로 segundo는 '두 번째'라는 뜻도 있습니다.","x":["horas: 시간이라서 ✗","tiempos: 시간, 때(셀 수 있는 단위가 아님)라서 ✗","segundos: 초 → 정답 ✓","días: 일, 날이라서 ✗"]},{"id":"V499","q":"En el ____ de mi abuela hay muchos árboles frutales.","o":["huerto","auto","cuarto","piso"],"a":0,"k":"장소 어휘","t":"우리 할머니의 텃밭에는 과일나무가 많다.","e":"huerto는 '텃밭, 과수원'입니다. 과일나무(árboles frutales)가 있는 곳으로 가장 알맞습니다. 비슷한 단어로 jardín(정원)이 있습니다.","x":["huerto: 텃밭, 과수원 → 정답 ✓","auto: 자동차(중남미)라서 나무가 있을 수 없습니다 ✗","cuarto: 방이라서 ✗","piso: 아파트, 층이라서 ✗"]},{"id":"V500","q":"El ____ del actor argentino Ricardo Darín se debe a su gran talento.","o":["afecto","fracaso","enfado","éxito"],"a":3,"k":"명사 어휘","t":"아르헨티나 배우 리카르도 다린의 성공은 그의 뛰어난 재능 덕분이다.","e":"éxito는 '성공'입니다(영어 exit와 혼동 주의, '출구'는 salida). 재능(talento) 덕분이라는 긍정적 원인과 연결되므로 éxito가 정답입니다. deberse a는 '~때문이다, ~덕분이다'입니다.","x":["afecto: 애정이라서 재능의 결과로 어색합니다 ✗","fracaso: 실패라서 '재능 덕분'과 맞지 않습니다 ✗","enfado: 화, 분노라서 ✗","éxito: 성공 → 정답 ✓"]},{"id":"V501","q":"¿Puedes ____ todos esos papeles en la papelera?","o":["tirar","completar","repartir","rellenar"],"a":0,"k":"동사 어휘","t":"그 종이들을 전부 휴지통에 버려 줄 수 있어?","e":"tirar는 '버리다, 던지다'입니다. tirar algo a la basura / en la papelera(쓰레기통에 버리다)는 자주 쓰는 표현입니다. papelera는 '휴지통'입니다.","x":["tirar: 버리다 → 휴지통에 버리다 → 정답 ✓","completar: 완성하다, 채우다라서 휴지통과 맞지 않습니다 ✗","repartir: 나눠 주다, 배달하다라서 ✗","rellenar: (서류를) 작성하다, 다시 채우다라서 ✗"]},{"id":"V502","q":"Mañana voy a hacer un examen muy importante. —¡____!","o":["Buen viaje","Saludos","Un abrazo","Buena suerte"],"a":3,"k":"인사·기원 표현","t":"내일 아주 중요한 시험을 봐. —행운을 빌어!","e":"¡Buena suerte!는 '행운을 빌어!'라는 뜻으로 시험·면접 등 앞두고 있는 사람에게 하는 말입니다. 비슷한 표현: ¡Mucha suerte!","x":["Buen viaje: 즐거운 여행 되세요라서 시험과 맞지 않습니다 ✗","Saludos: 안부 인사라서 ✗","Un abrazo: (편지 끝 인사) 포옹을 보내요라서 ✗","Buena suerte: 행운을 빌어 → 정답 ✓"]},{"id":"V503","q":"Vicente tiene muchas cualidades, pero también tiene un ____: es muy impulsivo.","o":["propósito","deseo","defecto","objetivo"],"a":2,"k":"성격 명사","t":"비센테는 장점이 많지만 단점도 있다. 매우 충동적이다.","e":"defecto는 '결점, 단점'입니다. cualidades(장점, 좋은 자질)와 pero(하지만)로 대조되므로 defecto가 알맞습니다. impulsivo(충동적인)가 그 단점의 예입니다.","x":["propósito: 목적, 결심이라서 ✗","deseo: 바람, 소원이라서 ✗","defecto: 단점 → 장점과 대조되어 정답 ✓","objetivo: 목표라서 ✗"]},{"id":"V504","q":"Tengo que comprar un teclado nuevo para mi ____.","o":["cuaderno","proyector","ordenador","bolígrafo"],"a":2,"k":"전자기기 어휘","t":"내 컴퓨터용 새 키보드를 사야 한다.","e":"ordenador는 스페인에서 쓰는 '컴퓨터'라는 단어이고, 중남미에서는 computadora(또는 computador)라고 합니다. teclado(키보드)가 필요한 기기이므로 ordenador가 정답입니다.","x":["cuaderno: 공책이라서 키보드가 없습니다 ✗","proyector: 프로젝터라서 키보드를 쓰지 않습니다 ✗","ordenador: 컴퓨터 → 정답 ✓","bolígrafo: 볼펜이라서 ✗"]},{"id":"V505","q":"Vamos a ir a un festival donde van a ____ grandes estrellas del flamenco.","o":["dibujar","pintar","escribir","actuar"],"a":3,"k":"공연 동사","t":"우리는 플라멩코 대스타들이 공연할 축제에 갈 거야.","e":"actuar는 '공연하다, 연기하다'입니다. 축제(festival)에서 스타들이 무대에 서는 것이므로 actuar가 정답입니다. 명사 actuación(공연, 연기)도 함께 기억하세요.","x":["dibujar: 그림을 그리다(선으로)라서 ✗","pintar: (물감으로) 그리다, 칠하다라서 ✗","escribir: 쓰다라서 ✗","actuar: 공연하다 → 정답 ✓"]},{"id":"V506","q":"Le han dado varios ____ por su brillante actuación en esta película.","o":["premios","desprecios","aprecios","precios"],"a":0,"k":"명사 어휘","t":"그는 이 영화에서의 훌륭한 연기로 여러 상을 받았다.","e":"premio는 '상'입니다. dar un premio(상을 주다)라는 표현이 자연스럽습니다. precio(가격)와 철자가 비슷하니 헷갈리지 않도록 주의하세요.","x":["premios: 상 → 정답 ✓","desprecios: 경멸, 무시라서 훌륭한 연기와 맞지 않습니다 ✗","aprecios: 존중, 평가(보통 복수로 쓰지 않음)라서 ✗","precios: 가격이라서 ✗"]},{"id":"V507","q":"Este pan está ____, no se lo des al bebé.","o":["blando","duro","bueno","delicioso"],"a":1,"k":"음식 형용사","t":"이 빵은 딱딱하니까 아기한테 주지 마.","e":"duro는 '딱딱한'입니다. 아기에게 주지 말라는 이유가 되므로 duro가 알맞습니다. 반대말은 blando(부드러운, 말랑한)입니다. pan duro는 '오래되어 굳은 빵'을 말하기도 합니다.","x":["blando: 부드러운이라서 아기에게 주지 말아야 할 이유가 아닙니다 ✗","duro: 딱딱한 → 정답 ✓","bueno: 맛있는, 좋은이라서 ✗","delicioso: 아주 맛있는이라서 ✗"]},{"id":"V508","q":"Siempre viajo en ____, no me gusta ir sola.","o":["avión","barco","grupo","tren"],"a":2,"k":"여행 표현","t":"나는 항상 단체로 여행해, 혼자 가는 건 좋아하지 않아.","e":"viajar en grupo는 '단체로 여행하다'입니다. 혼자(sola) 가는 것을 싫어한다는 이유와 연결됩니다. en avión, en tren처럼 교통수단도 en을 쓰지만 여기서는 '혼자 vs 여럿'의 대비가 핵심입니다.","x":["avión: 비행기라서 혼자 가는 것과 대비되지 않습니다 ✗","barco: 배라서 ✗","grupo: 단체 → 혼자와 반대 → 정답 ✓","tren: 기차라서 ✗"]},{"id":"V509","q":"¡Qué película tan lenta! Me muero de ____.","o":["alegría","aburrimiento","sed","hambre"],"a":1,"k":"morirse de 표현","t":"영화가 정말 지루하네! 지루해 죽겠어.","e":"morirse de + 명사는 '~해서 죽겠다'라는 과장 표현입니다. 느린(lenta) 영화이므로 aburrimiento(지루함)가 정답입니다. 예: Me muero de hambre.(배고파 죽겠어.)","x":["alegría: 기쁨이라서 지루한 영화와 맞지 않습니다 ✗","aburrimiento: 지루함 → 정답 ✓","sed: 갈증이라서 영화와 관계없습니다 ✗","hambre: 배고픔이라서 영화와 관계없습니다 ✗"]},{"id":"V510","q":"En este ____ hay flores muy bonitas.","o":["mar","río","lago","jardín"],"a":3,"k":"장소 어휘","t":"이 정원에는 아주 예쁜 꽃들이 있다.","e":"jardín은 '정원'입니다. 꽃(flores)이 피는 곳으로 가장 자연스럽습니다. 악센트(í)를 꼭 기억하세요.","x":["mar: 바다라서 꽃이 없습니다 ✗","río: 강이라서 ✗","lago: 호수라서 ✗","jardín: 정원 → 정답 ✓"]},{"id":"V511","q":"El suelo está ____ porque ha llovido.","o":["pintado","seco","mojado","caliente"],"a":2,"k":"상태 형용사","t":"비가 와서 바닥이 젖어 있다.","e":"mojado는 '젖은'입니다. 비가 왔기 때문이라는 이유와 연결됩니다. 반대말은 seco(마른)입니다. ha llovido는 llover(비가 오다)의 현재완료입니다.","x":["pintado: 칠해진이라서 비와 관계없습니다 ✗","seco: 마른이라서 비가 온 결과와 반대입니다 ✗","mojado: 젖은 → 정답 ✓","caliente: 뜨거운이라서 ✗"]},{"id":"V512","q":"Deberías ser más optimista, no todo es ____.","o":["fantástico","negativo","divertido","positivo"],"a":1,"k":"형용사 반의어","t":"너는 좀 더 낙관적이어야 해, 모든 게 부정적인 건 아니야.","e":"negativo는 '부정적인'입니다. optimista(낙관적인)가 되라는 조언이므로 '모든 것이 부정적이진 않다'가 자연스럽습니다. 반대말은 positivo(긍정적인)입니다.","x":["fantástico: 환상적인이라서 조언 문맥과 맞지 않습니다 ✗","negativo: 부정적인 → 정답 ✓","divertido: 재미있는이라서 ✗","positivo: 긍정적인이라서 '모든 게 긍정적인 건 아니다'는 반대 뜻입니다 ✗"]},{"id":"V513","q":"Odio las guerras, soy una persona ____.","o":["nerviosa","insensible","conocida","pacífica"],"a":3,"k":"성격 형용사","t":"나는 전쟁을 싫어해, 나는 평화를 사랑하는 사람이야.","e":"pacífico/pacífica는 '평화로운, 평화를 사랑하는'입니다. guerras(전쟁)을 싫어한다는 내용과 연결됩니다. persona가 여성 명사라 pacífica 형태입니다.","x":["nerviosa: 신경질적인, 긴장한이라서 ✗","insensible: 무감각한, 냉담한이라서 ✗","conocida: 유명한, 알려진이라서 ✗","pacífica: 평화를 사랑하는 → 정답 ✓"]},{"id":"V514","q":"En mi barrio no hay ambiente, por eso ____.","o":["me levanto","me aburro","me acuesto","me despierto"],"a":1,"k":"재귀동사 aburrirse","t":"우리 동네는 활기가 없어서 나는 심심하다.","e":"me aburro는 aburrirse(지루해하다)의 1인칭 현재입니다. ambiente는 여기서 '활기, 분위기(놀 거리)'를 뜻합니다. 활기가 없으니 지루하다는 결과가 자연스럽습니다.","x":["me levanto: 일어나다라서 이유와 연결되지 않습니다 ✗","me aburro: 지루하다 → 정답 ✓","me acuesto: 잠자리에 들다라서 ✗","me despierto: 잠에서 깨다라서 ✗"]},{"id":"V515","q":"Normalmente ____ el autobús de las ocho y media.","o":["cojo","realizo","creo","hago"],"a":0,"k":"교통 동사","t":"나는 보통 8시 반 버스를 탄다.","e":"coger는 스페인에서 '(교통수단을) 타다'라는 뜻으로 자주 씁니다: coger el autobús. 하지만 중남미 여러 나라(멕시코, 아르헨티나 등)에서는 coger가 비속어로 들릴 수 있어 tomar el autobús를 씁니다. cojo는 1인칭 현재형(g→j 철자 변화)입니다.","x":["cojo: coger '타다' → 정답 ✓","realizo: realizar(실행하다)라서 버스와 쓰지 않습니다 ✗","creo: crear(만들다) 또는 creer(믿다)라서 ✗","hago: hacer(하다)라서 버스를 탄다는 뜻이 되지 않습니다 ✗"]},{"id":"V516","q":"Ana y José Carlos se han separado. —Qué ____, hacían buena pareja.","o":["bien","pena","alegría","suerte"],"a":1,"k":"감탄 표현","t":"아나와 호세 카를로스가 헤어졌어. —안됐다, 잘 어울리는 커플이었는데.","e":"¡Qué pena!는 '안됐다, 아쉽다'라는 뜻으로 나쁜 소식을 들었을 때 하는 반응입니다. pena는 '슬픔, 유감'입니다. 비슷한 표현: ¡Qué lástima!","x":["bien: qué bien은 '잘됐다'라서 이별 소식에 맞지 않습니다 ✗","pena: qué pena '안됐다' → 정답 ✓","alegría: qué alegría는 '정말 기쁘다'라서 ✗","suerte: qué suerte는 '운 좋다'라서 ✗"]},{"id":"V517","q":"Es obvio que la ____ de la Tierra está contaminada.","o":["isla","montaña","atmósfera","península"],"a":2,"k":"환경 어휘","t":"지구의 대기가 오염되어 있다는 것은 명백하다.","e":"atmósfera는 '대기'입니다. contaminada(오염된)와 함께 la atmósfera de la Tierra(지구의 대기)가 가장 자연스럽습니다. es obvio que는 '~은 분명하다'입니다.","x":["isla: 섬이라서 '지구의 섬'은 어색합니다 ✗","montaña: 산이라서 ✗","atmósfera: 대기 → 정답 ✓","península: 반도라서 ✗"]},{"id":"V518","q":"He sacado un diez en el examen de inglés. —¡Qué buena ____!","o":["papelera","clase","pizarra","nota"],"a":3,"k":"학교 어휘","t":"영어 시험에서 10점 만점을 받았어. —정말 좋은 점수다!","e":"nota는 '점수, 성적'입니다. sacar una nota(점수를 받다)라고 씁니다. 스페인에서는 보통 10점 만점으로 성적을 매깁니다.","x":["papelera: 휴지통이라서 ✗","clase: 수업이라서 점수 이야기에 맞지 않습니다 ✗","pizarra: 칠판이라서 ✗","nota: 점수 → 정답 ✓"]},{"id":"V519","q":"Eres un ____, no haces nada en todo el día.","o":["experto","genio","vago","ángel"],"a":2,"k":"성격 명사","t":"너는 게으름뱅이야, 하루 종일 아무것도 안 해.","e":"vago는 '게으른 (사람)'입니다. 하루 종일 아무것도 하지 않는다는 설명과 일치합니다. 비슷한 말로 perezoso가 있습니다.","x":["experto: 전문가라서 ✗","genio: 천재라서 ✗","vago: 게으름뱅이 → 정답 ✓","ángel: 천사(착한 사람)라서 ✗"]},{"id":"V520","q":"____, por favor. ¡No os vayáis sin mí!","o":["Esperadme","Ignoradme","Preguntadme","Habladme"],"a":0,"k":"vosotros 명령형","t":"제발 나를 기다려 줘. 나 빼고 가지 마!","e":"Esperadme는 esperar(기다리다)의 vosotros(너희) 긍정 명령형 esperad + me(나를)입니다. 긍정 명령에서는 대명사를 동사 뒤에 붙여 씁니다. 중남미에서는 ustedes를 써서 Espérenme라고 합니다.","x":["Esperadme: 나를 기다려 → 정답 ✓","Ignoradme: 나를 무시해라서 문맥과 반대입니다 ✗","Preguntadme: 나에게 물어봐라서 ✗","Habladme: 나에게 말해라서 ✗"]},{"id":"V521","q":"Antes ____ piso con varias personas, pero ahora vivo solo.","o":["compartía","impartía","repartía","partía"],"a":0,"k":"compartir 어휘","t":"전에는 여러 사람과 집을 함께 썼지만 지금은 혼자 산다.","e":"compartir piso는 '집(아파트)을 함께 쓰다, 셰어하우스하다'입니다. compartía는 불완료과거(과거에 반복되거나 지속된 일)로 '전에는 ~했었다'를 나타냅니다. pero ahora vivo solo와 대조됩니다.","x":["compartía: 함께 썼다 → 정답 ✓","impartía: impartir(강의를 하다)라서 ✗","repartía: repartir(나누어 주다, 배달하다)라서 ✗","partía: partir(쪼개다, 출발하다)라서 ✗"]},{"id":"V522","q":"Conoce estas calles perfectamente porque ha sido ____ durante veinte años.","o":["taxista","futbolista","artista","socorrista"],"a":0,"k":"직업 어휘","t":"그는 20년 동안 택시 기사였기 때문에 이 거리들을 완벽하게 안다.","e":"taxista는 '택시 기사'입니다. 거리(calles)를 잘 아는 이유로 가장 알맞습니다. -ista로 끝나는 직업명은 남녀 형태가 같습니다(el/la taxista).","x":["taxista: 택시 기사 → 정답 ✓","futbolista: 축구 선수라서 ✗","artista: 예술가라서 ✗","socorrista: 인명 구조원이라서 ✗"]},{"id":"V523","q":"No puedo estar sin ____ cuando hace mucho calor.","o":["televisión","computadora","teléfono móvil","aire acondicionado"],"a":3,"k":"가전 어휘","t":"더울 때는 에어컨 없이 있을 수 없다.","e":"aire acondicionado는 '에어컨'입니다. 더울 때(cuando hace mucho calor) 필요한 것이므로 정답입니다. 날씨 표현 hace calor(덥다)도 함께 기억하세요.","x":["televisión: 텔레비전이라서 더위와 관계없습니다 ✗","computadora: 컴퓨터(중남미)라서 ✗","teléfono móvil: 휴대폰이라서 ✗","aire acondicionado: 에어컨 → 정답 ✓"]},{"id":"V524","q":"¿Cuántos minutos debo dejar el ____ en el horno?","o":["cuchillo","martillo","pan","tenedor"],"a":2,"k":"음식 어휘","t":"빵을 오븐에 몇 분 동안 넣어 둬야 하나요?","e":"horno는 '오븐'이므로 오븐에 굽는 것이 와야 합니다. 보기 중 음식은 pan(빵)뿐입니다.","x":["cuchillo: 칼이라서 오븐에 넣지 않습니다 ✗","martillo: 망치라서 ✗","pan: 빵 → 오븐에 굽는 음식 → 정답 ✓","tenedor: 포크라서 ✗"]},{"id":"V525","q":"La señora Martínez vive en la tercera ____ de este bloque.","o":["carretera","calle","planta","avenida"],"a":2,"k":"주거 어휘","t":"마르티네스 부인은 이 건물의 3층에 산다.","e":"planta는 건물의 '층'입니다(piso도 같은 뜻). bloque는 '아파트 건물'입니다. 서수 tercera(세 번째)는 planta가 여성 명사라서 여성형입니다. 참고로 스페인에서는 1층을 planta baja라고 하므로 tercera planta는 한국식으로 4층에 해당합니다.","x":["carretera: 국도, 도로라서 건물 안에 없습니다 ✗","calle: 거리라서 ✗","planta: 층 → 정답 ✓","avenida: 대로라서 ✗"]},{"id":"V526","q":"¿Cuántas personas ____ normalmente en este hotel?","o":["se sientan","se acuestan","se bañan","se alojan"],"a":3,"k":"숙박 동사","t":"이 호텔에는 보통 몇 명이 묵나요?","e":"alojarse는 '묵다, 숙박하다'입니다. 호텔(hotel)과 가장 잘 어울립니다. 명사 alojamiento(숙소)도 함께 기억하세요.","x":["se sientan: 앉다라서 ✗","se acuestan: 잠자리에 들다라서 호텔 숙박 인원을 묻는 말로 어색합니다 ✗","se bañan: 목욕하다, 수영하다라서 ✗","se alojan: 묵다 → 정답 ✓"]},{"id":"V527","q":"Ismael no para de hablar. ¡Es un ____!","o":["loro","pollo","delfín","tiburón"],"a":0,"k":"동물 비유 표현","t":"이스마엘은 쉬지 않고 말해. 완전 수다쟁이야!","e":"스페인어에서 ser un loro(앵무새다)는 '말이 많은 사람, 수다쟁이'를 뜻하는 비유 표현입니다. no parar de + 동사원형은 '계속 ~하다'입니다.","x":["loro: 앵무새 → 수다쟁이라는 비유 → 정답 ✓","pollo: 병아리, 닭고기라서 말이 많다는 뜻이 없습니다 ✗","delfín: 돌고래라서 ✗","tiburón: 상어(냉혹하거나 야심 찬 사람 비유)라서 ✗"]},{"id":"V528","q":"¿Os cae bien el nuevo empleado? —Sí, es muy ____.","o":["grosero","raro","majo","bruto"],"a":2,"k":"성격 형용사","t":"새 직원 마음에 들어? —응, 아주 괜찮은 사람이야.","e":"majo는 스페인 구어로 '착한, 호감 가는, 좋은 사람'이라는 뜻입니다. caer bien(~의 마음에 들다, 호감이 가다)에 대한 긍정 대답이므로 majo가 알맞습니다. 중남미에서는 simpático, buena onda 등을 더 많이 씁니다.","x":["grosero: 무례한이라서 긍정 대답과 맞지 않습니다 ✗","raro: 이상한이라서 ✗","majo: 호감 가는, 좋은 → 정답 ✓","bruto: 거친, 무식한이라서 ✗"]},{"id":"V529","q":"No debemos ____ las buenas oportunidades.","o":["aceptar","aprovechar","perder","tomar"],"a":2,"k":"동사 어휘","t":"우리는 좋은 기회를 놓치면 안 된다.","e":"perder는 '잃다, 놓치다'입니다. perder una oportunidad(기회를 놓치다)는 자주 쓰는 표현입니다. no debemos(~하면 안 된다)와 함께 쓰면 '좋은 기회를 놓쳐서는 안 된다'는 자연스러운 조언이 됩니다.","x":["aceptar: 받아들이다라서 '받아들이면 안 된다'는 뜻이 이상합니다 ✗","aprovechar: 활용하다라서 '활용하면 안 된다'는 반대 뜻이 됩니다 ✗","perder: 놓치다 → 정답 ✓","tomar: 잡다라서 '잡으면 안 된다'는 이상합니다 ✗"]},{"id":"V530","q":"Las temperaturas en esta región son ____, no hace mucho frío ni mucho calor.","o":["blandas","suaves","extremas","excesivas"],"a":1,"k":"날씨 형용사","t":"이 지역의 기온은 온화해서 많이 춥지도 많이 덥지도 않다.","e":"suave는 날씨·기온에 쓰면 '온화한, 포근한'이라는 뜻입니다. 춥지도 덥지도 않다는 설명과 일치합니다. temperaturas가 여성 복수라서 suaves 형태입니다.","x":["blandas: 말랑한, 부드러운(물체)이라서 기온에 쓰지 않습니다 ✗","suaves: 온화한 → 정답 ✓","extremas: 극단적인이라서 반대 뜻입니다 ✗","excesivas: 과도한이라서 ✗"]},{"id":"V531","q":"Las bromas de Óscar no tienen ninguna ____. Nunca me hacen reír.","o":["gracia","envidia","alegría","suerte"],"a":0,"k":"tener gracia","t":"오스카의 농담은 하나도 재미없어. 절대 나를 웃기지 못해.","e":"tener gracia는 '재미있다, 웃기다'입니다. no tener ninguna gracia는 '전혀 재미없다'입니다. 뒤 문장 'Nunca me hacen reír(나를 웃게 하지 않는다)'와 연결됩니다.","x":["gracia: 재미, 익살 → 정답 ✓","envidia: 질투라서 ✗","alegría: 기쁨이라서 농담이 '기쁨을 가지다'는 어색합니다 ✗","suerte: 운이라서 ✗"]},{"id":"V532","q":"Luis odia ____; es muy impaciente.","o":["esperar","andar","estudiar","cantar"],"a":0,"k":"동사 어휘","t":"루이스는 기다리는 것을 아주 싫어한다. 참을성이 매우 없다.","e":"esperar는 '기다리다'입니다. impaciente(참을성 없는)인 사람이 싫어하는 것으로 가장 자연스럽습니다. esperar는 '바라다'라는 뜻도 있습니다.","x":["esperar: 기다리다 → 참을성 없음과 연결 → 정답 ✓","andar: 걷다라서 참을성과 관계없습니다 ✗","estudiar: 공부하다라서 ✗","cantar: 노래하다라서 ✗"]},{"id":"V533","q":"No entiendo esta frase en inglés. ¿Puedes ____ al español?","o":["copiarla","subrayarla","traducirla","corregirla"],"a":2,"k":"동사 어휘","t":"이 영어 문장을 이해 못하겠어. 스페인어로 번역해 줄 수 있어?","e":"traducir는 '번역하다'입니다. traducir algo al español(스페인어로 번역하다) 구조로 씁니다. 여기서 -la는 la frase(문장)를 가리키는 직접목적격 대명사(~을/를)로 동사원형 뒤에 붙었습니다.","x":["copiarla: 그것을 베끼다라서 이해 문제를 해결하지 못합니다 ✗","subrayarla: 그것에 밑줄 긋다라서 ✗","traducirla: 그것을 번역하다 → 정답 ✓","corregirla: 그것을 고치다라서 ✗"]},{"id":"V534","q":"Rodrigo nunca termina sus trabajos a tiempo; es bastante ____.","o":["formal","serio","puntual","irresponsable"],"a":3,"k":"성격 형용사","t":"로드리고는 과제를 한 번도 제때 끝내지 않아. 꽤 무책임하다.","e":"irresponsable은 '무책임한'입니다. 과제를 제때 끝내지 않는다는 행동과 일치합니다. 반대말은 responsable(책임감 있는)입니다.","x":["formal: 성실한, 진지한이라서 반대입니다 ✗","serio: 진지한이라서 ✗","puntual: 시간을 잘 지키는이라서 반대입니다 ✗","irresponsable: 무책임한 → 정답 ✓"]},{"id":"V535","q":"Almudena está en el ____ porque ha tenido un accidente de moto.","o":["estudio","gimnasio","hospital","despacho"],"a":2,"k":"장소 어휘","t":"알무데나는 오토바이 사고를 당해서 병원에 있다.","e":"hospital은 '병원'입니다. 사고(accidente)를 당한 사람이 있는 곳으로 가장 알맞습니다. 스페인어에서 h는 발음하지 않습니다(오스피탈).","x":["estudio: 원룸, 작업실이라서 ✗","gimnasio: 체육관이라서 ✗","hospital: 병원 → 정답 ✓","despacho: 사무실, 서재라서 ✗"]},{"id":"V536","q":"Cada pregunta de este test ____ un punto.","o":["vale","trae","hace","sale"],"a":0,"k":"valer 동사","t":"이 시험의 각 문제는 1점이다.","e":"valer는 '가치가 있다, (값이) ~이다'입니다. 시험 문제의 배점을 말할 때 valer un punto(1점이다)라고 씁니다. 가격을 물을 때 ¿Cuánto vale?(얼마예요?)도 자주 씁니다.","x":["vale: valer '~의 가치가 있다' → 정답 ✓","trae: traer(가져오다)라서 ✗","hace: hacer(하다)라서 ✗","sale: salir(나가다)라서 ✗"]},{"id":"V537","q":"Este niño es muy ____. Siempre está pidiendo algo.","o":["generoso","respetuoso","cariñoso","caprichoso"],"a":3,"k":"성격 형용사","t":"이 아이는 무척 떼를 써. 항상 뭔가를 달라고 해.","e":"caprichoso는 '변덕스러운, 떼쓰는, 이것저것 원하는'이라는 뜻입니다. 항상 뭔가를 달라고 한다(pidiendo algo)는 설명과 일치합니다. 명사 capricho는 '변덕, 갖고 싶은 것'입니다.","x":["generoso: 너그러운이라서 ✗","respetuoso: 공손한, 예의 바른이라서 ✗","cariñoso: 다정한, 애정이 많은이라서 ✗","caprichoso: 떼쓰는, 변덕스러운 → 정답 ✓"]},{"id":"V538","q":"Mi ____ materna es el alemán. Además, hablo inglés y holandés.","o":["profesión","dirección","lengua","familia"],"a":2,"k":"언어 어휘","t":"내 모국어는 독일어다. 또한 영어와 네덜란드어도 한다.","e":"lengua materna는 '모국어'입니다. lengua는 '언어, 혀'라는 뜻이고 materna는 '어머니의'라는 뜻입니다. idioma도 '언어'이지만 '모국어'는 보통 lengua materna라고 합니다.","x":["profesión: 직업이라서 ✗","dirección: 주소, 방향이라서 ✗","lengua: 언어 → lengua materna '모국어' → 정답 ✓","familia: 가족이라서 ✗"]},{"id":"V539","q":"A José Miguel le encanta ____ en bicicleta cuando tiene tiempo libre.","o":["montar","caminar","caer","volar"],"a":0,"k":"montar 동사","t":"호세 미겔은 여가 시간이 있을 때 자전거 타는 것을 아주 좋아한다.","e":"montar en bicicleta는 '자전거를 타다'입니다. montar a caballo(말을 타다)도 함께 기억하세요. encantar는 gustar처럼 '좋아하는 사람'을 간접목적격 대명사(le)로 씁니다.","x":["montar: 타다 → montar en bicicleta 정답 ✓","caminar: 걷다라서 en bicicleta와 맞지 않습니다 ✗","caer: 떨어지다, 넘어지다라서 ✗","volar: 날다라서 ✗"]},{"id":"V540","q":"¿Cuánto cuesta un ____ de autobús en tu ciudad? —Casi dos euros.","o":["menú","cuaderno","papel","billete"],"a":3,"k":"교통 어휘","t":"너희 도시에서 버스표는 얼마야? —거의 2유로야.","e":"billete는 스페인에서 '(교통) 표, 승차권'입니다. 중남미에서는 boleto라고 하는 경우가 많습니다. billete는 '지폐'라는 뜻도 있습니다.","x":["menú: 메뉴, 정식이라서 버스와 맞지 않습니다 ✗","cuaderno: 공책이라서 ✗","papel: 종이라서 ✗","billete: 표, 승차권 → 정답 ✓"]},{"id":"V541","q":"Necesitamos más ____ para hacer un bizcocho tan grande.","o":["lechuga","harina","vinagre","pimiento"],"a":1,"k":"음식 재료 어휘","t":"이렇게 큰 카스텔라를 만들려면 밀가루가 더 필요해.","e":"harina는 '밀가루'입니다. bizcocho(스펀지케이크, 카스텔라)를 만드는 기본 재료입니다. 나머지는 샐러드나 요리 재료입니다.","x":["lechuga: 상추라서 케이크 재료가 아닙니다 ✗","harina: 밀가루 → 정답 ✓","vinagre: 식초라서 ✗","pimiento: 피망이라서 ✗"]},{"id":"V542","q":"Busco una casa que no esté ____ porque tengo mis propios muebles.","o":["alquilada","reformada","vacía","amueblada"],"a":3,"k":"주거 어휘","t":"나는 내 가구가 있어서 가구가 갖춰져 있지 않은 집을 찾고 있다.","e":"amueblado는 '가구가 비치된'입니다. 자기 가구가 있으니 가구 없는 집을 원한다는 뜻입니다. que no esté는 접속법(바람·불확실함을 나타내는 동사 형태)으로, 아직 찾지 못한 집을 묘사할 때 씁니다.","x":["alquilada: 임대된이라서 가구 문제와 관계없습니다 ✗","reformada: 리모델링된이라서 ✗","vacía: 비어 있는이라서 '비어 있지 않은 집'은 오히려 반대 뜻입니다 ✗","amueblada: 가구가 갖춰진 → 정답 ✓"]},{"id":"V543","q":"¿Tienes hermanos? —No, soy ____ única.","o":["tía","abuela","hija","madre"],"a":2,"k":"가족 어휘","t":"형제 있어? —아니, 나는 외동딸이야.","e":"hija única는 '외동딸'(아들은 hijo único)입니다. 형제가 있냐는 질문에 대한 대답이므로 hija가 알맞습니다.","x":["tía: 이모, 고모라서 형제 질문의 답이 아닙니다 ✗","abuela: 할머니라서 ✗","hija: 딸 → hija única '외동딸' → 정답 ✓","madre: 어머니라서 ✗"]},{"id":"V544","q":"Tu primo no es nada ____, por eso no tiene amigos.","o":["intolerante","grosero","simpático","indiscreto"],"a":2,"k":"성격 형용사","t":"네 사촌은 전혀 상냥하지 않아, 그래서 친구가 없어.","e":"simpático는 '상냥한, 호감 가는'입니다. no es nada simpático는 '전혀 상냥하지 않다'로 친구가 없는 이유가 됩니다. no ... nada는 '전혀 ~않다'라는 강한 부정입니다.","x":["intolerante: 편협한이라서 '전혀 편협하지 않다'면 친구가 없을 이유가 아닙니다 ✗","grosero: 무례한이라서 '전혀 무례하지 않다'는 이유와 반대입니다 ✗","simpático: 상냥한 → 정답 ✓","indiscreto: 눈치 없는, 입이 가벼운이라서 반대 논리가 됩니다 ✗"]},{"id":"V545","q":"¿Te importa sacar al perro? Yo no ____, tengo que irme.","o":["comprendo","quiero","puedo","sé"],"a":2,"k":"poder 동사","t":"개 좀 산책시켜 줄래? 나는 못 해, 가야 하거든.","e":"poder는 '할 수 있다'입니다. 가야 해서(tengo que irme) 할 수 없다는 상황이므로 no puedo가 알맞습니다. ¿Te importa + 동사원형?은 '~해 줄래?'라는 정중한 부탁입니다.","x":["comprendo: 이해한다라서 ✗","quiero: 원한다라서 '하기 싫다'가 되어 이유와 맞지 않습니다 ✗","puedo: 할 수 있다 → no puedo '못 한다' → 정답 ✓","sé: 안다라서 ✗"]},{"id":"V546","q":"La ____ está en mi estuche.","o":["cuchara","botella","taza","regla"],"a":3,"k":"학용품 어휘","t":"자는 내 필통 안에 있어.","e":"regla는 '자'입니다(규칙이라는 뜻도 있음). estuche(필통)에 들어가는 물건이므로 regla가 정답입니다.","x":["cuchara: 숟가락이라서 필통에 넣지 않습니다 ✗","botella: 병이라서 ✗","taza: 컵이라서 ✗","regla: 자 → 정답 ✓"]},{"id":"V547","q":"Estás ____, Juan es hermano de Carla, no de Ana.","o":["equivocado","listo","preparado","dormido"],"a":0,"k":"equivocado","t":"네가 잘못 알고 있어, 후안은 아나가 아니라 카를라의 형제(오빠·남동생)야.","e":"estar equivocado는 '틀리다, 잘못 알고 있다'입니다. 상대방의 잘못된 정보를 바로잡는 문장과 맞습니다.","x":["equivocado: 잘못 알고 있는 → 정답 ✓","listo: (estar) 준비된, (ser) 똑똑한이라서 ✗","preparado: 준비된이라서 ✗","dormido: 잠든이라서 ✗"]},{"id":"V548","q":"No tengo coche, así que no necesito una casa con ____.","o":["garaje","cocina","terraza","pasillo"],"a":0,"k":"주거 어휘","t":"나는 차가 없어서 차고가 있는 집이 필요 없다.","e":"garaje는 '차고'입니다. 차가 없으니 차고가 필요 없다는 논리입니다. así que는 '그래서'입니다.","x":["garaje: 차고 → 정답 ✓","cocina: 부엌이라서 차와 관계없습니다 ✗","terraza: 테라스라서 ✗","pasillo: 복도라서 ✗"]},{"id":"V549","q":"____, me llevo bien con mis compañeros de piso.","o":["Por desgracia","Tristemente","Afortunadamente","Desgraciadamente"],"a":2,"k":"문장 부사","t":"다행히 나는 룸메이트들과 잘 지낸다.","e":"afortunadamente는 '다행히'입니다. 잘 지낸다(me llevo bien)는 긍정적인 내용이므로 긍정 부사가 와야 합니다. 나머지 세 보기는 모두 '불행히도'라는 뜻입니다.","x":["Por desgracia: 불행히도라서 ✗","Tristemente: 슬프게도라서 ✗","Afortunadamente: 다행히 → 정답 ✓","Desgraciadamente: 불행히도라서 ✗"]},{"id":"V550","q":"Cada sábado por la noche vamos a la ____ y bailamos hasta que cierra.","o":["discoteca","floristería","librería","biblioteca"],"a":0,"k":"장소 어휘","t":"매주 토요일 밤 우리는 클럽에 가서 문 닫을 때까지 춤을 춘다.","e":"discoteca는 '나이트클럽, 디스코텍'입니다. 춤을 추는(bailamos) 곳이므로 정답입니다. 스페인에서는 줄여서 disco라고도 합니다.","x":["discoteca: 클럽 → 춤추는 곳이라 정답 ✓","floristería: 꽃집이라서 ✗","librería: 서점이라서 ✗","biblioteca: 도서관이라서 ✗"]},{"id":"V551","q":"Ese palacio es muy antiguo, tiene al menos tres ____.","o":["semanas","siglos","meses","años"],"a":1,"k":"시간 단위 어휘","t":"그 궁전은 아주 오래되었어, 적어도 300년은 됐어.","e":"siglo는 '세기(100년)'입니다. muy antiguo(아주 오래된)라고 했으니 tres siglos(3세기)가 가장 자연스럽습니다. al menos는 '적어도'입니다.","x":["semanas: 주라서 '아주 오래된'과 맞지 않습니다 ✗","siglos: 세기 → 정답 ✓","meses: 달이라서 ✗","años: 년이라서 3년은 '아주 오래된' 궁전이 아닙니다 ✗"]},{"id":"V552","q":"Voy a llevar a mi ____ al pediatra.","o":["niña","madre","abuela","tía"],"a":0,"k":"가족 어휘","t":"우리 딸을 소아과에 데려갈 거야.","e":"pediatra는 '소아과 의사'이므로 아이를 데려가는 곳입니다. niña(여자아이, 딸)가 정답입니다. mi niña는 '우리 딸'이라는 다정한 표현이기도 합니다.","x":["niña: 여자아이, 딸 → 소아과 대상 → 정답 ✓","madre: 어머니라서 소아과에 가지 않습니다 ✗","abuela: 할머니라서 ✗","tía: 이모, 고모라서 ✗"]},{"id":"V553","q":"El limón tiene muchos ____ para la salud, por eso lo consumo habitualmente.","o":["beneficios","inconvenientes","defectos","daños"],"a":0,"k":"건강 어휘","t":"레몬은 건강에 좋은 점이 많아서 나는 평소에 자주 먹는다.","e":"beneficio는 '이점, 효능, 이익'입니다. 자주 먹는 이유(por eso lo consumo)가 되므로 긍정적인 beneficios가 알맞습니다. beneficios para la salud(건강상의 이점)는 자주 쓰는 표현입니다.","x":["beneficios: 이점, 효능 → 정답 ✓","inconvenientes: 불편한 점, 단점이라서 자주 먹는 이유와 반대입니다 ✗","defectos: 결점이라서 ✗","daños: 해, 피해라서 ✗"]},{"id":"V554","q":"Una ____ es un edificio religioso.","o":["tienda","ópera","fábrica","catedral"],"a":3,"k":"건물 어휘","t":"대성당은 종교 건물이다.","e":"catedral은 '대성당'으로 종교 건물(edificio religioso)입니다. 비슷한 단어: iglesia(교회, 성당), templo(사원). catedral은 여성 명사(una catedral)입니다.","x":["tienda: 가게라서 종교 건물이 아닙니다 ✗","ópera: 오페라(극장)라서 ✗","fábrica: 공장이라서 ✗","catedral: 대성당 → 정답 ✓"]},{"id":"V555","q":"Los reyes viven en ____.","o":["palacios","apartamentos","chalés","haciendas"],"a":0,"k":"건물 어휘","t":"왕들은 궁전에 산다.","e":"palacio는 '궁전'입니다. 왕(reyes)이 사는 곳으로 알맞습니다. 참고: los reyes는 '왕과 왕비(국왕 부부)'를 뜻하기도 합니다.","x":["palacios: 궁전 → 정답 ✓","apartamentos: 아파트라서 왕이 사는 곳으로 어울리지 않습니다 ✗","chalés: 단독주택, 별장이라서 ✗","haciendas: 농장, 대농장이라서 ✗"]},{"id":"V556","q":"Mi madre siempre me ____ buenos consejos.","o":["pone","trae","hace","da"],"a":3,"k":"dar consejos","t":"우리 어머니는 항상 나에게 좋은 조언을 해 주신다.","e":"dar consejos는 '조언을 해 주다'라는 고정 표현입니다. 한국어로는 '조언을 하다'지만 스페인어는 hacer가 아니라 dar(주다)를 씁니다. 예: ¿Me das un consejo?(조언 하나 해 줄래?)","x":["pone: poner(놓다)라서 consejos와 쓰지 않습니다 ✗","trae: traer(가져오다)라서 ✗","hace: hacer(하다)는 consejos와 결합하지 않습니다 ✗","da: dar consejos '조언하다' → 정답 ✓"]},{"id":"V557","q":"Ana es de ____ argentina.","o":["profesión","nacionalidad","edad","dirección"],"a":1,"k":"신상 어휘","t":"아나는 아르헨티나 국적이다.","e":"nacionalidad는 '국적'입니다. ser de nacionalidad + 국적 형용사로 국적을 말합니다. argentina(아르헨티나의)는 국적 형용사라서 nacionalidad와 맞습니다.","x":["profesión: 직업이라서 argentina와 맞지 않습니다 ✗","nacionalidad: 국적 → 정답 ✓","edad: 나이라서 ✗","dirección: 주소라서 ✗"]},{"id":"V558","q":"La ____ del autobús es muy simpática.","o":["taxista","veterinaria","conductora","ejecutiva"],"a":2,"k":"직업 어휘","t":"그 버스 기사분은 아주 친절하다.","e":"conductor/conductora는 '운전기사'입니다. del autobús(버스의)와 함께 '버스 기사'가 됩니다. 중남미에서는 chofer(chófer)라고도 합니다.","x":["taxista: 택시 기사라서 버스와 맞지 않습니다 ✗","veterinaria: 수의사라서 ✗","conductora: 운전기사 → 정답 ✓","ejecutiva: 임원, 간부라서 ✗"]},{"id":"V559","q":"Afortunadamente, los ____ apagaron el fuego muy rápido.","o":["carpinteros","policías","bomberos","fontaneros"],"a":2,"k":"직업 어휘","t":"다행히 소방관들이 불을 아주 빨리 껐다.","e":"bombero는 '소방관'입니다. 불을 끄다(apagar el fuego)는 소방관의 일입니다. -ero로 끝나는 단어는 직업을 나타내는 경우가 많습니다.","x":["carpinteros: 목수라서 ✗","policías: 경찰이라서 불을 끄는 사람이 아닙니다 ✗","bomberos: 소방관 → 정답 ✓","fontaneros: 배관공이라서 ✗"]},{"id":"V560","q":"El pádel es un deporte ____.","o":["de pelota","de raqueta","acuático","de aventura"],"a":1,"k":"스포츠 어휘","t":"파델은 라켓 스포츠이다.","e":"pádel은 테니스와 비슷하게 라켓(raqueta)으로 하는 스포츠로 스페인과 아르헨티나에서 매우 인기가 많습니다. 공도 쓰지만 종류를 나눌 때는 deporte de raqueta(라켓 스포츠)로 분류합니다.","x":["de pelota: 공 스포츠라는 말은 너무 넓고 파델의 분류로 쓰지 않습니다 ✗","de raqueta: 라켓 스포츠 → 정답 ✓","acuático: 수상 스포츠라서 ✗","de aventura: 모험 스포츠라서 ✗"]},{"id":"V561","q":"Las ____ dan leche.","o":["abejas","vacas","palomas","gallinas"],"a":1,"k":"동물 어휘","t":"소는 우유를 준다.","e":"vaca는 '젖소, 암소'입니다. 우유(leche)를 주는 동물이므로 정답입니다. 참고로 꿀(miel)은 abeja(벌), 달걀(huevos)은 gallina(암탉)에게서 얻습니다.","x":["abejas: 벌이라서 꿀을 줍니다 ✗","vacas: 소 → 우유 → 정답 ✓","palomas: 비둘기라서 ✗","gallinas: 암탉이라서 달걀을 줍니다 ✗"]},{"id":"V562","q":"Los españoles ____ por la tarde.","o":["desayunan","empiezan","meriendan","preparan"],"a":2,"k":"식사 동사","t":"스페인 사람들은 오후에 간식을 먹는다.","e":"merendar는 '오후 간식(merienda)을 먹다'입니다. 스페인에서는 점심과 저녁 사이 오후 5~6시쯤 간식을 먹는 습관이 있습니다. desayunar(아침 먹다)는 오전이라 맞지 않습니다.","x":["desayunan: 아침을 먹다라서 오후와 맞지 않습니다 ✗","empiezan: 시작하다라서 목적어가 없어 불완전합니다 ✗","meriendan: 오후 간식을 먹다 → 정답 ✓","preparan: 준비하다라서 목적어가 필요합니다 ✗"]},{"id":"V563","q":"Hace un tiempo ____. ¿Damos un paseo?","o":["extraño","horrible","estupendo","malísimo"],"a":2,"k":"날씨 형용사","t":"날씨가 끝내주네. 산책할까?","e":"estupendo는 '훌륭한, 끝내주는'입니다. 산책을 제안하려면 날씨가 좋아야 하므로 긍정적인 estupendo가 알맞습니다. hace buen tiempo(날씨가 좋다)도 같은 의미입니다.","x":["extraño: 이상한이라서 산책 제안과 맞지 않습니다 ✗","horrible: 끔찍한이라서 ✗","estupendo: 훌륭한 → 정답 ✓","malísimo: 아주 나쁜이라서 ✗"]},{"id":"V564","q":"En esta página web puedes ver la ____ de televisión de toda la semana.","o":["programación","revista","afición","lista"],"a":0,"k":"미디어 어휘","t":"이 웹사이트에서 일주일 전체의 TV 편성표를 볼 수 있다.","e":"programación은 '(방송) 편성, 프로그램 편성표'입니다. la programación de televisión은 TV 편성표입니다. 동사 programar(편성하다)에서 나온 말입니다.","x":["programación: 편성표 → 정답 ✓","revista: 잡지라서 de televisión de toda la semana와 어울리지 않습니다 ✗","afición: 취미, 애호라서 ✗","lista: 목록이라서 TV 방송 일정을 가리키는 말로 쓰지 않습니다 ✗"]},{"id":"V565","q":"¿Qué ____ es? —Las dos y media.","o":["día","año","mes","hora"],"a":3,"k":"시간 묻기","t":"몇 시야? —2시 반이야.","e":"¿Qué hora es?는 '몇 시예요?'라는 기본 표현입니다. 대답 Las dos y media(2시 반)로 시간을 묻는 질문임을 알 수 있습니다. 1시는 Es la una, 나머지는 Son las...를 씁니다.","x":["día: 날이라서 대답과 맞지 않습니다 ✗","año: 해라서 ✗","mes: 달이라서 ✗","hora: 시간 → 정답 ✓"]},{"id":"V566","q":"El coche es más ____ que la bici.","o":["barato","contaminante","pequeño","sano"],"a":1,"k":"비교 표현","t":"자동차는 자전거보다 더 오염을 일으킨다.","e":"contaminante는 '오염시키는'입니다. más + 형용사 + que는 '~보다 더 ~한'이라는 비교 표현입니다. 자동차가 자전거보다 매연이 많다는 사실과 맞습니다.","x":["barato: 싼이라서 자동차가 더 싸다는 건 사실과 맞지 않습니다 ✗","contaminante: 오염시키는 → 정답 ✓","pequeño: 작은이라서 자동차가 더 작지 않습니다 ✗","sano: 건강한이라서 ✗"]},{"id":"V567","q":"Hacemos ____ cada día para mantenernos en forma.","o":["música","dulces","hamburguesas","gimnasia"],"a":3,"k":"운동 어휘","t":"우리는 건강을 유지하기 위해 매일 체조를 한다.","e":"hacer gimnasia는 '체조(운동)를 하다'입니다. mantenerse en forma(몸매·건강을 유지하다)의 방법이므로 정답입니다. 비슷하게 hacer ejercicio(운동하다)도 씁니다.","x":["música: 음악이라서 건강 유지와 거리가 멉니다 ✗","dulces: 단것, 과자라서 ✗","hamburguesas: 햄버거라서 건강 유지와 반대입니다 ✗","gimnasia: 체조 → 정답 ✓"]},{"id":"V568","q":"Me gustaría tener un horario de trabajo más ____ para poder hacer otras cosas.","o":["sensible","probable","amigable","flexible"],"a":3,"k":"직장 어휘","t":"다른 일들도 할 수 있도록 근무 시간이 더 유연했으면 좋겠다.","e":"flexible은 '유연한, 융통성 있는'입니다. horario flexible(유연 근무 시간)은 자주 쓰는 표현입니다. 영어 flexible과 철자가 같습니다.","x":["sensible: 예민한, 감수성이 풍부한(영어 sensible과 뜻이 다름)이라서 ✗","probable: 있을 법한이라서 ✗","amigable: 친근한이라서 ✗","flexible: 유연한 → 정답 ✓"]},{"id":"V569","q":"¿En qué mes naciste? —En ____.","o":["febrero","invierno","otoño","verano"],"a":0,"k":"달 이름","t":"몇 월에 태어났어? —2월에.","e":"febrero는 '2월'입니다. 몇 월(qué mes)이냐고 물었으므로 달 이름이 와야 합니다. 나머지 보기는 계절 이름입니다. 스페인어에서 달 이름은 소문자로 씁니다.","x":["febrero: 2월 → 정답 ✓","invierno: 겨울(계절)이라서 ✗","otoño: 가을(계절)이라서 ✗","verano: 여름(계절)이라서 ✗"]},{"id":"V570","q":"Suelo ponerme estas ____ cuando hace calor.","o":["bebidas","ensaladas","especias","sandalias"],"a":3,"k":"의류 어휘","t":"나는 더울 때 보통 이 샌들을 신는다.","e":"sandalia는 '샌들'입니다. ponerse는 '(옷·신발을) 입다, 신다'입니다. 더울 때 신는 것이므로 sandalias가 정답입니다. soler + 동사원형은 '보통 ~하다'입니다.","x":["bebidas: 음료라서 ponerse와 맞지 않습니다 ✗","ensaladas: 샐러드라서 ✗","especias: 향신료라서 ✗","sandalias: 샌들 → 정답 ✓"]},{"id":"V571","q":"Voy a comprar un ____ en la farmacia.","o":["tomate","huevo","aguacate","jarabe"],"a":3,"k":"약국 어휘","t":"약국에서 시럽약을 하나 살 거야.","e":"jarabe는 '시럽(물약)'으로 기침약 등에 씁니다. 약국(farmacia)에서 사는 물건이므로 정답입니다. 나머지는 모두 식료품입니다.","x":["tomate: 토마토라서 약국에서 팔지 않습니다 ✗","huevo: 달걀이라서 ✗","aguacate: 아보카도라서 ✗","jarabe: 시럽약 → 정답 ✓"]},{"id":"V572","q":"En todos los cuartos de baño hay un ____.","o":["lavabo","fregadero","perchero","colchón"],"a":0,"k":"욕실 어휘","t":"모든 욕실에는 세면대가 있다.","e":"lavabo는 '세면대'입니다(스페인에서는 '화장실'이라는 뜻으로도 씀). fregadero(싱크대)는 부엌에 있으니 구별하세요.","x":["lavabo: 세면대 → 정답 ✓","fregadero: 주방 싱크대라서 욕실에 없습니다 ✗","perchero: 옷걸이(행거)라서 ✗","colchón: 매트리스라서 ✗"]},{"id":"V573","q":"Estoy ____ de vivir con mis padres; quiero vivir solo.","o":["feliz","contento","encantado","harto"],"a":3,"k":"estar harto","t":"부모님과 사는 게 지긋지긋해. 혼자 살고 싶어.","e":"estar harto de + 명사/동사원형은 '~에 질리다, 지긋지긋하다'입니다. 혼자 살고 싶다는 뒷 문장과 연결됩니다. 예: Estoy harto de esperar.(기다리는 데 질렸어.)","x":["feliz: 행복한이라서 혼자 살고 싶다는 말과 맞지 않습니다 ✗","contento: 만족한이라서 ✗","encantado: 아주 기쁜이라서 ✗","harto: 질린, 지긋지긋한 → 정답 ✓"]},{"id":"V574","q":"Los visitantes sacan muchas fotos aquí porque es un sitio ____.","o":["feo","espectacular","normal","aburrido"],"a":1,"k":"묘사 형용사","t":"이곳은 장관을 이루는 곳이라 방문객들이 사진을 많이 찍는다.","e":"espectacular는 '장관인, 굉장한'입니다. 사진을 많이 찍는 이유로 가장 자연스럽습니다. sacar fotos는 '사진을 찍다'입니다.","x":["feo: 못생긴, 보기 흉한이라서 ✗","espectacular: 장관인 → 정답 ✓","normal: 평범한이라서 사진을 많이 찍을 이유가 아닙니다 ✗","aburrido: 지루한이라서 ✗"]},{"id":"V575","q":"Me gusta oler bien, por eso me echo colonia y ____ antes de salir.","o":["detergente","agua","pasta de dientes","desodorante"],"a":3,"k":"위생 용품 어휘","t":"나는 좋은 냄새가 나는 걸 좋아해서 외출 전에 향수와 데오도런트를 뿌린다.","e":"desodorante는 '데오도런트(냄새 제거제)'입니다. colonia(향수, 오드콜로뉴)와 함께 냄새(oler bien)와 관련된 제품입니다. echarse는 '(자기 몸에) 뿌리다, 바르다'입니다.","x":["detergente: 세제라서 몸에 뿌리지 않습니다 ✗","agua: 물이라서 좋은 냄새와 관계없습니다 ✗","pasta de dientes: 치약이라서 몸에 뿌리지 않습니다 ✗","desodorante: 데오도런트 → 정답 ✓"]},{"id":"V576","q":"Hoy tengo que acostarme pronto porque mañana tengo que ____.","o":["recordar","madrugar","probar","encontrar"],"a":1,"k":"madrugar 동사","t":"내일 일찍 일어나야 해서 오늘은 일찍 자야 한다.","e":"madrugar는 '새벽같이 일찍 일어나다'라는 한 단어 동사입니다. 일찍 자야 하는 이유가 되므로 정답입니다. 명사 madrugada는 '새벽'입니다.","x":["recordar: 기억하다라서 일찍 잘 이유가 아닙니다 ✗","madrugar: 일찍 일어나다 → 정답 ✓","probar: 맛보다, 시도하다라서 ✗","encontrar: 찾다, 발견하다라서 ✗"]},{"id":"V577","q":"Terminé mis estudios en la ____ a los veintitrés años.","o":["sociedad","universidad","actividad","necesidad"],"a":1,"k":"교육 어휘","t":"나는 스물세 살에 대학교 공부를 마쳤다.","e":"universidad는 '대학교'입니다. terminar los estudios(학업을 마치다)와 23세라는 나이가 대학 졸업과 잘 맞습니다. -dad로 끝나는 명사는 여성 명사(la universidad)입니다.","x":["sociedad: 사회라서 학업을 마치는 곳이 아닙니다 ✗","universidad: 대학교 → 정답 ✓","actividad: 활동이라서 ✗","necesidad: 필요라서 ✗"]},{"id":"V578","q":"Mi piso está ____ de la playa. Llego allí en menos de un minuto.","o":["a 80 kilómetros","a mucha distancia","al lado","lejos"],"a":2,"k":"위치 표현","t":"우리 집은 해변 바로 옆이야. 1분도 안 돼서 거기 도착해.","e":"al lado de는 '~의 바로 옆에'입니다. 1분도 안 걸린다(en menos de un minuto)고 했으니 아주 가까워야 합니다. 반대 표현은 lejos de(~에서 멀리)입니다.","x":["a 80 kilómetros: 80km 떨어진이라서 1분 안에 갈 수 없습니다 ✗","a mucha distancia: 아주 먼 거리에라서 ✗","al lado: 바로 옆에 → 정답 ✓","lejos: 멀리라서 반대입니다 ✗"]},{"id":"V579","q":"Apenas se lava, es un ____.","o":["cerdo","tiburón","zorro","pájaro"],"a":0,"k":"동물 비유 표현","t":"그는 거의 씻지 않아, 완전 돼지야.","e":"스페인어에서 ser un cerdo(돼지다)는 '지저분한 사람'을 뜻하는 비유 표현입니다(다소 무례한 말). apenas는 '거의 ~않다'입니다.","x":["cerdo: 돼지 → 지저분한 사람 비유 → 정답 ✓","tiburón: 상어(냉혹하고 야심 찬 사람)라서 ✗","zorro: 여우(교활한 사람)라서 ✗","pájaro: 새라서 씻지 않는다는 의미가 없습니다 ✗"]},{"id":"V580","q":"Me cuesta ____ bien algunos sonidos en español.","o":["comunicar","pronunciar","hablar","cantar"],"a":1,"k":"언어 학습 동사","t":"스페인어의 몇몇 소리는 제대로 발음하기 어렵다.","e":"pronunciar는 '발음하다'입니다. sonidos(소리)를 목적어로 쓰기에 가장 알맞습니다. me cuesta + 동사원형은 '~하기가 힘들다'입니다. 예: Me cuesta pronunciar la r.(r 발음이 어려워.)","x":["comunicar: 전달하다라서 소리와 맞지 않습니다 ✗","pronunciar: 발음하다 → 정답 ✓","hablar: 말하다는 sonidos를 목적어로 쓰지 않습니다 ✗","cantar: 노래하다라서 ✗"]},{"id":"V581","q":"Elena es una chica muy ____; casi nunca se pone nerviosa.","o":["puntual","pesimista","tranquila","irresponsable"],"a":2,"k":"성격 형용사","t":"엘레나는 아주 차분한 아이야. 거의 긴장하지 않아.","e":"tranquilo/tranquila는 '차분한, 침착한'입니다. 거의 긴장하지 않는다(casi nunca se pone nerviosa)는 설명과 일치합니다. ponerse nervioso는 '긴장하다'입니다.","x":["puntual: 시간을 잘 지키는이라서 긴장과 관계없습니다 ✗","pesimista: 비관적인이라서 ✗","tranquila: 차분한 → 정답 ✓","irresponsable: 무책임한이라서 ✗"]},{"id":"V582","q":"Siempre ____ errores de ortografía cuando escribo mis redacciones.","o":["doy","tomo","cometo","pongo"],"a":2,"k":"cometer errores","t":"나는 작문을 쓸 때 항상 맞춤법 실수를 한다.","e":"cometer un error는 '실수를 하다'라는 고정 표현입니다. 한국어로는 '하다'지만 hacer보다 cometer를 쓰는 것이 일반적입니다. redacción은 '작문'입니다.","x":["doy: dar(주다)라서 errores와 쓰지 않습니다 ✗","tomo: tomar(잡다, 먹다)라서 ✗","cometo: cometer errores '실수하다' → 정답 ✓","pongo: poner(놓다)라서 ✗"]},{"id":"V583","q":"Los barcos más grandes salen de este ____.","o":["aeropuerto","puerto","garaje","ayuntamiento"],"a":1,"k":"교통 장소 어휘","t":"가장 큰 배들은 이 항구에서 출발한다.","e":"puerto는 '항구'입니다. 배(barcos)가 출발하는 곳이므로 정답입니다. aeropuerto(공항)도 puerto에서 나온 단어로 '하늘의 항구'라는 뜻입니다.","x":["aeropuerto: 공항이라서 비행기가 출발합니다 ✗","puerto: 항구 → 정답 ✓","garaje: 차고라서 ✗","ayuntamiento: 시청이라서 ✗"]},{"id":"V584","q":"Lo contrario de ____ es rico.","o":["entretenido","hermoso","pobre","pequeño"],"a":2,"k":"반의어","t":"부자의 반대말은 가난한 사람이다.","e":"rico(부유한)의 반대말은 pobre(가난한)입니다. lo contrario de는 '~의 반대'입니다. 참고로 rico는 음식에 쓰면 '맛있는'이라는 뜻도 있습니다.","x":["entretenido: 재미있는이라서 rico의 반대가 아닙니다 ✗","hermoso: 아름다운이라서 ✗","pobre: 가난한 → 정답 ✓","pequeño: 작은이라서 ✗"]},{"id":"V585","q":"Compré estas libretas en esa ____.","o":["gasolinera","droguería","papelería","relojería"],"a":2,"k":"상점 어휘","t":"나는 이 공책들을 저 문구점에서 샀다.","e":"papelería는 '문구점'입니다. papel(종이)에서 나온 말로 libretas(공책, 수첩)를 파는 곳입니다. -ería는 가게를 나타냅니다.","x":["gasolinera: 주유소라서 ✗","droguería: 생활용품점(세제·화장품 등)이라서 공책을 주로 팔지 않습니다 ✗","papelería: 문구점 → 정답 ✓","relojería: 시계점이라서 ✗"]},{"id":"V586","q":"Comer muchos productos azucarados ____ los dientes.","o":["sana","limpia","estropea","fortalece"],"a":2,"k":"동사 어휘","t":"설탕이 든 제품을 많이 먹으면 이가 상한다.","e":"estropear는 '망가뜨리다, 상하게 하다'입니다. 설탕이 많은 음식은 이를 상하게 하므로 estropea가 알맞습니다. 주어는 Comer muchos productos azucarados(설탕 든 제품을 많이 먹는 것)라서 3인칭 단수입니다.","x":["sana: sanar(치료하다)라서 반대 의미입니다 ✗","limpia: limpiar(깨끗하게 하다)라서 반대입니다 ✗","estropea: 상하게 하다 → 정답 ✓","fortalece: fortalecer(강하게 하다)라서 반대입니다 ✗"]},{"id":"V587","q":"No te lo tomes en serio, está de ____.","o":["broma","anécdota","cuento","chiste"],"a":0,"k":"estar de broma","t":"진지하게 받아들이지 마, 그는 농담하는 거야.","e":"estar de broma는 '농담하고 있다'라는 고정 표현입니다. broma는 '장난, 농담'입니다. chiste도 '농담'이지만 '웃긴 이야기'를 뜻하며 estar de와 함께 쓰지 않습니다.","x":["broma: estar de broma '농담하는 중이다' → 정답 ✓","anécdota: 일화라서 estar de와 쓰지 않습니다 ✗","cuento: 이야기, 동화라서 ✗","chiste: 우스갯소리는 contar un chiste(농담을 하다)로 쓰고 estar de chiste는 쓰지 않습니다 ✗"]},{"id":"V588","q":"No quiero ir sola al médico. ¿Me ____?","o":["recuerdas","acompañas","llamas","soportas"],"a":1,"k":"동사 어휘","t":"혼자 병원에 가고 싶지 않아. 같이 가 줄래?","e":"acompañar는 '동행하다, 함께 가다'입니다. 혼자(sola) 가기 싫다는 이유와 자연스럽게 연결됩니다. me는 '나를'이라는 직접목적격 대명사(~을/를)입니다.","x":["recuerdas: 기억하다라서 ✗","acompañas: 같이 가 주다 → 정답 ✓","llamas: 전화하다, 부르다라서 ✗","soportas: 참다, 견디다라서 ✗"]},{"id":"V589","q":"Las ____ lluvias han provocado inundaciones en medio país.","o":["pocas","ligeras","intensas","insignificantes"],"a":2,"k":"날씨 형용사","t":"집중 호우로 나라 절반 지역에 홍수가 났다.","e":"intenso는 '강한, 격렬한'입니다. 홍수(inundaciones)를 일으킨 비이므로 강한 비여야 합니다. lluvias intensas는 '폭우, 집중 호우'입니다.","x":["pocas: 적은이라서 홍수의 원인이 될 수 없습니다 ✗","ligeras: 가벼운, 약한이라서 ✗","intensas: 강한 → 정답 ✓","insignificantes: 사소한이라서 ✗"]},{"id":"V590","q":"¿Me amas? —Te amo con toda el ____.","o":["paciencia","confianza","alma","calma"],"a":2,"k":"관용 표현","t":"나를 사랑해? —온 마음을 다해 너를 사랑해.","e":"con toda el alma는 '온 영혼을 다해, 진심으로'라는 관용 표현입니다. alma는 여성 명사이지만 강세가 있는 a로 시작해서 단수 관사는 el을 씁니다(el alma). 그래도 형용사는 여성형 toda를 씁니다.","x":["paciencia: 인내라서 toda el과 맞지 않고 의미도 어색합니다 ✗","confianza: 신뢰라서 la confianza가 되어야 하고 관용 표현이 아닙니다 ✗","alma: 영혼 → con toda el alma '진심으로' → 정답 ✓","calma: 침착함이라서 ✗"]},{"id":"V591","q":"Leo las noticias a diario porque me gusta estar ____.","o":["aburrido","comunicado","informado","descansado"],"a":2,"k":"estar informado","t":"나는 정보를 잘 알고 있는 것을 좋아해서 매일 뉴스를 읽는다.","e":"estar informado는 '소식을 잘 알고 있다, 정보에 밝다'입니다. 뉴스(noticias)를 매일 읽는 이유로 알맞습니다. a diario는 '매일'입니다.","x":["aburrido: 지루한이라서 ✗","comunicado: 연결된, 통신이 되는이라서 뉴스를 읽는 이유가 아닙니다 ✗","informado: 정보를 알고 있는 → 정답 ✓","descansado: 쉰, 피로가 풀린이라서 ✗"]},{"id":"V592","q":"No le aconsejo consumir mucha bollería si quiere tener una dieta ____.","o":["insana","pobre","sana","mala"],"a":2,"k":"건강 형용사","t":"건강한 식단을 원하신다면 빵·과자류를 많이 드시지 않기를 권해요.","e":"sano는 '건강한, 건강에 좋은'입니다. dieta sana는 '건강한 식단'입니다. bollería는 '(달콤한) 빵·페이스트리류'입니다. le aconsejo는 존댓말(usted)로 '권해 드려요'라는 뜻입니다.","x":["insana: 건강에 나쁜이라서 반대입니다 ✗","pobre: 빈약한이라서 ✗","sana: 건강한 → 정답 ✓","mala: 나쁜이라서 ✗"]},{"id":"V593","q":"He leído un artículo muy interesante en este ____.","o":["diccionario","folleto","anuncio","periódico"],"a":3,"k":"미디어 어휘","t":"이 신문에서 아주 흥미로운 기사를 읽었다.","e":"periódico는 '신문'입니다. artículo(기사)가 실리는 대표적인 매체입니다. 같은 뜻으로 diario도 씁니다.","x":["diccionario: 사전이라서 기사가 실리지 않습니다 ✗","folleto: 팸플릿, 안내 책자라서 기사를 싣지 않습니다 ✗","anuncio: 광고라서 ✗","periódico: 신문 → 정답 ✓"]},{"id":"V594","q":"Tu redacción es muy ____; deberías escribir un poco más.","o":["confusa","larga","fácil","corta"],"a":3,"k":"반의어 형용사","t":"네 작문은 너무 짧아. 조금 더 써야 해.","e":"corto는 '짧은'입니다. 조금 더 써야 한다(escribir un poco más)는 조언과 연결됩니다. 반대말은 largo(긴)입니다. redacción이 여성 명사라 corta입니다.","x":["confusa: 혼란스러운이라서 '더 써라'와 연결되지 않습니다 ✗","larga: 긴이라서 반대입니다 ✗","fácil: 쉬운이라서 ✗","corta: 짧은 → 정답 ✓"]},{"id":"V595","q":"El nuevo empleado es muy simpático. Nos ____ bien a todos.","o":["sube","cae","levanta","conoce"],"a":1,"k":"caer bien","t":"새 직원은 아주 상냥해. 우리 모두 그를 좋아해.","e":"caer bien은 '(누구의) 마음에 들다, 호감을 주다'라는 표현입니다. gustar처럼 '좋아하는 사람'을 간접목적격 대명사(nos)로 씁니다. 직역하면 '그가 우리 모두에게 좋게 떨어진다'입니다.","x":["sube: subir(올라가다)라서 ✗","cae: caer bien '호감을 주다' → 정답 ✓","levanta: levantar(들어 올리다)라서 ✗","conoce: conocer(알다)는 bien과 결합해도 이 구조가 아닙니다 ✗"]},{"id":"V596","q":"Antonio Banderas actúa en algunas ____ de Pedro Almodóvar.","o":["canciones","películas","pinturas","poesías"],"a":1,"k":"영화 어휘","t":"안토니오 반데라스는 페드로 알모도바르의 몇몇 영화에 출연한다.","e":"película는 '영화'입니다. actuar(연기하다)와 Pedro Almodóvar(스페인 영화감독)로 보아 영화가 알맞습니다.","x":["canciones: 노래라서 배우가 출연하지 않습니다 ✗","películas: 영화 → 정답 ✓","pinturas: 그림이라서 ✗","poesías: 시라서 ✗"]},{"id":"V597","q":"Salí muy tarde de casa, por eso no llegué ____ a la presentación del libro.","o":["luego","a tiempo","constantemente","después"],"a":1,"k":"시간 부사구","t":"집에서 너무 늦게 나와서 책 출간 발표회에 제시간에 도착하지 못했다.","e":"a tiempo는 '제시간에, 늦지 않게'입니다. 늦게 나왔다는 이유와 '제때 도착하지 못했다'는 결과가 맞습니다. 비슷한 표현: puntualmente(정각에).","x":["luego: 나중에라서 ✗","a tiempo: 제시간에 → 정답 ✓","constantemente: 끊임없이라서 ✗","después: 그 후에라서 ✗"]},{"id":"V598","q":"Mañana es el cumpleaños de mi hermano y todavía no sé qué ____.","o":["arreglarle","darle","pedirle","regalarle"],"a":3,"k":"선물 동사","t":"내일이 우리 형(동생) 생일인데 아직 무엇을 선물할지 모르겠다.","e":"regalar는 '선물하다'입니다. 생일(cumpleaños)과 가장 잘 어울립니다. 동사원형 뒤에 le(그에게)를 붙여 regalarle이 되었습니다. qué + 동사원형은 '무엇을 ~할지'입니다.","x":["arreglarle: 그에게 고쳐 주다라서 ✗","darle: 그에게 주다는 가능하지만 생일 선물의 뜻으로는 regalar가 정확합니다 ✗","pedirle: 그에게 요청하다라서 ✗","regalarle: 그에게 선물하다 → 정답 ✓"]},{"id":"V599","q":"Esta camiseta no es ____, la compré hace más de diez años.","o":["vieja","nueva","linda","bonita"],"a":1,"k":"형용사 반의어","t":"이 티셔츠는 새것이 아니야, 10년도 더 전에 샀거든.","e":"nuevo/nueva는 '새로운'입니다. 10년 전에 샀다는 이유와 함께 '새것이 아니다'가 논리적입니다. camiseta가 여성 명사라 nueva입니다.","x":["vieja: 낡은이라서 '낡지 않았다'는 10년 전에 샀다는 말과 맞지 않습니다 ✗","nueva: 새로운 → 정답 ✓","linda: 예쁜(중남미에서 자주 씀)이라서 이유와 연결되지 않습니다 ✗","bonita: 예쁜이라서 ✗"]},{"id":"V600","q":"A mi abuelo le gusta ____ la radio por la mañana.","o":["mirar","oler","escuchar","tocar"],"a":2,"k":"감각 동사","t":"우리 할아버지는 아침에 라디오 듣는 것을 좋아하신다.","e":"escuchar는 '(주의해서) 듣다'입니다. 라디오(la radio)는 듣는 것이므로 정답입니다. TV는 ver la televisión(TV를 보다)이라고 합니다. radio는 -o로 끝나지만 여성 명사(la radio)입니다.","x":["mirar: 보다라서 라디오와 맞지 않습니다 ✗","oler: 냄새 맡다라서 ✗","escuchar: 듣다 → 정답 ✓","tocar: 만지다, 연주하다라서 ✗"]},{"id":"V601","q":"Vamos a ver una exposición de ____ de Velázquez.","o":["novelas","poemas","canciones","cuadros"],"a":3,"k":"예술 어휘","t":"우리는 벨라스케스의 그림 전시회를 보러 갈 것이다.","e":"cuadro는 '(액자에 넣은) 그림, 회화'라는 뜻입니다. 벨라스케스(Velázquez)는 스페인의 유명한 화가이고, exposición(전시회)에서 보는 것은 그림이므로 cuadros가 정답입니다. 예: un cuadro de Picasso(피카소의 그림).","x":["novelas: 소설이라는 뜻으로, 화가의 전시회 내용과 맞지 않습니다 ✗","poemas: 시라는 뜻으로, 벨라스케스는 시인이 아니라 화가입니다 ✗","canciones: 노래라는 뜻으로, 전시회에서 보는 대상이 아닙니다 ✗","cuadros: 그림(회화)이라는 뜻으로, 화가의 전시회에 딱 맞습니다 ✓"]},{"id":"V602","q":"Es normal ____ el uso de algunas preposiciones en español. Yo todavía me equivoco.","o":["explorar","conseguir","repetir","confundir"],"a":3,"k":"동사 어휘","t":"스페인어에서 몇몇 전치사의 쓰임을 헷갈리는 것은 정상이다. 나도 아직 틀린다.","e":"confundir는 '혼동하다, 헷갈리다'라는 뜻입니다. 뒤 문장 'Yo todavía me equivoco(나도 아직 틀린다)'와 이어지려면 전치사를 헷갈린다는 의미가 자연스럽습니다. 예: Siempre confundo 'ser' y 'estar'(나는 늘 ser와 estar를 헷갈린다).","x":["explorar: 탐험하다라는 뜻으로, 전치사 쓰임과 어울리지 않습니다 ✗","conseguir: 얻다, 해내다라는 뜻으로, 틀린다는 뒷말과 맞지 않습니다 ✗","repetir: 반복하다라는 뜻으로, 실수와 연결되는 의미가 아닙니다 ✗","confundir: 혼동하다, 헷갈리다라는 뜻으로 문맥에 맞습니다 ✓"]},{"id":"V603","q":"Están ____ porque hace mucho calor.","o":["jugando","practicando","sudando","estudiando"],"a":2,"k":"동사 어휘(현재진행)","t":"날씨가 너무 더워서 그들은 땀을 흘리고 있다.","e":"sudar는 '땀을 흘리다'라는 뜻이고, estar + 현재분사(-ando/-iendo)는 '~하고 있다'라는 진행형입니다. 'hace mucho calor(매우 덥다)'가 이유이므로 sudando가 가장 자연스럽습니다.","x":["jugando: 놀고 있는이라는 뜻으로, 더위가 원인이라는 문맥과 맞지 않습니다 ✗","practicando: 연습하고 있는이라는 뜻으로, 더위와 직접 관련이 없습니다 ✗","sudando: 땀을 흘리고 있는이라는 뜻으로, 더위 때문이라는 이유와 맞습니다 ✓","estudiando: 공부하고 있는이라는 뜻으로, 더위가 이유가 되지 않습니다 ✗"]},{"id":"V604","q":"Compré este oso de peluche en esa ____.","o":["heladería","juguetería","perfumería","farmacia"],"a":1,"k":"가게 이름 어휘","t":"나는 이 곰 인형을 저 장난감 가게에서 샀다.","e":"juguetería는 '장난감 가게'입니다. juguete(장난감) + -ería(~가게)로 만들어진 단어예요. oso de peluche(곰 인형)는 장난감이므로 juguetería가 정답입니다. 스페인어는 -ería로 가게 이름을 많이 만듭니다: panadería(빵집), frutería(과일 가게).","x":["heladería: 아이스크림 가게로, 곰 인형을 파는 곳이 아닙니다 ✗","juguetería: 장난감 가게로, 곰 인형을 사는 곳입니다 ✓","perfumería: 향수·화장품 가게로, 인형과 관계없습니다 ✗","farmacia: 약국으로, 인형을 파는 곳이 아닙니다 ✗"]},{"id":"V605","q":"Aunque se llevan ____, viven juntos.","o":["genial","estupendamente","fatal","bien"],"a":2,"k":"llevarse 표현","t":"그들은 사이가 아주 나쁘지만 함께 산다.","e":"llevarse bien/mal은 '사이가 좋다/나쁘다'라는 표현이고, fatal은 '아주 나쁘게, 최악으로'라는 뜻입니다. aunque(~이지만)는 반대되는 내용을 연결하므로, '함께 산다'와 대조되는 '사이가 아주 나쁘다'가 와야 합니다.","x":["genial: 아주 좋게, 끝내주게라는 뜻이라 aunque의 대조 의미가 사라집니다 ✗","estupendamente: 아주 훌륭하게라는 뜻이라 대조가 되지 않습니다 ✗","fatal: 아주 나쁘게라는 뜻으로, 함께 산다는 사실과 대조되어 정답입니다 ✓","bien: 잘, 좋게라는 뜻이라 aunque와 어울리지 않습니다 ✗"]},{"id":"V606","q":"Es estupendo veros tan ____.","o":["apenados","preocupados","enfadados","felices"],"a":3,"k":"감정 형용사","t":"너희가 그렇게 행복해 보이니 정말 좋다.","e":"feliz(행복한)의 복수형 felices가 정답입니다. 'Es estupendo(정말 좋다)'라는 긍정적인 반응이므로 좋은 감정 상태가 와야 합니다. veros는 'ver(보다) + os(너희를)'로, '너희를 보는 것'이라는 뜻입니다.","x":["apenados: 슬퍼하는, 마음 아픈이라는 뜻이라 '정말 좋다'와 맞지 않습니다 ✗","preocupados: 걱정하는이라는 뜻이라 긍정적인 반응과 어울리지 않습니다 ✗","enfadados: 화난이라는 뜻이라 문맥과 반대입니다 ✗","felices: 행복한이라는 뜻으로 긍정적인 반응과 맞습니다 ✓"]},{"id":"V607","q":"No esperaba tener tanto éxito. Estoy ____.","o":["descontenta","sorprendida","desanimada","harta"],"a":1,"k":"감정 형용사","t":"이렇게 큰 성공을 거둘 줄 몰랐다. 나는 놀랐다.","e":"sorprendido/a는 '놀란'이라는 뜻입니다. 'No esperaba(기대하지 않았다)'라는 말 뒤에는 예상 밖의 일에 놀랐다는 표현이 자연스럽습니다. 주어가 여성이므로 sorprendida 형태입니다.","x":["descontenta: 불만스러운이라는 뜻이라 성공했다는 문맥과 맞지 않습니다 ✗","sorprendida: 놀란이라는 뜻으로, 예상치 못한 성공에 대한 반응으로 정답입니다 ✓","desanimada: 낙담한이라는 뜻이라 성공과 어울리지 않습니다 ✗","harta: 지긋지긋한, 질린이라는 뜻이라 문맥에 맞지 않습니다 ✗"]},{"id":"V608","q":"El microondas ____ la comida y la bebida muy rápido.","o":["prepara","congela","calienta","cocina"],"a":2,"k":"주방 동사 어휘","t":"전자레인지는 음식과 음료를 매우 빨리 데운다.","e":"calentar는 '데우다, 따뜻하게 하다'라는 뜻이며 calienta는 3인칭 단수 현재형입니다(e→ie로 바뀌는 불규칙 동사). 전자레인지(microondas)의 기본 기능은 음식과 음료를 데우는 것입니다.","x":["prepara: 준비하다라는 뜻으로, 전자레인지의 기능을 정확히 나타내지 못합니다 ✗","congela: 얼리다라는 뜻으로, 냉동실의 기능입니다 ✗","calienta: 데우다라는 뜻으로, 전자레인지의 기능에 딱 맞습니다 ✓","cocina: 요리하다라는 뜻으로, 음료를 '요리'하지는 않아 어색합니다 ✗"]},{"id":"V609","q":"Si tu maleta ____ demasiado, tienes que pagar extra en el aeropuerto.","o":["vale","pesa","cuesta","pasea"],"a":1,"k":"동사 어휘","t":"네 여행 가방이 너무 무거우면 공항에서 추가 요금을 내야 한다.","e":"pesar는 '무게가 나가다'라는 뜻입니다. pesar demasiado는 '너무 무겁다'로, 공항에서 추가 요금(pagar extra)을 내는 이유가 됩니다. 예: ¿Cuánto pesa? (무게가 얼마나 나가요?)","x":["vale: 값이 나가다라는 뜻으로, 가방 무게와 관계없습니다 ✗","pesa: 무게가 나가다라는 뜻으로, 추가 요금의 이유가 됩니다 ✓","cuesta: 비용이 들다라는 뜻으로, 공항 추가 요금 이유로는 어색합니다 ✗","pasea: 산책하다라는 뜻으로, 가방에 쓸 수 없습니다 ✗"]},{"id":"V610","q":"¡Qué noticia tan horrible! Un avión ____ y no hay supervivientes.","o":["ha aterrizado","ha despegado","se ha estrellado","ha volado"],"a":2,"k":"비행기 관련 동사","t":"정말 끔찍한 소식이야! 비행기가 추락했고 생존자가 없대.","e":"estrellarse는 '(비행기·차가) 추락하다, 충돌하다'라는 뜻입니다. 'noticia horrible(끔찍한 소식)'과 'no hay supervivientes(생존자가 없다)'에 맞는 것은 추락입니다. 여기서는 현재완료(ha + 과거분사, '~했다')가 쓰였습니다.","x":["ha aterrizado: 착륙했다라는 뜻으로, 끔찍한 소식이 아닙니다 ✗","ha despegado: 이륙했다라는 뜻으로, 생존자 없음과 맞지 않습니다 ✗","se ha estrellado: 추락했다라는 뜻으로 문맥에 맞습니다 ✓","ha volado: 비행했다라는 뜻으로, 사고를 나타내지 않습니다 ✗"]},{"id":"V611","q":"Carlos no es una persona ____; de hecho, no le gusta relacionarse con nadie.","o":["insegura","débil","sociable","impuntual"],"a":2,"k":"성격 형용사","t":"카를로스는 사교적인 사람이 아니다. 사실 그는 누구와도 어울리는 것을 좋아하지 않는다.","e":"sociable은 '사교적인'이라는 뜻입니다. 'no le gusta relacionarse con nadie(누구와도 어울리기 싫어한다)'는 사교적이지 않다는 앞 문장의 근거입니다. de hecho는 '사실은, 실제로'라는 뜻으로 앞말을 뒷받침합니다.","x":["insegura: 자신감 없는이라는 뜻으로, 사람과 어울리기 싫다는 근거와 직접 연결되지 않습니다 ✗","débil: 약한이라는 뜻으로 문맥과 맞지 않습니다 ✗","sociable: 사교적인이라는 뜻으로, 남과 어울리지 않는다는 설명과 맞습니다 ✓","impuntual: 시간을 안 지키는이라는 뜻으로 관계없습니다 ✗"]},{"id":"V612","q":"Una ensalada es más ____ que un potaje.","o":["dulce","ligera","pesada","saciante"],"a":1,"k":"음식 형용사","t":"샐러드는 포타헤(콩 스튜)보다 더 가볍다.","e":"ligero/a는 음식에 쓰면 '가벼운, 소화가 잘 되는'이라는 뜻입니다. potaje는 콩과 채소 등을 넣고 푹 끓인 든든한 스페인식 스튜라서, 샐러드가 더 가볍다는 비교가 자연스럽습니다. ensalada가 여성 명사이므로 ligera입니다.","x":["dulce: 단이라는 뜻으로, 샐러드와 스튜의 비교로 어색합니다 ✗","ligera: 가벼운이라는 뜻으로 샐러드의 특징에 맞습니다 ✓","pesada: 무거운, 속이 더부룩한이라는 뜻으로 오히려 potaje의 특징입니다 ✗","saciante: 포만감을 주는이라는 뜻으로, 스튜 쪽이 더 그렇습니다 ✗"]},{"id":"V613","q":"¿Dónde ____? —En la Universidad de Salamanca.","o":["naciste","te casaste","estudiaste","creciste"],"a":2,"k":"동사 어휘(과거)","t":"너 어디에서 공부했어? —살라망카 대학교에서.","e":"estudiar(공부하다)의 2인칭 단수 단순과거형이 estudiaste입니다. 대답이 'Universidad de Salamanca(살라망카 대학교)'이므로 대학교에서 공부했다는 질문이 가장 자연스럽습니다.","x":["naciste: 너는 태어났다라는 뜻으로, 대학교에서 태어나지는 않습니다 ✗","te casaste: 너는 결혼했다라는 뜻으로, 대학교가 장소로는 어색합니다 ✗","estudiaste: 너는 공부했다라는 뜻으로, 대학교라는 대답과 맞습니다 ✓","creciste: 너는 자랐다라는 뜻으로, 대학교와 어울리지 않습니다 ✗"]},{"id":"V614","q":"Andrés y yo somos ____, todavía no estamos casados.","o":["socios","novios","compañeros","colegas"],"a":1,"k":"인간관계 어휘","t":"안드레스와 나는 연인 사이야. 아직 결혼하지 않았어.","e":"novios는 '(결혼 전의) 연인, 애인'이라는 뜻입니다. 'todavía no estamos casados(아직 결혼하지 않았다)'는 결혼을 전제로 한 연인 관계를 보여 줍니다. 참고로 결혼식 당일의 신랑 신부도 novios라고 합니다.","x":["socios: 사업 파트너, 회원이라는 뜻으로 결혼과 관련 없습니다 ✗","novios: 연인, 애인이라는 뜻으로 문맥에 맞습니다 ✓","compañeros: 동료, 친구라는 뜻으로 결혼 이야기와 연결이 약합니다 ✗","colegas: 직장 동료라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V615","q":"¿Podrías tirar esta bolsa en ese ____ de basura?","o":["contenedor","tenedor","abridor","encendedor"],"a":0,"k":"생활 사물 어휘","t":"이 봉투를 저 쓰레기통에 버려 줄 수 있어?","e":"contenedor de basura는 '(길가의 큰) 쓰레기 수거함'입니다. tirar는 여기서 '버리다'라는 뜻이에요. 다른 보기들도 -dor로 끝나 비슷하게 보이지만 뜻이 완전히 다릅니다.","x":["contenedor: 수거함, 컨테이너라는 뜻으로 쓰레기를 버리는 곳입니다 ✓","tenedor: 포크라는 뜻으로 쓰레기를 넣을 수 없습니다 ✗","abridor: 병따개라는 뜻으로 맞지 않습니다 ✗","encendedor: 라이터라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V616","q":"No pases por esta calle por la noche. Puede ser ____.","o":["espectacular","relajante","peligroso","emocionante"],"a":2,"k":"형용사 어휘","t":"밤에는 이 길로 지나가지 마. 위험할 수 있어.","e":"peligroso는 '위험한'이라는 뜻입니다. 'No pases(지나가지 마)'라는 경고의 이유로 위험하다는 말이 자연스럽습니다. 예: Es peligroso nadar aquí(여기서 수영하는 것은 위험하다).","x":["espectacular: 장관인, 굉장한이라는 뜻으로 경고의 이유가 되지 않습니다 ✗","relajante: 편안하게 해 주는이라는 뜻으로 경고와 맞지 않습니다 ✗","peligroso: 위험한이라는 뜻으로 지나가지 말라는 이유가 됩니다 ✓","emocionante: 신나는, 감동적인이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V617","q":"No pases por ese callejón. Es un lugar ____.","o":["seguro","peligroso","interesante","bonito"],"a":1,"k":"형용사 어휘","t":"저 골목으로 지나가지 마. 위험한 곳이야.","e":"peligroso(위험한)가 정답입니다. callejón은 '좁은 골목'이고, 지나가지 말라는 경고 뒤에는 그 이유가 와야 합니다. lugar가 남성 명사라서 peligroso 형태를 씁니다.","x":["seguro: 안전한이라는 뜻으로, 지나가지 말라는 말과 반대입니다 ✗","peligroso: 위험한이라는 뜻으로 경고의 이유로 맞습니다 ✓","interesante: 흥미로운이라는 뜻으로 경고의 이유가 되지 않습니다 ✗","bonito: 예쁜이라는 뜻으로 경고와 맞지 않습니다 ✗"]},{"id":"V618","q":"Me gustaría aprender a ____ la guitarra.","o":["mover","tomar","jugar","tocar"],"a":3,"k":"tocar vs jugar","t":"나는 기타 치는 법을 배우고 싶다.","e":"악기를 '연주하다'는 tocar를 씁니다. 예: tocar el piano(피아노를 치다). 영어의 play처럼 jugar를 쓰면 안 되는데, jugar는 놀이나 운동 경기를 할 때 씁니다(jugar al fútbol, 축구를 하다).","x":["mover: 움직이다라는 뜻으로 악기 연주에 쓰지 않습니다 ✗","tomar: 잡다, 마시다라는 뜻으로 악기에 쓰지 않습니다 ✗","jugar: 놀다, 경기하다라는 뜻으로 운동·게임에 씁니다 ✗","tocar: 악기를 연주하다라는 뜻으로 정답입니다 ✓"]},{"id":"V619","q":"Esta noche vamos a ir al ____ de nuestro cantante favorito.","o":["cine","museo","concierto","teatro"],"a":2,"k":"여가 장소 어휘","t":"오늘 밤 우리는 가장 좋아하는 가수의 콘서트에 갈 것이다.","e":"concierto는 '콘서트, 음악회'입니다. cantante(가수)의 공연을 보러 가는 것이므로 concierto가 정답입니다. 'ir a + 동사원형'은 '~할 것이다'라는 가까운 미래 표현입니다.","x":["cine: 영화관이라는 뜻으로, 가수의 공연 장소가 아닙니다 ✗","museo: 박물관, 미술관이라는 뜻으로 맞지 않습니다 ✗","concierto: 콘서트라는 뜻으로 가수와 어울립니다 ✓","teatro: 극장(연극)이라는 뜻으로 가수 공연으로는 덜 자연스럽습니다 ✗"]},{"id":"V620","q":"¡Qué bien se come en esta tasca! Todo está ____.","o":["delicioso","malísimo","asqueroso","mal cocinado"],"a":0,"k":"음식 맛 형용사","t":"이 선술집은 음식이 정말 맛있어! 모든 게 맛있다.","e":"delicioso는 '아주 맛있는'이라는 뜻입니다. '¡Qué bien se come!(정말 잘 먹을 수 있는 곳이야!)'라는 칭찬 뒤에는 긍정적인 말이 와야 합니다. tasca는 스페인의 작고 소박한 선술집·식당을 말합니다.","x":["delicioso: 아주 맛있는이라는 뜻으로 칭찬과 맞습니다 ✓","malísimo: 아주 맛없는이라는 뜻으로 칭찬과 반대입니다 ✗","asqueroso: 역겨운이라는 뜻으로 맞지 않습니다 ✗","mal cocinado: 잘못 요리된이라는 뜻으로 칭찬과 반대입니다 ✗"]},{"id":"V621","q":"No se encuentra ____ porque ha comido demasiado.","o":["mal","fatal","bien","regular"],"a":2,"k":"encontrarse 상태","t":"그는 너무 많이 먹어서 몸 상태가 좋지 않다.","e":"encontrarse bien은 '몸 상태가 좋다'라는 표현입니다. 앞에 no가 있으므로 'No se encuentra bien'은 '몸이 좋지 않다'가 됩니다. 과식했다는 이유와 연결하려면 no와 함께 bien을 써야 자연스럽습니다.","x":["mal: 나쁘게라는 뜻이라 no와 함께 쓰면 '안 나쁘다'가 되어 과식과 맞지 않습니다 ✗","fatal: 최악으로라는 뜻이라 no와 함께 쓰면 '최악은 아니다'가 되어 어색합니다 ✗","bien: 좋게라는 뜻으로 no와 함께 '몸이 좋지 않다'가 됩니다 ✓","regular: 그저 그런이라는 뜻이라 no와 함께 쓰면 의미가 어색합니다 ✗"]},{"id":"V622","q":"Hace un tiempo ____. ¿Vamos al parque?","o":["horrible","desagradable","magnífico","lluvioso"],"a":2,"k":"날씨 형용사","t":"날씨가 아주 좋네. 공원에 갈까?","e":"magnífico는 '아주 훌륭한, 멋진'이라는 뜻입니다. 공원에 가자고 제안하려면 날씨가 좋아야 하므로 magnífico가 정답입니다. 'Hace un tiempo + 형용사'는 '날씨가 ~하다'라는 표현입니다.","x":["horrible: 끔찍한이라는 뜻으로, 공원에 가자는 제안과 맞지 않습니다 ✗","desagradable: 불쾌한이라는 뜻으로 맞지 않습니다 ✗","magnífico: 아주 좋은이라는 뜻으로 공원 제안과 어울립니다 ✓","lluvioso: 비가 오는이라는 뜻으로 공원에 가기 좋지 않습니다 ✗"]},{"id":"V623","q":"Habéis hecho un buen trabajo; estoy ____ de vosotros.","o":["cansada","aburrida","harta","orgullosa"],"a":3,"k":"감정 형용사","t":"너희는 일을 잘 해냈어. 나는 너희가 자랑스러워.","e":"estar orgulloso/a de + 사람은 '~가 자랑스럽다'라는 표현입니다. 'Habéis hecho un buen trabajo(일을 잘했다)'는 칭찬이므로 자랑스럽다는 감정이 맞습니다. vosotros는 스페인에서 쓰는 '너희'로, 중남미에서는 ustedes를 씁니다.","x":["cansada: 피곤한이라는 뜻으로 칭찬과 맞지 않습니다 ✗","aburrida: 지루한이라는 뜻으로 맞지 않습니다 ✗","harta: 질린, 지긋지긋한이라는 뜻으로 칭찬과 반대입니다 ✗","orgullosa: 자랑스러운이라는 뜻으로 칭찬과 맞습니다 ✓"]},{"id":"V624","q":"Quiero vivir en Colombia para ____ la cultura colombiana en primera persona.","o":["saber","notar","conocer","completar"],"a":2,"k":"saber vs conocer","t":"나는 콜롬비아 문화를 직접 체험하기 위해 콜롬비아에 살고 싶다.","e":"conocer는 사람·장소·문화 등을 '직접 경험해서 알다'라는 뜻입니다. saber는 정보나 사실을 '알다'에 쓰므로 문화를 직접 겪는다는 의미에는 conocer가 맞습니다. en primera persona는 '직접, 몸소'라는 뜻입니다.","x":["saber: 정보·사실을 알다라는 뜻으로, 문화를 경험하는 의미에 쓰지 않습니다 ✗","notar: 알아차리다라는 뜻으로 어색합니다 ✗","conocer: 직접 경험해 알다라는 뜻으로 정답입니다 ✓","completar: 완성하다라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V625","q":"El ____, a diferencia del tigre, es un animal de compañía.","o":["hipopótamo","gato","avestruz","cocodrilo"],"a":1,"k":"동물 어휘","t":"고양이는 호랑이와 달리 반려동물이다.","e":"animal de compañía는 '반려동물'입니다. 고양이(gato)는 호랑이(tigre)와 같은 고양잇과지만 집에서 기르는 동물입니다. a diferencia de는 '~와 달리'라는 뜻입니다.","x":["hipopótamo: 하마라는 뜻으로 반려동물이 아닙니다 ✗","gato: 고양이라는 뜻으로 대표적인 반려동물입니다 ✓","avestruz: 타조라는 뜻으로 반려동물이 아닙니다 ✗","cocodrilo: 악어라는 뜻으로 반려동물이 아닙니다 ✗"]},{"id":"V626","q":"¿Sabes ____ del 1 al 10 en francés?","o":["contestar","contar","comentar","cantar"],"a":1,"k":"비슷한 동사 구별","t":"너 프랑스어로 1부터 10까지 셀 줄 알아?","e":"contar는 '(숫자를) 세다'라는 뜻이고, 'del 1 al 10(1부터 10까지)'와 함께 쓰입니다. contar에는 '이야기하다'라는 뜻도 있습니다. 'saber + 동사원형'은 '~할 줄 알다'입니다.","x":["contestar: 대답하다라는 뜻으로 숫자 세기와 맞지 않습니다 ✗","contar: 세다라는 뜻으로 1부터 10까지와 맞습니다 ✓","comentar: 의견을 말하다라는 뜻으로 맞지 않습니다 ✗","cantar: 노래하다라는 뜻으로 숫자 세기와 맞지 않습니다 ✗"]},{"id":"V627","q":"No me ____, te escucho bien.","o":["grites","invites","mires","llames"],"a":0,"k":"부정 명령","t":"나한테 소리 지르지 마, 잘 들려.","e":"gritar는 '소리 지르다'라는 뜻이며, 'No me grites'는 tú에게 하는 부정 명령입니다(부정 명령은 접속법(바람·의심 등을 나타내는 동사 형태) 형태를 씁니다). 'te escucho bien(잘 들린다)'이 소리 지를 필요가 없다는 이유입니다.","x":["grites: 소리 지르다(gritar)의 부정 명령형으로, 잘 들린다는 이유와 맞습니다 ✓","invites: 초대하다(invitar)로, 잘 들린다는 말과 연결되지 않습니다 ✗","mires: 쳐다보다(mirar)로, 듣는 것과 관계없습니다 ✗","llames: 전화하다, 부르다(llamar)로, 잘 들린다는 이유와 맞지 않습니다 ✗"]},{"id":"V628","q":"¿Es usted una persona ____? —Sí, la salud es lo más importante para mí.","o":["sana","comilona","paciente","dormilona"],"a":0,"k":"성격·건강 형용사","t":"당신은 건강한 사람인가요? —네, 저에게는 건강이 가장 중요해요.","e":"sano/a는 '건강한, 건강하게 생활하는'이라는 뜻입니다. 대답에서 'la salud(건강)'이 가장 중요하다고 하므로 sana가 정답입니다. persona가 여성 명사라서 sana 형태입니다.","x":["sana: 건강한이라는 뜻으로 건강이 중요하다는 대답과 맞습니다 ✓","comilona: 대식가인이라는 뜻으로 건강 이야기와 맞지 않습니다 ✗","paciente: 참을성 있는이라는 뜻으로 대답과 연결되지 않습니다 ✗","dormilona: 잠꾸러기인이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V629","q":"La cigüeña es un ____.","o":["felino","ave","insecto","pez"],"a":1,"k":"동물 분류 어휘","t":"황새는 새이다.","e":"ave는 '새, 조류'입니다. ave는 여성 명사지만 강세가 있는 a로 시작하므로 발음 때문에 단수에서 관사 un/el을 씁니다(un ave, el ave). 복수는 las aves입니다. cigüeña(황새)는 새입니다.","x":["felino: 고양잇과 동물이라는 뜻으로 황새와 맞지 않습니다 ✗","ave: 새라는 뜻으로 황새를 분류하는 말입니다 ✓","insecto: 곤충이라는 뜻으로 맞지 않습니다 ✗","pez: 물고기라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V630","q":"¿Alberto está soltero? —No, está ____.","o":["ocupado","casado","libre","desocupado"],"a":1,"k":"결혼 여부 어휘","t":"알베르토는 미혼이야? —아니, 결혼했어.","e":"casado는 '결혼한, 기혼의'라는 뜻이며 soltero(미혼의)의 반대말입니다. 결혼 상태는 보통 estar와 함께 씁니다: estar casado(결혼한 상태이다). 질문에 No라고 답했으므로 casado가 맞습니다.","x":["ocupado: 바쁜이라는 뜻으로 결혼 여부와 관계없습니다 ✗","casado: 결혼한이라는 뜻으로 soltero의 반대입니다 ✓","libre: 자유로운, 비어 있는이라는 뜻으로 No라는 대답과 맞지 않습니다 ✗","desocupado: 한가한이라는 뜻으로 결혼 여부와 관계없습니다 ✗"]},{"id":"V631","q":"¡____ pronto! ¡Te echamos de menos!","o":["Espera","Vuelve","Vete","Recuerda"],"a":1,"k":"명령형 어휘","t":"빨리 돌아와! 네가 보고 싶어!","e":"volver는 '돌아오다'라는 뜻이며 Vuelve는 tú에게 하는 긍정 명령형입니다(o→ue로 바뀌는 불규칙 동사). 'Te echamos de menos(우리는 네가 그립다)'와 어울리는 것은 돌아오라는 말입니다. 중남미에서는 '그립다'를 extrañar로 많이 표현합니다.","x":["Espera: 기다려라는 뜻으로 pronto와 그립다는 말과 어울리지 않습니다 ✗","Vuelve: 돌아와라는 뜻으로 그리움과 연결됩니다 ✓","Vete: 가 버려라는 뜻으로 그립다는 말과 반대입니다 ✗","Recuerda: 기억해라는 뜻으로 pronto와 함께 쓰기 어색합니다 ✗"]},{"id":"V632","q":"Pablo es más joven que Luis; Pablo tiene ____ años y Luis, treinta.","o":["veintiséis","sesenta y dos","treinta y seis","sesenta"],"a":0,"k":"숫자 어휘","t":"파블로는 루이스보다 어리다. 파블로는 스물여섯 살이고 루이스는 서른 살이다.","e":"veintiséis는 26입니다. 21~29는 한 단어로 붙여 쓰며 veintiséis처럼 악센트가 붙는 경우가 있습니다. 파블로가 30살인 루이스보다 어리므로 30보다 작은 숫자가 와야 합니다.","x":["veintiséis: 26으로 30보다 작아 정답입니다 ✓","sesenta y dos: 62로 30보다 많아 더 어리지 않습니다 ✗","treinta y seis: 36으로 30보다 많습니다 ✗","sesenta: 60으로 30보다 많습니다 ✗"]},{"id":"V633","q":"En mi ____ libre, me gusta pasear por la playa con mi perrita.","o":["lado","lugar","sitio","tiempo"],"a":3,"k":"tiempo libre","t":"여가 시간에 나는 내 강아지와 해변을 산책하는 것을 좋아한다.","e":"tiempo libre는 '여가 시간, 자유 시간'이라는 고정 표현입니다. 'En mi tiempo libre(내 여가 시간에)'는 취미를 말할 때 자주 씁니다. perrita는 perra(암캐)에 작고 귀엽다는 뜻의 -ita가 붙은 말입니다.","x":["lado: 옆, 쪽이라는 뜻으로 libre와 어울리지 않습니다 ✗","lugar: 장소라는 뜻으로 '여가'의 의미가 되지 않습니다 ✗","sitio: 장소, 자리라는 뜻으로 맞지 않습니다 ✗","tiempo: 시간이라는 뜻으로 tiempo libre(여가 시간)가 됩니다 ✓"]},{"id":"V634","q":"¿Puede darme un champú especial para ____ seco?","o":["cabello","labio","cuello","pie"],"a":0,"k":"신체 어휘","t":"건성 모발용 특수 샴푸를 하나 주시겠어요?","e":"cabello는 '머리카락'이라는 뜻으로 pelo와 비슷하지만 조금 더 격식 있는 말입니다. 샴푸(champú)는 머리카락에 쓰므로 cabello seco(건조한 머리카락)가 자연스럽습니다.","x":["cabello: 머리카락이라는 뜻으로 샴푸와 맞습니다 ✓","labio: 입술이라는 뜻으로 샴푸를 쓰지 않습니다 ✗","cuello: 목이라는 뜻으로 샴푸와 맞지 않습니다 ✗","pie: 발이라는 뜻으로 샴푸와 맞지 않습니다 ✗"]},{"id":"V635","q":"____ es malo para la salud.","o":["Leer","Dormir","Charlar","Fumar"],"a":3,"k":"건강 어휘","t":"담배를 피우는 것은 건강에 나쁘다.","e":"fumar는 '담배를 피우다'라는 뜻입니다. 동사원형은 문장의 주어가 될 수 있어서 'Fumar es malo(담배 피우는 것은 나쁘다)'처럼 씁니다. 건강에 나쁜 행동은 흡연입니다.","x":["Leer: 읽기라는 뜻으로 건강에 나쁘다고 하지 않습니다 ✗","Dormir: 잠자기라는 뜻으로 오히려 건강에 필요합니다 ✗","Charlar: 수다 떨기라는 뜻으로 건강에 나쁘지 않습니다 ✗","Fumar: 담배 피우기라는 뜻으로 건강에 나쁩니다 ✓"]},{"id":"V636","q":"Esta casa no se ____, sino que se alquila.","o":["construye","renueva","pinta","vende"],"a":3,"k":"부동산 동사","t":"이 집은 판매용이 아니라 임대용이다.","e":"'no A, sino B'는 'A가 아니라 B'라는 뜻입니다. alquilar(임대하다)와 짝이 되는 것은 vender(팔다)입니다. 'se vende(팝니다)', 'se alquila(세놓습니다)'는 스페인어권 집 앞 표지판에서 흔히 볼 수 있는 표현입니다.","x":["construye: 짓다라는 뜻으로 alquila와 짝이 되지 않습니다 ✗","renueva: 리모델링하다라는 뜻으로 맞지 않습니다 ✗","pinta: 칠하다라는 뜻으로 맞지 않습니다 ✗","vende: 팔다라는 뜻으로 '팔지 않고 세놓는다'가 됩니다 ✓"]},{"id":"V637","q":"Anoche ____ un documental sobre la vida de Frida Kahlo.","o":["serví","observé","leí","vi"],"a":3,"k":"ver 단순과거","t":"어젯밤 나는 프리다 칼로의 삶에 관한 다큐멘터리를 봤다.","e":"ver(보다)의 1인칭 단수 단순과거형은 vi입니다(악센트 없음). 다큐멘터리(documental)는 'ver un documental(다큐를 보다)'처럼 ver와 함께 씁니다. anoche는 '어젯밤'으로 단순과거와 잘 어울립니다.","x":["serví: 내가 제공했다(servir)라는 뜻으로 다큐멘터리와 맞지 않습니다 ✗","observé: 내가 관찰했다라는 뜻으로 다큐를 보는 데 쓰기엔 어색합니다 ✗","leí: 내가 읽었다라는 뜻으로 다큐멘터리는 읽지 않습니다 ✗","vi: 내가 봤다라는 뜻으로 다큐멘터리와 맞습니다 ✓"]},{"id":"V638","q":"Lo mejor al estudiar una lengua extranjera es ____ el miedo a hablarla.","o":["recuperar","defender","escoger","perder"],"a":3,"k":"perder el miedo","t":"외국어를 공부할 때 가장 좋은 것은 그 언어로 말하는 것에 대한 두려움을 없애는 것이다.","e":"perder el miedo는 '두려움을 없애다(버리다)'라는 고정 표현입니다. perder는 원래 '잃다'라는 뜻이에요. 예: Perdí el miedo a volar(나는 비행 공포를 극복했다).","x":["recuperar: 되찾다라는 뜻으로 두려움을 되찾으면 반대 의미가 됩니다 ✗","defender: 지키다라는 뜻으로 맞지 않습니다 ✗","escoger: 고르다라는 뜻으로 맞지 않습니다 ✗","perder: 잃다라는 뜻으로 perder el miedo(두려움을 없애다)가 됩니다 ✓"]},{"id":"V639","q":"Tu español es perfecto. ¡Estoy ____!","o":["interesada","impresionada","preocupada","estresada"],"a":1,"k":"감정 형용사","t":"너 스페인어 완벽하다. 정말 감탄했어!","e":"impresionado/a는 '감명받은, 깊은 인상을 받은'이라는 뜻입니다. 상대의 완벽한 스페인어를 칭찬하는 상황이므로 impresionada가 맞습니다. 화자가 여성이라 -a 형태입니다.","x":["interesada: 관심 있는이라는 뜻으로 칭찬 반응으로 어색합니다 ✗","impresionada: 감탄한이라는 뜻으로 칭찬과 맞습니다 ✓","preocupada: 걱정하는이라는 뜻으로 맞지 않습니다 ✗","estresada: 스트레스 받은이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V640","q":"Cuando iba a la universidad, vivía en un ____ de estudiantes con otras cuatro personas.","o":["almacén","bufete","pasillo","piso"],"a":3,"k":"주거 어휘","t":"대학에 다닐 때 나는 다른 네 명과 함께 학생용 아파트에서 살았다.","e":"piso는 스페인에서 '아파트(공동주택의 한 세대)'라는 뜻입니다. piso de estudiantes는 학생들이 함께 세 들어 사는 집이에요. 중남미에서는 보통 departamento나 apartamento라고 하고, piso는 '층, 바닥'의 뜻으로 많이 씁니다.","x":["almacén: 창고라는 뜻으로 사는 곳이 아닙니다 ✗","bufete: 변호사 사무소라는 뜻으로 맞지 않습니다 ✗","pasillo: 복도라는 뜻으로 살 수 있는 곳이 아닙니다 ✗","piso: 아파트라는 뜻으로 학생들이 함께 사는 집에 맞습니다 ✓"]},{"id":"V641","q":"Me gustaría ser cantante, pero no tengo buena ____.","o":["vista","voz","nariz","cara"],"a":1,"k":"신체 어휘","t":"나는 가수가 되고 싶지만 목소리가 좋지 않다.","e":"voz는 '목소리'입니다. 가수(cantante)에게 필요한 것은 좋은 목소리이므로 voz가 정답입니다. 복수형은 z가 c로 바뀌어 voces가 됩니다.","x":["vista: 시력이라는 뜻으로 가수와 직접 관련이 없습니다 ✗","voz: 목소리라는 뜻으로 가수에게 필요합니다 ✓","nariz: 코라는 뜻으로 맞지 않습니다 ✗","cara: 얼굴이라는 뜻으로 노래 실력과 관계없습니다 ✗"]},{"id":"V642","q":"No quiero vivir en un piso tan ____, prefiero uno con mucha luz.","o":["antiguo","oscuro","grande","céntrico"],"a":1,"k":"집 형용사","t":"나는 이렇게 어두운 아파트에서 살고 싶지 않다. 빛이 많이 드는 곳이 좋다.","e":"oscuro는 '어두운'이라는 뜻으로 'mucha luz(빛이 많은)'의 반대입니다. 뒤 문장에서 빛이 많은 집을 원한다고 했으므로 지금 집은 어둡다는 뜻이 됩니다.","x":["antiguo: 오래된이라는 뜻으로 빛과 관련된 대조가 아닙니다 ✗","oscuro: 어두운이라는 뜻으로 빛이 많은 집과 대조됩니다 ✓","grande: 큰이라는 뜻으로 빛과 대조되지 않습니다 ✗","céntrico: 시내 중심에 있는이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V643","q":"Aprender con juegos puede ser muy ____, sobre todo para los niños.","o":["divertido","convertido","introvertido","extrovertido"],"a":0,"k":"형용사 어휘","t":"게임으로 배우는 것은 특히 아이들에게 매우 재미있을 수 있다.","e":"divertido는 '재미있는, 즐거운'이라는 뜻입니다. 게임(juegos)으로 배우는 것은 재미있다는 의미가 자연스럽습니다. 다른 보기도 -vertido로 끝나 비슷해 보이지만 뜻이 다릅니다.","x":["divertido: 재미있는이라는 뜻으로 게임 학습과 어울립니다 ✓","convertido: 변환된, 개종한이라는 뜻으로 맞지 않습니다 ✗","introvertido: 내성적인이라는 뜻으로 사람 성격에 씁니다 ✗","extrovertido: 외향적인이라는 뜻으로 사람 성격에 씁니다 ✗"]},{"id":"V644","q":"Antonio es ____, así que no puede dormir en una cama tan pequeña.","o":["bellísimo","altísimo","inteligentísimo","delgadísimo"],"a":1,"k":"최상급 -ísimo","t":"안토니오는 키가 아주 커서 그렇게 작은 침대에서 잘 수 없다.","e":"-ísimo는 형용사에 붙어 '아주 ~한'이라는 뜻을 만듭니다(절대 최상급). alto(키 큰) → altísimo(아주 키가 큰). 작은 침대에서 잘 수 없는 이유는 키가 크기 때문입니다.","x":["bellísimo: 아주 아름다운이라는 뜻으로 침대 크기와 관계없습니다 ✗","altísimo: 아주 키가 큰이라는 뜻으로 작은 침대에서 못 자는 이유가 됩니다 ✓","inteligentísimo: 아주 똑똑한이라는 뜻으로 관계없습니다 ✗","delgadísimo: 아주 마른이라는 뜻으로 오히려 작은 침대에 맞을 수 있습니다 ✗"]},{"id":"V645","q":"La ____ de mi cuarto tiene cinco cajones.","o":["puerta","litera","cuna","cómoda"],"a":3,"k":"가구 어휘","t":"내 방의 서랍장에는 서랍이 다섯 개 있다.","e":"cómoda는 '서랍장'이라는 명사입니다(형용사 cómodo/a는 '편안한'). cajón은 '서랍'이므로 서랍이 다섯 개 달린 가구는 서랍장입니다.","x":["puerta: 문이라는 뜻으로 서랍이 없습니다 ✗","litera: 2층 침대라는 뜻으로 서랍과 관계없습니다 ✗","cuna: 아기 침대라는 뜻으로 맞지 않습니다 ✗","cómoda: 서랍장이라는 뜻으로 서랍이 있는 가구입니다 ✓"]},{"id":"V646","q":"La hermana de mi madre es mi ____.","o":["cuñada","nieta","abuela","tía"],"a":3,"k":"가족 어휘","t":"우리 어머니의 자매는 나의 이모이다.","e":"tía는 '이모, 고모, 숙모' 등 부모의 자매를 뜻합니다. 남자는 tío(삼촌, 외삼촌)입니다. 한국어처럼 친가·외가를 구분하지 않는 점에 주의하세요.","x":["cuñada: 형수, 처제 등 배우자의 자매나 형제의 아내입니다 ✗","nieta: 손녀라는 뜻입니다 ✗","abuela: 할머니라는 뜻으로 어머니의 어머니입니다 ✗","tía: 이모라는 뜻으로 어머니의 자매입니다 ✓"]},{"id":"V647","q":"Casi no tengo comida en casa, así que voy a ir ahora mismo al ____.","o":["supermercado","estadio","estanco","cine"],"a":0,"k":"가게 어휘","t":"집에 먹을 게 거의 없어서 지금 바로 슈퍼마켓에 갈 거야.","e":"supermercado는 '슈퍼마켓'입니다. 집에 음식이 거의 없으니 음식을 사러 가는 곳이 와야 합니다. 'ahora mismo'는 '지금 당장'이라는 뜻입니다.","x":["supermercado: 슈퍼마켓이라는 뜻으로 음식을 사는 곳입니다 ✓","estadio: 경기장이라는 뜻으로 음식을 사러 가지 않습니다 ✗","estanco: (스페인의) 담배·우표 판매점이라는 뜻으로 맞지 않습니다 ✗","cine: 영화관이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V648","q":"¿Qué ____ del año prefieres? —La primavera.","o":["estación","mes","semana","día"],"a":0,"k":"계절 어휘","t":"너는 1년 중 어느 계절을 좋아해? —봄.","e":"estación은 '계절'이라는 뜻입니다(기차역이라는 뜻도 있어요). 대답이 primavera(봄)이므로 계절을 묻는 질문입니다. 네 계절: primavera(봄), verano(여름), otoño(가을), invierno(겨울).","x":["estación: 계절이라는 뜻으로 봄이라는 대답과 맞습니다 ✓","mes: 달(월)이라는 뜻으로 봄은 달 이름이 아닙니다 ✗","semana: 주라는 뜻으로 맞지 않습니다 ✗","día: 날이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V649","q":"El profesor nos ____ cuando hacemos mucho ruido en clase.","o":["felicita","admira","saluda","regaña"],"a":3,"k":"동사 어휘","t":"우리가 수업 중에 시끄럽게 하면 선생님이 우리를 꾸짖는다.","e":"regañar는 '꾸짖다, 야단치다'라는 뜻입니다. 수업 시간에 떠들 때(hacemos mucho ruido) 선생님이 하는 행동은 꾸짖는 것입니다. 여기서 nos는 '우리를'이라는 직접목적격 대명사(~을/를에 해당)입니다.","x":["felicita: 축하하다, 칭찬하다라는 뜻으로 떠드는 상황과 맞지 않습니다 ✗","admira: 감탄하다, 존경하다라는 뜻으로 맞지 않습니다 ✗","saluda: 인사하다라는 뜻으로 떠드는 것과 관계없습니다 ✗","regaña: 꾸짖다라는 뜻으로 떠드는 학생에게 하는 행동입니다 ✓"]},{"id":"V650","q":"¿Lo has comprendido todo? —Sí, no tengo ____.","o":["explicaciones","excusas","dudas","respuestas"],"a":2,"k":"tener dudas","t":"다 이해했니? —네, 궁금한 점이 없어요.","e":"duda는 '의문, 궁금한 점'이라는 뜻이고, 'no tengo dudas'는 '질문(의문)이 없다'는 표현입니다. 다 이해했다는 대답에 맞습니다. 수업에서 '¿Tenéis alguna duda?(질문 있나요?)'처럼 자주 씁니다.","x":["explicaciones: 설명이라는 뜻으로 이해했다는 대답과 연결이 어색합니다 ✗","excusas: 변명이라는 뜻으로 맞지 않습니다 ✗","dudas: 의문, 궁금한 점이라는 뜻으로 다 이해했다는 의미가 됩니다 ✓","respuestas: 대답이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V651","q":"No puedo usar mi ____ porque no tiene batería.","o":["celular","gorro","sombrero","pañuelo"],"a":0,"k":"전자기기 어휘","t":"배터리가 없어서 휴대폰을 쓸 수 없다.","e":"celular는 '휴대폰'으로 중남미에서 주로 쓰는 말입니다. 스페인에서는 móvil이라고 합니다. 배터리(batería)가 있는 물건은 휴대폰뿐입니다.","x":["celular: 휴대폰이라는 뜻으로 배터리가 있는 기기입니다 ✓","gorro: 털모자라는 뜻으로 배터리가 없습니다 ✗","sombrero: 챙 있는 모자라는 뜻으로 맞지 않습니다 ✗","pañuelo: 손수건, 스카프라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V652","q":"Estamos preparando una fiesta ____ para Patricia. ¡Nadie puede decirle nada!","o":["extraña","rara","sorpresa","normal"],"a":2,"k":"fiesta sorpresa","t":"우리는 파트리시아를 위해 깜짝 파티를 준비하고 있어. 아무도 그녀에게 말하면 안 돼!","e":"fiesta sorpresa는 '깜짝 파티'입니다. sorpresa(놀라움)가 명사지만 다른 명사 뒤에 붙어 '깜짝 ~'이라는 뜻을 만듭니다. 아무에게도 말하지 말라는 것이 힌트입니다.","x":["extraña: 이상한이라는 뜻으로 비밀로 하는 이유와 맞지 않습니다 ✗","rara: 이상한, 드문이라는 뜻으로 맞지 않습니다 ✗","sorpresa: 깜짝이라는 뜻으로 비밀 파티에 맞습니다 ✓","normal: 평범한이라는 뜻으로 비밀로 할 이유가 없습니다 ✗"]},{"id":"V653","q":"Prefiero ponerme unos pantalones ____ porque hace mucho calor hoy.","o":["largos","vaqueros","estrechos","cortos"],"a":3,"k":"옷 어휘","t":"오늘 너무 더워서 반바지를 입는 게 낫겠다.","e":"pantalones cortos는 '짧은 바지, 반바지'입니다. 더운 날(hace mucho calor)에는 짧은 바지가 자연스럽습니다. ponerse는 '(옷을) 입다'라는 뜻입니다.","x":["largos: 긴이라는 뜻으로 더운 날에 맞지 않습니다 ✗","vaqueros: 청바지라는 뜻으로 더위를 피하는 이유가 되지 않습니다 ✗","estrechos: 꽉 끼는이라는 뜻으로 더위와 관계가 약합니다 ✗","cortos: 짧은이라는 뜻으로 더운 날 입는 반바지가 됩니다 ✓"]},{"id":"V654","q":"Las paredes están ____. Tengo que pintarlas.","o":["lavadas","empapeladas","sucias","limpias"],"a":2,"k":"상태 형용사","t":"벽이 더럽다. 페인트를 칠해야 한다.","e":"sucio/a는 '더러운'이라는 뜻입니다. 벽을 칠해야 하는 이유는 벽이 더럽기 때문입니다. paredes가 여성 복수이므로 sucias입니다. 반대말은 limpio/a(깨끗한)입니다.","x":["lavadas: 씻긴이라는 뜻으로 칠해야 할 이유가 되지 않습니다 ✗","empapeladas: 벽지가 발린이라는 뜻으로 칠할 이유와 연결되지 않습니다 ✗","sucias: 더러운이라는 뜻으로 칠해야 하는 이유가 됩니다 ✓","limpias: 깨끗한이라는 뜻으로 칠할 필요가 없습니다 ✗"]},{"id":"V655","q":"Jorge siempre está dando ____. Es un mandón.","o":["regalos","dinero","órdenes","plata"],"a":2,"k":"dar órdenes","t":"호르헤는 항상 명령을 한다. 그는 이래라저래라 하는 사람이다.","e":"dar órdenes는 '명령을 내리다'라는 뜻입니다. mandón은 '남에게 명령하기 좋아하는 사람'이므로 órdenes가 정답입니다. orden은 '명령'일 때 여성 명사입니다(la orden).","x":["regalos: 선물이라는 뜻으로 mandón과 연결되지 않습니다 ✗","dinero: 돈이라는 뜻으로 mandón과 관계없습니다 ✗","órdenes: 명령이라는 뜻으로 mandón(명령하기 좋아하는 사람)과 맞습니다 ✓","plata: 중남미에서 돈이라는 뜻으로 mandón과 관계없습니다 ✗"]},{"id":"V656","q":"Andrea piensa que es ____, pero en realidad es muy inteligente.","o":["divina","lista","tonta","perfecta"],"a":2,"k":"성격 형용사","t":"안드레아는 자신이 바보라고 생각하지만 사실은 매우 똑똑하다.","e":"tonto/a는 '바보 같은, 어리석은'이라는 뜻입니다. 'pero en realidad(하지만 실제로는)'는 앞의 생각과 반대되는 사실을 말하므로, muy inteligente(아주 똑똑한)와 반대인 tonta가 맞습니다.","x":["divina: 아주 멋진, 신성한이라는 뜻으로 똑똑하다와 대조되지 않습니다 ✗","lista: 똑똑한이라는 뜻으로 inteligente와 같아 대조가 안 됩니다 ✗","tonta: 바보 같은이라는 뜻으로 inteligente와 대조됩니다 ✓","perfecta: 완벽한이라는 뜻으로 대조가 되지 않습니다 ✗"]},{"id":"V657","q":"Por desgracia, el hospital más cercano a mi casa está a una gran ____.","o":["estancia","distancia","ambulancia","constancia"],"a":1,"k":"distancia","t":"안타깝게도 우리 집에서 가장 가까운 병원도 아주 멀리 떨어져 있다.","e":"estar a una gran distancia는 '멀리 떨어져 있다'는 뜻입니다. distancia(거리)는 'estar a + 거리' 구조로 위치를 나타냅니다. 예: Está a 5 km(5km 떨어져 있다). 나머지 보기는 -ancia로 끝나는 비슷한 모양의 단어입니다.","x":["estancia: 머무름, 체류라는 뜻으로 맞지 않습니다 ✗","distancia: 거리라는 뜻으로 멀리 있다는 의미가 됩니다 ✓","ambulancia: 구급차라는 뜻으로 병원과 관련 있지만 문장 구조에 맞지 않습니다 ✗","constancia: 꾸준함이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V658","q":"Esta ____ es la que mejor me corta el pelo.","o":["peluquera","profesora","escritora","enfermera"],"a":0,"k":"직업 어휘","t":"이 미용사가 내 머리를 가장 잘 잘라 준다.","e":"peluquero/a는 '미용사'입니다. 머리를 자르는(cortar el pelo) 사람이므로 peluquera가 정답입니다. 미용실은 peluquería입니다.","x":["peluquera: 미용사라는 뜻으로 머리를 자르는 사람입니다 ✓","profesora: 선생님이라는 뜻으로 머리를 자르지 않습니다 ✗","escritora: 작가라는 뜻으로 맞지 않습니다 ✗","enfermera: 간호사라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V659","q":"Voy a comprar unos tulipanes en esa ____.","o":["juguetería","perfumería","floristería","frutería"],"a":2,"k":"가게 이름 어휘","t":"나는 저 꽃집에서 튤립을 좀 살 것이다.","e":"floristería는 '꽃집'입니다. flor(꽃) + -ería(가게)에서 온 말로, 튤립(tulipanes)은 꽃이므로 꽃집에서 삽니다.","x":["juguetería: 장난감 가게라는 뜻으로 꽃을 팔지 않습니다 ✗","perfumería: 향수 가게라는 뜻으로 맞지 않습니다 ✗","floristería: 꽃집이라는 뜻으로 튤립을 파는 곳입니다 ✓","frutería: 과일 가게라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V660","q":"No me gusta el sabor amargo; de hecho, soy muy ____.","o":["celoso","goloso","hablador","delicado"],"a":1,"k":"성격 형용사","t":"나는 쓴맛을 좋아하지 않는다. 사실 나는 단것을 아주 좋아한다.","e":"goloso/a는 '단것을 좋아하는'이라는 뜻입니다. 쓴맛(sabor amargo)을 싫어한다는 말 뒤에, 반대로 단 것을 좋아한다는 말이 이어지는 구조입니다. 예: Soy muy golosa, me encantan los pasteles(나는 단 걸 좋아해서 케이크를 정말 좋아해).","x":["celoso: 질투하는이라는 뜻으로 맛과 관계없습니다 ✗","goloso: 단것을 좋아하는이라는 뜻으로 쓴맛과 대조됩니다 ✓","hablador: 말이 많은이라는 뜻으로 맞지 않습니다 ✗","delicado: 섬세한, 연약한이라는 뜻으로 맛 취향과 연결되지 않습니다 ✗"]},{"id":"V661","q":"El ciclismo es un buen deporte para fortalecer ____.","o":["las piernas","los brazos","los hombros","el cabello"],"a":0,"k":"신체 어휘","t":"자전거 타기는 다리를 튼튼하게 하는 데 좋은 운동이다.","e":"pierna는 '다리'입니다. 자전거(ciclismo)는 페달을 밟는 운동이라 주로 다리 근육을 강화합니다. fortalecer는 '강화하다, 튼튼하게 하다'라는 뜻입니다.","x":["las piernas: 다리라는 뜻으로 자전거로 강화되는 부위입니다 ✓","los brazos: 팔이라는 뜻으로 자전거의 주된 효과가 아닙니다 ✗","los hombros: 어깨라는 뜻으로 맞지 않습니다 ✗","el cabello: 머리카락이라는 뜻으로 운동으로 강화하지 않습니다 ✗"]},{"id":"V662","q":"Los alimentos se fríen en ____ caliente.","o":["agua","vino","aceite","jugo"],"a":2,"k":"요리 어휘","t":"음식은 뜨거운 기름에 튀긴다.","e":"aceite는 '기름'입니다. freír(튀기다)는 기름으로 하는 조리법입니다. 'se fríen'은 '튀겨진다'라는 수동의 의미입니다(se + 3인칭 동사).","x":["agua: 물이라는 뜻으로 물로는 튀길 수 없습니다 ✗","vino: 포도주라는 뜻으로 맞지 않습니다 ✗","aceite: 기름이라는 뜻으로 튀김에 씁니다 ✓","jugo: 주스라는 뜻(중남미, 스페인은 zumo)으로 맞지 않습니다 ✗"]},{"id":"V663","q":"Es muy práctico vivir tan cerca de una ____ de metro.","o":["tienda","comisaría","agencia","estación"],"a":3,"k":"교통 어휘","t":"지하철역 이렇게 가까이에 사는 것은 아주 편리하다.","e":"estación de metro는 '지하철역'입니다. estación은 '역'이라는 뜻이고, 기차역은 estación de tren입니다. 버스는 정류장이라서 보통 parada de autobús라고 합니다.","x":["tienda: 가게라는 뜻으로 de metro와 어울리지 않습니다 ✗","comisaría: 경찰서라는 뜻으로 맞지 않습니다 ✗","agencia: 대리점, 여행사라는 뜻으로 맞지 않습니다 ✗","estación: 역이라는 뜻으로 지하철역이 됩니다 ✓"]},{"id":"V664","q":"Soy profesora de japonés. Trabajo en una ____.","o":["tasca","escuela de idiomas","oficina","papelería"],"a":1,"k":"직장 장소 어휘","t":"나는 일본어 선생님이다. 어학원에서 일한다.","e":"escuela de idiomas는 '어학원, 외국어 학교'입니다. idioma는 '언어'라는 뜻이에요. 일본어 선생님이 일하는 곳으로 가장 자연스럽습니다.","x":["tasca: 선술집이라는 뜻으로 맞지 않습니다 ✗","escuela de idiomas: 어학원이라는 뜻으로 일본어 선생님의 직장입니다 ✓","oficina: 사무실이라는 뜻으로 선생님 직장으로는 어색합니다 ✗","papelería: 문구점이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V665","q":"Hace tanto viento que se han caído las ____ de los árboles.","o":["piedras","raíces","hojas","olas"],"a":2,"k":"자연 어휘","t":"바람이 너무 많이 불어서 나무의 잎들이 떨어졌다.","e":"hoja는 '(나무의) 잎'입니다(종이 한 장이라는 뜻도 있어요). 바람이 세게 불면 나뭇잎이 떨어집니다. 'Hace viento'는 '바람이 분다'라는 날씨 표현입니다.","x":["piedras: 돌이라는 뜻으로 나무에 달려 있지 않습니다 ✗","raíces: 뿌리라는 뜻으로 떨어지는 것이 아닙니다 ✗","hojas: 잎이라는 뜻으로 바람에 떨어집니다 ✓","olas: 파도라는 뜻으로 나무와 관계없습니다 ✗"]},{"id":"V666","q":"Ana es muy ____ todavía, solo tiene quince años.","o":["linda","guapa","joven","bonita"],"a":2,"k":"외모·나이 형용사","t":"아나는 아직 아주 어리다. 겨우 열다섯 살이다.","e":"joven은 '젊은, 어린'이라는 뜻입니다. todavía(아직)와 'solo tiene quince años(겨우 15살)'는 나이를 말하므로 joven이 정답입니다. 다른 보기는 모두 외모가 예쁘다는 뜻입니다.","x":["linda: 예쁜(주로 중남미)이라는 뜻으로 나이와 관계없습니다 ✗","guapa: 예쁜, 잘생긴이라는 뜻으로 나이와 관계없습니다 ✗","joven: 어린, 젊은이라는 뜻으로 15살과 맞습니다 ✓","bonita: 예쁜이라는 뜻으로 나이와 관계없습니다 ✗"]},{"id":"V667","q":"Mi ____ es ser cantante y voy a hacer todo lo posible para conseguirlo.","o":["caso","mensaje","sueño","asunto"],"a":2,"k":"명사 어휘","t":"내 꿈은 가수가 되는 것이고, 그것을 이루기 위해 할 수 있는 모든 것을 할 것이다.","e":"sueño는 '꿈'입니다(잠, 졸음이라는 뜻도 있어요). '가수가 되는 것'은 이루고 싶은 목표이므로 sueño가 정답입니다. conseguirlo는 '그것을 이루다'라는 뜻입니다.","x":["caso: 경우, 사건이라는 뜻으로 맞지 않습니다 ✗","mensaje: 메시지라는 뜻으로 맞지 않습니다 ✗","sueño: 꿈이라는 뜻으로 이루고 싶은 목표에 맞습니다 ✓","asunto: 일, 용건이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V668","q":"Ana va en ____ de ruedas desde que tuvo el accidente de tráfico.","o":["silla","butaca","asiento","sillón"],"a":0,"k":"silla de ruedas","t":"아나는 교통사고를 당한 뒤로 휠체어를 탄다.","e":"silla de ruedas는 '휠체어'라는 고정 표현입니다(silla 의자 + ruedas 바퀴). 'ir en silla de ruedas'는 '휠체어를 타고 다니다'라는 뜻입니다.","x":["silla: 의자라는 뜻으로 silla de ruedas(휠체어)가 됩니다 ✓","butaca: 안락의자, 극장 좌석이라는 뜻으로 고정 표현이 아닙니다 ✗","asiento: 좌석이라는 뜻으로 휠체어 표현에 쓰지 않습니다 ✗","sillón: 팔걸이 의자라는 뜻으로 휠체어가 아닙니다 ✗"]},{"id":"V669","q":"En esta ____ hay muchas cafeterías.","o":["plaza","casa","habitación","cocina"],"a":0,"k":"도시 장소 어휘","t":"이 광장에는 카페가 많다.","e":"plaza는 '광장'입니다. 스페인어권 도시의 광장에는 카페와 식당이 많이 모여 있습니다. 'hay'는 '~이 있다'라는 뜻으로 존재를 나타냅니다.","x":["plaza: 광장이라는 뜻으로 카페가 많은 곳입니다 ✓","casa: 집이라는 뜻으로 카페가 많을 수 없습니다 ✗","habitación: 방이라는 뜻으로 맞지 않습니다 ✗","cocina: 부엌이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V670","q":"El ____ no sirve si está caducado.","o":["cuaderno","bolígrafo","sacapuntas","pasaporte"],"a":3,"k":"caducado","t":"여권은 유효기간이 지나면 쓸모가 없다.","e":"caducado는 '유효기간이 지난, 만료된'이라는 뜻입니다. 기한이 있는 것은 여권(pasaporte) 같은 서류입니다. 음식에도 쓰여 'leche caducada(유통기한 지난 우유)'처럼 말합니다.","x":["cuaderno: 공책이라는 뜻으로 유효기간이 없습니다 ✗","bolígrafo: 볼펜이라는 뜻으로 유효기간이 없습니다 ✗","sacapuntas: 연필깎이라는 뜻으로 맞지 않습니다 ✗","pasaporte: 여권이라는 뜻으로 유효기간이 있는 서류입니다 ✓"]},{"id":"V671","q":"Hace mucho ____, es mejor ir por la sombra.","o":["tiempo","viento","frío","sol"],"a":3,"k":"날씨 표현 hacer","t":"햇볕이 아주 강하니 그늘로 가는 게 낫다.","e":"hacer sol은 '햇볕이 나다'라는 날씨 표현입니다. 'Hace mucho sol'은 '햇볕이 강하다'이고, 그래서 그늘(sombra)로 가자는 말이 자연스럽습니다.","x":["tiempo: 날씨, 시간이라는 뜻으로 'Hace mucho tiempo'는 '오래 전'이 되어 맞지 않습니다 ✗","viento: 바람이라는 뜻으로 그늘로 갈 이유가 되지 않습니다 ✗","frío: 추위라는 뜻으로 그늘로 가면 더 춥습니다 ✗","sol: 햇볕이라는 뜻으로 그늘로 가는 이유가 됩니다 ✓"]},{"id":"V672","q":"Almudena es una mujer muy ____. Siempre está haciendo algo.","o":["vaga","discreta","perezosa","activa"],"a":3,"k":"성격 형용사","t":"알무데나는 매우 활동적인 여성이다. 항상 무언가를 하고 있다.","e":"activo/a는 '활동적인, 부지런히 움직이는'이라는 뜻입니다. 'Siempre está haciendo algo(늘 무언가를 하고 있다)'는 활동적인 성격을 보여 줍니다.","x":["vaga: 게으른이라는 뜻으로 문맥과 반대입니다 ✗","discreta: 조심스러운, 신중한이라는 뜻으로 맞지 않습니다 ✗","perezosa: 게으른이라는 뜻으로 문맥과 반대입니다 ✗","activa: 활동적인이라는 뜻으로 늘 무언가를 한다는 말과 맞습니다 ✓"]},{"id":"V673","q":"No me gusta comer ____, prefiero la carne.","o":["zumo","té","pescado","leche"],"a":2,"k":"음식 어휘","t":"나는 생선을 먹는 걸 좋아하지 않는다. 고기를 더 좋아한다.","e":"pescado는 '(음식으로서의) 생선'입니다. 살아 있는 물고기는 pez라고 해요. comer(먹다)와 어울리고 carne(고기)와 비교되는 것은 생선입니다.","x":["zumo: 주스라는 뜻으로 마시는 것이라 comer와 어울리지 않습니다 ✗","té: 차라는 뜻으로 마시는 것입니다 ✗","pescado: 생선이라는 뜻으로 고기와 비교됩니다 ✓","leche: 우유라는 뜻으로 마시는 것입니다 ✗"]},{"id":"V674","q":"En este museo hay ____ de arte maravillosas.","o":["obras","máquinas","horas","bombas"],"a":0,"k":"obra de arte","t":"이 박물관에는 훌륭한 예술 작품들이 있다.","e":"obra de arte는 '예술 작품'입니다. obra는 '작품'이라는 뜻으로 여성 명사라서 maravillosas(훌륭한)와 성·수가 일치합니다. 박물관(museo)에서 볼 수 있는 것입니다.","x":["obras: 작품이라는 뜻으로 obra de arte(예술 작품)가 됩니다 ✓","máquinas: 기계라는 뜻으로 de arte와 어울리지 않습니다 ✗","horas: 시간이라는 뜻으로 맞지 않습니다 ✗","bombas: 폭탄, 펌프라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V675","q":"Confío en Begoña porque es una persona ____.","o":["parlanchina","insegura","misteriosa","leal"],"a":3,"k":"성격 형용사","t":"베고냐는 의리 있는 사람이라서 나는 그녀를 믿는다.","e":"leal은 '충실한, 의리 있는'이라는 뜻입니다. confiar en은 '~를 믿다, 신뢰하다'라는 뜻이므로 그 이유로 leal이 자연스럽습니다. 명사는 lealtad(충성, 의리)입니다.","x":["parlanchina: 수다스러운이라는 뜻으로 믿는 이유가 되지 않습니다 ✗","insegura: 자신 없는이라는 뜻으로 믿을 이유가 아닙니다 ✗","misteriosa: 신비로운이라는 뜻으로 믿음의 이유로 어색합니다 ✗","leal: 의리 있는이라는 뜻으로 믿는 이유가 됩니다 ✓"]},{"id":"V676","q":"Voy a tomarme ____ de té mientras leo las noticias.","o":["un cuenco","una copa","un plato","una taza"],"a":3,"k":"식기 어휘","t":"뉴스를 읽는 동안 차 한 잔을 마실 것이다.","e":"taza는 '(손잡이 있는) 찻잔, 컵'입니다. 'una taza de té'는 '차 한 잔'입니다. 와인은 copa(굽 있는 잔), 물은 vaso(유리컵)를 씁니다.","x":["un cuenco: 사발, 그릇이라는 뜻으로 차를 마시는 데 쓰지 않습니다 ✗","una copa: 굽 있는 잔(와인잔)이라는 뜻으로 차에는 어색합니다 ✗","un plato: 접시라는 뜻으로 차를 담을 수 없습니다 ✗","una taza: 찻잔이라는 뜻으로 차와 어울립니다 ✓"]},{"id":"V677","q":"Mi padre no tiene barba, pero sí tiene ____.","o":["labios","bigote","frente","nariz"],"a":1,"k":"얼굴 어휘","t":"우리 아빠는 턱수염은 없지만 콧수염은 있다.","e":"bigote는 '콧수염'입니다. barba는 '턱수염'이에요. 'no tiene..., pero sí tiene...'는 '~은 없지만 ~은 있다'라는 대조 구조이므로 수염 종류가 와야 합니다.","x":["labios: 입술이라는 뜻으로 누구나 있어 대조가 되지 않습니다 ✗","bigote: 콧수염이라는 뜻으로 barba(턱수염)와 대조됩니다 ✓","frente: 이마라는 뜻으로 맞지 않습니다 ✗","nariz: 코라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V678","q":"No he reconocido a Luis porque ____ muchísimo.","o":["ha salido","se ha mudado","se ha acercado","ha cambiado"],"a":3,"k":"동사 어휘(현재완료)","t":"루이스가 너무 많이 변해서 그를 알아보지 못했다.","e":"cambiar는 '변하다'라는 뜻이고 'ha cambiado muchísimo'는 '아주 많이 변했다'입니다. reconocer(알아보다)하지 못한 이유는 외모가 많이 변했기 때문입니다.","x":["ha salido: 나갔다라는 뜻으로 알아보지 못한 이유가 되지 않습니다 ✗","se ha mudado: 이사했다라는 뜻으로 muchísimo와 함께 어색합니다 ✗","se ha acercado: 다가왔다라는 뜻으로 알아보지 못할 이유가 아닙니다 ✗","ha cambiado: 변했다라는 뜻으로 알아보지 못한 이유가 됩니다 ✓"]},{"id":"V679","q":"Ese ____ tiene una bicicleta increíblemente ligera.","o":["ciclista","chef","bombero","electricista"],"a":0,"k":"직업 어휘","t":"저 사이클 선수는 엄청나게 가벼운 자전거를 가지고 있다.","e":"ciclista는 '자전거 타는 사람, 사이클 선수'입니다. -ista로 끝나는 직업명은 남녀 형태가 같습니다(el/la ciclista). 가벼운 자전거(bicicleta ligera)와 연결됩니다.","x":["ciclista: 사이클 선수라는 뜻으로 자전거와 연결됩니다 ✓","chef: 요리사라는 뜻으로 자전거와 관계없습니다 ✗","bombero: 소방관이라는 뜻으로 맞지 않습니다 ✗","electricista: 전기 기사라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V680","q":"El toro tiene fama de ser un animal ____.","o":["cariñoso","de compañía","fuerte","doméstico"],"a":2,"k":"동물 형용사","t":"황소는 힘센 동물로 유명하다.","e":"fuerte는 '힘센, 강한'이라는 뜻입니다. 황소(toro)는 힘이 세기로 알려진 동물입니다. tener fama de는 '~로 유명하다, ~라는 평판이 있다'입니다.","x":["cariñoso: 다정한이라는 뜻으로 황소의 이미지와 맞지 않습니다 ✗","de compañía: 반려용이라는 뜻으로 황소는 반려동물이 아닙니다 ✗","fuerte: 힘센이라는 뜻으로 황소의 이미지와 맞습니다 ✓","doméstico: 집에서 기르는이라는 뜻으로 황소에 대한 평판으로 어색합니다 ✗"]},{"id":"V681","q":"En mi ciudad no hay metro, hay autobuses y ____.","o":["semáforos","carreteras","tranvías","pasos de cebra"],"a":2,"k":"교통수단 어휘","t":"우리 도시에는 지하철이 없고 버스와 트램이 있다.","e":"tranvía는 '트램, 노면전차'입니다. 지하철(metro), 버스(autobús)와 같은 대중교통 수단을 나열하고 있으므로 tranvías가 정답입니다.","x":["semáforos: 신호등이라는 뜻으로 교통수단이 아닙니다 ✗","carreteras: 도로, 국도라는 뜻으로 교통수단이 아닙니다 ✗","tranvías: 트램이라는 뜻으로 대중교통 수단입니다 ✓","pasos de cebra: 횡단보도라는 뜻으로 교통수단이 아닙니다 ✗"]},{"id":"V682","q":"Quería una ____ sin cebolla, patatas fritas y un refresco de limón.","o":["hamburguesa","heladería","panadería","pizzería"],"a":0,"k":"음식 어휘","t":"양파를 뺀 햄버거 하나, 감자튀김, 레몬 탄산음료 하나 주세요.","e":"hamburguesa는 '햄버거'입니다. 음식을 주문하는 상황이며, 'sin cebolla(양파 없이)'는 음식에 붙는 말입니다. 'Quería'는 과거형이지만 주문할 때 '~를 원하는데요'라고 공손하게 말하는 표현입니다.","x":["hamburguesa: 햄버거라는 뜻으로 주문하는 음식입니다 ✓","heladería: 아이스크림 가게라는 뜻으로 음식이 아니라 가게입니다 ✗","panadería: 빵집이라는 뜻으로 가게 이름입니다 ✗","pizzería: 피자 가게라는 뜻으로 가게 이름입니다 ✗"]},{"id":"V683","q":"Me gusta ver comedias porque me hacen ____.","o":["reír","llorar","sufrir","enfermar"],"a":0,"k":"hacer + 동사원형","t":"나는 코미디를 보는 걸 좋아한다. 나를 웃게 해 주기 때문이다.","e":"'hacer + 동사원형'은 '~하게 만들다'라는 뜻입니다. 'me hacen reír'는 '나를 웃게 한다'입니다. 코미디(comedias)는 웃음을 주는 장르이므로 reír가 정답입니다.","x":["reír: 웃다라는 뜻으로 코미디와 맞습니다 ✓","llorar: 울다라는 뜻으로 코미디를 좋아하는 이유로 맞지 않습니다 ✗","sufrir: 고통받다라는 뜻으로 맞지 않습니다 ✗","enfermar: 병나다라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V684","q":"Tenéis que ____ caminando. No podéis parar ahora.","o":["reír","sentir","describir","seguir"],"a":3,"k":"seguir + 현재분사","t":"너희는 계속 걸어가야 해. 지금 멈추면 안 돼.","e":"'seguir + 현재분사(-ando/-iendo)'는 '계속 ~하다'라는 뜻입니다. 'seguir caminando'는 '계속 걷다'이고, 'No podéis parar(멈추면 안 된다)'와 잘 맞습니다. tenéis/podéis는 vosotros 형태로, 중남미에서는 tienen/pueden(ustedes)을 씁니다.","x":["reír: 웃다라는 뜻으로 caminando와 이어질 수 없습니다 ✗","sentir: 느끼다라는 뜻으로 맞지 않습니다 ✗","describir: 묘사하다라는 뜻으로 맞지 않습니다 ✗","seguir: 계속하다라는 뜻으로 seguir caminando(계속 걷다)가 됩니다 ✓"]},{"id":"V685","q":"Te recomiendo esta ____ de zapatos porque es de calidad.","o":["marca","contraseña","talla","señal"],"a":0,"k":"쇼핑 어휘","t":"이 신발 브랜드는 품질이 좋아서 추천한다.","e":"marca는 '브랜드, 상표'입니다. 'de calidad(품질이 좋은)'는 브랜드에 대한 평가로 자연스럽습니다. 신발 크기는 talla(옷)나 número(신발 사이즈)라고 합니다.","x":["marca: 브랜드라는 뜻으로 품질 평가와 어울립니다 ✓","contraseña: 비밀번호라는 뜻으로 맞지 않습니다 ✗","talla: 치수라는 뜻으로 품질이 좋다는 이유와 맞지 않습니다 ✗","señal: 신호, 표지라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V686","q":"Victoria está muy triste porque ____ con su novio.","o":["ha roto","ha charlado","se ha mudado","ha bailado"],"a":0,"k":"romper con","t":"빅토리아는 남자 친구와 헤어져서 매우 슬프다.","e":"romper con + 사람은 '~와 헤어지다, 관계를 끊다'라는 뜻입니다. romper는 원래 '깨뜨리다'라는 뜻이에요. 슬픈 이유로 이별이 가장 자연스럽고, 과거분사가 roto로 불규칙인 점에 주의하세요.","x":["ha roto: 헤어졌다라는 뜻으로 슬픈 이유가 됩니다 ✓","ha charlado: 수다 떨었다라는 뜻으로 슬픈 이유가 아닙니다 ✗","se ha mudado: 이사했다라는 뜻으로 con su novio와 함께 슬픈 이유가 되기 어렵습니다 ✗","ha bailado: 춤췄다라는 뜻으로 슬픈 이유가 아닙니다 ✗"]},{"id":"V687","q":"Necesito un buen ____ para que me ayude con este problema legal.","o":["maestro","abogado","mesero","empresario"],"a":1,"k":"직업 어휘","t":"이 법적 문제를 도와줄 좋은 변호사가 필요하다.","e":"abogado/a는 '변호사'입니다. problema legal(법적 문제)을 도와주는 사람은 변호사입니다. 'para que + 접속법(바람·목적을 나타내는 동사 형태)'은 '~하도록'이라는 목적을 나타냅니다.","x":["maestro: 선생님이라는 뜻으로 법적 문제와 관계없습니다 ✗","abogado: 변호사라는 뜻으로 법적 문제를 돕습니다 ✓","mesero: 웨이터(중남미, 스페인은 camarero)라는 뜻으로 맞지 않습니다 ✗","empresario: 기업가라는 뜻으로 법적 문제 해결 담당이 아닙니다 ✗"]},{"id":"V688","q":"Las ____ tienen el cuello muy largo.","o":["ranas","jirafas","ballenas","moscas"],"a":1,"k":"동물 어휘","t":"기린은 목이 매우 길다.","e":"jirafa는 '기린'입니다. 목(cuello)이 아주 긴 동물로 유명합니다. 스페인어에서 j는 한국어 'ㅎ'처럼 강하게 발음해 '히라파'처럼 들립니다.","x":["ranas: 개구리라는 뜻으로 목이 길지 않습니다 ✗","jirafas: 기린이라는 뜻으로 목이 긴 동물입니다 ✓","ballenas: 고래라는 뜻으로 목이 길지 않습니다 ✗","moscas: 파리라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V689","q":"Esta es la ____ que uso para hacer mis deberes escolares.","o":["novela","revista","lista","libreta"],"a":3,"k":"학용품 어휘","t":"이것이 내가 학교 숙제를 할 때 쓰는 공책이다.","e":"libreta는 '공책, 수첩'입니다. 숙제(deberes escolares)를 할 때 쓰는(uso) 물건이므로 공책이 가장 자연스럽습니다. cuaderno와 비슷한 말입니다.","x":["novela: 소설이라는 뜻으로 숙제할 때 쓰는 물건이 아닙니다 ✗","revista: 잡지라는 뜻으로 맞지 않습니다 ✗","lista: 목록이라는 뜻으로 숙제 도구가 아닙니다 ✗","libreta: 공책이라는 뜻으로 숙제할 때 씁니다 ✓"]},{"id":"V690","q":"____ lloviendo mucho; vamos a esperar a que pare.","o":["Tiene","Es","Hace","Está"],"a":3,"k":"estar + 현재분사","t":"비가 많이 오고 있어. 그칠 때까지 기다리자.","e":"'estar + 현재분사'는 '~하고 있다'라는 진행형입니다. 'Está lloviendo'는 '비가 오고 있다'입니다. 날씨에 hacer를 쓰지만(hace frío), llover(비 오다)는 그 자체가 동사이므로 hacer와 함께 쓰지 않습니다.","x":["Tiene: 가지다(tener)로 진행형을 만들 수 없습니다 ✗","Es: ser로는 진행형을 만들지 않습니다 ✗","Hace: 날씨 표현에 쓰지만 현재분사 lloviendo와는 쓰지 않습니다 ✗","Está: estar + lloviendo로 '비가 오고 있다'가 됩니다 ✓"]},{"id":"V691","q":"Para caminar durante tantas horas es mejor utilizar un calzado ____.","o":["estrecho","cómodo","nuevo","duro"],"a":1,"k":"신발 형용사","t":"그렇게 오랜 시간 걸으려면 편한 신발을 신는 것이 좋다.","e":"cómodo는 '편한, 편안한'이라는 뜻입니다. 오래 걸을 때는 편한 신발이 필요합니다. calzado는 '신발류'를 통틀어 부르는 말입니다.","x":["estrecho: 꽉 끼는이라는 뜻으로 오래 걷기에 좋지 않습니다 ✗","cómodo: 편한이라는 뜻으로 오래 걷기에 좋습니다 ✓","nuevo: 새로운이라는 뜻으로 새 신발은 오히려 발이 아플 수 있습니다 ✗","duro: 딱딱한이라는 뜻으로 걷기에 좋지 않습니다 ✗"]},{"id":"V692","q":"¿Cuántas veces has estado en París? — ____.","o":["En el futuro","En otoño","Nueve o diez","Hace tiempo"],"a":2,"k":"횟수 묻고 답하기","t":"파리에 몇 번 가 봤어? —아홉 번인가 열 번.","e":"¿Cuántas veces...?는 '몇 번?'이라고 횟수를 묻는 질문입니다. 그래서 숫자로 답한 'Nueve o diez(아홉 번이나 열 번)'가 정답입니다. vez(번)의 복수는 veces입니다.","x":["En el futuro: 미래에라는 뜻으로 횟수가 아닙니다 ✗","En otoño: 가을에라는 뜻으로 시기를 말합니다 ✗","Nueve o diez: 아홉이나 열이라는 뜻으로 횟수를 답합니다 ✓","Hace tiempo: 오래 전에라는 뜻으로 횟수가 아닙니다 ✗"]},{"id":"V693","q":"Trabajo como entrenador de un ____ de fútbol.","o":["programa","equipo","periódico","documental"],"a":1,"k":"스포츠 어휘","t":"나는 축구팀의 코치로 일한다.","e":"equipo는 '팀'입니다. entrenador(코치, 감독)는 equipo de fútbol(축구팀)을 지도합니다. equipo에는 '장비'라는 뜻도 있습니다.","x":["programa: 프로그램이라는 뜻으로 코치와 맞지 않습니다 ✗","equipo: 팀이라는 뜻으로 축구팀 코치가 됩니다 ✓","periódico: 신문이라는 뜻으로 맞지 않습니다 ✗","documental: 다큐멘터리라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V694","q":"¿Me das el ____ de teléfono de Carmen?","o":["nombre","carné","dato","número"],"a":3,"k":"número de teléfono","t":"카르멘의 전화번호 좀 줄래?","e":"número de teléfono는 '전화번호'입니다. ¿Me das...?는 '~ 좀 줄래?'라는 부탁 표현으로, 친구 사이에서 자주 씁니다.","x":["nombre: 이름이라는 뜻으로 de teléfono와 어울리지 않습니다 ✗","carné: 신분증, 카드라는 뜻으로 맞지 않습니다 ✗","dato: 자료, 정보라는 뜻으로 전화번호를 나타내지 않습니다 ✗","número: 번호라는 뜻으로 전화번호가 됩니다 ✓"]},{"id":"V695","q":"Estoy en paro, por eso estoy buscando ____.","o":["amor","trabajo","amistad","vivienda"],"a":1,"k":"일자리 어휘","t":"나는 실업 상태라서 일자리를 찾고 있다.","e":"estar en paro는 스페인에서 '실업 상태이다'라는 뜻입니다(중남미에서는 estar desempleado). 실업자가 찾는 것은 trabajo(일, 일자리)입니다.","x":["amor: 사랑이라는 뜻으로 실업과 관계없습니다 ✗","trabajo: 일자리라는 뜻으로 실업자가 찾는 것입니다 ✓","amistad: 우정이라는 뜻으로 맞지 않습니다 ✗","vivienda: 집이라는 뜻으로 실업과 직접 관계없습니다 ✗"]},{"id":"V696","q":"No puedo ____ más, estoy lleno.","o":["comer","dormir","decir","hacer"],"a":0,"k":"동사 어휘","t":"더 이상 못 먹겠어, 배불러.","e":"comer는 '먹다'입니다. 'estoy lleno'는 '배가 부르다'라는 뜻이므로 더 먹을 수 없다는 말이 자연스럽습니다. lleno는 원래 '가득 찬'이라는 뜻입니다.","x":["comer: 먹다라는 뜻으로 배부르다는 말과 맞습니다 ✓","dormir: 자다라는 뜻으로 배부름과 관계없습니다 ✗","decir: 말하다라는 뜻으로 맞지 않습니다 ✗","hacer: 하다라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V697","q":"Cada día tomo el sol en ____ de mi casa.","o":["el garaje","la terraza","el comedor","el aseo"],"a":1,"k":"집 구조 어휘","t":"나는 매일 우리 집 테라스에서 일광욕을 한다.","e":"terraza는 '테라스, 베란다'입니다. tomar el sol(일광욕하다)은 햇볕이 드는 바깥 공간에서 하므로 테라스가 맞습니다.","x":["el garaje: 차고라는 뜻으로 햇볕이 들지 않습니다 ✗","la terraza: 테라스라는 뜻으로 일광욕하는 곳입니다 ✓","el comedor: 식당(식사하는 방)이라는 뜻으로 맞지 않습니다 ✗","el aseo: 화장실이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V698","q":"La sopa está bien de sal, no está ____ ni demasiado salada.","o":["agria","amarga","sosa","ácida"],"a":2,"k":"맛 형용사","t":"수프는 간이 딱 맞다. 싱겁지도 너무 짜지도 않다.","e":"soso/a는 '싱거운, 간이 안 된'이라는 뜻으로 salado(짠)의 반대입니다. 'ni A ni B'는 'A도 B도 아닌'이라는 뜻이라 짠 것과 반대인 맛이 와야 합니다.","x":["agria: 시큼한이라는 뜻으로 소금 간과 관계없습니다 ✗","amarga: 쓴이라는 뜻으로 짠맛의 반대가 아닙니다 ✗","sosa: 싱거운이라는 뜻으로 짠맛의 반대입니다 ✓","ácida: 산성의, 신이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V699","q":"Siempre dejo la ____ de té cinco minutos en una taza de agua hervida.","o":["cajita","botellita","bolita","bolsita"],"a":3,"k":"축소사 -ita","t":"나는 항상 티백을 끓인 물 한 잔에 5분 동안 담가 둔다.","e":"bolsita de té는 '티백'입니다. bolsa(봉지)에 '작은'이라는 뜻의 축소사 -ita가 붙은 말입니다. 다른 보기도 모두 -ita가 붙은 작은 물건이지만 티백은 bolsita입니다.","x":["cajita: 작은 상자라는 뜻으로 물에 담그는 것이 아닙니다 ✗","botellita: 작은 병이라는 뜻으로 맞지 않습니다 ✗","bolita: 작은 공이라는 뜻으로 티백이 아닙니다 ✗","bolsita: 작은 봉지라는 뜻으로 bolsita de té(티백)가 됩니다 ✓"]},{"id":"V700","q":"Un año tiene ____ meses.","o":["dos","once","trece","doce"],"a":3,"k":"숫자 어휘","t":"1년은 12개월이다.","e":"doce는 12입니다. 1년은 열두 달이므로 doce가 정답입니다. 참고: once(11), doce(12), trece(13).","x":["dos: 2라는 뜻으로 틀립니다 ✗","once: 11이라는 뜻으로 틀립니다 ✗","trece: 13이라는 뜻으로 틀립니다 ✗","doce: 12라는 뜻으로 1년의 개월 수입니다 ✓"]},{"id":"V701","q":"Tenemos que ____ la ropa a mano porque la lavadora no funciona.","o":["recoger","lavar","planchar","secar"],"a":1,"k":"집안일 어휘","t":"세탁기가 고장 나서 옷을 손으로 빨아야 한다.","e":"lavar는 '씻다, 빨다'입니다. 세탁기(lavadora)가 작동하지 않으니 손빨래(lavar a mano)를 해야 합니다. lavadora도 lavar에서 나온 말이에요.","x":["recoger: 거두다, 정리하다라는 뜻으로 세탁기와 연결되지 않습니다 ✗","lavar: 빨다라는 뜻으로 세탁기 대신 하는 일입니다 ✓","planchar: 다림질하다라는 뜻으로 세탁기와 관계없습니다 ✗","secar: 말리다라는 뜻으로 세탁기 고장의 대안이 아닙니다 ✗"]},{"id":"V702","q":"Mis padres están enfadados porque ____ tres asignaturas.","o":["he aprobado","he completado","he hecho","he suspendido"],"a":3,"k":"학교 어휘","t":"내가 세 과목에서 낙제해서 부모님이 화가 나셨다.","e":"suspender는 스페인에서 '(시험·과목에서) 낙제하다'라는 뜻입니다. 반대말은 aprobar(합격하다)입니다. 부모님이 화난 이유이므로 suspendido가 맞습니다. 중남미에서는 reprobar를 많이 씁니다.","x":["he aprobado: 합격했다라는 뜻으로 부모님이 화날 이유가 아닙니다 ✗","he completado: 완료했다라는 뜻으로 화날 이유가 아닙니다 ✗","he hecho: 했다라는 뜻으로 의미가 분명하지 않습니다 ✗","he suspendido: 낙제했다라는 뜻으로 부모님이 화난 이유가 됩니다 ✓"]},{"id":"V703","q":"Este palacio es muy ____, tiene más de trescientos años.","o":["antiguo","moderno","reciente","nuevo"],"a":0,"k":"형용사 어휘","t":"이 궁전은 아주 오래되었다. 300년도 넘었다.","e":"antiguo는 '오래된, 옛날의'라는 뜻입니다. 'más de trescientos años(300년 이상)'라는 설명과 잘 맞습니다. 반대말은 moderno(현대적인), nuevo(새로운)입니다.","x":["antiguo: 오래된이라는 뜻으로 300년 넘은 궁전과 맞습니다 ✓","moderno: 현대적인이라는 뜻으로 반대 의미입니다 ✗","reciente: 최근의이라는 뜻으로 반대 의미입니다 ✗","nuevo: 새로운이라는 뜻으로 반대 의미입니다 ✗"]},{"id":"V704","q":"El ____ es un vehículo de gran tamaño.","o":["patinete","andador","monopatín","camión"],"a":3,"k":"탈것 어휘","t":"트럭은 크기가 큰 차량이다.","e":"camión은 '트럭'입니다. 'de gran tamaño(크기가 큰)' 차량(vehículo)은 트럭입니다. 멕시코에서는 camión이 '버스'를 뜻하기도 합니다.","x":["patinete: 킥보드라는 뜻으로 작은 탈것입니다 ✗","andador: 보행 보조기라는 뜻으로 큰 차량이 아닙니다 ✗","monopatín: 스케이트보드라는 뜻으로 작은 탈것입니다 ✗","camión: 트럭이라는 뜻으로 큰 차량입니다 ✓"]},{"id":"V705","q":"No me gusta hablar en público; me ____ vergüenza.","o":["hace","da","tiene","pone"],"a":1,"k":"dar vergüenza","t":"나는 사람들 앞에서 말하는 걸 좋아하지 않는다. 부끄럽다.","e":"'dar vergüenza'는 '부끄럽게 하다'라는 고정 표현으로 'me da vergüenza(나는 부끄럽다)'처럼 씁니다. 같은 구조로 'me da miedo(나는 무섭다)', 'me da pena(나는 안타깝다)'도 있습니다.","x":["hace: hacer는 vergüenza와 함께 쓰지 않습니다 ✗","da: dar vergüenza(부끄럽게 하다)라는 고정 표현이 됩니다 ✓","tiene: 'tengo vergüenza'는 가능하지만 me와 함께 3인칭 tiene는 쓸 수 없습니다 ✗","pone: poner는 vergüenza와 이런 구조로 쓰지 않습니다 ✗"]},{"id":"V706","q":"¿Con qué frecuencia te conectas a internet? — ____.","o":["A las 7","Ayer","Mañana","Cada día"],"a":3,"k":"빈도 표현","t":"얼마나 자주 인터넷에 접속해? —매일.","e":"¿Con qué frecuencia...?는 '얼마나 자주?'라고 빈도를 묻는 질문입니다. 빈도로 답하는 것은 'Cada día(매일)'입니다. todos los días도 같은 뜻입니다.","x":["A las 7: 7시에라는 뜻으로 시각을 말합니다 ✗","Ayer: 어제라는 뜻으로 빈도가 아닙니다 ✗","Mañana: 내일이라는 뜻으로 빈도가 아닙니다 ✗","Cada día: 매일이라는 뜻으로 빈도를 답합니다 ✓"]},{"id":"V707","q":"Necesitamos leña para ____ la chimenea.","o":["abrir","encender","arreglar","ordenar"],"a":1,"k":"encender","t":"벽난로에 불을 피우려면 장작이 필요하다.","e":"encender는 '불을 켜다, 불을 붙이다'라는 뜻입니다. leña(장작)는 chimenea(벽난로)에 불을 피울 때 씁니다. 전등이나 TV를 켤 때도 encender를 씁니다.","x":["abrir: 열다라는 뜻으로 장작이 필요한 일이 아닙니다 ✗","encender: 불을 피우다라는 뜻으로 장작과 맞습니다 ✓","arreglar: 고치다라는 뜻으로 장작이 필요하지 않습니다 ✗","ordenar: 정리하다라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V708","q":"No puedo tener mi propia casa porque los precios de las ____ están por las nubes.","o":["tiendas","academias","escuelas","viviendas"],"a":3,"k":"주거 어휘","t":"집값이 너무 비싸서 나는 내 집을 가질 수 없다.","e":"vivienda는 '주택, 집'입니다. 내 집(mi propia casa)을 가질 수 없는 이유는 주택 가격이 비싸기 때문입니다. 'estar por las nubes'는 '(가격이) 하늘 높이 치솟다'라는 관용 표현입니다.","x":["tiendas: 가게라는 뜻으로 내 집과 관계없습니다 ✗","academias: 학원이라는 뜻으로 맞지 않습니다 ✗","escuelas: 학교라는 뜻으로 맞지 않습니다 ✗","viviendas: 주택이라는 뜻으로 집값을 말합니다 ✓"]},{"id":"V709","q":"Un toro es más ____ que un ratón.","o":["pequeño","joven","grande","viejo"],"a":2,"k":"비교급","t":"황소는 생쥐보다 크다.","e":"'más + 형용사 + que'는 '~보다 더 ~한'이라는 비교급입니다. 황소(toro)와 생쥐(ratón)를 비교하면 황소가 크므로 grande가 정답입니다.","x":["pequeño: 작은이라는 뜻으로 황소가 생쥐보다 작지 않습니다 ✗","joven: 젊은이라는 뜻으로 두 동물의 일반적인 비교가 아닙니다 ✗","grande: 큰이라는 뜻으로 황소가 생쥐보다 큽니다 ✓","viejo: 늙은이라는 뜻으로 일반적인 비교가 아닙니다 ✗"]},{"id":"V710","q":"Me gustaría tener un ____ más alto. Con tan poco dinero no llego a fin de mes.","o":["suelo","piso","sueldo","cuerpo"],"a":2,"k":"돈 어휘","t":"월급이 더 많았으면 좋겠다. 이렇게 적은 돈으로는 월말까지 버틸 수 없다.","e":"sueldo는 '월급, 급여'입니다. 'no llego a fin de mes'는 '월말까지 돈이 버티지 못한다'는 표현이에요. suelo(바닥)와 철자가 비슷하니 주의하세요.","x":["suelo: 바닥이라는 뜻으로 돈과 관계없습니다 ✗","piso: 아파트, 층이라는 뜻으로 맞지 않습니다 ✗","sueldo: 월급이라는 뜻으로 돈이 부족하다는 말과 맞습니다 ✓","cuerpo: 몸이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V711","q":"¿Qué solemos responder cuando nos dan las gracias? — ____.","o":["Hasta pronto","De nada","Nos vemos","Hablamos"],"a":1,"k":"인사 표현","t":"누군가 고맙다고 하면 보통 뭐라고 대답하나요? —천만에요.","e":"'De nada'는 '천만에요, 별말씀을요'라는 뜻으로 'Gracias'에 대한 기본 대답입니다. 비슷하게 'No hay de qué'도 씁니다.","x":["Hasta pronto: 곧 또 봐요라는 작별 인사입니다 ✗","De nada: 천만에요라는 뜻으로 감사에 대한 대답입니다 ✓","Nos vemos: 또 봐요라는 작별 인사입니다 ✗","Hablamos: 나중에 얘기해요라는 작별 인사입니다 ✗"]},{"id":"V712","q":"Vamos a celebrar nuestro ____ aniversario de boda.","o":["dos","quince","doce","segundo"],"a":3,"k":"서수","t":"우리는 결혼 2주년을 축하할 것이다.","e":"'몇 번째'를 나타낼 때는 서수를 씁니다: primero(첫 번째), segundo(두 번째), tercero(세 번째). aniversario(기념일) 앞에는 '두 번째'라는 서수 segundo가 와야 합니다. 기수(dos, doce 등)는 '몇 개'를 셀 때 씁니다.","x":["dos: 기수 2로 aniversario 앞에서 '두 번째' 뜻으로 쓰지 않습니다 ✗","quince: 기수 15로 서수가 아닙니다 ✗","doce: 기수 12로 서수가 아닙니다 ✗","segundo: 서수 '두 번째'로 aniversario 앞에 알맞습니다 ✓"]},{"id":"V713","q":"Veo series en español para ____ mi comprensión de la lengua.","o":["acabar","mejorar","finalizar","terminar"],"a":1,"k":"동사 어휘","t":"나는 스페인어 이해력을 향상시키려고 스페인어 드라마를 본다.","e":"mejorar는 '향상시키다, 좋아지게 하다'라는 뜻입니다. 드라마(series)를 보는 목적은 이해력(comprensión)을 높이는 것입니다. 나머지 보기는 모두 '끝내다'라는 뜻입니다.","x":["acabar: 끝내다라는 뜻으로 이해력을 끝낼 수 없습니다 ✗","mejorar: 향상시키다라는 뜻으로 학습 목적에 맞습니다 ✓","finalizar: 마치다라는 뜻으로 맞지 않습니다 ✗","terminar: 끝내다라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V714","q":"Este ____ sale en muchas películas de acción.","o":["maestro","conductor","actor","plomero"],"a":2,"k":"직업 어휘","t":"이 배우는 많은 액션 영화에 나온다.","e":"actor는 '배우(남자)'이고 여자는 actriz입니다. 'salir en una película'는 '영화에 나오다'라는 표현입니다.","x":["maestro: 선생님이라는 뜻으로 영화 출연자가 아닙니다 ✗","conductor: 운전사, 진행자라는 뜻으로 맞지 않습니다 ✗","actor: 배우라는 뜻으로 영화에 나오는 사람입니다 ✓","plomero: 배관공(중남미, 스페인은 fontanero)이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V715","q":"¿Te importa ____ la ventana? Tengo frío.","o":["abrir","quitar","romper","cerrar"],"a":3,"k":"동사 어휘","t":"창문 좀 닫아 줄래? 추워.","e":"cerrar는 '닫다'라는 뜻입니다. 추울 때(tengo frío) 창문을 닫아 달라고 부탁하는 것이 자연스럽습니다. '¿Te importa + 동사원형?'은 '~해 줄래?'라는 공손한 부탁 표현입니다.","x":["abrir: 열다라는 뜻으로 추운데 창문을 열면 더 춥습니다 ✗","quitar: 치우다, 떼다라는 뜻으로 창문에 어색합니다 ✗","romper: 깨다라는 뜻으로 맞지 않습니다 ✗","cerrar: 닫다라는 뜻으로 추울 때의 부탁에 맞습니다 ✓"]},{"id":"V716","q":"No podemos cruzar porque el semáforo está en ____ para nosotros.","o":["negro","rojo","rosa","blanco"],"a":1,"k":"색 어휘","t":"우리 쪽 신호등이 빨간불이라 건널 수 없다.","e":"rojo는 '빨간색'입니다. 신호등(semáforo)이 빨간불일 때 건널 수 없습니다. 'estar en rojo/verde'는 '빨간불/초록불이다'입니다.","x":["negro: 검은색이라는 뜻으로 신호등 색이 아닙니다 ✗","rojo: 빨간색이라는 뜻으로 건너면 안 되는 신호입니다 ✓","rosa: 분홍색이라는 뜻으로 신호등 색이 아닙니다 ✗","blanco: 흰색이라는 뜻으로 신호등 색이 아닙니다 ✗"]},{"id":"V717","q":"Voy a meter los ____ sucios en el lavavajillas.","o":["pantalones","platos","discos","papeles"],"a":1,"k":"주방 어휘","t":"더러운 접시들을 식기세척기에 넣을 거야.","e":"plato는 '접시'입니다. lavavajillas(식기세척기)에는 식기를 넣습니다. lavavajillas는 lavar(씻다) + vajilla(식기)가 합쳐진 말입니다.","x":["pantalones: 바지라는 뜻으로 세탁기에 넣습니다 ✗","platos: 접시라는 뜻으로 식기세척기에 넣습니다 ✓","discos: 음반, 원반이라는 뜻으로 맞지 않습니다 ✗","papeles: 종이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V718","q":"No le ____ dinero a nadie. No me gusta tener deudas.","o":["presto","dejo","debo","doy"],"a":2,"k":"돈 관련 동사","t":"나는 누구에게도 돈을 빚지고 있지 않다. 빚이 있는 걸 좋아하지 않는다.","e":"deber dinero a alguien은 '~에게 돈을 빚지다'라는 뜻입니다. deudas(빚)와 연결되므로 debo가 정답입니다. deber에는 '~해야 한다'라는 뜻도 있습니다.","x":["presto: 빌려주다라는 뜻으로 내가 빚지는 것과 반대입니다 ✗","dejo: (스페인 구어로) 빌려주다라는 뜻으로 빚과 연결되지 않습니다 ✗","debo: 빚지다라는 뜻으로 deudas(빚)와 맞습니다 ✓","doy: 주다라는 뜻으로 빚과 관계없습니다 ✗"]},{"id":"V719","q":"Nos reímos mucho con los chistes que ____ Paco.","o":["cuenta","dice","habla","comenta"],"a":0,"k":"contar chistes","t":"우리는 파코가 들려주는 농담에 많이 웃는다.","e":"'contar chistes'는 '농담을 하다(들려주다)'라는 고정 표현입니다. contar에는 '이야기하다, 들려주다'라는 뜻이 있어서 contar un cuento(이야기를 들려주다)처럼 씁니다.","x":["cuenta: 들려주다(contar)라는 뜻으로 chistes와 짝을 이룹니다 ✓","dice: 말하다(decir)라는 뜻으로 가능은 하지만 chistes와는 contar가 가장 자연스럽습니다 ✗","habla: 말하다(hablar)라는 뜻으로 목적어 chistes와 어울리지 않습니다 ✗","comenta: 언급하다라는 뜻으로 농담과 어울리지 않습니다 ✗"]},{"id":"V720","q":"¿Cuál es la prenda que más te gusta de tu armario? — ____.","o":["El verde","El salón","El abrigo gris","La lasaña"],"a":2,"k":"옷 어휘","t":"네 옷장에서 가장 좋아하는 옷은 뭐야? —회색 코트.","e":"prenda는 '옷 한 벌, 의류'입니다. 질문이 옷을 묻고 있으므로 옷 이름인 'El abrigo gris(회색 코트)'가 정답입니다. 'El verde'는 명사가 생략된 표현이라 무엇인지 알 수 없습니다.","x":["El verde: 초록색 것이라는 뜻으로, 어떤 옷인지 알 수 없어 대답으로 부족합니다 ✗","El salón: 거실이라는 뜻으로 옷이 아닙니다 ✗","El abrigo gris: 회색 코트라는 뜻으로 옷을 답합니다 ✓","La lasaña: 라자냐라는 뜻으로 음식입니다 ✗"]},{"id":"V721","q":"Soy ____; reparto cartas y otros envíos.","o":["abogada","atleta","bailarina","cartera"],"a":3,"k":"직업 어휘","t":"나는 우편배달부다. 편지와 다른 우편물을 배달한다.","e":"cartero/a는 '우편배달부'입니다. carta(편지)에서 온 말이에요. repartir cartas(편지를 배달하다)는 우편배달부의 일입니다. 참고로 cartera는 '지갑, 서류 가방'이라는 뜻도 있습니다.","x":["abogada: 변호사라는 뜻으로 편지를 배달하지 않습니다 ✗","atleta: 운동선수라는 뜻으로 맞지 않습니다 ✗","bailarina: 무용수라는 뜻으로 맞지 않습니다 ✗","cartera: 우편배달부라는 뜻으로 편지를 배달합니다 ✓"]},{"id":"V722","q":"El tiempo de ____ es importante porque hay que descansar y disfrutar.","o":["ocio","estudio","trabajo","empleo"],"a":0,"k":"여가 어휘","t":"쉬고 즐겨야 하기 때문에 여가 시간은 중요하다.","e":"ocio는 '여가, 레저'입니다. 'tiempo de ocio'는 '여가 시간'이며 tiempo libre와 비슷합니다. 쉬고 즐기는(descansar y disfrutar) 시간이므로 ocio가 맞습니다.","x":["ocio: 여가라는 뜻으로 쉬고 즐기는 시간입니다 ✓","estudio: 공부라는 뜻으로 휴식과 반대입니다 ✗","trabajo: 일이라는 뜻으로 휴식과 반대입니다 ✗","empleo: 고용, 직업이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V723","q":"Alberto es un chico muy ____ que lo entiende todo fácilmente.","o":["listo","tímido","cerrado","abierto"],"a":0,"k":"성격 형용사","t":"알베르토는 무엇이든 쉽게 이해하는 아주 똑똑한 아이다.","e":"listo는 ser와 함께 쓰면 '똑똑한, 영리한'이라는 뜻입니다. estar listo는 '준비된'이라는 뜻이 되니 주의하세요. 무엇이든 쉽게 이해한다는 설명과 맞습니다.","x":["listo: 똑똑한이라는 뜻으로 쉽게 이해한다는 말과 맞습니다 ✓","tímido: 수줍은이라는 뜻으로 이해력과 관계없습니다 ✗","cerrado: 닫힌, 폐쇄적인이라는 뜻으로 맞지 않습니다 ✗","abierto: 개방적인이라는 뜻으로 이해력과 직접 관계없습니다 ✗"]},{"id":"V724","q":"El proyecto salió mal porque no fue bien ____.","o":["pisado","pasado","planeado","plantado"],"a":2,"k":"과거분사 어휘","t":"그 프로젝트는 계획이 잘 세워지지 않아서 실패했다.","e":"planear는 '계획하다'이고 과거분사는 planeado입니다. 'fue bien planeado'는 '잘 계획되었다'라는 수동태(ser + 과거분사)입니다. 프로젝트가 실패한 이유로 계획 부족이 자연스럽습니다.","x":["pisado: 밟힌이라는 뜻으로 프로젝트와 맞지 않습니다 ✗","pasado: 지나간이라는 뜻으로 맞지 않습니다 ✗","planeado: 계획된이라는 뜻으로 실패 이유와 맞습니다 ✓","plantado: 심어진이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V725","q":"En este edificio no hay ____, así que tenemos que usar las escaleras.","o":["ascensor","entrada","puerta","salida"],"a":0,"k":"건물 어휘","t":"이 건물에는 엘리베이터가 없어서 계단을 이용해야 한다.","e":"ascensor는 '엘리베이터'입니다. 계단(escaleras)을 써야 하는 이유는 엘리베이터가 없기 때문입니다. 중남미 일부에서는 elevador라고도 합니다.","x":["ascensor: 엘리베이터라는 뜻으로 계단을 써야 하는 이유가 됩니다 ✓","entrada: 입구라는 뜻으로 계단 사용 이유가 되지 않습니다 ✗","puerta: 문이라는 뜻으로 맞지 않습니다 ✗","salida: 출구라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V726","q":"Mi hijo es muy ____. Su habitación es un auténtico desastre.","o":["impuntual","desorganizado","inteligente","responsable"],"a":1,"k":"성격 형용사","t":"우리 아들은 정리를 정말 못한다. 그의 방은 완전히 엉망이다.","e":"desorganizado는 '정리정돈을 못하는, 무질서한'이라는 뜻입니다. des-는 반대 의미를 만드는 접두사입니다(organizado 정리된 → desorganizado). 방이 엉망(un auténtico desastre)이라는 설명과 맞습니다.","x":["impuntual: 시간을 안 지키는이라는 뜻으로 방 상태와 관계없습니다 ✗","desorganizado: 정리를 못하는이라는 뜻으로 엉망인 방과 맞습니다 ✓","inteligente: 똑똑한이라는 뜻으로 방 상태와 관계없습니다 ✗","responsable: 책임감 있는이라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V727","q":"Mi sobrina tiene los ojos ____.","o":["naranjas","lisos","marrones","largos"],"a":2,"k":"눈 색깔 어휘","t":"내 조카딸은 눈이 갈색이다.","e":"marrón은 '갈색'입니다. 'tener los ojos + 색'은 '눈이 ~색이다'라는 표현입니다. 복수형은 marrones입니다. 다른 눈 색: azules(파란), verdes(초록), negros(검은).","x":["naranjas: 주황색이라는 뜻으로 눈 색으로 쓰지 않습니다 ✗","lisos: 곧은, 매끈한이라는 뜻으로 머리카락에 씁니다 ✗","marrones: 갈색이라는 뜻으로 눈 색에 씁니다 ✓","largos: 긴이라는 뜻으로 눈 색이 아닙니다 ✗"]},{"id":"V728","q":"Hoy está la plaza ____ porque todos quieren escuchar a los músicos que van a tocar allí.","o":["tranquila","llena","vacía","sucia"],"a":1,"k":"상태 형용사","t":"오늘 광장은 사람들로 가득하다. 모두가 그곳에서 연주할 음악가들의 연주를 듣고 싶어 하기 때문이다.","e":"lleno/a는 '가득 찬'이라는 뜻입니다. 모두(todos)가 음악을 들으러 오니 광장이 사람으로 가득합니다. 반대말은 vacío/a(텅 빈)입니다.","x":["tranquila: 조용한이라는 뜻으로 사람이 많은 상황과 맞지 않습니다 ✗","llena: 가득 찬이라는 뜻으로 사람이 많이 모인 광장에 맞습니다 ✓","vacía: 텅 빈이라는 뜻으로 문맥과 반대입니다 ✗","sucia: 더러운이라는 뜻으로 모인 이유와 관계없습니다 ✗"]},{"id":"V729","q":"Disculpe, esta blusa me queda pequeña. ¿Tiene una ____ más grande?","o":["cantidad","talla","reducción","rebaja"],"a":1,"k":"쇼핑 어휘","t":"실례합니다, 이 블라우스가 작아요. 더 큰 사이즈 있나요?","e":"talla는 '(옷의) 치수, 사이즈'입니다. 'me queda pequeña'는 '나에게 작다'라는 표현이에요. 옷 가게에서 '¿Qué talla usa?(어떤 사이즈를 입으세요?)'처럼 자주 씁니다.","x":["cantidad: 양이라는 뜻으로 옷 크기를 나타내지 않습니다 ✗","talla: 사이즈라는 뜻으로 더 큰 옷을 요청할 때 씁니다 ✓","reducción: 감소, 할인이라는 뜻으로 맞지 않습니다 ✗","rebaja: 할인이라는 뜻으로 크기와 관계없습니다 ✗"]},{"id":"V730","q":"No tengo ninguna ____, todo sigue igual.","o":["especialidad","atención","novedad","experiencia"],"a":2,"k":"명사 어휘","t":"새로운 소식은 없어. 모든 게 그대로야.","e":"novedad는 '새로운 일, 새 소식'입니다. 'todo sigue igual(모든 게 그대로다)'와 맞으려면 새로운 일이 없다는 뜻이어야 합니다. '¿Alguna novedad?(무슨 새로운 소식 있어?)'처럼 자주 씁니다.","x":["especialidad: 전문 분야라는 뜻으로 맞지 않습니다 ✗","atención: 주의, 관심이라는 뜻으로 맞지 않습니다 ✗","novedad: 새로운 소식이라는 뜻으로 그대로라는 말과 맞습니다 ✓","experiencia: 경험이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V731","q":"____, ya estoy curado.","o":["Tristemente","Desgraciadamente","Desafortunadamente","Afortunadamente"],"a":3,"k":"부사 어휘","t":"다행히도 나는 이제 다 나았다.","e":"afortunadamente는 '다행히도'라는 뜻입니다. 병이 나았다(estoy curado)는 좋은 소식이므로 긍정적인 부사가 와야 합니다. 형용사 + -mente는 부사를 만듭니다(afortunado → afortunadamente).","x":["Tristemente: 슬프게도라는 뜻으로 좋은 소식과 맞지 않습니다 ✗","Desgraciadamente: 불행히도라는 뜻으로 맞지 않습니다 ✗","Desafortunadamente: 운 나쁘게도라는 뜻으로 맞지 않습니다 ✗","Afortunadamente: 다행히도라는 뜻으로 나았다는 소식과 맞습니다 ✓"]},{"id":"V732","q":"Los ____ escriben poemas.","o":["secretarios","cuidadores","poetas","guardias"],"a":2,"k":"직업 어휘","t":"시인들은 시를 쓴다.","e":"poeta는 '시인'이고 poema는 '시'입니다. poeta는 -a로 끝나지만 남성에게도 씁니다(el poeta). 시를 쓰는(escriben poemas) 사람은 시인입니다.","x":["secretarios: 비서라는 뜻으로 시를 쓰는 직업이 아닙니다 ✗","cuidadores: 돌보는 사람이라는 뜻으로 맞지 않습니다 ✗","poetas: 시인이라는 뜻으로 시를 쓰는 사람입니다 ✓","guardias: 경비원이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V733","q":"Ese apartamento es muy ____, por eso necesita reformas.","o":["antiguo","caro","nuevo","barato"],"a":0,"k":"집 형용사","t":"그 아파트는 아주 오래되어서 수리가 필요하다.","e":"antiguo는 '오래된'이라는 뜻입니다. reformas(리모델링, 수리)가 필요한 이유는 집이 낡았기 때문입니다. 'por eso'는 '그래서'라는 뜻으로 결과를 이어 줍니다.","x":["antiguo: 오래된이라는 뜻으로 수리가 필요한 이유가 됩니다 ✓","caro: 비싼이라는 뜻으로 수리 필요의 이유가 아닙니다 ✗","nuevo: 새로운이라는 뜻으로 수리가 필요 없습니다 ✗","barato: 싼이라는 뜻으로 수리 필요의 직접 이유가 아닙니다 ✗"]},{"id":"V734","q":"¿Sabes cuándo va a volver Mariana? —No, no ____ ni idea.","o":["hago","tengo","doy","tomo"],"a":1,"k":"tener idea","t":"마리아나가 언제 돌아올지 알아? —아니, 전혀 모르겠어.","e":"'no tener ni idea'는 '전혀 모르다'라는 관용 표현입니다. ni는 '~조차'라는 뜻으로 부정을 강조합니다. 일상 대화에서 '¡Ni idea!(전혀 몰라!)'처럼 짧게도 씁니다.","x":["hago: 하다(hacer)로 idea와 이런 표현을 만들지 않습니다 ✗","tengo: 가지다(tener)로 no tener ni idea(전혀 모르다)가 됩니다 ✓","doy: 주다(dar)로 이 관용 표현에 쓰지 않습니다 ✗","tomo: 잡다(tomar)로 이 표현에 쓰지 않습니다 ✗"]},{"id":"V735","q":"Me robaron la cartera, por eso tengo que ir a la ____ de policía.","o":["vivienda","residencia","casa","comisaría"],"a":3,"k":"공공 장소 어휘","t":"지갑을 도둑맞아서 경찰서에 가야 한다.","e":"comisaría (de policía)는 '경찰서'입니다. 도난(robar 훔치다)을 신고하는 곳입니다. robaron은 '(누군가가) 훔쳤다'라는 단순과거입니다.","x":["vivienda: 주택이라는 뜻으로 de policía와 어울리지 않습니다 ✗","residencia: 거주지, 기숙사라는 뜻으로 맞지 않습니다 ✗","casa: 집이라는 뜻으로 경찰서를 나타내지 않습니다 ✗","comisaría: 경찰서라는 뜻으로 도난 신고하는 곳입니다 ✓"]},{"id":"V736","q":"¿Me pasas la receta de este ____?","o":["pastel","instrumento","traje","concurso"],"a":0,"k":"음식 어휘","t":"이 케이크 레시피 좀 알려 줄래?","e":"pastel은 '케이크'입니다. receta(조리법, 레시피)는 음식에 대한 것이므로 pastel이 정답입니다. receta에는 '처방전'이라는 뜻도 있습니다.","x":["pastel: 케이크라는 뜻으로 레시피가 있는 음식입니다 ✓","instrumento: 악기, 도구라는 뜻으로 레시피와 관계없습니다 ✗","traje: 정장이라는 뜻으로 맞지 않습니다 ✗","concurso: 대회라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V737","q":"Me siento ____, no tengo fuerzas para nada.","o":["débil","ligera","sana","tranquila"],"a":0,"k":"몸 상태 형용사","t":"몸에 힘이 없어. 아무것도 할 기운이 없어.","e":"débil은 '약한, 힘이 없는'이라는 뜻입니다. 'no tengo fuerzas para nada(아무것도 할 힘이 없다)'와 맞습니다. 반대말은 fuerte(강한)입니다.","x":["débil: 약한이라는 뜻으로 힘이 없다는 말과 맞습니다 ✓","ligera: 가벼운이라는 뜻으로 힘이 없다는 설명과 맞지 않습니다 ✗","sana: 건강한이라는 뜻으로 문맥과 반대입니다 ✗","tranquila: 차분한이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V738","q":"Toma, prueba estos ____. ¡Están buenísimos!","o":["borradores","estuches","caramelos","lápices"],"a":2,"k":"음식 어휘","t":"자, 이 사탕 먹어 봐. 정말 맛있어!","e":"caramelo는 '사탕, 캐러멜'입니다. probar는 '맛보다'라는 뜻이고 '¡Están buenísimos!(정말 맛있어!)'는 먹는 것에 대한 말이므로 caramelos가 정답입니다.","x":["borradores: 지우개(칠판지우개)라는 뜻으로 먹을 수 없습니다 ✗","estuches: 필통이라는 뜻으로 먹을 수 없습니다 ✗","caramelos: 사탕이라는 뜻으로 맛볼 수 있습니다 ✓","lápices: 연필이라는 뜻으로 먹을 수 없습니다 ✗"]},{"id":"V739","q":"Tengo que barrer el suelo, pero no encuentro la ____.","o":["toalla","escoba","esponja","fregona"],"a":1,"k":"청소 도구 어휘","t":"바닥을 쓸어야 하는데 빗자루를 못 찾겠다.","e":"escoba는 '빗자루'입니다. barrer는 '(빗자루로) 쓸다'라는 뜻입니다. fregona(대걸레)는 바닥을 '닦을(fregar)' 때 씁니다.","x":["toalla: 수건이라는 뜻으로 바닥을 쓸지 않습니다 ✗","escoba: 빗자루라는 뜻으로 바닥을 쓸 때 씁니다 ✓","esponja: 스펀지라는 뜻으로 쓸기와 맞지 않습니다 ✗","fregona: 대걸레라는 뜻으로 쓸기가 아니라 닦기에 씁니다 ✗"]},{"id":"V740","q":"La ____ de este programa lleva muchos años en televisión.","o":["viajera","presentadora","jardinera","dependienta"],"a":1,"k":"직업 어휘","t":"이 프로그램의 진행자는 수년째 TV에 나오고 있다.","e":"presentador/a는 '(TV·라디오) 진행자'입니다. programa(프로그램)의 진행자가 오래 TV에 나왔다는 의미입니다. 'llevar + 기간'은 '~동안 ~해 오다'라는 뜻입니다.","x":["viajera: 여행자라는 뜻으로 프로그램 진행과 관계없습니다 ✗","presentadora: 진행자라는 뜻으로 TV 프로그램과 맞습니다 ✓","jardinera: 정원사라는 뜻으로 맞지 않습니다 ✗","dependienta: 점원이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V741","q":"Nuestro negocio va bien; estamos ____ mucho.","o":["descansando","saliendo","relajándonos","vendiendo"],"a":3,"k":"사업 어휘","t":"우리 사업은 잘되고 있다. 많이 팔고 있다.","e":"vender는 '팔다'이고 vendiendo는 현재분사입니다. 사업(negocio)이 잘된다는 근거로 많이 팔고 있다는 말이 자연스럽습니다. 'ir bien'은 '잘 되어 가다'라는 뜻입니다.","x":["descansando: 쉬고 있는이라는 뜻으로 사업이 잘되는 이유가 아닙니다 ✗","saliendo: 나가고 있는이라는 뜻으로 맞지 않습니다 ✗","relajándonos: 쉬고 있는이라는 뜻으로 사업 근거가 아닙니다 ✗","vendiendo: 팔고 있는이라는 뜻으로 사업이 잘되는 이유입니다 ✓"]},{"id":"V742","q":"Eva es una persona ____ y cariñosa.","o":["odiosa","fría","antipática","dulce"],"a":3,"k":"성격 형용사","t":"에바는 다정하고 상냥한 사람이다.","e":"dulce는 원래 '단'이라는 뜻이지만 사람에게 쓰면 '다정한, 상냥한'이라는 뜻이 됩니다. y로 연결된 cariñosa(애정 어린)와 비슷한 긍정적인 성격이 와야 합니다.","x":["odiosa: 밉살스러운이라는 뜻으로 cariñosa와 어울리지 않습니다 ✗","fría: 차가운이라는 뜻으로 다정함과 반대입니다 ✗","antipática: 불친절한이라는 뜻으로 맞지 않습니다 ✗","dulce: 다정한이라는 뜻으로 cariñosa와 잘 어울립니다 ✓"]},{"id":"V743","q":"¿Por qué ____ estás aprendiendo sueco? —Porque mi esposa es de Suecia.","o":["idea","explicación","motivo","pensamiento"],"a":2,"k":"명사 어휘","t":"너는 왜 스웨덴어를 배우고 있어? —내 아내가 스웨덴 사람이거든.","e":"motivo는 '이유, 동기'입니다. '¿Por qué motivo...?'는 '무슨 이유로?'라는 뜻으로 ¿Por qué?보다 조금 더 정중한 표현입니다. 대답이 porque(왜냐하면)로 이유를 말합니다.","x":["idea: 생각이라는 뜻으로 por qué와 함께 이유를 묻지 않습니다 ✗","explicación: 설명이라는 뜻으로 이 구조에 쓰지 않습니다 ✗","motivo: 이유라는 뜻으로 por qué motivo(무슨 이유로)가 됩니다 ✓","pensamiento: 생각, 사고라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V744","q":"Roberto es muy organizado. ____ sus viajes con bastante antelación.","o":["Inventa","Olvida","Planea","Cancela"],"a":2,"k":"동사 어휘","t":"로베르토는 매우 체계적이다. 여행을 꽤 일찍부터 계획한다.","e":"planear는 '계획하다'이고 Planea는 3인칭 단수 현재형입니다. organizado(체계적인) 사람은 여행을 미리(con antelación) 계획합니다.","x":["Inventa: 지어내다, 발명하다라는 뜻으로 맞지 않습니다 ✗","Olvida: 잊다라는 뜻으로 체계적인 사람과 반대입니다 ✗","Planea: 계획하다라는 뜻으로 체계적인 사람과 맞습니다 ✓","Cancela: 취소하다라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V745","q":"No me ____; háblame con respeto.","o":["mientas","ofendas","informes","esperes"],"a":1,"k":"부정 명령","t":"나를 모욕하지 마. 예의 있게 말해.","e":"ofender는 '모욕하다, 기분 상하게 하다'라는 뜻이며 'No me ofendas'는 tú에게 하는 부정 명령입니다(접속법 형태). 'háblame con respeto(예의 있게 말해)'와 연결됩니다.","x":["mientas: 거짓말하다(mentir)로 respeto와 직접 연결되지 않습니다 ✗","ofendas: 모욕하다(ofender)로 예의 있게 말하라는 말과 맞습니다 ✓","informes: 알리다(informar)로 맞지 않습니다 ✗","esperes: 기다리다(esperar)로 맞지 않습니다 ✗"]},{"id":"V746","q":"¿Qué ____ tienes para el fin de semana? —Voy a visitar a mi hermana.","o":["saludos","diseños","planes","recuerdos"],"a":2,"k":"명사 어휘","t":"주말에 무슨 계획 있어? —언니를 만나러 갈 거야.","e":"plan은 '계획'이고 복수는 planes입니다. '¿Qué planes tienes?'는 '무슨 계획 있어?'라는 자주 쓰는 질문입니다. 대답이 앞으로 할 일이므로 planes가 맞습니다.","x":["saludos: 인사라는 뜻으로 맞지 않습니다 ✗","diseños: 디자인이라는 뜻으로 맞지 않습니다 ✗","planes: 계획이라는 뜻으로 앞으로의 일정과 맞습니다 ✓","recuerdos: 추억, 기념품이라는 뜻으로 과거와 관련됩니다 ✗"]},{"id":"V747","q":"¿Por qué estás tan ____? —Es que estoy preocupada por mi hija.","o":["alegre","seria","sonriente","relajada"],"a":1,"k":"감정 형용사","t":"왜 그렇게 심각해? —딸이 걱정돼서 그래.","e":"serio/a는 '진지한, 심각한(표정)'이라는 뜻입니다. 걱정하는(preocupada) 사람은 표정이 심각해 보입니다. 'Es que...'는 '그게 말이야, ~ 때문이야'라고 이유를 말할 때 씁니다.","x":["alegre: 즐거운이라는 뜻으로 걱정과 맞지 않습니다 ✗","seria: 심각한이라는 뜻으로 걱정하는 모습과 맞습니다 ✓","sonriente: 미소 짓는이라는 뜻으로 맞지 않습니다 ✗","relajada: 편안한이라는 뜻으로 걱정과 반대입니다 ✗"]},{"id":"V748","q":"Necesitamos un ____ más para formar un equipo de balonmano.","o":["jugador","investigador","espectador","bailaor"],"a":0,"k":"스포츠 어휘","t":"핸드볼 팀을 꾸리려면 선수가 한 명 더 필요하다.","e":"jugador/a는 '선수, 경기하는 사람'입니다. jugar(경기하다)에 -dor가 붙은 말이에요. 팀(equipo)을 만들려면 선수가 필요합니다.","x":["jugador: 선수라는 뜻으로 팀을 만들 때 필요합니다 ✓","investigador: 연구원이라는 뜻으로 맞지 않습니다 ✗","espectador: 관객이라는 뜻으로 팀 구성원이 아닙니다 ✗","bailaor: 플라멩코 무용수라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V749","q":"Ayer visitamos un pueblo ____. Es uno de los sitios más bonitos que he visto.","o":["sucio","horrible","feísimo","precioso"],"a":3,"k":"형용사 어휘","t":"어제 우리는 아름다운 마을을 방문했다. 내가 본 곳 중 가장 예쁜 곳 중 하나다.","e":"precioso는 '아주 예쁜, 아름다운'이라는 뜻입니다. 뒤 문장의 'uno de los sitios más bonitos(가장 예쁜 곳 중 하나)'와 맞습니다.","x":["sucio: 더러운이라는 뜻으로 가장 예쁜 곳이라는 말과 반대입니다 ✗","horrible: 끔찍한이라는 뜻으로 반대입니다 ✗","feísimo: 아주 못생긴이라는 뜻으로 반대입니다 ✗","precioso: 아주 예쁜이라는 뜻으로 뒤 문장과 맞습니다 ✓"]},{"id":"V750","q":"Rocío es una chica maravillosa. Es simpática, educada y ____.","o":["egoísta","desagradable","amable","mala"],"a":2,"k":"성격 형용사","t":"로시오는 멋진 아이다. 상냥하고 예의 바르고 친절하다.","e":"amable은 '친절한'이라는 뜻입니다. maravillosa(멋진)라고 칭찬하면서 simpática(호감 가는), educada(예의 바른)를 나열하므로 같은 긍정적인 성격이 와야 합니다.","x":["egoísta: 이기적인이라는 뜻으로 칭찬과 맞지 않습니다 ✗","desagradable: 불쾌한이라는 뜻으로 맞지 않습니다 ✗","amable: 친절한이라는 뜻으로 긍정적인 나열과 맞습니다 ✓","mala: 나쁜이라는 뜻으로 맞지 않습니다 ✗"]}];